def normalize_days_window(days: int, default: int = 2) -> int:
    try:
        value = int(days)
    except Exception:
        value = default
    return max(1, min(value, 365))


def normalize_pull_limit(limit: Any, default: int = 0) -> int:
    try:
        value = int(limit)
    except Exception:
        value = default
    return max(0, min(value, 50000))


def stored_pull_limit() -> int:
    return normalize_pull_limit(get_setting("pull_orders_limit", get_service_settings().get("pull_orders_limit", "0")), 0)


def auto_pull_limit(limit: Any) -> int:
    normalized = normalize_pull_limit(limit, 0)
    # A tiny scheduled limit silently misses confirmed paid orders. Keep limit 0
    # as the safe automation default: pull every matching order in the window.
    return 0 if normalized <= 1 else normalized


def stored_pull_days(default: int = 7) -> int:
    return normalize_days_window(get_setting("pull_orders_days", get_service_settings().get("pull_orders_days", str(default))), default)


def stored_pull_batch_size() -> int:
    return normalize_pull_batch_size(get_service_settings().get("pull_orders_batch_size", "50"))


