def shopify_clients_for_route(route: str) -> list[Any]:
    module, _script_path, state_scope = shopify_route_script_config(route)
    state = module.StateDB(state_scope)
    clients = []
    for dest in module.DESTS:
        token = module.get_shopify_access_token(dest, state)
        clients.append(module.ShopifyClient(dest["name"], dest["shop"], token, dest.get("api_version") or "2025-10"))
    return clients


def shopify_admin_order_url(shop: str, order_id: Any) -> str:
    shop_slug = clean_text(shop).split(".")[0]
    order_id_text = clean_text(order_id)
    if not shop_slug or not order_id_text:
        return ""
    return f"https://admin.shopify.com/store/{shop_slug}/orders/{order_id_text}"


def shopify_fulfillment_at_from_node(node: dict[str, Any]) -> str:
    fulfillments = node.get("fulfillments") or []
    if isinstance(fulfillments, dict):
        fulfillments = fulfillments.get("nodes") or fulfillments.get("edges") or []
    dates: list[str] = []
    for item in fulfillments if isinstance(fulfillments, list) else []:
        fulfillment = item.get("node") if isinstance(item, dict) and item.get("node") else item
        if not isinstance(fulfillment, dict):
            continue
        for key in ("deliveredAt", "updatedAt", "createdAt"):
            value = clean_text(fulfillment.get(key))
            if value:
                dates.append(value)
                break
    return min(dates) if dates else ""


def shopify_orders_by_name(shop: Any, order_name: str, limit: int = 20) -> list[dict[str, Any]]:
    clean_name = clean_text(order_name)
    if not clean_name:
        return []
    query = """
    query($q: String!, $limit: Int!) {
      orders(first: $limit, query: $q, sortKey: CREATED_AT) {
        nodes {
          id
          legacyResourceId
          name
          createdAt
          cancelledAt
          displayFinancialStatus
          displayFulfillmentStatus
          note
          fulfillments(first: 10) {
            id
            status
            createdAt
            updatedAt
            deliveredAt
          }
        }
      }
    }
    """
    search = f'name:"{clean_name}"'
    data = shop.graphql(query, {"q": search, "limit": max(1, min(50, int(limit or 20)))})
    nodes = ((data.get("orders") or {}).get("nodes") or [])
    matching = []
    for node in nodes:
        node_name = clean_text(node.get("name"))
        if node_name.lstrip("#") != clean_name.lstrip("#"):
            continue
        legacy_id = clean_text(node.get("legacyResourceId"))
        matching.append({
            "id": legacy_id,
            "gid": clean_text(node.get("id")),
            "name": node_name,
            "created_at": clean_text(node.get("createdAt")),
            "cancelled_at": clean_text(node.get("cancelledAt")),
            "financial_status": clean_text(node.get("displayFinancialStatus")),
            "fulfillment_status": clean_text(node.get("displayFulfillmentStatus")),
            "fulfillment_at": shopify_fulfillment_at_from_node(node),
            "note": clean_text(node.get("note")),
            "url": shopify_admin_order_url(shop.shop, legacy_id),
        })
    matching.sort(key=lambda row: row.get("created_at") or "")
    return matching


def shopify_order_by_id(shop: Any, order_id: Any) -> dict[str, Any] | None:
    legacy_id = clean_text(order_id)
    if not legacy_id:
        return None
    query = """
    query($id: ID!) {
      node(id: $id) {
        ... on Order {
          id
          legacyResourceId
          name
          createdAt
          cancelledAt
          displayFinancialStatus
          displayFulfillmentStatus
          fulfillments(first: 10) {
            id
            status
            createdAt
            updatedAt
            deliveredAt
          }
        }
      }
    }
    """
    data = shop.graphql(query, {"id": f"gid://shopify/Order/{legacy_id}"})
    node = data.get("node") or {}
    if not node:
        return None
    returned_legacy_id = clean_text(node.get("legacyResourceId")) or legacy_id
    return {
        "id": returned_legacy_id,
        "gid": clean_text(node.get("id")),
        "name": clean_text(node.get("name")),
        "created_at": clean_text(node.get("createdAt")),
        "cancelled_at": clean_text(node.get("cancelledAt")),
        "financial_status": clean_text(node.get("displayFinancialStatus")),
        "fulfillment_status": clean_text(node.get("displayFulfillmentStatus")),
        "fulfillment_at": shopify_fulfillment_at_from_node(node),
        "url": shopify_admin_order_url(shop.shop, returned_legacy_id),
    }


def shopify_order_is_fulfilled(order: dict[str, Any]) -> bool:
    status = clean_text(order.get("fulfillment_status")).upper().replace(" ", "_")
    return status in {"FULFILLED", "PARTIALLY_FULFILLED", "PARTIAL"}


def inventory_fulfilment_note_for_order(store_id: int, order_name: str) -> str:
    with db() as conn:
        rows = rows_to_dicts(conn.execute(
            """
            SELECT asin, quantity, inventory_allocated_quantity
            FROM order_lines
            WHERE store_id=? AND UPPER(odoo_order_name)=UPPER(?)
              AND COALESCE(inventory_allocated_quantity, 0) > 0
            ORDER BY id
            """,
            (store_id, order_name),
        ).fetchall())
    if not rows:
        return ""
    details = []
    for row in rows:
        total = max(0.0, float(row.get("quantity") or 0))
        local = min(total, max(0.0, float(row.get("inventory_allocated_quantity") or 0)))
        amazon = max(0.0, total - local)
        detail = f"ASIN {normalize_asin(row.get('asin'))}: {local:g} from local inventory"
        detail += f", {amazon:g} ordered from Amazon" if amazon > 0 else ", no Amazon purchase"
        details.append(detail)
    return "Inventory fulfilment audit for " + clean_text(order_name).upper() + ": " + "; ".join(details)


def append_shopify_inventory_note(shop: Any, order: dict[str, Any], note: str) -> None:
    note = clean_text(note)
    gid = clean_text(order.get("gid"))
    if not note or not gid:
        return
    current = clean_text(order.get("note"))
    if note in current:
        return
    combined = f"{current}\n{note}".strip() if current else note
    mutation = """
    mutation($input: OrderInput!) {
      orderUpdate(input: $input) {
        order { id note }
        userErrors { field message }
      }
    }
    """
    result = shop.graphql(mutation, {"input": {"id": gid, "note": combined}})
    errors = (result.get("orderUpdate") or {}).get("userErrors") or []
    if errors:
        raise RuntimeError("; ".join(clean_text(item.get("message")) for item in errors))


def shopify_status_is_fulfilled(status: Any) -> bool:
    normalized = clean_text(status).upper().replace(" ", "_")
    return normalized in {"FULFILLED", "PARTIALLY_FULFILLED", "PARTIAL"}


ODOO_DISPLAY_TIMEZONE = ZoneInfo(os.getenv("ODOO_DISPLAY_TIMEZONE", "Asia/Kolkata"))
MIN_PLACEABLE_ODOO_ORDER_DATE = datetime(2026, 5, 18, tzinfo=ODOO_DISPLAY_TIMEZONE)


def odoo_order_date_for_guard(row: dict[str, Any]) -> Optional[datetime]:
    return (
        parse_iso_date(clean_text(row.get("odoo_order_date")))
        or parse_iso_date(clean_text(row.get("pulled_at")))
        or parse_iso_date(clean_text(row.get("created_at")))
    )


def odoo_display_date_for_guard(value: datetime) -> datetime.date:
    return value.astimezone(ODOO_DISPLAY_TIMEZONE).date()


def amazon_order_date_guard_enabled() -> bool:
    return str(get_service_settings().get("amazon_order_date_guard_enabled", "true")).strip().lower() in {"1", "true", "yes", "on"}


def shopify_fulfilled_order_guard_enabled() -> bool:
    return str(get_service_settings().get("shopify_fulfilled_order_guard_enabled", "false")).strip().lower() in {"1", "true", "yes", "on"}


def block_lines_before_min_odoo_order_date(conn: Any, lines: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], int, list[str]]:
    if not lines:
        return lines, 0, []
    if not amazon_order_date_guard_enabled():
        return lines, 0, []
    allowed: list[dict[str, Any]] = []
    blocked_ids: list[int] = []
    messages: list[str] = []
    for line in lines:
        order_date = odoo_order_date_for_guard(line)
        display_date = odoo_display_date_for_guard(order_date) if order_date else None
        if not display_date or display_date >= MIN_PLACEABLE_ODOO_ORDER_DATE.date():
            allowed.append(line)
            continue
        blocked_ids.append(int(line["id"]))
        order_name = clean_text(line.get("odoo_order_name")) or str(line.get("odoo_order_id") or "")
        messages.append(f"{order_name}: Odoo order date {display_date.isoformat()} is before 2026-05-18.")
    if blocked_ids:
        conn.execute(
            f"""
            UPDATE order_lines
            SET state='error',
                last_error=?,
                updated_at=?
            WHERE id IN ({",".join("?" for _ in blocked_ids)})
              AND COALESCE(amazon_order_id, '') = ''
            """,
            [
                "Blocked: Odoo order date is before 2026-05-18, so this order must never be placed.",
                utc_now(),
                *blocked_ids,
            ],
        )
    return allowed, len(set(blocked_ids)), sorted(set(messages))


def upsert_shopify_order_status(
    store_id: int,
    route: str,
    dest_name: str,
    shop: str,
    odoo_order_name: str,
    order: Optional[dict[str, Any]],
) -> None:
    if not order:
        return
    ensure_shopify_order_status_cache_table()
    order_id = clean_text(order.get("id"))
    order_name = clean_text(order.get("name")) or clean_text(odoo_order_name)
    with db() as conn:
        conn.execute(
            """
            INSERT INTO shopify_order_status_cache
            (store_id, odoo_order_name, route, dest_name, shop, shopify_order_id, shopify_order_name,
             shopify_order_url, financial_status, fulfillment_status, fulfillment_at, cancelled_at, synced_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(store_id, odoo_order_name, route, dest_name) DO UPDATE SET
              shop=excluded.shop,
              shopify_order_id=excluded.shopify_order_id,
              shopify_order_name=excluded.shopify_order_name,
              shopify_order_url=excluded.shopify_order_url,
              financial_status=excluded.financial_status,
              fulfillment_status=excluded.fulfillment_status,
              fulfillment_at=excluded.fulfillment_at,
              cancelled_at=excluded.cancelled_at,
              synced_at=excluded.synced_at
            """,
            (
                int(store_id),
                clean_text(odoo_order_name),
                clean_text(route).lower(),
                clean_text(dest_name),
                clean_text(shop),
                order_id,
                order_name,
                clean_text(order.get("url")) or shopify_admin_order_url(shop, order_id),
                clean_text(order.get("financial_status")),
                clean_text(order.get("fulfillment_status")) or "UNFULFILLED",
                clean_text(order.get("fulfillment_at")),
                clean_text(order.get("cancelled_at")),
                utc_now(),
            ),
        )


def sync_shopify_status_for_order_names(store_id: int, order_names: list[str], force: bool = False) -> None:
    clean_names = sorted({clean_text(name).upper() for name in order_names if clean_text(name)})
    if not clean_names:
        return
    ensure_shopify_order_status_cache_table()
    now = datetime.now(timezone.utc)
    mapped_targets: dict[str, list[dict[str, str]]] = {}
    with db() as conn:
        store_row = conn.execute("SELECT odoo_db FROM stores WHERE id=?", (store_id,)).fetchone()
        odoo_db = clean_text((store_row or {}).get("odoo_db"))
        if odoo_db:
            source_keys = [f"{odoo_db}:{name}" for name in clean_names]
            export_rows = conn.execute(
                f"""
                SELECT state_scope, dest_name, src_order_key, dest_order_id
                FROM shopify_export_order_map
                WHERE src_order_key IN ({",".join("?" for _ in source_keys)})
                  AND COALESCE(dest_order_id, '') != ''
                ORDER BY created_at DESC
                """,
                source_keys,
            ).fetchall()
            for row in export_rows:
                source_key = clean_text(row.get("src_order_key"))
                order_name = clean_text(source_key.split(":", 1)[-1]).upper()
                if not order_name:
                    continue
                mapped_targets.setdefault(order_name, []).append(
                    {
                        "route": clean_text(row.get("state_scope")).lower(),
                        "dest_name": clean_text(row.get("dest_name")),
                        "order_id": clean_text(row.get("dest_order_id")),
                    }
                )
    if not force:
        with db() as conn:
            cached = conn.execute(
                f"""
                SELECT odoo_order_name, MAX(synced_at) AS synced_at
                FROM shopify_order_status_cache
                WHERE store_id=?
                  AND UPPER(odoo_order_name) IN ({",".join("?" for _ in clean_names)})
                GROUP BY odoo_order_name
                """,
                [store_id, *clean_names],
            ).fetchall()
        fresh_names = set()
        for row in cached:
            synced_at = parse_iso_date(clean_text(row.get("synced_at")))
            if synced_at and (now - synced_at).total_seconds() < 1800:
                fresh_names.add(clean_text(row.get("odoo_order_name")).upper())
        clean_names = [name for name in clean_names if name not in fresh_names]
        if not clean_names:
            return
    for route in ("dtc", "dtb"):
        try:
            module, _script_path, state_scope = shopify_route_script_config(route)
            state = module.StateDB(state_scope)
            clients = []
            for dest in module.DESTS:
                token = module.get_shopify_access_token(dest, state)
                clients.append(module.ShopifyClient(dest["name"], dest["shop"], token, dest.get("api_version") or "2025-10"))
        except Exception:
            continue
        for shop in clients:
            for order_name in clean_names:
                try:
                    candidates: list[dict[str, Any]] = []
                    mapped = [
                        target for target in mapped_targets.get(order_name, [])
                        if target.get("route") == route and target.get("dest_name") == shop.name and target.get("order_id")
                    ]
                    if mapped:
                        for target in mapped:
                            mapped_order = shopify_order_by_id(shop, target["order_id"])
                            if mapped_order:
                                candidates.append(mapped_order)
                    if not candidates:
                        orders = shopify_orders_by_name(shop, order_name, limit=10)
                        candidates.extend(orders)
                    deduped: list[dict[str, Any]] = []
                    seen_order_ids: set[str] = set()
                    for order in candidates:
                        order_id = clean_text(order.get("id"))
                        if not order_id or order_id in seen_order_ids:
                            continue
                        seen_order_ids.add(order_id)
                        deduped.append(order)
                    active = [order for order in deduped if not order.get("cancelled_at")]
                    chosen = next((order for order in active if shopify_order_is_fulfilled(order)), active[0] if active else (deduped[0] if deduped else None))
                    if chosen:
                        upsert_shopify_order_status(store_id, route, shop.name, shop.shop, order_name, chosen)
                except Exception:
                    continue


_SHOPIFY_STATUS_CACHE_ENSURED = False
_SHOPIFY_STATUS_CACHE_ENSURE_LOCK = threading.Lock()


def ensure_shopify_order_status_cache_table_once() -> None:
    global _SHOPIFY_STATUS_CACHE_ENSURED
    if _SHOPIFY_STATUS_CACHE_ENSURED:
        return
    with _SHOPIFY_STATUS_CACHE_ENSURE_LOCK:
        if _SHOPIFY_STATUS_CACHE_ENSURED:
            return
        ensure_shopify_order_status_cache_table()
        _SHOPIFY_STATUS_CACHE_ENSURED = True


def attach_shopify_status_to_rows(rows: list[dict[str, Any]], conn: Optional[Any] = None) -> list[dict[str, Any]]:
    if not rows:
        return rows
    store_ids = sorted({int(row["store_id"]) for row in rows if row.get("store_id")})
    order_names = sorted({clean_text(row.get("odoo_order_name")).upper() for row in rows if clean_text(row.get("odoo_order_name"))})
    if not store_ids or not order_names:
        return rows
    ensure_shopify_order_status_cache_table_once()
    def fetch_cached_status(active_conn: Any) -> list[dict[str, Any]]:
        return active_conn.execute(
            f"""
            SELECT DISTINCT ON (store_id, odoo_order_name)
                   store_id, odoo_order_name, shopify_order_id, shopify_order_name,
                   shopify_order_url, financial_status, fulfillment_status,
                   fulfillment_at, cancelled_at, synced_at
            FROM shopify_order_status_cache
            WHERE store_id = ANY(?::int[])
              AND odoo_order_name = ANY(?::text[])
            ORDER BY store_id, odoo_order_name,
                     CASE WHEN COALESCE(cancelled_at, '') = '' THEN 0 ELSE 1 END,
                     CASE WHEN fulfillment_status ILIKE '%FULFILLED%' THEN 0 ELSE 1 END,
                     synced_at DESC
            """,
            (store_ids, order_names),
        ).fetchall()
    if conn is not None:
        cached_rows = fetch_cached_status(conn)
    else:
        with db() as status_conn:
            cached_rows = fetch_cached_status(status_conn)
    status_by_key = {
        (int(row["store_id"]), clean_text(row["odoo_order_name"]).upper()): dict(row)
        for row in cached_rows
    }
    for row in rows:
        cached = status_by_key.get((int(row.get("store_id") or 0), clean_text(row.get("odoo_order_name")).upper()))
        if cached is None and (
            clean_text(row.get("shopify_order_id"))
            or clean_text(row.get("shopify_order_name"))
            or clean_text(row.get("shopify_fulfillment_status"))
        ):
            continue
        row["shopify_order_id"] = clean_text((cached or {}).get("shopify_order_id"))
        row["shopify_order_name"] = clean_text((cached or {}).get("shopify_order_name"))
        row["shopify_order_url"] = clean_text((cached or {}).get("shopify_order_url"))
        row["shopify_financial_status"] = clean_text((cached or {}).get("financial_status"))
        row["shopify_fulfillment_status"] = clean_text((cached or {}).get("fulfillment_status"))
        row["shopify_fulfillment_at"] = clean_text((cached or {}).get("fulfillment_at"))
        row["shopify_cancelled_at"] = clean_text((cached or {}).get("cancelled_at"))
        row["shopify_synced_at"] = clean_text((cached or {}).get("synced_at"))
    return rows


def refresh_missing_shopify_status_for_rows(rows: list[dict[str, Any]], *, wait: bool = False) -> int:
    groups: dict[int, set[str]] = {}
    now = datetime.now(timezone.utc)
    for row in rows:
        synced_at_text = clean_text(row.get("shopify_synced_at") or row.get("shopify_status_synced_at"))
        status_text = clean_text(row.get("shopify_fulfillment_status")).lower()
        cancelled_at = clean_text(row.get("shopify_cancelled_at"))
        synced_at = parse_iso_date(synced_at_text)
        stale_status = bool(
            synced_at
            and (now - synced_at).total_seconds() >= 1800
            and not cancelled_at
            and (
                not status_text
                or status_text in {"unfulfilled", "partial", "partially_fulfilled"}
                or ("fulfilled" in status_text and not clean_text(row.get("shopify_fulfillment_at")))
            )
        )
        if synced_at_text and not stale_status:
            continue
        store_id = parse_optional_int(row.get("store_id"))
        order_name = clean_text(row.get("odoo_order_name")).upper()
        if not store_id or not order_name:
            continue
        groups.setdefault(store_id, set()).add(order_name)
    if not groups:
        return 0
    if wait:
        for store_id, order_names in groups.items():
            sync_shopify_status_for_order_names(store_id, sorted(order_names), force=True)
        fast_page_cache_clear_matching({"dashboard", "orders", "fulfilment-pending"})
        return sum(len(order_names) for order_names in groups.values())

    queued_groups: dict[int, set[str]] = {}
    queued_keys: set[tuple[int, str]] = set()
    with _SHOPIFY_STATUS_REFRESH_LOCK:
        for store_id, order_names in groups.items():
            for order_name in order_names:
                key = (store_id, order_name)
                if key in _SHOPIFY_STATUS_REFRESH_IN_FLIGHT:
                    continue
                _SHOPIFY_STATUS_REFRESH_IN_FLIGHT.add(key)
                queued_keys.add(key)
                queued_groups.setdefault(store_id, set()).add(order_name)
    if not queued_groups:
        return 0

    def worker() -> None:
        try:
            for store_id, order_names in queued_groups.items():
                sync_shopify_status_for_order_names(store_id, sorted(order_names), force=True)
                fast_page_cache_clear_matching({"dashboard", "orders", "fulfilment-pending"})
        finally:
            with _SHOPIFY_STATUS_REFRESH_LOCK:
                for key in queued_keys:
                    _SHOPIFY_STATUS_REFRESH_IN_FLIGHT.discard(key)

    threading.Thread(target=worker, daemon=True).start()
    return sum(len(order_names) for order_names in queued_groups.values())


def block_lines_with_fulfilled_shopify_orders(conn: Any, store_id: int, lines: list[dict[str, Any]], live_sync: bool = True) -> tuple[list[dict[str, Any]], int, list[str]]:
    if not lines:
        return lines, 0, []
    if not shopify_fulfilled_order_guard_enabled():
        return lines, 0, []
    order_names = sorted({clean_text(row.get("odoo_order_name")).upper() for row in lines if clean_text(row.get("odoo_order_name"))})
    ensure_shopify_order_status_cache_table()
    if live_sync:
        sync_shopify_status_for_order_names(store_id, order_names, force=True)
    cached_rows = conn.execute(
        f"""
        SELECT *
        FROM shopify_order_status_cache
        WHERE store_id=?
          AND UPPER(odoo_order_name) IN ({",".join("?" for _ in order_names)})
          AND COALESCE(cancelled_at, '') = ''
        """,
        [store_id, *order_names],
    ).fetchall() if order_names else []
    fulfilled_by_order: dict[str, dict[str, Any]] = {}
    for cached in cached_rows:
        if shopify_status_is_fulfilled(cached.get("fulfillment_status")):
            fulfilled_by_order[clean_text(cached.get("odoo_order_name")).upper()] = dict(cached)
    if not fulfilled_by_order:
        return lines, 0, []
    allowed: list[dict[str, Any]] = []
    blocked_ids: list[int] = []
    messages: list[str] = []
    for line in lines:
        order_name = clean_text(line.get("odoo_order_name")).upper()
        blocked = fulfilled_by_order.get(order_name)
        if not blocked:
            allowed.append(line)
            continue
        blocked_ids.append(int(line["id"]))
        shopify_ref = clean_text(blocked.get("shopify_order_name")) or clean_text(blocked.get("shopify_order_id")) or order_name
        messages.append(f"{order_name}: Shopify order {shopify_ref} is already fulfilled; customer may have received it.")
    if blocked_ids:
        conn.execute(
            f"""
            UPDATE order_lines
            SET state='error',
                last_error=?,
                updated_at=?
            WHERE id IN ({",".join("?" for _ in blocked_ids)})
              AND COALESCE(amazon_order_id, '') = ''
            """,
            [
                "Shopify order is already fulfilled. Amazon order or third-party reference is blocked because the customer may have received it.",
                utc_now(),
                *blocked_ids,
            ],
        )
    return allowed, len(set(blocked_ids)), sorted(set(messages))


def set_shopify_order_status_force_sync_progress(**updates: Any) -> dict[str, Any]:
    with _SHOPIFY_ORDER_STATUS_FORCE_SYNC_LOCK:
        _SHOPIFY_ORDER_STATUS_FORCE_SYNC_PROGRESS.update(updates)
        _SHOPIFY_ORDER_STATUS_FORCE_SYNC_PROGRESS["updated_at"] = utc_now()
        return dict(_SHOPIFY_ORDER_STATUS_FORCE_SYNC_PROGRESS)


def shopify_order_status_force_sync_progress() -> dict[str, Any]:
    with _SHOPIFY_ORDER_STATUS_FORCE_SYNC_LOCK:
        return dict(_SHOPIFY_ORDER_STATUS_FORCE_SYNC_PROGRESS)


def count_distinct_odoo_orders(store_id: Optional[int] = None, where_sql: str = "", params: Optional[list[Any]] = None) -> int:
    clause = "WHERE odoo_order_id IS NOT NULL"
    query_params: list[Any] = []
    if store_id is not None:
        clause += " AND store_id=?"
        query_params.append(store_id)
    if where_sql:
        clause += f" AND ({where_sql})"
        query_params.extend(params or [])
    with db() as conn:
        row = conn.execute(f"SELECT COUNT(DISTINCT store_id || ':' || odoo_order_id) AS count FROM order_lines {clause}", query_params).fetchone()
    return int(row["count"] or 0)


def force_sync_shopify_order_statuses(store_id: Optional[int] = None, batch_size: int = 25, pause_seconds: float = 1.0) -> None:
    batch_size = max(5, min(50, int(batch_size or 25)))
    pause_seconds = max(0.2, min(5.0, float(pause_seconds or 1.0)))
    started_at = utc_now()
    try:
        with db() as conn:
            rows = rows_to_dicts(conn.execute(
                """
                SELECT DISTINCT store_id, odoo_order_name
                FROM order_lines
                WHERE (? IS NULL OR store_id=?)
                  AND COALESCE(odoo_order_name, '') != ''
                ORDER BY store_id, odoo_order_name DESC
                """,
                (store_id, store_id),
            ).fetchall())
        total = len(rows)
        set_shopify_order_status_force_sync_progress(
            status="running",
            total=total,
            processed=0,
            matched=0,
            current_order="",
            message=f"Force syncing Shopify status for {total} Odoo order{'s' if total != 1 else ''} in batches of {batch_size}.",
            started_at=started_at,
            completed_at="",
            error="",
        )
        matched_before = 0
        processed = 0
        for offset in range(0, total, batch_size):
            batch = rows[offset:offset + batch_size]
            by_store: dict[int, list[str]] = {}
            for row in batch:
                by_store.setdefault(int(row["store_id"]), []).append(clean_text(row["odoo_order_name"]))
            for batch_store_id, order_names in by_store.items():
                sync_shopify_status_for_order_names(batch_store_id, order_names, force=True)
            processed += len(batch)
            with db() as conn:
                matched = int(conn.execute(
                    """
                    SELECT COUNT(DISTINCT store_id || ':' || odoo_order_name) AS count
                    FROM shopify_order_status_cache
                    WHERE (? IS NULL OR store_id=?)
                    """,
                    (store_id, store_id),
                ).fetchone()["count"] or 0)
            matched_before = matched
            set_shopify_order_status_force_sync_progress(
                processed=processed,
                matched=matched,
                current_order=clean_text(batch[-1].get("odoo_order_name")) if batch else "",
                message=f"Synced {processed} of {total} Odoo order{'s' if total != 1 else ''}; matched {matched} Shopify order{'s' if matched != 1 else ''}.",
            )
            if processed < total:
                time.sleep(pause_seconds)
        set_shopify_order_status_force_sync_progress(
            status="completed",
            processed=total,
            matched=matched_before,
            current_order="",
            completed_at=utc_now(),
            message=f"Shopify status force sync complete. Matched {matched_before} of {total} Odoo order{'s' if total != 1 else ''}.",
        )
    except Exception as exc:
        set_shopify_order_status_force_sync_progress(status="failed", error=str(exc), completed_at=utc_now(), message=f"Shopify status force sync failed: {exc}")


PACKAGE_TRACKER_SHOPIFY_SYNC_INTERVAL_SECONDS = 3 * 60 * 60
_PACKAGE_TRACKER_SHOPIFY_SYNC_LOCK = threading.Lock()


def sync_package_tracker_shopify_statuses() -> None:
    if not _PACKAGE_TRACKER_SHOPIFY_SYNC_LOCK.acquire(blocking=False):
        return
    started_at = utc_now()
    try:
        set_setting("package_tracker_shopify_sync_status", "running")
        set_setting("package_tracker_shopify_sync_started_at", started_at)
        cutoff = (datetime.now(timezone.utc) - timedelta(seconds=PACKAGE_TRACKER_SHOPIFY_SYNC_INTERVAL_SECONDS)).isoformat()
        recent_order_cutoff = (datetime.now(timezone.utc) - timedelta(days=30)).strftime("%Y-%m-%d")
        with db() as conn:
            rows = rows_to_dicts(conn.execute(
                """
                WITH cached AS (
                    SELECT store_id, UPPER(odoo_order_name) AS odoo_order_name, MAX(synced_at) AS synced_at,
                           BOOL_OR(LOWER(COALESCE(fulfillment_status, '')) IN ('fulfilled', 'success')) AS is_fulfilled
                    FROM shopify_order_status_cache
                    GROUP BY store_id, UPPER(odoo_order_name)
                ), tracker_orders AS (
                    SELECT l.store_id, UPPER(l.odoo_order_name) AS odoo_order_name, MAX(l.updated_at) AS updated_at
                    FROM order_lines l
                    WHERE COALESCE(l.amazon_order_id, '') != '' AND COALESCE(l.odoo_order_name, '') != ''
                      AND COALESCE(l.odoo_order_date, '') >= ?
                    GROUP BY l.store_id, UPPER(l.odoo_order_name)
                )
                SELECT tracker_orders.store_id, tracker_orders.odoo_order_name
                FROM tracker_orders
                LEFT JOIN cached
                  ON cached.store_id=tracker_orders.store_id AND cached.odoo_order_name=tracker_orders.odoo_order_name
                WHERE COALESCE(cached.synced_at, '') < ?
                  AND NOT COALESCE(cached.is_fulfilled, FALSE)
                ORDER BY tracker_orders.updated_at DESC, tracker_orders.odoo_order_name DESC
                """,
                (recent_order_cutoff, cutoff),
            ).fetchall())
        total = len(rows)
        processed = 0
        for offset in range(0, total, 40):
            batch = rows[offset:offset + 40]
            by_store: dict[int, list[str]] = {}
            for row in batch:
                by_store.setdefault(int(row["store_id"]), []).append(clean_text(row.get("odoo_order_name")))
            for store_id, order_names in by_store.items():
                sync_shopify_status_for_order_names(store_id, order_names, force=True)
            processed += len(batch)
            set_setting("package_tracker_shopify_sync_progress", f"{processed}/{total}")
            fast_page_cache_clear_matching({"public-package-tracker", "dashboard", "orders", "fulfilment-pending"})
        completed_at = utc_now()
        set_setting("package_tracker_shopify_sync_status", "completed")
        set_setting("package_tracker_shopify_sync_last_run_at", completed_at)
        set_setting("package_tracker_shopify_sync_progress", f"{total}/{total}")
    except Exception as exc:
        set_setting("package_tracker_shopify_sync_status", "failed")
        set_setting("package_tracker_shopify_sync_error", clean_error_message(exc))
        set_setting("package_tracker_shopify_sync_last_run_at", utc_now())
    finally:
        _PACKAGE_TRACKER_SHOPIFY_SYNC_LOCK.release()


def package_tracker_shopify_status_schedule_loop() -> None:
    try:
        if not parse_iso_date(get_setting("package_tracker_shopify_sync_last_run_at", "")):
            set_setting("package_tracker_shopify_sync_status", "scheduled")
            set_setting("package_tracker_shopify_sync_progress", "Initial automatic refresh starts after the 2-minute startup warm-up")
    except Exception:
        pass
    # Let the normal startup database warmers finish before any overdue refresh.
    time.sleep(120)
    while True:
        try:
            last_run = parse_iso_date(get_setting("package_tracker_shopify_sync_last_run_at", ""))
            due = not last_run or (datetime.now(timezone.utc) - last_run).total_seconds() >= PACKAGE_TRACKER_SHOPIFY_SYNC_INTERVAL_SECONDS
            if due:
                sync_package_tracker_shopify_statuses()
        except Exception as exc:
            try:
                set_setting("package_tracker_shopify_sync_status", "failed")
                set_setting("package_tracker_shopify_sync_error", clean_error_message(exc))
            except Exception:
                pass
        time.sleep(60)


def pushed_shopify_order_targets(store_id: Optional[int] = None) -> list[dict[str, str]]:
    with db() as conn:
        params: list[Any] = [store_id, store_id]
        rows = conn.execute(
            """
            SELECT DISTINCT shopify_fulfilment_jobs.route,
                   shopify_fulfilment_jobs.odoo_order_name,
                   shopify_fulfilment_jobs.odoo_order_id,
                   stores.odoo_url AS odoo_url
            FROM shopify_fulfilment_jobs
            LEFT JOIN stores ON stores.id=shopify_fulfilment_jobs.store_id
            WHERE (? IS NULL OR shopify_fulfilment_jobs.store_id=?)
              AND COALESCE(shopify_fulfilment_jobs.odoo_order_name, '') != ''
              AND shopify_fulfilment_jobs.route IN ('dtc', 'dtb')
            ORDER BY shopify_fulfilment_jobs.route, shopify_fulfilment_jobs.odoo_order_name
            """,
            params,
        ).fetchall()
        map_rows = conn.execute(
            """
            SELECT DISTINCT state_scope AS route, src_order_key
            FROM shopify_export_order_map
            WHERE state_scope IN ('dtc', 'dtb')
            ORDER BY state_scope, src_order_key
            """
        ).fetchall()
    targets: dict[tuple[str, str], dict[str, str]] = {}
    for row in rows:
        route = clean_text(row["route"]).lower()
        order_name = clean_text(row["odoo_order_name"])
        odoo_url = clean_text(row["odoo_url"]) if "odoo_url" in row.keys() else ""
        if route and order_name:
            targets[(route, order_name)] = {
                "route": route,
                "odoo_order_name": order_name,
                "odoo_order_url": odoo_order_admin_url({"odoo_url": odoo_url}, row["odoo_order_id"]) if odoo_url else "",
            }
    for row in map_rows:
        route = clean_text(row["route"]).lower()
        src_order_key = clean_text(row["src_order_key"])
        order_name = src_order_key.split(":", 1)[1] if ":" in src_order_key else src_order_key
        if route and order_name:
            targets.setdefault((route, order_name), {"route": route, "odoo_order_name": order_name, "odoo_order_url": ""})
    return list(targets.values())


def scan_shopify_duplicate_orders(store_id: Optional[int] = None) -> None:
    if not _SHOPIFY_DUPLICATE_SCAN_RUNNING_LOCK.acquire(blocking=False):
        return
    try:
        targets = pushed_shopify_order_targets(store_id)
        set_shopify_duplicate_progress(
            status="running",
            total=len(targets),
            processed=0,
            duplicates_found=0,
            cancelled=0,
            cancel_failed=0,
            message=f"Scanning {len(targets)} pushed Shopify order reference{'s' if len(targets) != 1 else ''}.",
            started_at=utc_now(),
            completed_at="",
            error="",
        )
        with _SHOPIFY_DUPLICATE_SCAN_LOCK:
            _SHOPIFY_DUPLICATE_SCAN_RESULTS.clear()
        clients_by_route: dict[str, list[Any]] = {}
        duplicates_found = 0
        for index, target in enumerate(targets, start=1):
            route = target["route"]
            order_name = target["odoo_order_name"]
            try:
                clients = clients_by_route.setdefault(route, shopify_clients_for_route(route))
                for client in clients:
                    orders = shopify_orders_by_name(client, order_name)
                    active_orders = [order for order in orders if not order.get("cancelled_at")]
                    if len(active_orders) <= 1:
                        continue
                    fulfilled_orders = [order for order in active_orders if shopify_order_is_fulfilled(order)]
                    keep_id = (fulfilled_orders[0] if fulfilled_orders else active_orders[0]).get("id")
                    duplicate_orders = []
                    cancellable_count = 0
                    for order in active_orders:
                        is_keep = order.get("id") == keep_id
                        is_fulfilled = shopify_order_is_fulfilled(order)
                        is_cancellable_duplicate = not is_keep and not is_fulfilled
                        if is_cancellable_duplicate:
                            cancellable_count += 1
                        duplicate_orders.append({
                            **order,
                            "keep": is_keep,
                            "duplicate": is_cancellable_duplicate,
                            "protected": bool(is_fulfilled and not is_keep),
                            "cancel_status": "keep" if is_keep else "protected_fulfilled" if is_fulfilled else "pending",
                            "cancel_error": "",
                        })
                    row = {
                        "key": f"{route}:{client.name}:{order_name}",
                        "route": route,
                        "dest_name": client.name,
                        "shop": client.shop,
                        "odoo_order_name": order_name,
                        "odoo_order_url": target.get("odoo_order_url") or "",
                        "duplicate_count": cancellable_count,
                        "orders": duplicate_orders,
                    }
                    duplicates_found += int(row["duplicate_count"])
                    with _SHOPIFY_DUPLICATE_SCAN_LOCK:
                        _SHOPIFY_DUPLICATE_SCAN_RESULTS.append(row)
            except Exception as exc:
                with _SHOPIFY_DUPLICATE_SCAN_LOCK:
                    _SHOPIFY_DUPLICATE_SCAN_RESULTS.append({
                        "key": f"{route}:error:{order_name}",
                        "route": route,
                        "dest_name": "",
                        "shop": "",
                        "odoo_order_name": order_name,
                        "duplicate_count": 0,
                        "orders": [],
                        "error": str(exc)[:1000],
                    })
            set_shopify_duplicate_progress(
                processed=index,
                duplicates_found=duplicates_found,
                message=f"Scanned {index} of {len(targets)} order reference{'s' if len(targets) != 1 else ''}; found {duplicates_found} duplicate order{'s' if duplicates_found != 1 else ''}.",
            )
        set_shopify_duplicate_progress(
            status="completed",
            processed=len(targets),
            total=len(targets),
            duplicates_found=duplicates_found,
            completed_at=utc_now(),
            message=f"Duplicate scan complete. Found {duplicates_found} duplicate Shopify order{'s' if duplicates_found != 1 else ''}.",
        )
    except Exception as exc:
        set_shopify_duplicate_progress(status="failed", error=str(exc), completed_at=utc_now(), message=f"Duplicate scan failed: {exc}")
    finally:
        _SHOPIFY_DUPLICATE_SCAN_RUNNING_LOCK.release()


def cancel_scanned_shopify_duplicates() -> dict[str, Any]:
    progress = set_shopify_duplicate_progress(
        status="cancelling",
        cancelled=0,
        cancel_failed=0,
        message="Cancelling scanned duplicate Shopify orders.",
        error="",
    )
    results = shopify_duplicate_results()
    client_cache: dict[tuple[str, str], Any] = {}
    cancelled = 0
    failed = 0
    for group in results:
        route = clean_text(group.get("route")).lower()
        dest_name = clean_text(group.get("dest_name"))
        if not route or not dest_name:
            continue
        try:
            cache_key = (route, dest_name)
            if cache_key not in client_cache:
                clients = shopify_clients_for_route(route)
                client_cache[cache_key] = next(client for client in clients if client.name == dest_name)
            client = client_cache[cache_key]
        except Exception as exc:
            failed += int(group.get("duplicate_count") or 0)
            group["error"] = str(exc)[:1000]
            continue
        for order in group.get("orders") or []:
            if not order.get("duplicate") or order.get("cancel_status") == "cancelled":
                continue
            try:
                latest_order = shopify_order_by_id(client, order.get("id"))
                if latest_order:
                    order.update(latest_order)
                if shopify_order_is_fulfilled(order):
                    order["duplicate"] = False
                    order["protected"] = True
                    order["cancel_status"] = "protected_fulfilled"
                    order["cancel_error"] = ""
                    continue
                if order.get("cancelled_at"):
                    order["cancel_status"] = "cancelled"
                    order["cancel_error"] = ""
                    continue
                client.cancel_order(int(order["id"]), restock=False, refund=False, reason="other")
                order["cancel_status"] = "cancelled"
                order["cancelled_at"] = utc_now()
                order["cancel_error"] = ""
                cancelled += 1
            except Exception as exc:
                order["cancel_status"] = "failed"
                order["cancel_error"] = str(exc)[:1000]
                failed += 1
            set_shopify_duplicate_progress(cancelled=cancelled, cancel_failed=failed, message=f"Cancelled {cancelled} duplicate order{'s' if cancelled != 1 else ''}; {failed} failed.")
    with _SHOPIFY_DUPLICATE_SCAN_LOCK:
        _SHOPIFY_DUPLICATE_SCAN_RESULTS[:] = results
    return set_shopify_duplicate_progress(
        status="completed",
        cancelled=cancelled,
        cancel_failed=failed,
        completed_at=utc_now(),
        message=f"Duplicate cancellation complete. Cancelled {cancelled}; failed {failed}.",
    )


def synced_shopify_product_repair_targets(store_id: Optional[int] = None, limit: int = 500) -> list[dict[str, Any]]:
    limit = max(1, min(5000, int(limit or 500)))
    today_start = datetime.now(timezone.utc).date().isoformat() + "T00:00:00+00:00"
    tomorrow_start = (datetime.now(timezone.utc).date() + timedelta(days=1)).isoformat() + "T00:00:00+00:00"
    with db() as conn:
        rows = conn.execute(
            """
            SELECT shopify_fulfilment_jobs.route,
                   shopify_fulfilment_jobs.store_id,
                   shopify_fulfilment_jobs.odoo_order_id,
                   shopify_fulfilment_jobs.odoo_order_name,
                   shopify_fulfilment_jobs.completed_at,
                   stores.odoo_url,
                   stores.odoo_db,
                   stores.odoo_user,
                   stores.odoo_password,
                   shopify_export_order_map.dest_name AS shopify_dest_name,
                   shopify_export_order_map.dest_order_id AS shopify_order_id,
                   shopify_export_oauth_tokens.shop AS shopify_shop
            FROM shopify_fulfilment_jobs
            JOIN stores ON stores.id=shopify_fulfilment_jobs.store_id
            JOIN shopify_export_order_map
              ON shopify_export_order_map.state_scope=shopify_fulfilment_jobs.route
             AND shopify_export_order_map.src_order_key=(stores.odoo_db || ':' || shopify_fulfilment_jobs.odoo_order_name)
            LEFT JOIN shopify_export_oauth_tokens
              ON shopify_export_oauth_tokens.state_scope=shopify_fulfilment_jobs.route
             AND shopify_export_oauth_tokens.dest_name=shopify_export_order_map.dest_name
            WHERE (? IS NULL OR shopify_fulfilment_jobs.store_id=?)
              AND shopify_fulfilment_jobs.route IN ('dtc', 'dtb')
              AND COALESCE(shopify_export_order_map.dest_order_id, '') != ''
              AND COALESCE(shopify_fulfilment_jobs.completed_at, shopify_export_order_map.created_at, shopify_fulfilment_jobs.updated_at) >= ?
              AND COALESCE(shopify_fulfilment_jobs.completed_at, shopify_export_order_map.created_at, shopify_fulfilment_jobs.updated_at) < ?
            ORDER BY COALESCE(shopify_fulfilment_jobs.completed_at, shopify_fulfilment_jobs.updated_at) DESC
            LIMIT ?
            """,
            (store_id, store_id, today_start, tomorrow_start, limit),
        ).fetchall()
    return rows_to_dicts(rows)


def shopify_should_check_existing_order(job: dict[str, Any]) -> bool:
    # Shopify order creation must always be preceded by a remote lookup.  The old
    # fast-export rule skipped this for recent third-party orders, allowing an
    # existing order to be created again when its local export map was missing.
    return True


def shopify_order_line_variants(module: Any, shop: Any, order_id: Any) -> list[dict[str, Any]]:
    order_id_text = clean_text(order_id)
    if not order_id_text:
        return []
    query = """
    query($id: ID!) {
      node(id: $id) {
        ... on Order {
          lineItems(first: 250) {
            nodes {
              title
              sku
              variant {
                id
                legacyResourceId
                sku
                product {
                  id
                  legacyResourceId
                  title
                }
              }
            }
          }
        }
      }
    }
    """
    data = shop.graphql(query, {"id": f"gid://shopify/Order/{order_id_text}"})
    nodes = (((data.get("node") or {}).get("lineItems") or {}).get("nodes") or [])
    variants: list[dict[str, Any]] = []
    for node in nodes:
        variant = node.get("variant") or {}
        product = variant.get("product") or {}
        variant_id = clean_text(variant.get("legacyResourceId"))
        product_id = clean_text(product.get("legacyResourceId"))
        if not variant_id and variant.get("id"):
            try:
                variant_id = str(module.gid_to_int(variant["id"]))
            except Exception:
                variant_id = ""
        if not product_id and product.get("id"):
            try:
                product_id = str(module.gid_to_int(product["id"]))
            except Exception:
                product_id = ""
        if not variant_id:
            continue
        variants.append({
            "variant_id": int(variant_id),
            "product_id": int(product_id) if product_id else None,
            "old_sku": clean_text(variant.get("sku") or node.get("sku")),
            "old_product_title": clean_text(product.get("title") or node.get("title")),
            "line_title": clean_text(node.get("title")),
        })
    return variants


def shopify_variant_product_snapshot(module: Any, shop: Any, variant_id: int | None) -> dict[str, Any]:
    if not variant_id:
        return {}
    query = """
    query($id: ID!) {
      productVariant(id: $id) {
        legacyResourceId
        sku
        product {
          legacyResourceId
          title
        }
      }
    }
    """
    data = shop.graphql(query, {"id": f"gid://shopify/ProductVariant/{int(variant_id)}"})
    variant = data.get("productVariant") or {}
    product = variant.get("product") or {}
    return {
        "verified_variant_sku": clean_text(variant.get("sku")),
        "verified_product_title": clean_text(product.get("title")),
        "verified_variant_id": clean_text(variant.get("legacyResourceId")),
        "verified_product_id": clean_text(product.get("legacyResourceId")),
    }


def repair_shopify_synced_line_product(
    module: Any,
    odoo: Any,
    shop: Any,
    state: Any,
    rename_manager: Any,
    *,
    line: dict[str, Any],
    order_name: str,
    shopify_order_id: Any,
    order_variants: list[dict[str, Any]],
) -> dict[str, Any]:
    base_log = {
        "odoo_order_name": order_name,
        "shopify_order_id": clean_text(shopify_order_id),
        "shopify_order_url": shopify_admin_order_url(shop.shop, shopify_order_id),
        "dest_name": shop.name,
        "shop": shop.shop,
        "order_line_title": "",
        "order_line_sku": "",
        "old_product_title": "",
        "old_sku": "",
        "new_product_title": "",
        "new_sku": "",
        "verified_product_title": "",
        "verified_variant_sku": "",
        "status": "skipped",
        "error": "",
    }
    if line.get("display_type"):
        return base_log
    qty_int = module.qty_to_int_or_none(float(line.get("product_uom_qty") or 0.0))
    if qty_int is None:
        return base_log
    prod = line.get("product_id")
    if not prod or not isinstance(prod, (list, tuple)) or len(prod) < 1:
        return base_log
    pp = odoo.get_product_product(int(prod[0]))
    if not pp:
        return {**base_log, "status": "missing", "error": "Odoo product was not found."}
    sku_raw = clean_text(pp.get("default_code"))
    sku = module.maybe_decode_asin_sku(sku_raw)
    if module._should_ignore_odoo_line_item(sku or sku_raw or None, line.get("name")):
        return base_log
    tmpl = None
    tmpl_ref = pp.get("product_tmpl_id")
    if isinstance(tmpl_ref, (list, tuple)) and tmpl_ref:
        tmpl = odoo.get_product_template(int(tmpl_ref[0]))
    source_title_for_sku = clean_text(
        pp.get("name")
        or ((tmpl or {}).get("name") if tmpl else "")
        or line.get("name")
        or sku
        or sku_raw
        or "Item"
    )
    title = source_title_for_sku
    if getattr(module, "STRIP_WORDS", None):
        title = module.strip_words(title, module.STRIP_WORDS)
    title = rename_manager.resolve_title(order_name=order_name, sku=sku or sku_raw, original_title=title)
    source_sku = clean_text(sku or sku_raw) or None
    destination_sku = rename_manager.destination_sku(source_sku=source_sku, source_title=source_title_for_sku)
    if not destination_sku:
        return base_log
    candidates: list[str] = []
    for candidate in (destination_sku, source_sku, sku_raw):
        candidate = clean_text(candidate)
        if candidate and candidate not in candidates:
            candidates.append(candidate)
    matched_variant = None
    for variant in order_variants:
        if clean_text(variant.get("old_sku")) in candidates:
            matched_variant = variant
            break
    if not matched_variant:
        return {
            **base_log,
            "new_product_title": title,
            "new_sku": destination_sku,
            "status": "missing",
            "error": "No matching variant was found on the linked Shopify order.",
        }
    variant_id = int(matched_variant["variant_id"])
    product_id = int(matched_variant["product_id"]) if matched_variant.get("product_id") else None
    old_sku = clean_text(matched_variant.get("old_sku"))
    old_product_title = clean_text(matched_variant.get("old_product_title"))
    order_line_title = clean_text(matched_variant.get("line_title"))
    if product_id:
        shop.update_product(product_id, title=title)
    if old_sku != destination_sku:
        shop.update_variant(variant_id, sku=destination_sku)
    verified = shopify_variant_product_snapshot(module, shop, variant_id)
    state.set_variant_for_sku(shop.name, destination_sku, variant_id, product_id)
    if source_sku and source_sku != destination_sku:
        state.set_variant_for_sku(shop.name, source_sku, variant_id, product_id)
    if sku_raw and sku_raw not in {source_sku, destination_sku}:
        state.set_variant_for_sku(shop.name, sku_raw, variant_id, product_id)
    return {
        **base_log,
        "order_line_title": order_line_title,
        "order_line_sku": old_sku,
        "old_product_title": old_product_title,
        "old_sku": old_sku,
        "new_product_title": title,
        "new_sku": destination_sku,
        "verified_product_title": verified.get("verified_product_title") or "",
        "verified_variant_sku": verified.get("verified_variant_sku") or "",
        "status": "repaired",
    }


def repair_shopify_synced_products(store_id: Optional[int] = None, limit: int = 500) -> None:
    if not _SHOPIFY_PRODUCT_REPAIR_RUNNING_LOCK.acquire(blocking=False):
        return
    try:
        _SHOPIFY_PRODUCT_REPAIR_CANCEL_EVENT.clear()
        targets = synced_shopify_product_repair_targets(store_id, limit)
        with _SHOPIFY_PRODUCT_REPAIR_LOCK:
            _SHOPIFY_PRODUCT_REPAIR_LOGS.clear()
        set_shopify_product_repair_progress(
            status="running",
            total=len(targets),
            processed=0,
            repaired=0,
            missing=0,
            failed=0,
            current_order="",
            cancel_requested=False,
            message=f"Repairing products for {len(targets)} already-linked Shopify order{'s' if len(targets) != 1 else ''} synced today.",
            started_at=utc_now(),
            completed_at="",
            error="",
        )
        settings = get_service_settings()
        module_cache: dict[str, Any] = {}
        client_cache: dict[str, list[Any]] = {}
        odoo_cache: dict[int, Any] = {}
        repaired = 0
        missing = 0
        failed = 0
        for index, target in enumerate(targets, start=1):
            if _SHOPIFY_PRODUCT_REPAIR_CANCEL_EVENT.is_set():
                set_shopify_product_repair_progress(
                    status="cancelled",
                    processed=index - 1,
                    repaired=repaired,
                    missing=missing,
                    failed=failed,
                    current_order="",
                    cancel_requested=False,
                    completed_at=utc_now(),
                    message=f"Product repair cancelled. Repaired {repaired}; missing {missing}; failed {failed}.",
                )
                return
            route = clean_text(target.get("route")).lower()
            order_name = clean_text(target.get("odoo_order_name"))
            dest_name = clean_text(target.get("shopify_dest_name"))
            shopify_order_id = clean_text(target.get("shopify_order_id"))
            set_shopify_product_repair_progress(
                processed=index - 1,
                current_order=order_name,
                cancel_requested=False,
                message=f"Repairing product names/SKUs for {order_name} linked to Shopify order #{shopify_order_id}.",
            )
            try:
                if route not in module_cache:
                    module, _script_path, state_scope = shopify_route_script_config(route)
                    module_cache[route] = (module, state_scope, shopify_product_rename_manager(module, settings))
                module, state_scope, rename_manager = module_cache[route]
                store_id_value = int(target["store_id"])
                if store_id_value not in odoo_cache:
                    odoo = module.OdooClient(target["odoo_url"], target["odoo_db"], target["odoo_user"], target["odoo_password"])
                    odoo.connect()
                    odoo_cache[store_id_value] = odoo
                odoo = odoo_cache[store_id_value]
                order = odoo.get_order_by_number(order_name)
                if not order:
                    missing += 1
                    append_shopify_product_repair_log({
                        "odoo_order_name": order_name,
                        "shopify_order_id": shopify_order_id,
                        "shopify_order_url": shopify_admin_order_url(clean_text(target.get("shopify_shop")), shopify_order_id),
                        "dest_name": dest_name,
                        "shop": clean_text(target.get("shopify_shop")),
                        "old_product_title": "",
                        "old_sku": "",
                        "new_product_title": "",
                        "new_sku": "",
                        "status": "missing",
                        "error": "Odoo order was not found.",
                    })
                    continue
                lines = odoo.get_order_lines(order.get("order_line") or [])
                if route not in client_cache:
                    client_cache[route] = shopify_clients_for_route(route)
                shops = [shop for shop in client_cache[route] if not dest_name or shop.name == dest_name]
                state = module.StateDB(state_scope)
                for shop in shops:
                    order_variants = shopify_order_line_variants(module, shop, shopify_order_id)
                    if not order_variants:
                        missing += 1
                        append_shopify_product_repair_log({
                            "odoo_order_name": order_name,
                            "shopify_order_id": shopify_order_id,
                            "shopify_order_url": shopify_admin_order_url(shop.shop, shopify_order_id),
                            "dest_name": shop.name,
                            "shop": shop.shop,
                            "old_product_title": "",
                            "old_sku": "",
                            "new_product_title": "",
                            "new_sku": "",
                            "status": "missing",
                            "error": "No product variants were found on the linked Shopify order.",
                        })
                        continue
                    for line in lines:
                        if _SHOPIFY_PRODUCT_REPAIR_CANCEL_EVENT.is_set():
                            set_shopify_product_repair_progress(
                                status="cancelled",
                                processed=index - 1,
                                repaired=repaired,
                                missing=missing,
                                failed=failed,
                                current_order="",
                                cancel_requested=False,
                                completed_at=utc_now(),
                                message=f"Product repair cancelled. Repaired {repaired}; missing {missing}; failed {failed}.",
                            )
                            return
                        try:
                            result = repair_shopify_synced_line_product(
                                module,
                                odoo,
                                shop,
                                state,
                                rename_manager,
                                line=line,
                                order_name=order_name,
                                shopify_order_id=shopify_order_id,
                                order_variants=order_variants,
                            )
                            if result.get("status") != "skipped":
                                append_shopify_product_repair_log(result)
                            if result.get("status") == "repaired":
                                repaired += 1
                            elif result.get("status") == "missing":
                                missing += 1
                        except Exception as exc:
                            failed += 1
                            append_shopify_product_repair_log({
                                "odoo_order_name": order_name,
                                "shopify_order_id": shopify_order_id,
                                "shopify_order_url": shopify_admin_order_url(shop.shop, shopify_order_id),
                                "dest_name": shop.name,
                                "shop": shop.shop,
                                "old_product_title": "",
                                "old_sku": "",
                                "new_product_title": "",
                                "new_sku": "",
                                "status": "failed",
                                "error": str(exc)[:1000],
                            })
                set_shopify_product_repair_progress(
                    processed=index,
                    repaired=repaired,
                    missing=missing,
                    failed=failed,
                    message=f"Repaired {repaired} product/variant record{'s' if repaired != 1 else ''}; {missing} missing; {failed} failed.",
                )
            except Exception as exc:
                failed += 1
                set_shopify_product_repair_progress(failed=failed, error=str(exc)[:1000])
        set_shopify_product_repair_progress(
            status="completed",
            processed=len(targets),
            total=len(targets),
            repaired=repaired,
            missing=missing,
            failed=failed,
            current_order="",
            cancel_requested=False,
            completed_at=utc_now(),
            message=f"Product repair complete. Repaired {repaired}; missing {missing}; failed {failed}.",
        )
    except Exception as exc:
        set_shopify_product_repair_progress(status="failed", error=str(exc), completed_at=utc_now(), message=f"Product repair failed: {exc}")
    finally:
        _SHOPIFY_PRODUCT_REPAIR_RUNNING_LOCK.release()


def run_shopify_script_export(job: dict[str, Any]) -> None:
    settings = get_service_settings()
    store = get_store(int(job["store_id"]))
    route = clean_text(job["route"]).lower()
    script_path = settings["shopify_dtb_script_path"] if route == "dtb" else settings["shopify_dtc_script_path"]
    module = load_external_script(script_path, f"shopify_export_{route}_{uuid.uuid4().hex}")
    apply_shopify_runtime_settings(module, route, settings)
    request_rate, request_burst = shopify_api_rate_config(settings)
    original_shopify_client = module.ShopifyClient

    class RateLimitedShopifyClient(original_shopify_client):  # type: ignore[misc, valid-type]
        def _request(
            self,
            method: str,
            url: str,
            json_body: Optional[dict[str, Any]] = None,
            **request_options: Any,
        ) -> dict[str, Any]:
            shopify_wait_for_api_slot(getattr(self, "shop", "") or getattr(self, "name", "") or route, request_rate, request_burst)
            return super()._request(method, url, json_body, **request_options)

    module.ShopifyClient = RateLimitedShopifyClient
    module.ODOO_URL = store.odoo_url
    module.ODOO_DB = store.odoo_db
    module.ODOO_USERNAME = store.odoo_user
    module.ODOO_PASSWORD = store.odoo_password
    module.StateDB = lambda _path="", *_args, **_kwargs: PostgresShopifyExportStateDB(route)
    module.STATE_DB = f"postgres:{route}"
    module._NON_INTERACTIVE_AUTH_URL = ""
    original_authorize_url = module.shopify_authorize_url
    def capture_authorize_url(shop: str, client_id: str, scopes: str, redirect_uri: str, state: str) -> str:
        url = original_authorize_url(shop, client_id, scopes, redirect_uri, state)
        module._NON_INTERACTIVE_AUTH_URL = url
        return url
    def fail_interactive_oauth(redirect_uri: str, timeout_s: int = 600) -> dict[str, Any]:
        auth_url = getattr(module, "_NON_INTERACTIVE_AUTH_URL", "")
        suffix = f" Authorization URL: {auth_url}" if auth_url else ""
        raise RuntimeError(
            "Shopify OAuth token is missing or expired. Open the matching export script once manually to authorize the Shopify store, "
            "then retry this queued job. The backend will not wait for an interactive OAuth callback."
            f"{suffix}"
        )
    module.shopify_authorize_url = capture_authorize_url
    module.run_local_oauth_server = fail_interactive_oauth
    rename_manager = shopify_product_rename_manager(module, settings)
    state = module.StateDB(route)
    odoo = module.OdooClient(store.odoo_url, store.odoo_db, store.odoo_user, store.odoo_password)
    odoo.connect()
    shops = []
    for dest in module.DESTS:
        token = module.get_shopify_access_token(dest, state)
        shops.append(module.ShopifyClient(dest["name"], dest["shop"], token, dest.get("api_version") or "2025-10"))
    if not shops:
        raise RuntimeError(f"No Shopify destination configured in {script_path}")
    for shop in shops:
        src_order_key = f"{store.odoo_db}:{job['odoo_order_name']}"
        if shopify_should_check_existing_order(job):
            existing_orders = shopify_orders_by_name(shop, str(job["odoo_order_name"]), limit=10)
            active_existing = [order for order in existing_orders if not order.get("cancelled_at")]
            if active_existing:
                fulfilled = [order for order in active_existing if shopify_order_is_fulfilled(order)]
                keep = fulfilled[0] if fulfilled else active_existing[0]
                state.mark_order_synced(shop.name, src_order_key, clean_text(keep.get("id")) or None)
                upsert_shopify_order_status(int(job["store_id"]), route, shop.name, shop.shop, str(job["odoo_order_name"]), keep)
                inventory_note = inventory_fulfilment_note_for_order(int(job["store_id"]), str(job["odoo_order_name"]))
                if inventory_note:
                    append_shopify_inventory_note(shop, keep, inventory_note)
                return
        module.sync_one_order_to_dest(odoo, shop, state, str(job["odoo_order_name"]), rename_manager)
        synced_orders = [order for order in shopify_orders_by_name(shop, str(job["odoo_order_name"]), limit=5) if not order.get("cancelled_at")]
        if synced_orders:
            synced_order = synced_orders[-1]
            upsert_shopify_order_status(int(job["store_id"]), route, shop.name, shop.shop, str(job["odoo_order_name"]), synced_order)
            inventory_note = inventory_fulfilment_note_for_order(int(job["store_id"]), str(job["odoo_order_name"]))
            if inventory_note:
                append_shopify_inventory_note(shop, synced_order, inventory_note)


def process_one_shopify_fulfilment_job(worker_name: str = "") -> bool:
    job = claim_shopify_fulfilment_job()
    if not job:
        return False
    progress = shopify_fulfilment_progress()
    if str(progress.get("status") or "") not in {"running", "queued"}:
        set_shopify_fulfilment_progress(
            status="running",
            total=max(1, due_shopify_fulfilment_job_count() + 1),
            processed=0,
            started_at=utc_now(),
            completed_at="",
            error="",
        )
    route = str(job["route"] or "").upper()
    worker_label = f" {worker_name}" if worker_name else ""
    set_shopify_fulfilment_progress(
        status="running",
        current_order=str(job["odoo_order_name"] or ""),
        current_route=route,
        message=f"Syncing {job['odoo_order_name']} to Shopify {route}{worker_label}.",
    )
    try:
        run_shopify_script_export(job)
        try:
            sync_shopify_status_for_order_names(
                int(job["store_id"]),
                [str(job["odoo_order_name"] or "")],
                force=True,
            )
        except Exception as status_exc:
            print(f"Shopify fulfilment status refresh failed for {job['odoo_order_name']}: {status_exc}")
        with db() as conn:
            conn.execute(
                "UPDATE shopify_fulfilment_jobs SET status='completed', last_error='', completed_at=?, updated_at=? WHERE id=?",
                (utc_now(), utc_now(), job["id"]),
            )
        increment_shopify_fulfilment_progress(
            message=f"Synced {job['odoo_order_name']} to Shopify.",
            error="",
        )
    except Exception as exc:
        retry_delay = min(3600, 60 * max(1, int(job["attempts"] or 1)))
        next_run = (datetime.now(timezone.utc) + timedelta(seconds=retry_delay)).isoformat()
        next_status = "failed" if int(job["attempts"] or 0) < int(job["max_attempts"] or 5) else "dead"
        error_text = str(exc)[:2000]
        with db() as conn:
            conn.execute(
                """
                UPDATE shopify_fulfilment_jobs
                SET status=?, last_error=?, next_run_at=?, updated_at=?
                WHERE id=?
                """,
                (next_status, error_text, next_run, utc_now(), job["id"]),
            )
        if not error_text.startswith("Shopify OAuth token"):
            send_email_alert_async(
                f"Shopify fulfilment {next_status}: {job['odoo_order_name']}",
                f"Order: {job['odoo_order_name']}\nRoute: {job['route']}\nStatus: {next_status}\nError: {error_text}",
            )
        increment_shopify_fulfilment_progress(
            message=f"Shopify sync stopped on {job['odoo_order_name']}: {error_text}",
            error=error_text,
        )
    return True


def shopify_fulfilment_worker() -> None:
    try:
        settings = get_service_settings()
        concurrency = shopify_fulfilment_concurrency(settings)
        progress = shopify_fulfilment_progress()
        if str(progress.get("status") or "") != "running":
            total = due_shopify_fulfilment_job_count()
            set_shopify_fulfilment_progress(
                status="running" if total else "idle",
                total=total,
                processed=0,
                current_order="",
                current_route="",
                message=f"Shopify fulfilment worker started with {total} job{'s' if total != 1 else ''} using {concurrency} concurrent push{'es' if concurrency != 1 else ''}.",
                started_at=utc_now() if total else "",
                completed_at="",
                error="",
            )
        no_more_jobs = False
        future_index = 0
        with ThreadPoolExecutor(max_workers=concurrency, thread_name_prefix="shopify-fulfil") as executor:
            futures: set[Any] = set()
            while futures or not no_more_jobs:
                while not no_more_jobs and len(futures) < concurrency:
                    future_index += 1
                    futures.add(executor.submit(process_one_shopify_fulfilment_job, f"worker {future_index}"))
                if not futures:
                    break
                done, futures = wait(futures, return_when=FIRST_COMPLETED)
                for future in done:
                    try:
                        processed_job = bool(future.result())
                    except Exception as exc:
                        processed_job = True
                        set_shopify_fulfilment_progress(error=str(exc), message=f"Shopify worker error: {exc}")
                    if not processed_job:
                        no_more_jobs = True
        progress = shopify_fulfilment_progress()
        if str(progress.get("status") or "") == "running":
            processed = int(progress.get("processed") or 0)
            total = max(int(progress.get("total") or 0), processed)
            set_shopify_fulfilment_progress(
                status="completed" if total else "idle",
                total=total,
                processed=processed,
                current_order="",
                current_route="",
                completed_at=utc_now(),
                message=(
                    f"Shopify fulfilment worker finished {processed} of {total} job{'s' if total != 1 else ''}."
                    if total else "No Shopify fulfilment jobs were ready."
                ),
            )
    finally:
        _SHOPIFY_WORKER_RUNNING_LOCK.release()


def start_shopify_fulfilment_worker() -> dict[str, Any]:
    recovered = recover_stale_shopify_not_found_jobs()
    total = due_shopify_fulfilment_job_count()
    settings = get_service_settings()
    concurrency = shopify_fulfilment_concurrency(settings)
    lock_acquired = False
    if total:
        lock_acquired = _SHOPIFY_WORKER_RUNNING_LOCK.acquire(blocking=False)
        if not lock_acquired:
            return set_shopify_fulfilment_progress(message="Shopify fulfilment worker is already running.")
    set_shopify_fulfilment_progress(
        status="running" if total else "idle",
        total=total,
        processed=0,
        current_order="",
        current_route="",
        message=f"Shopify fulfilment worker started with {total} job{'s' if total != 1 else ''} using {concurrency} concurrent push{'es' if concurrency != 1 else ''}." + (f" Recovered {recovered} stale Shopify 404 job{'s' if recovered != 1 else ''}." if recovered else ""),
        started_at=utc_now() if total else "",
        completed_at="",
        error="",
    )
    if lock_acquired:
        threading.Thread(target=shopify_fulfilment_worker, daemon=True).start()
    return shopify_fulfilment_progress()


def shopify_fulfilment_job_status_counts() -> dict[str, int]:
    with db() as conn:
        rows = conn.execute(
            """
            SELECT status, COUNT(*) AS count
            FROM shopify_fulfilment_jobs
            GROUP BY status
            """
        ).fetchall()
        attention = conn.execute(
            """
            SELECT COUNT(*) AS count
            FROM shopify_fulfilment_jobs
            LEFT JOIN stores ON stores.id=shopify_fulfilment_jobs.store_id
            LEFT JOIN shopify_export_order_map
              ON shopify_export_order_map.state_scope=shopify_fulfilment_jobs.route
             AND shopify_export_order_map.src_order_key=(stores.odoo_db || ':' || shopify_fulfilment_jobs.odoo_order_name)
            LEFT JOIN shopify_order_status_cache
              ON shopify_order_status_cache.store_id=shopify_fulfilment_jobs.store_id
             AND shopify_order_status_cache.route=shopify_fulfilment_jobs.route
             AND UPPER(shopify_order_status_cache.odoo_order_name)=UPPER(shopify_fulfilment_jobs.odoo_order_name)
             AND shopify_order_status_cache.dest_name=shopify_export_order_map.dest_name
            WHERE shopify_fulfilment_jobs.status IN ('amazon_placed', 'queued', 'failed', 'dead')
               OR (
                    shopify_fulfilment_jobs.status='completed'
                AND COALESCE(shopify_export_order_map.dest_order_id, '')=''
               )
               OR (
                    shopify_fulfilment_jobs.status='completed'
                AND COALESCE(shopify_export_order_map.dest_order_id, '')!=''
                AND COALESCE(shopify_order_status_cache.synced_at, '')=''
               )
            """
        ).fetchone()
    counts = {clean_text(row["status"]) or "unknown": int(row["count"] or 0) for row in rows}
    counts["attention"] = int(attention["count"] or 0) if attention else 0
    return counts


def shopify_fulfilment_attention_where() -> str:
    return """
    (
        shopify_fulfilment_jobs.status IN ('amazon_placed', 'queued', 'failed', 'dead')
        OR (
             shopify_fulfilment_jobs.status='completed'
         AND COALESCE(shopify_export_order_map.dest_order_id, '')=''
        )
        OR (
             shopify_fulfilment_jobs.status='completed'
         AND COALESCE(shopify_export_order_map.dest_order_id, '')!=''
         AND COALESCE(shopify_order_status_cache.synced_at, '')=''
        )
    )
    """


def shopify_fulfilment_attention_reason(row: dict[str, Any]) -> str:
    status = clean_text(row.get("status"))
    shopify_order_id = clean_text(row.get("shopify_order_id"))
    shopify_status_synced_at = clean_text(row.get("shopify_status_synced_at"))
    if status in {"failed", "dead"}:
        return clean_text(row.get("last_error")) or "Shopify push failed. Retry or inspect the job."
    if status in {"amazon_placed", "queued"}:
        if shopify_order_id:
            return "Shopify order exists, but the fulfilment job status is still pending. Refresh status to verify and settle it."
        return "Amazon order is placed, but the Shopify push has not completed yet."
    if status == "completed" and not shopify_order_id:
        return "Job completed but no Shopify order link was recorded."
    if status == "completed" and shopify_order_id and not shopify_status_synced_at:
        return "Shopify order was linked, but fulfilment/status cache was not refreshed."
    return ""


def list_shopify_fulfilment_jobs(page: int = 1, per_page: int = 100, status: str = "all", store_id: Optional[int] = None) -> tuple[list[dict[str, Any]], int, int, int]:
    page, per_page, offset = pagination_bounds(page, per_page)
    status_filter = clean_text(status).lower() or "all"
    params: list[Any] = []
    where_parts: list[str] = []
    if store_id:
        where_parts.append("shopify_fulfilment_jobs.store_id=?")
        params.append(int(store_id))
    if status_filter == "attention":
        where_parts.append(shopify_fulfilment_attention_where())
    elif status_filter != "all":
        where_parts.append("shopify_fulfilment_jobs.status=?")
        params.append(status_filter)
    where_sql = f"WHERE {' AND '.join(where_parts)}" if where_parts else ""
    with db() as conn:
        total = int(conn.execute(
            f"""
            SELECT COUNT(*) AS count
            FROM shopify_fulfilment_jobs
            LEFT JOIN stores ON stores.id=shopify_fulfilment_jobs.store_id
            LEFT JOIN shopify_export_order_map
              ON shopify_export_order_map.state_scope=shopify_fulfilment_jobs.route
             AND shopify_export_order_map.src_order_key=(stores.odoo_db || ':' || shopify_fulfilment_jobs.odoo_order_name)
            LEFT JOIN shopify_order_status_cache
              ON shopify_order_status_cache.store_id=shopify_fulfilment_jobs.store_id
             AND shopify_order_status_cache.route=shopify_fulfilment_jobs.route
             AND UPPER(shopify_order_status_cache.odoo_order_name)=UPPER(shopify_fulfilment_jobs.odoo_order_name)
             AND shopify_order_status_cache.dest_name=shopify_export_order_map.dest_name
            {where_sql}
            """,
            params,
        ).fetchone()["count"] or 0)
        rows = conn.execute(
            f"""
            SELECT shopify_fulfilment_jobs.*,
                   stores.name AS store_name,
                   stores.odoo_url AS odoo_url,
                   shopify_export_order_map.dest_name AS shopify_dest_name,
                   shopify_export_order_map.dest_order_id AS shopify_order_id,
                   shopify_export_oauth_tokens.shop AS shopify_shop,
                   shopify_order_status_cache.shopify_order_name AS cached_shopify_order_name,
                   shopify_order_status_cache.fulfillment_status AS shopify_fulfillment_status,
                   shopify_order_status_cache.financial_status AS shopify_financial_status,
                   shopify_order_status_cache.cancelled_at AS shopify_cancelled_at,
                   shopify_order_status_cache.synced_at AS shopify_status_synced_at
            FROM shopify_fulfilment_jobs
            LEFT JOIN stores ON stores.id=shopify_fulfilment_jobs.store_id
            LEFT JOIN shopify_export_order_map
              ON shopify_export_order_map.state_scope=shopify_fulfilment_jobs.route
             AND shopify_export_order_map.src_order_key=(stores.odoo_db || ':' || shopify_fulfilment_jobs.odoo_order_name)
            LEFT JOIN shopify_export_oauth_tokens
              ON shopify_export_oauth_tokens.state_scope=shopify_fulfilment_jobs.route
             AND shopify_export_oauth_tokens.dest_name=shopify_export_order_map.dest_name
            LEFT JOIN shopify_order_status_cache
              ON shopify_order_status_cache.store_id=shopify_fulfilment_jobs.store_id
             AND shopify_order_status_cache.route=shopify_fulfilment_jobs.route
             AND UPPER(shopify_order_status_cache.odoo_order_name)=UPPER(shopify_fulfilment_jobs.odoo_order_name)
             AND shopify_order_status_cache.dest_name=shopify_export_order_map.dest_name
            {where_sql}
            ORDER BY created_at DESC
            LIMIT ? OFFSET ?
            """,
            [*params, per_page, offset],
        ).fetchall()
    result = rows_to_dicts(rows)
    for row in result:
        row["odoo_order_url"] = odoo_order_admin_url({"odoo_url": row.get("odoo_url") or ""}, row.get("odoo_order_id")) if row.get("odoo_url") else ""
        shopify_order_id = clean_text(row.get("shopify_order_id"))
        shop = clean_text(row.get("shopify_shop"))
        if shopify_order_id and shop:
            row["shopify_order_url"] = f"https://admin.shopify.com/store/{shop.split('.')[0]}/orders/{shopify_order_id}"
        elif shopify_order_id:
            row["shopify_order_url"] = ""
        else:
            row["shopify_order_url"] = ""
        attention_reason = shopify_fulfilment_attention_reason(row)
        row["needs_attention"] = bool(attention_reason)
        row["attention_reason"] = attention_reason
    linked_unsynced = [
        row for row in result
        if clean_text(row.get("shopify_order_id"))
        and not clean_text(row.get("shopify_status_synced_at"))
    ]
    if linked_unsynced:
        refresh_missing_shopify_status_for_rows(linked_unsynced)
    return result, total, page, per_page


def clear_completed_shopify_fulfilment_jobs() -> int:
    with db() as conn:
        cursor = conn.execute(
            """
            DELETE FROM shopify_fulfilment_jobs
            WHERE status='completed'
            """
        )
        return int(cursor.rowcount or 0)


def list_shopify_tracking_jobs(page: int = 1, per_page: int = 100) -> tuple[list[dict[str, Any]], int, int, int]:
    reconcile_stale_shopify_tracking_jobs()
    page, per_page, offset = pagination_bounds(page, per_page)
    with db() as conn:
        total = int(conn.execute("SELECT COUNT(*) AS count FROM shopify_tracking_jobs").fetchone()["count"] or 0)
        rows = conn.execute(
            """
            SELECT *
            FROM shopify_tracking_jobs
            ORDER BY created_at DESC
            LIMIT ? OFFSET ?
            """,
            (per_page, offset),
        ).fetchall()
    result = rows_to_dicts(rows)
    for row in result:
        try:
            row["progress"] = json.loads(row.get("progress_json") or "{}")
        except Exception:
            row["progress"] = {}
        try:
            row["counters"] = json.loads(row.get("counters_json") or "{}")
        except Exception:
            row["counters"] = {}
        row["report_url"] = f"/api/shopify/tracking/jobs/{row['id']}/download" if row.get("report_csv") else ""
    return result, total, page, per_page


def set_shopify_tracking_job_progress(job_id: str, progress: dict[str, Any]) -> None:
    safe_progress = {
        "status": clean_text(progress.get("status")) or "running",
        "total": int(progress.get("total") or 0),
        "processed": int(progress.get("processed") or 0),
        "current_order": clean_text(progress.get("current_order")),
        "source": clean_text(progress.get("source")),
        "message": clean_text(progress.get("message")),
        "updated_at": utc_now(),
        "counters": progress.get("counters") if isinstance(progress.get("counters"), dict) else {},
    }
    with db() as conn:
        conn.execute(
            "UPDATE shopify_tracking_jobs SET progress_json=?, updated_at=? WHERE id=? AND status IN ('queued', 'running', 'cancel_requested')",
            (json.dumps(safe_progress), safe_progress["updated_at"], job_id),
        )


SHOPIFY_TRACKING_ACTIVE_JOBS: set[str] = set()
SHOPIFY_TRACKING_ACTIVE_LOCK = threading.Lock()
SHOPIFY_TRACKING_HEARTBEAT_SECONDS = 30


def shopify_tracking_job_cancel_requested(job_id: str) -> bool:
    with db() as conn:
        row = conn.execute("SELECT status FROM shopify_tracking_jobs WHERE id=?", (job_id,)).fetchone()
    return bool(row and row["status"] in {"cancel_requested", "cancelled"})


def mark_shopify_tracking_job_cancelled(job_id: str, message: str = "Tracking sync cancelled by user.") -> None:
    now = utc_now()
    progress = {
        "status": "cancelled",
        "total": 0,
        "processed": 0,
        "current_order": "",
        "source": "",
        "message": message,
        "updated_at": now,
        "counters": {},
    }
    with db() as conn:
        existing = conn.execute("SELECT progress_json FROM shopify_tracking_jobs WHERE id=?", (job_id,)).fetchone()
        if existing:
            try:
                progress.update(json.loads(existing["progress_json"] or "{}"))
            except Exception:
                pass
        progress["status"] = "cancelled"
        progress["current_order"] = ""
        progress["message"] = message
        progress["updated_at"] = now
        conn.execute(
            "UPDATE shopify_tracking_jobs SET status='cancelled', progress_json=?, last_error=?, completed_at=?, updated_at=? WHERE id=?",
            (json.dumps(progress), message, now, now, job_id),
        )


def start_shopify_tracking_job_heartbeat(job_id: str, stop_event: threading.Event) -> threading.Thread:
    def heartbeat() -> None:
        while not stop_event.wait(SHOPIFY_TRACKING_HEARTBEAT_SECONDS):
            try:
                now = utc_now()
                with db() as conn:
                    row = conn.execute("SELECT status FROM shopify_tracking_jobs WHERE id=?", (job_id,)).fetchone()
                    if not row or row["status"] not in {"queued", "running", "cancel_requested"}:
                        return
                    conn.execute("UPDATE shopify_tracking_jobs SET updated_at=? WHERE id=?", (now, job_id))
            except Exception:
                continue

    thread = threading.Thread(target=heartbeat, daemon=True)
    thread.start()
    return thread


def request_shopify_tracking_job_cancel(job_id: str, message: str = "Tracking sync cancelled by user.") -> None:
    # Mark the job terminal immediately so the UI leaves the "Killing" state.
    # Active worker threads observe this status through CANCEL_CALLBACK and stop
    # at their next network-safe checkpoint.
    mark_shopify_tracking_job_cancelled(job_id, message)


def request_shopify_tracking_job_cancel_fast(job_id: str, message: str = "Tracking sync cancelled by user.") -> str:
    """Cancel through a short-lived Postgres connection so kill is not blocked by the app DB pool."""
    now = utc_now()
    progress = {
        "status": "cancelled",
        "total": 0,
        "processed": 0,
        "current_order": "",
        "source": "",
        "message": message,
        "updated_at": now,
        "counters": {},
    }
    postgres_url = db_session.POSTGRES_URL
    if not postgres_url:
        mark_shopify_tracking_job_cancelled(job_id, message)
        return "cancelled"
    raw = None
    try:
        raw = db_session.psycopg2.connect(postgres_url, connect_timeout=3, options="-c statement_timeout=5000")
        raw.autocommit = False
        with raw.cursor() as cursor:
            cursor.execute("SELECT status, progress_json FROM shopify_tracking_jobs WHERE id=%s", (job_id,))
            row = cursor.fetchone()
            if not row:
                raise KeyError(job_id)
            status, progress_json = row
            if status not in {"queued", "running", "cancel_requested"}:
                raw.rollback()
                return str(status)
            try:
                existing = json.loads(progress_json or "{}")
                if isinstance(existing, dict):
                    progress.update(existing)
            except Exception:
                pass
            progress["status"] = "cancelled"
            progress["current_order"] = ""
            progress["message"] = message
            progress["updated_at"] = now
            cursor.execute(
                """
                UPDATE shopify_tracking_jobs
                SET status='cancelled', progress_json=%s, last_error=%s, completed_at=%s, updated_at=%s
                WHERE id=%s
                """,
                (json.dumps(progress), message, now, now, job_id),
            )
        raw.commit()
        return "cancelled"
    except KeyError:
        if raw:
            raw.rollback()
        raise HTTPException(404, "Tracking sync job not found.")
    except Exception:
        if raw:
            raw.rollback()
        # Fallback keeps older/dev environments working if a direct connection fails.
        mark_shopify_tracking_job_cancelled(job_id, message)
        return "cancelled"
    finally:
        if raw:
            try:
                raw.close()
            except Exception:
                pass


def run_shopify_tracking_job(job_id: str) -> None:
    cancel_before_start = False
    heartbeat_stop = threading.Event()
    heartbeat_thread: Optional[threading.Thread] = None
    settings = get_service_settings()
    report_dir = BASE_DIR / "reports"
    report_dir.mkdir(exist_ok=True)
    report_csv = str(report_dir / f"shopify_tracking_{job_id}.csv")
    with db() as conn:
        job = conn.execute("SELECT * FROM shopify_tracking_jobs WHERE id=?", (job_id,)).fetchone()
        if not job:
            return
        previous_report_csv = clean_text(job["report_csv"])
        if int(job["attempts"] or 0) > 0 and previous_report_csv:
            for stale_report in (Path(previous_report_csv), Path(previous_report_csv.replace(".csv", "_odoo_ineligible.csv"))):
                try:
                    if stale_report.exists() and stale_report.is_file():
                        stale_report.unlink()
                except Exception:
                    pass
        if job["status"] == "cancel_requested":
            cancel_before_start = True
        if cancel_before_start:
            pass
        else:
            now = utc_now()
            progress = {
                "status": "running",
                "total": 0,
                "processed": 0,
                "current_order": "",
                "source": "",
                "message": "Starting Shopify tracking sync.",
                "updated_at": now,
                "counters": {},
            }
            cursor = conn.execute(
                "UPDATE shopify_tracking_jobs SET status='running', attempts=attempts+1, locked_at=?, report_csv=?, progress_json=?, counters_json='{}', last_error='', completed_at=NULL, updated_at=? WHERE id=? AND status='queued'",
                (now, report_csv, json.dumps(progress), now, job_id),
            )
            if not cursor.rowcount:
                current = conn.execute("SELECT status FROM shopify_tracking_jobs WHERE id=?", (job_id,)).fetchone()
                cancel_before_start = bool(current and current["status"] == "cancel_requested")
                if not cancel_before_start:
                    return
    if cancel_before_start:
        mark_shopify_tracking_job_cancelled(job_id)
        return
    heartbeat_thread = start_shopify_tracking_job_heartbeat(job_id, heartbeat_stop)
    argv = [
        str(settings["shopify_tracking_script_path"]),
        "--from-date",
        str(job["from_date"]),
        "--to-date",
        str(job["to_date"]),
        "--report-csv",
        report_csv,
        "--workers",
        str(shopify_tracking_worker_count(settings)),
    ]
    if int(job["dry_run"] or 0):
        argv.append("--dry-run")
    if int(job["skip_done_pickings"] or 0):
        argv.append("--skip-done-pickings")
    if not int(job["validate_deliveries"] or 1):
        argv.append("--no-validate-deliveries")
    def fail_tracking_job(exc: BaseException) -> None:
        error_text = str(exc)[:2000] or exc.__class__.__name__
        now = utc_now()
        progress = {
            "status": "failed",
            "total": 0,
            "processed": 0,
            "current_order": "",
            "source": "",
            "message": f"Shopify tracking sync failed: {error_text}",
            "error": error_text,
            "updated_at": now,
            "counters": {},
        }
        with db() as conn:
            existing = conn.execute("SELECT progress_json FROM shopify_tracking_jobs WHERE id=?", (job_id,)).fetchone()
            if existing:
                try:
                    existing_progress = json.loads(existing["progress_json"] or "{}")
                    if isinstance(existing_progress, dict):
                        progress.update(existing_progress)
                except Exception:
                    pass
            progress["status"] = "failed"
            progress["current_order"] = ""
            progress["message"] = f"Shopify tracking sync failed: {error_text}"
            progress["error"] = error_text
            progress["updated_at"] = now
            conn.execute(
                "UPDATE shopify_tracking_jobs SET status='failed', progress_json=?, last_error=?, completed_at=?, updated_at=? WHERE id=?",
                (json.dumps(progress), error_text, now, now, job_id),
            )
        send_email_alert_async("Shopify tracking sync failed", f"Job: {job_id}\nError: {error_text}")

    try:
        module = load_external_script(settings["shopify_tracking_script_path"], f"shopify_tracking_{uuid.uuid4().hex}")
        apply_shopify_runtime_settings(module, "tracking", settings)
        module.StateDB = PostgresShopifyTrackingStateDB
        module.STATE_DB = "postgres:tracking"
        cancelled_exc = getattr(module, "TrackingSyncCancelled", BaseException)
        module.CANCEL_CALLBACK = lambda: shopify_tracking_job_cancel_requested(job_id)

        def progress_callback(progress: dict[str, Any]) -> None:
            if shopify_tracking_job_cancel_requested(job_id):
                raise cancelled_exc("Tracking sync cancelled by user.")
            set_shopify_tracking_job_progress(job_id, progress)

        module.PROGRESS_CALLBACK = progress_callback
        stdout = io.StringIO()
        stderr = io.StringIO()
        old_argv = sys.argv[:]
        sys.argv = argv
        try:
            with redirect_stdout(stdout), redirect_stderr(stderr):
                module.main()
        finally:
            sys.argv = old_argv
        if shopify_tracking_job_cancel_requested(job_id):
            raise cancelled_exc("Tracking sync cancelled by user.")
        counters = {"stdout": stdout.getvalue()[-8000:], "stderr": stderr.getvalue()[-8000:], "returncode": 0}
        with db() as conn:
            progress = {
                "status": "completed",
                "total": 0,
                "processed": 0,
                "current_order": "",
                "source": "",
                "message": "Shopify tracking sync complete.",
                "updated_at": utc_now(),
                "counters": counters,
            }
            existing = conn.execute("SELECT progress_json FROM shopify_tracking_jobs WHERE id=?", (job_id,)).fetchone()
            if existing:
                try:
                    progress.update(json.loads(existing["progress_json"] or "{}"))
                except Exception:
                    pass
            progress["status"] = "completed"
            progress["current_order"] = ""
            progress["message"] = "Shopify tracking sync complete."
            progress["updated_at"] = utc_now()
            conn.execute(
                "UPDATE shopify_tracking_jobs SET status='completed', report_csv=?, progress_json=?, counters_json=?, last_error='', completed_at=?, updated_at=? WHERE id=?",
                (report_csv, json.dumps(progress), json.dumps(counters), progress["updated_at"], progress["updated_at"], job_id),
            )
        if not int(job["dry_run"] or 0):
            try:
                set_setting("shopify_tracking_last_success_at", shopify_tracking_cursor_from_to_date(job["to_date"]))
            except Exception as exc:
                warning = f"Tracking sync completed, but last success timestamp could not be saved: {exc}"
                print(warning, flush=True)
                try:
                    success_cursor = shopify_tracking_cursor_from_to_date(job["to_date"])
                    with db() as conn:
                        conn.execute(
                            """
                            INSERT INTO app_settings (key, value, updated_at)
                            VALUES (?, ?, ?)
                            ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at
                            """,
                            ("shopify_tracking_last_success_at", app_setting_storage_value(success_cursor), progress["updated_at"]),
                        )
                except Exception as fallback_exc:
                    warning = f"{warning}; fallback also failed: {fallback_exc}"
                    try:
                        progress["message"] = warning
                        progress["last_success_warning"] = warning
                        with db() as conn:
                            conn.execute(
                                "UPDATE shopify_tracking_jobs SET progress_json=?, last_error=?, updated_at=? WHERE id=?",
                                (json.dumps(progress), warning[:2000], utc_now(), job_id),
                            )
                    except Exception:
                        pass
    except SystemExit as exc:
        fail_tracking_job(RuntimeError(f"Tracking script exited {exc.code}"))
    except BaseException as exc:
        if exc.__class__.__name__ == "TrackingSyncCancelled":
            mark_shopify_tracking_job_cancelled(job_id, str(exc)[:2000] or "Tracking sync cancelled by user.")
        else:
            fail_tracking_job(exc)
    finally:
        heartbeat_stop.set()
        if heartbeat_thread:
            heartbeat_thread.join(timeout=1)


def start_shopify_tracking_job(job_id: str) -> None:
    def runner() -> None:
        try:
            run_shopify_tracking_job(job_id)
        finally:
            with SHOPIFY_TRACKING_ACTIVE_LOCK:
                SHOPIFY_TRACKING_ACTIVE_JOBS.discard(job_id)

    with SHOPIFY_TRACKING_ACTIVE_LOCK:
        SHOPIFY_TRACKING_ACTIVE_JOBS.add(job_id)
    threading.Thread(target=runner, daemon=True).start()


def parse_utc_datetime(value: str) -> Optional[datetime]:
    cleaned = clean_text(value)
    if not cleaned:
        return None
    try:
        parsed = datetime.fromisoformat(cleaned.replace("Z", "+00:00"))
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except Exception:
        return None


def reconcile_stale_shopify_tracking_jobs(max_idle_seconds: int = 300) -> int:
    with SHOPIFY_TRACKING_ACTIVE_LOCK:
        active_job_ids = set(SHOPIFY_TRACKING_ACTIVE_JOBS)
    cutoff = datetime.now(timezone.utc) - timedelta(seconds=max_idle_seconds)
    now = utc_now()
    updated = 0
    with db() as conn:
        rows = conn.execute(
            """
            SELECT id, status, progress_json, updated_at
            FROM shopify_tracking_jobs
            WHERE status IN ('queued', 'running', 'cancel_requested')
            """
        ).fetchall()
        for row in rows:
            if row["id"] in active_job_ids:
                continue
            if row["status"] == "cancel_requested":
                message = "Tracking sync cancelled by user."
                progress = {
                    "status": "cancelled",
                    "total": 0,
                    "processed": 0,
                    "current_order": "",
                    "source": "",
                    "message": message,
                    "updated_at": now,
                    "counters": {},
                }
                try:
                    existing_progress = json.loads(row["progress_json"] or "{}")
                    if isinstance(existing_progress, dict):
                        progress.update(existing_progress)
                except Exception:
                    pass
                progress["status"] = "cancelled"
                progress["current_order"] = ""
                progress["message"] = message
                progress["updated_at"] = now
                conn.execute(
                    "UPDATE shopify_tracking_jobs SET status='cancelled', progress_json=?, last_error=?, completed_at=?, updated_at=? WHERE id=?",
                    (json.dumps(progress), message, now, now, row["id"]),
                )
                updated += 1
                continue
            updated_at = parse_utc_datetime(row["updated_at"])
            if updated_at and updated_at > cutoff:
                continue
            message = "Tracking sync worker is no longer active. Retry the job to run it again."
            progress = {
                "status": "stalled",
                "total": 0,
                "processed": 0,
                "current_order": "",
                "source": "",
                "message": message,
                "updated_at": now,
                "counters": {},
            }
            try:
                existing_progress = json.loads(row["progress_json"] or "{}")
                if isinstance(existing_progress, dict):
                    progress.update(existing_progress)
            except Exception:
                pass
            progress["status"] = "stalled"
            progress["current_order"] = ""
            progress["message"] = message
            progress["updated_at"] = now
            conn.execute(
                "UPDATE shopify_tracking_jobs SET status='stalled', progress_json=?, last_error=?, completed_at=?, updated_at=? WHERE id=?",
                (json.dumps(progress), message, now, now, row["id"]),
            )
            updated += 1
    return updated


def resume_interrupted_shopify_tracking_jobs() -> int:
    with SHOPIFY_TRACKING_ACTIVE_LOCK:
        active_job_ids = set(SHOPIFY_TRACKING_ACTIVE_JOBS)
    now = utc_now()
    resume_ids: list[str] = []
    with db() as conn:
        rows = conn.execute(
            """
            SELECT id, status, progress_json
            FROM shopify_tracking_jobs
            WHERE status IN ('queued', 'running')
            ORDER BY created_at ASC
            """
        ).fetchall()
        for row in rows:
            job_id = row["id"]
            if job_id in active_job_ids:
                continue
            progress = {
                "status": "queued",
                "total": 0,
                "processed": 0,
                "current_order": "",
                "source": "",
                "message": "Resuming tracking sync after server restart.",
                "updated_at": now,
                "counters": {},
            }
            try:
                existing_progress = json.loads(row["progress_json"] or "{}")
                if isinstance(existing_progress, dict):
                    progress.update(existing_progress)
            except Exception:
                pass
            progress["status"] = "queued"
            progress["current_order"] = ""
            progress["message"] = "Resuming tracking sync after server restart."
            progress["updated_at"] = now
            conn.execute(
                "UPDATE shopify_tracking_jobs SET status='queued', progress_json=?, last_error='', completed_at=NULL, updated_at=? WHERE id=?",
                (json.dumps(progress), now, job_id),
            )
            resume_ids.append(job_id)
    for job_id in resume_ids:
        start_shopify_tracking_job(job_id)
    return len(resume_ids)


def ymd_from_iso_datetime(value: str) -> str:
    cleaned = clean_text(value)
    if not cleaned:
        return ""
    try:
        return datetime.fromisoformat(cleaned.replace("Z", "+00:00")).date().isoformat()
    except Exception:
        return cleaned[:10] if re.match(r"^\d{4}-\d{2}-\d{2}", cleaned) else ""


def tracking_schedule_interval(schedule: str) -> timedelta:
    return {
        "daily": timedelta(days=1),
        "every_2_days": timedelta(days=2),
        "every_3_days": timedelta(days=3),
        "every_4_days": timedelta(days=4),
        "weekly": timedelta(days=7),
    }.get(clean_text(schedule), timedelta(0))


def has_active_shopify_tracking_job() -> bool:
    with db() as conn:
        row = conn.execute(
            """
            SELECT COUNT(*) AS count
            FROM shopify_tracking_jobs
            WHERE status IN ('queued', 'running', 'cancel_requested')
            """
        ).fetchone()
    return int(row["count"] or 0) > 0


def create_shopify_tracking_job(payload: dict[str, Any], queued_by: str = "manual") -> dict[str, Any]:
    settings = get_service_settings()
    today = datetime.now(timezone.utc).date()
    now_dt = datetime.now(timezone.utc)
    from_days = max(1, min(365, int(float(settings.get("shopify_tracking_from_days") or 7))))
    requested_from = clean_text(payload.get("from_date"))
    requested_to = clean_text(payload.get("to_date"))
    incremental = bool(payload.get("incremental", True)) and not requested_from and not requested_to
    last_success_at = get_setting("shopify_tracking_last_success_at", "")
    if incremental and last_success_at:
        last_success_dt = parse_utc_datetime(last_success_at)
        if last_success_dt:
            overlap_minutes = max(0, min(1440, int(float(settings.get("shopify_tracking_incremental_overlap_minutes") or 180))))
            from_date = (last_success_dt - timedelta(minutes=overlap_minutes)).astimezone(timezone.utc).isoformat()
        else:
            from_date = last_success_at
        to_date = now_dt.isoformat()
    else:
        from_date = requested_from or (today - timedelta(days=from_days)).isoformat()
        to_date = requested_to or today.isoformat()
    dry_run = bool(payload.get("dry_run", False))
    skip_done = bool(payload.get("skip_done_pickings", str(settings.get("shopify_tracking_skip_done_pickings", "false")).lower() in {"1", "true", "yes", "on"}))
    validate = bool(payload.get("validate_deliveries", str(settings.get("shopify_tracking_validate_deliveries", "true")).lower() in {"1", "true", "yes", "on"}))
    job_id = uuid.uuid4().hex
    with db() as conn:
        conn.execute(
            """
            INSERT INTO shopify_tracking_jobs
            (id, status, attempts, max_attempts, from_date, to_date, dry_run, skip_done_pickings,
             validate_deliveries, report_csv, progress_json, counters_json, last_error, created_at, updated_at)
            VALUES (?, 'queued', 0, 3, ?, ?, ?, ?, ?, '', '{}', '{}', '', ?, ?)
            """,
            (job_id, from_date, to_date, 1 if dry_run else 0, 1 if skip_done else 0, 1 if validate else 0, utc_now(), utc_now()),
        )
    if queued_by == "auto":
        message = f"Queued automatic tracking sync: {from_date} to {to_date}."
        set_setting("shopify_tracking_auto_last_run_at", utc_now())
        set_setting("shopify_tracking_auto_last_message", message)
    else:
        mode_label = "new tracking since last successful sync" if incremental and last_success_at else "selected date range"
        message = f"Shopify tracking sync queued for {mode_label}: {from_date} to {to_date}."
    start_shopify_tracking_job(job_id)
    return {
        "ok": True,
        "message": message,
        "job_id": job_id,
        "from_date": from_date,
        "to_date": to_date,
        "incremental": incremental,
        "last_success_at": last_success_at,
        "queued_by": queued_by,
    }


def maybe_queue_scheduled_shopify_tracking(settings: dict[str, str]) -> None:
    interval = tracking_schedule_interval(settings.get("shopify_tracking_auto_schedule", "off"))
    if interval <= timedelta(0):
        return
    reconcile_stale_shopify_tracking_jobs()
    if has_active_shopify_tracking_job():
        return
    last_run = parse_utc_datetime(get_setting("shopify_tracking_auto_last_run_at", ""))
    if last_run and datetime.now(timezone.utc) - last_run < interval:
        return
    create_shopify_tracking_job({"incremental": True, "dry_run": False}, queued_by="auto")


def run_scheduled_shopify_tracking_safely(settings: dict[str, str]) -> None:
    try:
        maybe_queue_scheduled_shopify_tracking(settings)
    except Exception as exc:
        message = f"Automatic Shopify tracking scheduler failed: {exc}"
        set_setting("shopify_tracking_auto_last_message", message)
        print(message, flush=True)


def shopify_tracking_schedule_loop() -> None:
    while True:
        try:
            run_scheduled_shopify_tracking_safely(get_service_settings())
        except Exception as exc:
            message = f"Automatic Shopify tracking scheduler failed: {exc}"
            try:
                set_setting("shopify_tracking_auto_last_message", message)
            except Exception:
                pass
            print(message, flush=True)
        time.sleep(60)


def set_service_settings(values: dict[str, str]) -> None:
    global _ADMIN_ACCESS_TOKEN_CACHE, _SERVICE_SETTINGS_CACHE
    now = utc_now()
    allowed = {key: str(value or "") for key, value in values.items() if key in DEFAULT_SERVICE_SETTINGS}
    if not allowed:
        return
    with db() as conn:
        for key, value in allowed.items():
            conn.execute(
                """
                INSERT INTO app_settings (key, value, updated_at)
                VALUES (?, ?, ?)
                ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at
                """,
                (key, app_setting_storage_value(value), now),
            )
    with _SERVICE_SETTINGS_CACHE_LOCK:
        _SERVICE_SETTINGS_CACHE = ({}, 0.0)
    if {"redis_url", "redis_enabled", "dramatiq_enabled"} & set(allowed):
        redis_support.reset_client()
        fast_page_cache_clear()
    else:
        fast_page_cache_clear_matching({"settings-services"})


def send_email_alert(subject: str, message: str) -> None:
    settings = get_service_settings()
    if str(settings.get("email_alerts_enabled", "false")).lower() not in {"1", "true", "yes", "on"}:
        return
    to_address = clean_text(settings.get("email_alert_to") or settings.get("email_system_address"))
    if not to_address or clean_text(settings.get("email_driver")).lower() != "smtp":
        return
    smtp_host = clean_text(settings.get("email_smtp_host"))
    if not smtp_host:
        return
    smtp_port = int(float(settings.get("email_smtp_port") or 465))
    smtp_user = clean_text(settings.get("email_smtp_user"))
    smtp_password = str(settings.get("email_smtp_password") or "")
    from_address = clean_text(settings.get("email_from_address")) or clean_text(settings.get("email_system_address")) or smtp_user
    from_name = clean_text(settings.get("email_from_name")) or "GofinchCRM"
    msg = EmailMessage()
    msg["Subject"] = subject[:180]
    msg["From"] = f"{from_name} <{from_address}>"
    msg["To"] = to_address
    msg.set_content(message)
    secure = str(settings.get("email_smtp_secure", "true")).lower() in {"1", "true", "yes", "on", "ssl"}
    try:
        if secure:
            with smtplib.SMTP_SSL(smtp_host, smtp_port, timeout=20) as smtp:
                if smtp_user or smtp_password:
                    smtp.login(smtp_user, smtp_password)
                smtp.send_message(msg)
        else:
            with smtplib.SMTP(smtp_host, smtp_port, timeout=20) as smtp:
                smtp.ehlo()
                if smtp_port == 587:
                    smtp.starttls()
                    smtp.ehlo()
                if smtp_user or smtp_password:
                    smtp.login(smtp_user, smtp_password)
                smtp.send_message(msg)
    except Exception as exc:
        print(f"Email alert failed: {exc}", flush=True)


def send_email_alert_async(subject: str, message: str) -> None:
    threading.Thread(target=send_email_alert, args=(subject, message), daemon=True).start()


def upsert_amazon_otp_record(parsed: Any, folder: str = "", uid: str = "") -> bool:
    order_id = clean_text(parsed.amazon_order_id)
    if not order_id or parsed.email_type not in {"otp", "dispatch"}:
        return False
    now = utc_now()
    with db() as conn:
        if uid:
            existing = conn.execute(
                "SELECT id FROM amazon_otp_email_uids WHERE folder=? AND uid=?",
                (folder, uid),
            ).fetchone()
            if existing:
                return False
        conn.execute(
            """
            INSERT INTO amazon_otp_records
              (amazon_order_id, otp, otp_required, tracking_url, shipment_id, package_index,
               recipient, product_summary, otp_email_subject, otp_email_date,
               dispatch_email_subject, dispatch_email_date, status, raw_json,
               last_email_uid, last_synced_at, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(amazon_order_id) DO UPDATE SET
              otp=COALESCE(NULLIF(excluded.otp, ''), amazon_otp_records.otp),
              otp_required=CASE WHEN excluded.otp_required=1 THEN 1 ELSE amazon_otp_records.otp_required END,
              tracking_url=COALESCE(NULLIF(excluded.tracking_url, ''), amazon_otp_records.tracking_url),
              shipment_id=COALESCE(NULLIF(excluded.shipment_id, ''), amazon_otp_records.shipment_id),
              package_index=COALESCE(NULLIF(excluded.package_index, ''), amazon_otp_records.package_index),
              recipient=COALESCE(NULLIF(excluded.recipient, ''), amazon_otp_records.recipient),
              product_summary=COALESCE(NULLIF(excluded.product_summary, ''), amazon_otp_records.product_summary),
              otp_email_subject=COALESCE(NULLIF(excluded.otp_email_subject, ''), amazon_otp_records.otp_email_subject),
              otp_email_date=COALESCE(NULLIF(excluded.otp_email_date, ''), amazon_otp_records.otp_email_date),
              dispatch_email_subject=COALESCE(NULLIF(excluded.dispatch_email_subject, ''), amazon_otp_records.dispatch_email_subject),
              dispatch_email_date=COALESCE(NULLIF(excluded.dispatch_email_date, ''), amazon_otp_records.dispatch_email_date),
              status=excluded.status,
              raw_json=excluded.raw_json,
              last_email_uid=COALESCE(NULLIF(excluded.last_email_uid, ''), amazon_otp_records.last_email_uid),
              last_synced_at=excluded.last_synced_at,
              updated_at=excluded.updated_at
            """,
            (
                order_id,
                parsed.otp if parsed.email_type == "otp" else "",
                1 if parsed.email_type == "otp" else 0,
                parsed.tracking_url,
                parsed.shipment_id,
                parsed.package_index,
                parsed.recipient,
                parsed.product_summary,
                parsed.subject if parsed.email_type == "otp" else "",
                parsed.email_date if parsed.email_type == "otp" else "",
                parsed.subject if parsed.email_type == "dispatch" else "",
                parsed.email_date if parsed.email_type == "dispatch" else "",
                parsed.email_type,
                parsed.raw_json,
                uid,
                now,
                now,
                now,
            ),
        )
        if uid:
            conn.execute(
                """
                INSERT INTO amazon_otp_email_uids
                  (folder, uid, message_id, amazon_order_id, email_type, subject, email_date, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(folder, uid) DO NOTHING
                """,
                (folder, uid, parsed.message_id, order_id, parsed.email_type, parsed.subject, parsed.email_date, now),
            )
        updated = conn.execute("SELECT * FROM amazon_otp_records WHERE amazon_order_id=?", (order_id,)).fetchone()
    if updated:
        _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(updated) or {}: _index_named_document_sync("amazon_otp_records", amazon_otp_search_document(snapshot)))
    return True


def sync_amazon_otp_emails() -> dict[str, Any]:
    settings = get_service_settings()
    if not settings.get("amazon_otp_imap_host") or not settings.get("amazon_otp_imap_username") or not settings.get("amazon_otp_imap_password"):
        return {"ok": False, "message": "Amazon OTP IMAP settings are incomplete.", "processed": 0}
    folder = clean_text(settings.get("amazon_otp_imap_folder")) or "INBOX"
    since_days = int(float(settings.get("amazon_otp_imap_since_days") or 14))
    delete_processed = str(settings.get("amazon_otp_delete_processed_emails", "true")).lower() in {"1", "true", "yes", "on"}
    processed = 0
    matched = 0
    deleted = 0
    client = imap_connect(settings)
    try:
        status, _ = client.select(folder)
        if status != "OK":
            raise RuntimeError(f"Unable to select IMAP folder {folder}.")
        criteria = f'(SINCE "{imap_search_since(since_days)}")'
        status, data = client.uid("SEARCH", None, criteria)
        if status != "OK":
            status, data = client.uid("SEARCH", None, f'(SINCE "{imap_search_since(since_days)}")')
        uids = (data[0] or b"").split() if data else []
        for uid_bytes in uids[-500:]:
            uid = uid_bytes.decode("ascii", errors="ignore")
            status, payload = client.uid("FETCH", uid, "(RFC822)")
            if status != "OK" or not payload:
                continue
            raw = b""
            for item in payload:
                if isinstance(item, tuple) and item[1]:
                    raw = item[1]
                    break
            if not raw:
                continue
            processed += 1
            parsed = parse_amazon_email(raw)
            if upsert_amazon_otp_record(parsed, folder, uid):
                matched += 1
            if delete_processed:
                status, _ = client.uid("STORE", uid, "+FLAGS.SILENT", r"(\Deleted)")
                if status == "OK":
                    deleted += 1
        if delete_processed and deleted:
            client.expunge()
        set_setting("amazon_otp_last_sync_at", utc_now())
        set_setting("amazon_otp_last_sync_message", f"Processed {processed}, matched {matched}, deleted {deleted}.")
        return {"ok": True, "processed": processed, "matched": matched, "deleted": deleted, "message": f"Processed {processed} email(s), matched {matched} Amazon OTP/dispatch email(s), deleted {deleted} processed email(s)."}
    finally:
        try:
            client.logout()
        except Exception:
            pass


def amazon_otp_loop() -> None:
    last_run = 0.0
    while True:
        try:
            settings = get_service_settings()
            interval = int(float(settings.get("amazon_otp_imap_interval_minutes") or 5))
            if interval > 0 and time.time() - last_run >= interval * 60:
                sync_amazon_otp_emails()
                last_run = time.time()
        except Exception as exc:
            try:
                set_setting("amazon_otp_last_sync_message", str(exc)[:500])
                set_setting("amazon_otp_last_sync_at", utc_now())
            except Exception:
                pass
        time.sleep(60)


def backfill_missing_order_dates(rows: list[dict[str, Any]], fetch_remote: bool = False) -> list[dict[str, Any]]:
    candidates = [row for row in rows if not clean_text(row.get("odoo_order_date")) and int(row.get("store_id") or 0) and int(row.get("odoo_order_id") or 0)]
    if not candidates:
        return rows
    updated_rows = [dict(row) for row in rows]
    parsed_dates: dict[int, str] = {}
    for row in candidates:
        try:
            payload = json.loads(row.get("raw_json") or "{}")
            order_date = clean_text((payload.get("order") or {}).get("date_order"))
            if order_date:
                parsed_dates[int(row["id"])] = order_date
        except Exception:
            continue
    if parsed_dates:
        with db() as conn:
            for row in updated_rows:
                order_date = parsed_dates.get(int(row.get("id") or 0))
                if not order_date:
                    continue
                row["odoo_order_date"] = order_date
                conn.execute(
                    "UPDATE order_lines SET odoo_order_date=?, updated_at=? WHERE id=?",
                    (order_date, utc_now(), row["id"]),
                )
        candidates = [row for row in updated_rows if not clean_text(row.get("odoo_order_date")) and int(row.get("store_id") or 0) and int(row.get("odoo_order_id") or 0)]
        if not candidates or not fetch_remote:
            return updated_rows
    if not fetch_remote:
        return rows
    by_store: dict[int, set[int]] = {}
    for row in candidates:
        by_store.setdefault(int(row["store_id"]), set()).add(int(row["odoo_order_id"]))
    dates: dict[tuple[int, int], str] = {}
    for store_id, order_ids in by_store.items():
        try:
            store = get_store(store_id)
            odoo = OdooClient(store)
            fields = odoo.existing_fields("sale.order", ["id", "date_order"])
            if "date_order" not in fields:
                continue
            for order in odoo.read("sale.order", sorted(order_ids), fields):
                order_date = clean_text(order.get("date_order"))
                if order_date:
                    dates[(store_id, int(order["id"]))] = order_date
        except Exception:
            continue
    if not dates:
        return rows
    with db() as conn:
        for row in updated_rows:
            order_date = dates.get((int(row.get("store_id") or 0), int(row.get("odoo_order_id") or 0)))
            if not order_date:
                continue
            row["odoo_order_date"] = order_date
            conn.execute(
                "UPDATE order_lines SET odoo_order_date=?, updated_at=? WHERE id=?",
                (order_date, utc_now(), row["id"]),
            )
    return updated_rows


def amazon_otp_rows(q: str = "", record_ids: Optional[set[int]] = None) -> list[dict[str, Any]]:
    term = clean_text(q).lower()
    term_digits = re.sub(r"\D+", "", term)
    with db() as conn:
        records = conn.execute(
            """
            SELECT *
            FROM amazon_otp_records
            WHERE otp_required=1 OR COALESCE(otp, '') != '' OR COALESCE(tracking_url, '') != ''
            ORDER BY COALESCE(otp_email_date, dispatch_email_date, updated_at) DESC
            LIMIT 500
            """
        ).fetchall()
        otp_order_ids = sorted({clean_text(row["amazon_order_id"]) for row in records if clean_text(row["amazon_order_id"])})
        lines = []
        if otp_order_ids:
            placeholders = ",".join("?" for _ in otp_order_ids)
            lines = conn.execute(
                f"""
                SELECT amazon_order_id, odoo_order_name, store_id, tracking_status, tracking_payload, tracking_checked_at, state
                FROM order_lines
                WHERE amazon_order_id IN ({placeholders})
                """,
                otp_order_ids,
            ).fetchall()
        dispatch_packages = []
        if otp_order_ids:
            placeholders = ",".join("?" for _ in otp_order_ids)
            dispatch_packages = conn.execute(
                f"""
                SELECT amazon_order_id, odoo_order_name, store_id, scan_code, display_code, canonical_scan_code,
                       package_status, promise, carrier, tracking_url, updated_at
                FROM amazon_dispatch_packages
                WHERE amazon_order_id IN ({placeholders})
                """,
                otp_order_ids,
            ).fetchall()
    lines_by_order: dict[str, list[dict[str, Any]]] = {}
    for line in rows_to_dicts(lines):
        lines_by_order.setdefault(clean_text(line.get("amazon_order_id")), []).append(line)
    dispatch_packages_by_order: dict[str, list[dict[str, Any]]] = {}
    for package in rows_to_dicts(dispatch_packages):
        dispatch_packages_by_order.setdefault(clean_text(package.get("amazon_order_id")), []).append(package)
    stores = {int(store["id"]): store for store in list_stores()}
    results: list[dict[str, Any]] = []
    for record in rows_to_dicts(records):
        if record_ids is not None and int(record.get("id") or 0) not in record_ids:
            continue
        order_id = clean_text(record.get("amazon_order_id"))
        order_lines = lines_by_order.get(order_id, [])
        packages: list[dict[str, Any]] = []
        odoo_order_names: list[str] = []
        statuses: list[str] = []
        checked_at = ""
        store_names: list[str] = []
        for line in order_lines:
            odoo_name = clean_text(line.get("odoo_order_name"))
            if odoo_name and odoo_name not in odoo_order_names:
                odoo_order_names.append(odoo_name)
            status = clean_text(line.get("tracking_status") or line.get("state"))
            if status and status not in statuses:
                statuses.append(status)
            if line.get("tracking_checked_at") and not checked_at:
                checked_at = line.get("tracking_checked_at")
            store = stores.get(int(line.get("store_id") or 0))
            if store and store["name"] not in store_names:
                store_names.append(store["name"])
            try:
                parsed_packages = json.loads(line.get("tracking_payload") or "[]")
                if isinstance(parsed_packages, list):
                    for package in parsed_packages:
                        if isinstance(package, dict) and package not in packages:
                            packages.append(package)
            except Exception:
                pass
        for dispatch_package in dispatch_packages_by_order.get(order_id, []):
            odoo_name = clean_text(dispatch_package.get("odoo_order_name"))
            if odoo_name and odoo_name not in odoo_order_names:
                odoo_order_names.append(odoo_name)
            status = clean_text(dispatch_package.get("package_status") or dispatch_package.get("promise"))
            if status and status not in statuses:
                statuses.append(status)
            if dispatch_package.get("updated_at") and not checked_at:
                checked_at = dispatch_package.get("updated_at")
            store = stores.get(int(dispatch_package.get("store_id") or 0))
            if store and store["name"] not in store_names:
                store_names.append(store["name"])
            tracking_candidates = [
                dispatch_package.get("scan_code"),
                dispatch_package.get("display_code"),
                dispatch_package.get("canonical_scan_code"),
            ]
            tracking_id = ""
            for candidate in tracking_candidates:
                candidate_text = clean_text(candidate)
                if candidate_text and candidate_text.lower() not in {"amazon tracking page", "tracking page"}:
                    tracking_id = candidate_text
                    break
            package = {
                "tracking_id": tracking_id,
                "carrier": clean_text(dispatch_package.get("carrier")),
                "status": status,
                "tracking_url": clean_text(dispatch_package.get("tracking_url")),
            }
            if any(package.values()) and package not in packages:
                packages.append(package)
        tracking_numbers = []
        carriers = []
        for package in packages:
            tracking_id = clean_text(package.get("tracking_id") or package.get("trackingId") or package.get("tracking_number"))
            carrier = clean_text(package.get("carrier") or package.get("carrier_name"))
            if tracking_id and tracking_id not in tracking_numbers:
                tracking_numbers.append(tracking_id)
            if carrier and carrier not in carriers:
                carriers.append(carrier)
        status_text = " ".join(statuses).lower()
        package_text = json.dumps(packages, default=str).lower()
        if order_lines and ("delivered" in status_text or "delivered" in package_text):
            continue
        last_updated = max(
            [value for value in [clean_text(record.get("updated_at")), clean_text(checked_at)] if value],
            default=clean_text(record.get("updated_at")),
        )
        if record.get("otp"):
            match_status = "matched" if tracking_numbers or record.get("tracking_url") else "needs tracking"
        else:
            match_status = "tracking captured" if tracking_numbers else "waiting for OTP"
        row = {
            **record,
            "store_names": ", ".join(store_names),
            "odoo_order_names": ", ".join(odoo_order_names),
            "tracking_status": ", ".join(statuses) or clean_text(record.get("status")),
            "tracking_checked_at": checked_at,
            "tracking_numbers": ", ".join(tracking_numbers),
            "carriers": ", ".join(carriers),
            "package_count": len(packages),
            "updated_at": last_updated,
            "amazon_order_url": order_line_amazon_url(order_id),
            "match_status": match_status,
        }
        searchable = " ".join(str(row.get(key) or "") for key in ("amazon_order_id", "otp", "tracking_numbers", "carriers", "odoo_order_names", "product_summary", "recipient")).lower()
        searchable_digits = re.sub(r"\D+", "", searchable)
        if not term or term in searchable or (term_digits and term_digits in searchable_digits):
            results.append(row)
    return results


def get_default_ordering_engine() -> str:
    return normalize_ordering_engine(get_setting("default_ordering_engine", "rest"))


def read_proc_cpu_sample() -> Optional[tuple[int, int]]:
    try:
        parts = Path("/proc/stat").read_text().splitlines()[0].split()
        values = [int(value) for value in parts[1:]]
        idle = values[3] + (values[4] if len(values) > 4 else 0)
        total = sum(values)
        return idle, total
    except Exception:
        return None


def host_cpu_percent() -> Optional[float]:
    first = read_proc_cpu_sample()
    if first:
        time.sleep(0.08)
        second = read_proc_cpu_sample()
        if second:
            idle_delta = second[0] - first[0]
            total_delta = second[1] - first[1]
            if total_delta > 0:
                return round(max(0.0, min(100.0, 100.0 * (1.0 - (idle_delta / total_delta)))), 1)
    try:
        output = subprocess.check_output(["ps", "-A", "-o", "%cpu="], text=True, timeout=2)
        total = sum(float(line.strip() or 0) for line in output.splitlines())
        cores = max(1, os.cpu_count() or 1)
        return round(max(0.0, min(100.0, total / cores)), 1)
    except Exception:
        return None


def host_memory_usage() -> dict[str, Optional[Union[int, float]]]:
    try:
        values: dict[str, int] = {}
        for line in Path("/proc/meminfo").read_text().splitlines():
            key, raw = line.split(":", 1)
            values[key] = int(raw.strip().split()[0]) * 1024
        total = values.get("MemTotal")
        available = values.get("MemAvailable")
        if total and available is not None:
            used = total - available
            return {"total_bytes": total, "used_bytes": used, "available_bytes": available, "percent": round((used / total) * 100, 1)}
    except Exception:
        pass
    try:
        total = int(subprocess.check_output(["sysctl", "-n", "hw.memsize"], text=True, timeout=2).strip())
        page_size = int(subprocess.check_output(["sysctl", "-n", "hw.pagesize"], text=True, timeout=2).strip())
        vm_output = subprocess.check_output(["vm_stat"], text=True, timeout=2)
        pages: dict[str, int] = {}
        for line in vm_output.splitlines():
            if ":" not in line:
                continue
            key, raw = line.split(":", 1)
            pages[key.strip()] = int(re.sub(r"[^0-9]", "", raw) or "0")
        free_pages = pages.get("Pages free", 0) + pages.get("Pages speculative", 0)
        available = free_pages * page_size
        used = max(0, total - available)
        return {"total_bytes": total, "used_bytes": used, "available_bytes": available, "percent": round((used / total) * 100, 1)}
    except Exception:
        return {"total_bytes": None, "used_bytes": None, "available_bytes": None, "percent": None}


def postgres_connection_stats() -> dict[str, Any]:
    stats: dict[str, Any] = {
        "total": None,
        "active": None,
        "idle": None,
        "idle_in_transaction": None,
        "max_connections": None,
        "app_pool_max": int(os.getenv("POSTGRES_POOL_MAX", "30") or 30),
        "database": "",
        "host": "",
        "error": "",
    }
    postgres_url = active_postgres_url()
    if postgres_url:
        parsed = urlsplit(postgres_url)
        stats["database"] = (parsed.path or "").strip("/")
        stats["host"] = parsed.hostname or ""
    try:
        with db() as conn:
            row = conn.execute(
                """
                SELECT
                    COUNT(*) AS total,
                    COUNT(*) FILTER (WHERE state='active') AS active,
                    COUNT(*) FILTER (WHERE state='idle') AS idle,
                    COUNT(*) FILTER (WHERE state='idle in transaction') AS idle_in_transaction
                FROM pg_stat_activity
                WHERE datname = current_database()
                """
            ).fetchone() or {}
            max_row = conn.execute("SHOW max_connections").fetchone() or {}
        stats.update({
            "total": int(row.get("total") or 0),
            "active": int(row.get("active") or 0),
            "idle": int(row.get("idle") or 0),
            "idle_in_transaction": int(row.get("idle_in_transaction") or 0),
            "max_connections": int(max_row.get("max_connections") or 0),
        })
    except Exception as error:
        stats["error"] = str(error)
    return stats


def system_diagnostics() -> dict[str, Any]:
    try:
        load_1, load_5, load_15 = os.getloadavg()
    except Exception:
        load_1 = load_5 = load_15 = None
    return {
        "ok": True,
        "host": socket.gethostname(),
        "platform": platform.platform(),
        "cpu": {
            "percent": host_cpu_percent(),
            "cores": os.cpu_count() or 1,
            "load_1": round(load_1, 2) if load_1 is not None else None,
            "load_5": round(load_5, 2) if load_5 is not None else None,
            "load_15": round(load_15, 2) if load_15 is not None else None,
        },
        "memory": host_memory_usage(),
        "postgres": postgres_connection_stats(),
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }


def dashboard_data(store_id: Optional[int] = None, page: int = 1, per_page: int = 100, sort_by: str = "odoo_order_date", sort_dir: str = "desc") -> dict[str, Any]:
    page, per_page, offset = pagination_bounds(page, per_page)
    order_by_sql = order_group_sort_sql(sort_by, sort_dir)
    with db() as conn:
        payload = conn.execute(
            f"""
            WITH stores_cte AS (
                SELECT * FROM stores ORDER BY name
            ),
            chosen AS (
                SELECT CAST(? AS INTEGER) AS store_id
            ),
            order_groups AS (
                SELECT {order_group_select_sql(sort_by)}
                FROM order_lines
                WHERE ((SELECT store_id FROM chosen) IS NULL OR store_id=(SELECT store_id FROM chosen))
                  AND odoo_order_id IS NOT NULL
                GROUP BY store_id, odoo_order_id
            ),
            page_orders AS (
                SELECT *,
                       ROW_NUMBER() OVER (ORDER BY {order_by_sql}) AS sort_order
                FROM order_groups
                ORDER BY {order_by_sql}
                LIMIT ? OFFSET ?
            ),
            page_rows AS (
                SELECT {qualified_order_line_page_select("order_lines")},
                       page_orders.sort_order AS sort_order
                FROM order_lines
                JOIN page_orders
                  ON page_orders.store_id=order_lines.store_id
                 AND page_orders.odoo_order_id=order_lines.odoo_order_id
            ),
            page_asins AS (
                SELECT DISTINCT store_id, asin
                FROM page_rows
                WHERE COALESCE(asin, '') != ''
            ),
            duplicate_counts AS (
                SELECT duplicate_lines.store_id,
                       duplicate_lines.asin,
                       COUNT(*) AS duplicate_asin_count
                FROM order_lines AS duplicate_lines
                JOIN page_asins
                  ON page_asins.store_id = duplicate_lines.store_id
                 AND page_asins.asin = duplicate_lines.asin
                WHERE COALESCE(duplicate_lines.amazon_order_id, '') = ''
                  AND COALESCE(duplicate_lines.odoo_status_label, '') NOT IN ('cancelled', 'refunded')
                GROUP BY duplicate_lines.store_id, duplicate_lines.asin
            ),
            inventory_counts AS (
                SELECT inventory_items.store_id,
                       inventory_items.asin,
                       SUM(inventory_items.quantity) AS inventory_quantity
                FROM inventory_items
                JOIN page_asins
                  ON page_asins.store_id = inventory_items.store_id
                 AND page_asins.asin = inventory_items.asin
                WHERE inventory_items.status = 'available'
                GROUP BY inventory_items.store_id, inventory_items.asin
            ),
            order_asin_counts AS (
                SELECT same_order_lines.store_id,
                       same_order_lines.odoo_order_id,
                       COUNT(DISTINCT same_order_lines.asin) AS odoo_order_distinct_asin_count
                FROM order_lines AS same_order_lines
                JOIN page_orders
                  ON page_orders.store_id = same_order_lines.store_id
                 AND page_orders.odoo_order_id = same_order_lines.odoo_order_id
                WHERE COALESCE(same_order_lines.asin, '') != ''
                  AND same_order_lines.state != 'missing'
                  AND COALESCE(same_order_lines.odoo_status_label, '') NOT IN ('cancelled', 'refunded')
                GROUP BY same_order_lines.store_id, same_order_lines.odoo_order_id
            ),
            line_rows AS (
                SELECT page_rows.*,
                       COALESCE(duplicate_counts.duplicate_asin_count, 0) AS duplicate_asin_count,
                       COALESCE(inventory_counts.inventory_quantity, 0) AS inventory_quantity,
                       COALESCE(order_asin_counts.odoo_order_distinct_asin_count, 0) AS odoo_order_distinct_asin_count
                FROM page_rows
                LEFT JOIN duplicate_counts
                  ON duplicate_counts.store_id = page_rows.store_id
                 AND duplicate_counts.asin = page_rows.asin
                LEFT JOIN inventory_counts
                  ON inventory_counts.store_id = page_rows.store_id
                 AND inventory_counts.asin = page_rows.asin
                LEFT JOIN order_asin_counts
                  ON order_asin_counts.store_id = page_rows.store_id
                 AND order_asin_counts.odoo_order_id = page_rows.odoo_order_id
            )
            SELECT
                (SELECT COALESCE(JSON_AGG(ROW_TO_JSON(stores_cte)), '[]'::json) FROM stores_cte) AS stores,
                (SELECT COALESCE(JSON_AGG(ROW_TO_JSON(a)), '[]'::json) FROM (SELECT * FROM fulfilment_addresses ORDER BY is_default DESC, label) a) AS addresses,
                (SELECT COALESCE(JSON_AGG(ROW_TO_JSON(ac)), '[]'::json) FROM (SELECT * FROM amazon_accounts ORDER BY is_default DESC, name) ac) AS amazon_accounts,
                (SELECT COALESCE(JSON_AGG(ROW_TO_JSON(p)), '[]'::json) FROM (SELECT * FROM punchout_return_urls ORDER BY is_default DESC, label) p) AS punchout_return_urls,
                (SELECT COALESCE(JSON_AGG(TO_JSONB(line_rows) - 'sort_order' ORDER BY sort_order, odoo_order_id DESC, id ASC), '[]'::json) FROM line_rows) AS rows,
                (SELECT COUNT(DISTINCT store_id || ':' || odoo_order_id) FROM order_lines WHERE ((SELECT store_id FROM chosen) IS NULL OR store_id=(SELECT store_id FROM chosen)) AND odoo_order_id IS NOT NULL) AS total,
                (SELECT COALESCE(JSON_AGG(ROW_TO_JSON(c)), '[]'::json) FROM (
                    SELECT state, COUNT(*) AS count
                    FROM order_lines
                    WHERE ((SELECT store_id FROM chosen) IS NULL OR store_id=(SELECT store_id FROM chosen))
                    GROUP BY state
                ) c) AS counts,
                (SELECT store_id FROM chosen) AS current_store_id,
                (SELECT value FROM app_settings WHERE key='default_ordering_engine') AS default_ordering_engine,
                (SELECT value FROM app_settings WHERE key='pull_orders_days') AS pull_orders_days,
                (SELECT value FROM app_settings WHERE key='pull_orders_limit') AS pull_orders_limit,
                (SELECT value FROM app_settings WHERE key='pull_orders_batch_size') AS pull_orders_batch_size
            """
            ,
            (store_id, per_page, offset),
        ).fetchone()
    stores = payload.get("stores") or []
    addresses = payload.get("addresses") or []
    amazon_accounts = payload.get("amazon_accounts") or []
    punchout_return_urls = payload.get("punchout_return_urls") or []
    current_store_id = payload.get("current_store_id")
    row_dicts = payload.get("rows") or []
    stores_by_id = {store["id"]: store for store in stores}
    row_dicts = backfill_missing_order_dates(row_dicts)
    attach_shopify_status_to_rows(row_dicts)
    for row in row_dicts:
        store = stores_by_id.get(row.get("store_id"))
        row["store_name"] = store.get("name") if store else ""
        row["odoo_order_url"] = odoo_order_admin_url(store, row.get("odoo_order_id")) if store else ""
        country_code, country_name, country_display = destination_country_from_row(row)
        row["destination_country_code"] = country_code
        row["destination_country_name"] = country_name
        row["destination_country"] = country_display
        if row.get("amazon_order_id") and not row.get("amazon_order_url"):
            row["amazon_order_url"] = order_line_amazon_url(row["amazon_order_id"])
    return {
        "stores": rows_to_dicts(stores),
        "current_store_id": current_store_id,
        "rows": row_dicts,
        "page": page,
        "per_page": per_page,
        "total": int(payload.get("total") or 0),
        "counts": payload.get("counts") or [],
        "addresses": addresses,
        "amazon_accounts": amazon_accounts,
        "punchout_return_urls": punchout_return_urls,
        "duplicate_asins": [],
        "duplicate_asins_page": 1,
        "duplicate_asins_per_page": 12,
        "duplicate_asins_total": 0,
        "default_ordering_engine": normalize_ordering_engine(str(payload.get("default_ordering_engine") or "rest")),
        "pull_orders_days": int(payload.get("pull_orders_days") or DEFAULT_SERVICE_SETTINGS.get("pull_orders_days", "7") or 7),
        "pull_orders_limit": normalize_pull_limit(payload.get("pull_orders_limit") or DEFAULT_SERVICE_SETTINGS.get("pull_orders_limit", "0"), 0),
        "pull_orders_batch_size": normalize_pull_batch_size(payload.get("pull_orders_batch_size") or DEFAULT_SERVICE_SETTINGS.get("pull_orders_batch_size", "50")),
        "system": system_diagnostics(),
    }


def order_lines_page_data(store_id: Optional[int] = None, page: int = 1, per_page: int = 100, sort_by: str = "odoo_order_date", sort_dir: str = "desc", country: str = "") -> dict[str, Any]:
    page, per_page, offset = pagination_bounds(page, per_page)
    order_by_sql = order_sort_sql(sort_by, sort_dir)
    store_clause, params, _ = order_condition_sql("all", store_id, country)
    with db() as conn:
        rows = conn.execute(
            f"""
            SELECT {ORDER_LINE_PAGE_SELECT}
            FROM order_lines
            {store_clause}
            ORDER BY {order_by_sql}
            LIMIT ? OFFSET ?
            """,
            [*params, per_page, offset],
        ).fetchall()
        count_cache_key = ("orders-count", store_id, clean_text(country))
        total = fast_page_cache_get(count_cache_key)
        if total is None:
            total_row = conn.execute(
                f"SELECT COUNT(*) AS total FROM order_lines {store_clause}",
                params,
            ).fetchone()
            total = int(total_row["total"] if total_row else 0)
            fast_page_cache_set(count_cache_key, total, 300)
        row_dicts = hydrate_order_line_rows(rows, conn=conn, include_metrics=False, include_shopify=False)
    return {
        "rows": row_dicts,
        "page": page,
        "per_page": per_page,
        "total": int(total or 0),
    }


