def enrich_order_line_page_metrics(conn: Any, rows: list[dict[str, Any]]) -> None:
    if not conn or not rows:
        return
    metric_fields = ("duplicate_asin_count", "inventory_quantity", "odoo_order_distinct_asin_count")
    if all(all(field in row for field in metric_fields) for row in rows):
        return
    for row in rows:
        row.setdefault("duplicate_asin_count", 0)
        row.setdefault("inventory_quantity", 0)
        row.setdefault("odoo_order_distinct_asin_count", 0)

    page_asins = sorted({
        (int(row.get("store_id") or 0), clean_text(row.get("asin")))
        for row in rows
        if int(row.get("store_id") or 0) > 0 and clean_text(row.get("asin"))
    })
    if page_asins:
        asin_store_ids = [store_id for store_id, _asin in page_asins]
        asin_values = [asin for _store_id, asin in page_asins]
        duplicate_rows = rows_to_dicts(conn.execute(
            """
            SELECT duplicate_lines.store_id,
                   duplicate_lines.asin,
                   COUNT(*) AS duplicate_asin_count
            FROM order_lines AS duplicate_lines
            JOIN UNNEST(?::int[], ?::text[]) AS page_asins(store_id, asin)
              ON page_asins.store_id=duplicate_lines.store_id
             AND page_asins.asin=duplicate_lines.asin
            WHERE COALESCE(duplicate_lines.amazon_order_id, '') = ''
              AND COALESCE(duplicate_lines.odoo_status_label, '') NOT IN ('cancelled', 'refunded')
            GROUP BY duplicate_lines.store_id, duplicate_lines.asin
            """,
            (asin_store_ids, asin_values),
        ).fetchall())
        duplicate_by_key = {
            (int(row["store_id"]), clean_text(row["asin"])): int(row["duplicate_asin_count"] or 0)
            for row in duplicate_rows
        }
        inventory_rows = rows_to_dicts(conn.execute(
            """
            SELECT inventory_items.store_id,
                   inventory_items.asin,
                   SUM(inventory_items.quantity) AS inventory_quantity
            FROM inventory_items
            JOIN UNNEST(?::int[], ?::text[]) AS page_asins(store_id, asin)
              ON page_asins.store_id=inventory_items.store_id
             AND page_asins.asin=inventory_items.asin
            WHERE inventory_items.status='available'
            GROUP BY inventory_items.store_id, inventory_items.asin
            """,
            (asin_store_ids, asin_values),
        ).fetchall())
        inventory_by_key = {
            (int(row["store_id"]), clean_text(row["asin"])): float(row["inventory_quantity"] or 0)
            for row in inventory_rows
        }
        for row in rows:
            key = (int(row.get("store_id") or 0), clean_text(row.get("asin")))
            row["duplicate_asin_count"] = duplicate_by_key.get(key, 0)
            row["inventory_quantity"] = inventory_by_key.get(key, 0)

    order_keys = sorted({
        (int(row.get("store_id") or 0), int(row.get("odoo_order_id") or 0))
        for row in rows
        if int(row.get("store_id") or 0) > 0 and int(row.get("odoo_order_id") or 0) > 0
    })
    if order_keys:
        order_store_ids = [store_id for store_id, _order_id in order_keys]
        order_ids = [order_id for _store_id, order_id in order_keys]
        count_rows = rows_to_dicts(conn.execute(
            """
            SELECT same_order_lines.store_id,
                   same_order_lines.odoo_order_id,
                   COUNT(DISTINCT same_order_lines.asin) AS odoo_order_distinct_asin_count
            FROM order_lines AS same_order_lines
            JOIN UNNEST(?::int[], ?::bigint[]) AS page_orders(store_id, odoo_order_id)
              ON page_orders.store_id=same_order_lines.store_id
             AND page_orders.odoo_order_id=same_order_lines.odoo_order_id
            WHERE COALESCE(same_order_lines.asin, '') != ''
              AND same_order_lines.state != 'missing'
              AND COALESCE(same_order_lines.odoo_status_label, '') NOT IN ('cancelled', 'refunded')
            GROUP BY same_order_lines.store_id, same_order_lines.odoo_order_id
            """,
            (order_store_ids, order_ids),
        ).fetchall())
        counts_by_key = {
            (int(row["store_id"]), int(row["odoo_order_id"])): int(row["odoo_order_distinct_asin_count"] or 0)
            for row in count_rows
        }
        for row in rows:
            key = (int(row.get("store_id") or 0), int(row.get("odoo_order_id") or 0))
            row["odoo_order_distinct_asin_count"] = counts_by_key.get(key, 0)


def hydrate_order_line_rows(
    rows: list[dict[str, Any]],
    stores: Optional[list[dict[str, Any]]] = None,
    conn: Optional[Any] = None,
    include_metrics: bool = True,
    include_shopify: bool = True,
) -> list[dict[str, Any]]:
    row_dicts = rows_to_dicts(rows)
    for row in row_dicts:
        row.setdefault("duplicate_asin_count", 0)
        row.setdefault("inventory_quantity", 0)
        row.setdefault("odoo_order_distinct_asin_count", 0)
    if conn is not None and include_metrics:
        enrich_order_line_page_metrics(conn, row_dicts)
    if stores is None and conn is not None:
        try:
            stores = rows_to_dicts(conn.execute("SELECT * FROM stores ORDER BY name").fetchall())
        except Exception:
            stores = None
    stores = stores or rows_to_dicts(list_stores())
    stores_by_id = {store["id"]: store for store in stores}
    row_dicts = backfill_missing_order_dates(row_dicts)
    if include_shopify:
        attach_shopify_status_to_rows(row_dicts, conn)
    else:
        for row in row_dicts:
            row.setdefault("shopify_order_id", "")
            row.setdefault("shopify_order_name", "")
            row.setdefault("shopify_order_url", "")
            row.setdefault("shopify_financial_status", "")
            row.setdefault("shopify_fulfillment_status", "")
            row.setdefault("shopify_fulfillment_at", "")
            row.setdefault("shopify_cancelled_at", "")
            row.setdefault("shopify_synced_at", "")
    for row in row_dicts:
        store = stores_by_id.get(row.get("store_id"))
        row["store_name"] = store.get("name") if store else ""
        row["odoo_order_url"] = odoo_order_admin_url(store, row.get("odoo_order_id")) if store else ""
        country_code, country_name, country_display = destination_country_from_row(row)
        row["destination_country_code"] = country_code
        row["destination_country_name"] = country_name
        row["destination_country"] = country_display
        if row.get("amazon_order_id") and not row.get("amazon_order_url"):
            row["amazon_order_url"] = order_line_amazon_url(row["amazon_order_id"])
    return row_dicts


def order_line_search_select_sql(where_sql: str) -> str:
    return f"""
        SELECT order_lines.*,
               COALESCE((
                   SELECT COUNT(*)
                   FROM order_lines AS duplicate_lines
                   WHERE duplicate_lines.store_id = order_lines.store_id
                     AND duplicate_lines.asin = order_lines.asin
                     AND COALESCE(duplicate_lines.amazon_order_id, '') = ''
                     AND COALESCE(duplicate_lines.odoo_status_label, '') NOT IN ('cancelled', 'refunded')
               ), 0) AS duplicate_asin_count,
               COALESCE((
                   SELECT SUM(quantity)
                   FROM inventory_items
                   WHERE inventory_items.store_id = order_lines.store_id
                     AND inventory_items.asin = order_lines.asin
                     AND inventory_items.status = 'available'
               ), 0) AS inventory_quantity,
               COALESCE((
                   SELECT COUNT(DISTINCT same_order_lines.asin)
                   FROM order_lines AS same_order_lines
                   WHERE same_order_lines.store_id = order_lines.store_id
                     AND same_order_lines.odoo_order_id = order_lines.odoo_order_id
                     AND COALESCE(same_order_lines.asin, '') != ''
                     AND same_order_lines.state != 'missing'
                     AND COALESCE(same_order_lines.odoo_status_label, '') NOT IN ('cancelled', 'refunded')
               ), 0) AS odoo_order_distinct_asin_count
        FROM order_lines
        {where_sql}
    """


def order_lines_by_ids(ids: list[int], stores: Optional[list[dict[str, Any]]] = None) -> list[dict[str, Any]]:
    if not ids:
        return []
    with db() as conn:
        rows = conn.execute(
            f"""
            WITH matched(id, sort_order) AS (
                SELECT * FROM UNNEST(?::int[]) WITH ORDINALITY
            )
            SELECT {qualified_order_line_page_select("order_lines")}
            FROM order_lines
            JOIN matched ON matched.id = order_lines.id
            ORDER BY matched.sort_order
            """,
            (ids,),
        ).fetchall()
        return hydrate_order_line_rows(rows, stores, conn=conn, include_metrics=False, include_shopify=False)


def is_exact_order_reference_query(query: str) -> bool:
    clean_query = clean_text(query).upper()
    return bool(ORDER_REF_RE.fullmatch(clean_query) or re.fullmatch(r"\d{3}-\d{7}-\d{7}", clean_query))


def fast_exact_order_reference_search(
    query: str,
    store_id: Optional[int],
    page: int = 1,
    per_page: int = 100,
    sort_by: str = "odoo_order_date",
    sort_dir: str = "desc",
    condition: str = "all",
    country: str = "",
) -> Optional[dict[str, Any]]:
    clean_query = clean_text(query)
    if not is_exact_order_reference_query(clean_query):
        return None
    page, per_page, offset = pagination_bounds(page, per_page)
    order_by_sql = order_sort_sql(sort_by, sort_dir)
    condition_where_sql, condition_params, _ = order_condition_sql(condition, store_id, country)
    condition_suffix = condition_where_sql.removeprefix("WHERE ").strip()
    exact_columns = ("odoo_order_name", "amazon_order_id", "amazon_cancelled_order_id")
    exact_clause = " OR ".join(f"UPPER(COALESCE(order_lines.{column}, '')) = UPPER(?)" for column in exact_columns)
    params: list[Any] = [*condition_params, *[clean_query for _ in exact_columns]]
    where_sql = f"WHERE ({condition_suffix}) AND ({exact_clause})"
    with db() as conn:
        rows = conn.execute(
            f"""
            WITH filtered_order_lines AS (
                SELECT order_lines.*
                FROM order_lines
                {where_sql}
            ),
            total_match AS (
                SELECT COUNT(DISTINCT filtered_order_lines.store_id || ':' || filtered_order_lines.odoo_order_id) AS count
                FROM filtered_order_lines
            )
            SELECT filtered_order_lines.*,
                   total_match.count AS _total_count,
                   0 AS duplicate_asin_count,
                   0 AS inventory_quantity,
                   COALESCE((
                       SELECT COUNT(DISTINCT same_order_lines.asin)
                       FROM order_lines AS same_order_lines
                       WHERE same_order_lines.store_id = filtered_order_lines.store_id
                         AND same_order_lines.odoo_order_id = filtered_order_lines.odoo_order_id
                         AND COALESCE(same_order_lines.asin, '') != ''
                         AND same_order_lines.state != 'missing'
                         AND COALESCE(same_order_lines.odoo_status_label, '') NOT IN ('cancelled', 'refunded')
                   ), 0) AS odoo_order_distinct_asin_count,
                   stores.name AS _store_name,
                   stores.odoo_url AS _store_odoo_url,
                   stores.odoo_db AS _store_odoo_db,
                   stores.odoo_user AS _store_odoo_user,
                   stores.website_id AS _store_website_id,
                   shopify_status.shopify_order_id AS _shopify_order_id,
                   shopify_status.shopify_order_name AS _shopify_order_name,
                   shopify_status.shopify_order_url AS _shopify_order_url,
                   shopify_status.financial_status AS _shopify_financial_status,
                   shopify_status.fulfillment_status AS _shopify_fulfillment_status,
                   shopify_status.fulfillment_at AS _shopify_fulfillment_at,
                   shopify_status.cancelled_at AS _shopify_cancelled_at,
                   shopify_status.synced_at AS _shopify_synced_at
            FROM filtered_order_lines
            CROSS JOIN total_match
            LEFT JOIN stores ON stores.id = filtered_order_lines.store_id
            LEFT JOIN LATERAL (
                SELECT *
                FROM shopify_order_status_cache
                WHERE shopify_order_status_cache.store_id = filtered_order_lines.store_id
                  AND UPPER(shopify_order_status_cache.odoo_order_name)=UPPER(filtered_order_lines.odoo_order_name)
                ORDER BY
                  CASE WHEN COALESCE(cancelled_at, '') = '' THEN 0 ELSE 1 END,
                  CASE WHEN fulfillment_status ILIKE '%FULFILLED%' THEN 0 ELSE 1 END,
                  synced_at DESC
                LIMIT 1
            ) AS shopify_status ON TRUE
            ORDER BY {order_by_sql}
            LIMIT ? OFFSET ?
            """,
            [*params, per_page, offset],
        ).fetchall()
    if not rows:
        return None
    row_dicts = rows_to_dicts(rows)
    total = int(row_dicts[0].pop("_total_count", 0) or 0)
    for row in row_dicts:
        row.pop("_total_count", None)
        store = {
            "id": row.get("store_id"),
            "name": row.pop("_store_name", "") or "",
            "odoo_url": row.pop("_store_odoo_url", "") or "",
            "odoo_db": row.pop("_store_odoo_db", "") or "",
            "odoo_user": row.pop("_store_odoo_user", "") or "",
            "website_id": row.pop("_store_website_id", "") or "",
        }
        row["store_name"] = store["name"]
        row["odoo_order_url"] = odoo_order_admin_url(store, row.get("odoo_order_id")) if store.get("odoo_url") else ""
        row["shopify_order_id"] = clean_text(row.pop("_shopify_order_id", ""))
        row["shopify_order_name"] = clean_text(row.pop("_shopify_order_name", ""))
        row["shopify_order_url"] = clean_text(row.pop("_shopify_order_url", ""))
        row["shopify_financial_status"] = clean_text(row.pop("_shopify_financial_status", ""))
        row["shopify_fulfillment_status"] = clean_text(row.pop("_shopify_fulfillment_status", ""))
        row["shopify_fulfillment_at"] = clean_text(row.pop("_shopify_fulfillment_at", ""))
        row["shopify_cancelled_at"] = clean_text(row.pop("_shopify_cancelled_at", ""))
        row["shopify_synced_at"] = clean_text(row.pop("_shopify_synced_at", ""))
        country_code, country_name, country_display = destination_country_from_row(row)
        row["destination_country_code"] = country_code
        row["destination_country_name"] = country_name
        row["destination_country"] = country_display
        if row.get("amazon_order_id") and not row.get("amazon_order_url"):
            row["amazon_order_url"] = order_line_amazon_url(row["amazon_order_id"])
    return {
        "rows": row_dicts,
        "page": page,
        "per_page": per_page,
        "total": total,
        "search_engine": "postgres_exact",
    }


def search_order_lines_sql(
    query: str,
    store_id: Optional[int],
    page: int = 1,
    per_page: int = 100,
    sort_by: str = "pulled_at",
    sort_dir: str = "desc",
    condition: str = "all",
    country: str = "",
) -> dict[str, Any]:
    page, per_page, offset = pagination_bounds(page, per_page)
    clean_query = query.strip()
    if not clean_query:
        return order_lines_condition_page_data(store_id, page, per_page, condition, sort_by, sort_dir, country)
    exact_result = fast_exact_order_reference_search(clean_query, store_id, page, per_page, sort_by, sort_dir, condition, country)
    if exact_result is not None:
        return exact_result
    order_by_sql = order_sort_sql(sort_by, sort_dir)
    condition_where_sql, condition_params, _ = order_condition_sql(condition, store_id, country)
    condition_suffix = condition_where_sql.removeprefix("WHERE ").strip()
    exact_columns = (
        "odoo_order_name",
        "amazon_order_id",
        "amazon_cancelled_order_id",
        "asin",
        "missing_asin",
        "replacement_asin",
        "supplier_part_auxiliary_id",
        "default_code",
    )
    exact_clause = " OR ".join(f"UPPER(COALESCE({column}, '')) = UPPER(?)" for column in exact_columns)
    exact_params: list[Any] = [*condition_params, *[clean_query for _ in exact_columns]]
    exact_where_sql = f"WHERE ({condition_suffix}) AND ({exact_clause})"
    with db() as conn:
        exact_total = int(conn.execute(
            f"SELECT COUNT(DISTINCT store_id || ':' || odoo_order_id) AS count FROM order_lines {exact_where_sql}",
            exact_params,
        ).fetchone()["count"] or 0)
        if exact_total:
            rows = conn.execute(
                f"""
                {order_line_search_select_sql(exact_where_sql)}
                ORDER BY {order_by_sql}
                LIMIT ? OFFSET ?
                """,
                [*exact_params, per_page, offset],
            ).fetchall()
            return {
                "rows": hydrate_order_line_rows(rows),
                "page": page,
                "per_page": per_page,
                "total": exact_total,
            }

    term = f"%{clean_query}%"
    search_clause = " OR ".join(f"COALESCE({column}, '') ILIKE ?" for column in ORDER_LINE_SEARCH_COLUMNS)
    params: list[Any] = [*condition_params, *[term for _ in ORDER_LINE_SEARCH_COLUMNS]]
    where_sql = f"WHERE ({condition_suffix}) AND ({search_clause})"
    with db() as conn:
        total = int(conn.execute(
            f"SELECT COUNT(DISTINCT store_id || ':' || odoo_order_id) AS count FROM order_lines {where_sql}",
            params,
        ).fetchone()["count"] or 0)
        rows = conn.execute(
            f"""
            {order_line_search_select_sql(where_sql)}
            ORDER BY {order_by_sql}
            LIMIT ? OFFSET ?
            """,
            [*params, per_page, offset],
        ).fetchall()
    return {
        "rows": hydrate_order_line_rows(rows),
        "page": page,
        "per_page": per_page,
        "total": total,
    }


def sql_rows_by_ids(table: str, ids: list[Any], id_column: str = "id", order_by: str = "") -> list[dict[str, Any]]:
    if not ids:
        return []
    with db() as conn:
        rows = conn.execute(
            f"""
            WITH matched(id, sort_order) AS (
                SELECT * FROM UNNEST(?::text[]) WITH ORDINALITY
            )
            SELECT {table}.*
            FROM {table}
            JOIN matched ON matched.id = {table}.{id_column}::text
            ORDER BY {order_by or "matched.sort_order"}
            """,
            ([str(value) for value in ids],),
        ).fetchall()
    return rows_to_dicts(rows)


def line_filter_for_typesense(store_id: Optional[int] = None, state: str = "", since_ts: int = 0) -> str:
    filters = []
    if store_id:
        filters.append(f"store_id:={int(store_id)}")
    if state:
        filters.append(f"state:={state}")
    if since_ts:
        filters.append(f"order_date_ts:>={int(since_ts)}")
    return " && ".join(filters)


def typesense_order_line_ids_for_filter(filter_by: str, limit: int = 50000, query: str = "*") -> list[int]:
    settings = get_service_settings()
    if not typesense_enabled(settings):
        return []
    ensure_typesense_collection(settings)
    ids: list[int] = []
    page = 1
    per_page = 250
    while len(ids) < limit:
        params = {
            "q": query.strip() or "*",
            "query_by": "odoo_order_name,product_name,asin,amazon_order_id,amazon_status,amazon_account_name,tracking_status,fulfilment_note,last_error",
            "filter_by": filter_by,
            "page": str(page),
            "per_page": str(per_page),
            "sort_by": "order_date_ts:desc,updated_ts:desc",
            "prefix": "true",
            "infix": "always",
        }
        response = requests.get(
            f"{typesense_base(settings)}/collections/order_lines/documents/search",
            headers=typesense_headers(settings),
            params=params,
            timeout=8,
        )
        if response.status_code >= 400 and "infix" in response.text.lower():
            retry_params = dict(params)
            retry_params.pop("infix", None)
            response = requests.get(
                f"{typesense_base(settings)}/collections/order_lines/documents/search",
                headers=typesense_headers(settings),
                params=retry_params,
                timeout=8,
            )
        if response.status_code >= 400:
            raise RuntimeError(f"Typesense search failed for order_lines: HTTP {response.status_code}: {response.text[:500]}")
        payload = response.json()
        batch = [int((hit.get("document") or {}).get("row_id")) for hit in payload.get("hits") or [] if (hit.get("document") or {}).get("row_id")]
        if not batch:
            break
        ids.extend(batch)
        if len(ids) >= int(payload.get("found") or 0):
            break
        page += 1
    return ids[:limit]


def order_window_since_ts(days: int) -> int:
    days = normalize_days_window(days)
    cutoff = datetime.now(timezone.utc).date() - timedelta(days=days - 1)
    return int(datetime(cutoff.year, cutoff.month, cutoff.day, tzinfo=timezone.utc).timestamp())


def order_line_ids_for_state(store_id: Optional[int], state: str, page: int, per_page: int) -> dict[str, Any]:
    settings = get_service_settings()
    if not typesense_enabled(settings):
        return {"ids": [], "total": 0, "enabled": False}
    page, per_page, _ = pagination_bounds(page, per_page)
    ensure_typesense_collection(settings)
    params = {
        "q": "*",
        "query_by": "odoo_order_name,product_name,asin,amazon_order_id,last_error",
        "filter_by": line_filter_for_typesense(store_id, state),
        "page": str(page),
        "per_page": str(per_page),
        "sort_by": "updated_ts:desc,odoo_order_id:desc",
    }
    response = requests.get(
        f"{typesense_base(settings)}/collections/order_lines/documents/search",
        headers=typesense_headers(settings),
        params=params,
        timeout=8,
    )
    if response.status_code >= 400:
        raise RuntimeError(f"Typesense search failed for order_lines: HTTP {response.status_code}: {response.text[:500]}")
    payload = response.json()
    return {
        "ids": [int((hit.get("document") or {}).get("row_id")) for hit in payload.get("hits") or [] if (hit.get("document") or {}).get("row_id")],
        "total": int(payload.get("found") or 0),
        "enabled": True,
    }


@app.on_event("startup")
def startup() -> None:
    global _sync_thread_started, _SHOPIFY_STATUS_CACHE_ENSURED
    if not _sync_thread_started:
        _sync_thread_started = True

        def bootstrap_after_bind() -> None:
            global _SHOPIFY_STATUS_CACHE_ENSURED
            try:
                with db() as conn:
                    conn.execute("SELECT 1")
                ensure_shopify_order_status_cache_table()
                _SHOPIFY_STATUS_CACHE_ENSURED = True
                should_reindex_typesense = typesense_enabled() and get_setting("typesense_schema_version", "") != TYPESENSE_SCHEMA_VERSION
                threading.Thread(target=shopify_tracking_schedule_loop, daemon=True).start()
                threading.Thread(target=package_tracker_shopify_status_schedule_loop, daemon=True).start()
                threading.Thread(target=shopify_push_reconciliation_loop, daemon=True).start()
                threading.Thread(target=init_db, daemon=True).start()
                resume_interrupted_shopify_tracking_jobs()
                threading.Thread(target=backfill_cxml_order_references, daemon=True).start()
                threading.Thread(target=autosync_loop, daemon=True).start()
                threading.Thread(target=backup_loop, daemon=True).start()
                threading.Thread(target=amazon_otp_loop, daemon=True).start()
                threading.Thread(target=odoo_chatter_outbox_schedule_loop, daemon=True).start()
                threading.Thread(target=odoo_ordered_tag_reconciliation_loop, daemon=True).start()
                if should_reindex_typesense:
                    threading.Thread(target=start_typesense_reindex_job, daemon=True).start()
                threading.Thread(target=enqueue_dispatch_summary_warm, daemon=True).start()
                threading.Thread(target=enqueue_app_pages_warm, daemon=True).start()
                threading.Thread(target=lambda: api_tracking_fulfilment_pending(page=1, per_page=30), daemon=True).start()
                threading.Thread(target=lambda: api_tracking_payment_failures(page=1, per_page=20), daemon=True).start()
            except Exception as exc:
                print(f"Startup background bootstrap failed: {exc}", flush=True)

        threading.Thread(target=bootstrap_after_bind, daemon=True).start()


