@app.get("/api/search")
def api_search(q: str = "", store_id: Optional[int] = None, page: int = 1, per_page: int = 100, condition: str = "all", sort_by: str = "odoo_order_date", sort_dir: str = "desc", country: str = "") -> dict[str, Any]:
    page, per_page, _ = pagination_bounds(page, per_page)
    cache_key = ("search", clean_text(q), store_id, page, per_page, clean_text(condition), clean_text(sort_by), clean_text(sort_dir), clean_text(country))
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    filter_by, filtered = order_condition_filter(condition, store_id, country)
    if not q.strip() and not filtered:
        return fast_page_cache_set(cache_key, dashboard_data(store_id, page, per_page, sort_by, sort_dir), 60)
    exact_result = fast_exact_order_reference_search(q, store_id, page, per_page, sort_by, sort_dir, condition, country)
    if exact_result is not None:
        return fast_page_cache_set(cache_key, exact_result, 60)
    try:
        if filtered and not order_condition_uses_typesense(condition, country):
            raise RuntimeError("Postgres filter required for this condition.")
        search_result = typesense_search_order_lines(q or "*", store_id, page, per_page, filter_by=filter_by, sort_by=sort_by, sort_dir=sort_dir)
        ids = list(search_result.get("ids") or [])
        if search_result.get("enabled"):
            return fast_page_cache_set(cache_key, {
                "rows": order_lines_by_ids(ids),
                "page": page,
                "per_page": per_page,
                "total": int(search_result.get("total") or 0),
                "search_engine": "typesense",
            }, 45)
        if filtered:
            raise HTTPException(503, "Typesense is required for order condition filters.")
        search_warning = "Typesense is disabled or not configured; using Postgres fallback."
    except Exception as exc:
        if filtered:
            fallback = search_order_lines_sql(q, store_id, page, per_page, sort_by, sort_dir, condition, country)
            fallback["search_engine"] = "postgres"
            if order_condition_uses_typesense(condition, country):
                fallback["search_warning"] = f"Typesense order filter unavailable; using Postgres fallback: {exc}"
            return fast_page_cache_set(cache_key, fallback, 30)
        search_warning = str(exc)
    fallback = search_order_lines_sql(q, store_id, page, per_page, sort_by, sort_dir, condition, country)
    fallback["search_engine"] = "postgres"
    fallback["search_warning"] = search_warning
    return fast_page_cache_set(cache_key, fallback, 30)


def setting_elapsed_seconds(key: str, default_seconds: float = 0.0) -> float:
    parsed = parse_iso_date(get_setting(key, ""))
    if not parsed:
        return default_seconds
    return max(0.0, (datetime.now(timezone.utc) - parsed).total_seconds())


def queue_auto_pull_jobs(days: int, limit: int, batch_size: int) -> dict[str, Any]:
    stores = rows_to_dicts(list_stores())
    with db() as conn:
        mark_stale_pull_jobs(conn)
        active_rows = conn.execute(
            """
            SELECT pull_jobs.*, stores.name AS store_name
            FROM pull_jobs
            LEFT JOIN stores ON stores.id = pull_jobs.store_id
            WHERE pull_jobs.status IN ('queued', 'running')
            ORDER BY pull_jobs.created_at ASC
            """
        ).fetchall()
    if active_rows:
        return {
            "queued": 0,
            "active": len(active_rows),
            "stores": len(stores),
            "message": f"Auto pull skipped because {len(active_rows)} pull job{'s' if len(active_rows) != 1 else ''} are already running.",
        }
    jobs = start_pull_jobs([int(store["id"]) for store in stores], days, limit, batch_size)
    return {
        "queued": len(jobs),
        "active": 0,
        "stores": len(stores),
        "message": (
            f"Auto queued {len(jobs)} pull job{'s' if len(jobs) != 1 else ''} "
            f"for {len(stores)} store{'s' if len(stores) != 1 else ''} "
            f"using last {days} day{'s' if days != 1 else ''}, limit {'all' if limit == 0 else limit}, batch size {batch_size}."
        ),
    }


def autosync_loop() -> None:
    last_run = time.time()
    last_chrome_run = time.time()
    last_cancelled_run = time.time()
    last_epost_run = 0.0
    while True:
        try:
            settings = get_service_settings()
            interval = int(float(settings.get("autosync_interval_minutes") or 0))
            elapsed = max(time.time() - last_run, setting_elapsed_seconds("autosync_last_run_at", interval * 60))
            if interval > 0 and elapsed >= interval * 60:
                days = stored_pull_days(7)
                limit = auto_pull_limit(stored_pull_limit())
                batch_size = stored_pull_batch_size()
                result = queue_auto_pull_jobs(days, limit, batch_size)
                set_setting("autosync_last_message", result["message"])
                set_setting("autosync_last_run_at", utc_now())
                last_run = time.time()
            raw_chrome_interval = int(float(settings.get("auto_chrome_fulfil_interval_minutes") or 0))
            chrome_enabled = clean_text(settings.get("auto_chrome_fulfil_enabled")).lower() in {"1", "true", "yes", "on", "enabled"}
            chrome_interval = max(1, raw_chrome_interval or 5)
            chrome_elapsed = max(time.time() - last_chrome_run, setting_elapsed_seconds("auto_chrome_fulfil_last_run_at", chrome_interval * 60))
            if chrome_enabled and chrome_elapsed >= chrome_interval * 60:
                with _AUTO_CHROME_QUEUE_CONTROL_LOCK:
                    # Pause owns this same lock. Re-read after acquiring it so a
                    # scheduler pass observed before Pause cannot refill the queue.
                    if auto_chrome_ordering_enabled():
                        current_settings = get_service_settings()
                        days = max(1, min(30, int(float(current_settings.get("auto_chrome_fulfil_days") or 2))))
                        limit = max(1, min(500, int(float(current_settings.get("auto_chrome_fulfil_limit") or 100))))
                        minimum_age = max(1, min(1440, int(float(current_settings.get("auto_chrome_fulfil_minimum_age_minutes") or 60))))
                        start_date = normalized_auto_chrome_start_date(current_settings.get("auto_chrome_fulfil_start_date"))
                        queued_total = 0
                        skipped_total = 0
                        for store in list_stores():
                            store_id = int(store["id"])
                            pulled_count = fetch_odoo_lines_exclusive(get_store(store_id), days=days, limit=limit, wait=False)
                            if pulled_count:
                                start_typesense_reindex_job()
                            if pulled_count is not None:
                                queued, skipped = place_orders(
                                    store_id,
                                    ordering_engine="chrome",
                                    minimum_order_age_minutes=minimum_age,
                                    minimum_odoo_order_date=start_date,
                                )
                                queued_total += queued
                                skipped_total += skipped
                        set_setting("auto_chrome_fulfil_last_run_at", utc_now())
                        set_setting(
                            "auto_chrome_fulfil_last_message",
                            (
                                f"Queued {queued_total} whole order(s) dated {start_date or 'any date'} or later "
                                f"and at least {minimum_age} minutes old; skipped {skipped_total}."
                            ),
                        )
                        last_chrome_run = time.time()
            cancelled_interval = max(15, int(float(settings.get("cancelled_orders_sync_interval_minutes") or 15)))
            if time.time() - last_cancelled_run >= cancelled_interval * 60:
                days = max(1, min(365, int(float(settings.get("cancelled_orders_sync_days") or 30))))
                for store in list_stores():
                    sync_cancelled_orders_for_store(int(store["id"]), days=days)
                last_cancelled_run = time.time()
            if time.time() - last_epost_run >= EPOST_NEW_CODE_SYNC_INTERVAL_MINUTES * 60:
                try:
                    result = sync_epost_tracking_and_final_mile(
                        days=7,
                        refresh_hours=EPOST_STATUS_REFRESH_INTERVAL_HOURS,
                    )
                    set_setting(
                        "epost_auto_sync_last_message",
                        (
                            f"Imported {result['synced']} new EPG shipments from {result['scanned']} recent Odoo records; "
                            f"refreshed {result['checked']} tracking records, {result['found']} with final-mile details, "
                            f"failed {result['failed']}. New-code scan: {EPOST_NEW_CODE_SYNC_INTERVAL_MINUTES} minutes; "
                            f"status refresh: {EPOST_STATUS_REFRESH_INTERVAL_HOURS} hours."
                        ),
                    )
                    set_setting("epost_auto_sync_last_run_at", utc_now())
                except Exception as exc:
                    set_setting("epost_auto_sync_last_message", f"Automatic EPG sync failed: {str(exc)[:400]}")
                last_epost_run = time.time()
        except Exception:
            pass
        time.sleep(60)


def s3_endpoint_base(endpoint: str) -> str:
    value = clean_text(endpoint).rstrip("/")
    parsed = urlsplit(value)
    if not parsed.scheme or not parsed.netloc:
        return value
    path = parsed.path.rstrip("/")
    parent_path = path.rsplit("/", 1)[0] if path else ""
    return f"{parsed.scheme}://{parsed.netloc}{parent_path}"


