@app.post("/api/cancelled-orders/sync")
def api_cancelled_orders_sync(payload: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    payload = payload or {}
    store_id = parse_optional_int(payload.get("store_id"))
    days = max(1, min(365, int(float(payload.get("days") or get_service_settings().get("cancelled_orders_sync_days") or 30))))
    stores = [get_store(store_id)] if store_id else list_stores()
    results = []
    total_updated = 0
    total_shopify_cancelled = 0
    total_shopify_failed = 0
    total_shopify_protected = 0
    for store in stores:
        result = sync_cancelled_orders_for_store(int(store["id"]), days=days)
        results.append(result)
        total_updated += int(result.get("updated") or 0)
        total_shopify_cancelled += int(result.get("shopify_cancelled") or 0)
        total_shopify_failed += int(result.get("shopify_failed") or 0)
        total_shopify_protected += int(result.get("shopify_protected") or 0)
    rows, total = list_cancelled_order_lines(store_id, 1, 100)
    stores_payload = rows_to_dicts(list_stores())
    for store in stores_payload:
        if store.get("odoo_password"):
            store["odoo_password"] = "********"
    return {
        "ok": total_shopify_failed == 0 and total_shopify_protected == 0,
        "message": (
            f"Cancelled order sync complete. Updated {total_updated} app line(s), cancelled "
            f"{total_shopify_cancelled} Shopify order(s), failed {total_shopify_failed}, "
            f"manual review {total_shopify_protected}."
        ),
        "results": results,
        "rows": cancelled_order_rows_payload(rows, stores_payload),
        "page": 1,
        "per_page": 100,
        "total": total,
    }


@app.post("/api/inventory")
def api_create_inventory(payload: dict[str, Any]) -> dict[str, Any]:
    store_id = int(payload.get("store_id") or 0)
    if not store_id:
        raise HTTPException(400, "Store is required.")
    asin = normalize_asin(str(payload.get("asin") or ""))
    odoo_order_name = clean_text(payload.get("odoo_order_name"))
    amazon_order_id = clean_text(payload.get("amazon_order_id"))
    matched_line = None
    if odoo_order_name or amazon_order_id:
        clauses = ["store_id=?"]
        params: list[Any] = [store_id]
        if odoo_order_name:
            clauses.append("UPPER(odoo_order_name)=UPPER(?)")
            params.append(odoo_order_name)
        if amazon_order_id:
            clauses.append("amazon_order_id=?")
            params.append(amazon_order_id)
        with db() as conn:
            candidates = rows_to_dicts(conn.execute(
                f"""
                SELECT *
                FROM order_lines
                WHERE {' AND '.join(clauses)}
                ORDER BY updated_at DESC, id DESC
                LIMIT 50
                """,
                params,
            ).fetchall())
        if asin:
            matched_line = next((row for row in candidates if normalize_asin(row.get("asin") or "") == asin), None)
        elif candidates:
            asins = sorted({normalize_asin(row.get("asin") or "") for row in candidates if normalize_asin(row.get("asin") or "")})
            if len(asins) == 1:
                asin = asins[0]
                matched_line = candidates[0]
            else:
                raise HTTPException(400, "Enter ASIN too because the Odoo/Amazon reference has multiple items.")
    if not asin:
        raise HTTPException(400, "ASIN is required.")
    quantity = float(payload.get("quantity") or 0)
    if not quantity and matched_line:
        quantity = float(matched_line.get("quantity") or 0)
    if quantity <= 0:
        raise HTTPException(400, "Quantity must be greater than zero.")
    page_image_url = amazon_product_page_image_url(asin)
    product_name = clean_text(payload.get("product_name")) or (clean_text(matched_line.get("product_name")) if matched_line else "")
    notes = clean_text(payload.get("notes"))
    amazon_order_url = clean_text(payload.get("amazon_order_url")) or (clean_text(matched_line.get("amazon_order_url")) if matched_line else "") or (order_line_amazon_url(amazon_order_id) if amazon_order_id else "")
    amazon_account_name = clean_text(payload.get("amazon_account_name")) or (clean_text(matched_line.get("amazon_account_name")) if matched_line else "")
    source_odoo_order_id = int(matched_line.get("odoo_order_id") or 0) if matched_line else None
    source_odoo_order_name = odoo_order_name or (clean_text(matched_line.get("odoo_order_name")) if matched_line else "")
    manual_reference = f"manual-{uuid.uuid4().hex[:10]}"
    with db() as conn:
        cursor = conn.execute(
            f"""
            INSERT INTO inventory_items
            (store_id, order_line_id, asin, quantity, product_name, source_odoo_order_id, source_odoo_order_name,
             amazon_order_id, amazon_order_url, amazon_account_name, image_url, image_source, status, source_type, notes, manual_reference, created_at, updated_at)
            VALUES (?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'available', 'manual', ?, ?, ?, ?)
            RETURNING id
            """,
            (
                store_id,
                asin,
                quantity,
                product_name,
                source_odoo_order_id,
                source_odoo_order_name,
                amazon_order_id,
                amazon_order_url,
                amazon_account_name,
                page_image_url,
                "amazon_page" if page_image_url else "",
                notes,
                manual_reference,
                utc_now(),
                utc_now(),
            ),
        )
        inserted = cursor.fetchone()
        if not inserted:
            row = conn.execute(
                "SELECT * FROM inventory_items WHERE store_id=? AND manual_reference=? ORDER BY id DESC LIMIT 1",
                (store_id, manual_reference),
            ).fetchone()
        else:
            row = conn.execute("SELECT * FROM inventory_items WHERE id=?", (inserted["id"],)).fetchone()
    if row:
        _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(row) or {}: _index_named_document_sync("inventory_items", inventory_search_document(snapshot)))
    return {"ok": True, "message": f"Added {quantity:g} inventory unit(s) for {asin}.", **refresh_inventory_response(store_id, 1, 100)}


@app.post("/api/inventory/{inventory_id}/attach")
def api_attach_inventory_item(inventory_id: int, payload: dict[str, Any]) -> dict[str, Any]:
    order_ref = clean_text(payload.get("order_ref") or payload.get("odoo_order_name"))
    if not order_ref:
        raise HTTPException(400, "Enter the new Odoo order name to attach this inventory item.")
    with db() as conn:
        item = conn.execute("SELECT * FROM inventory_items WHERE id=? FOR UPDATE", (inventory_id,)).fetchone()
        if not item:
            raise HTTPException(404, "Inventory item not found.")
        if clean_text(item["status"]) == "used":
            raise HTTPException(400, "This inventory item has already been used.")
        if clean_text(item["status"]) == "reserved":
            raise HTTPException(400, "This inventory item is already attached to an order.")
        asin = normalize_asin(item["asin"])
        candidates = conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE store_id=?
              AND UPPER(odoo_order_name)=UPPER(?)
              AND asin=?
              AND state NOT IN ('ordered', 'dispatched', 'delivered', 'inventory', 'ignored')
              AND COALESCE(odoo_status_label, '') NOT IN ('cancelled', 'refunded')
            ORDER BY id ASC
            FOR UPDATE
            """,
            (item["store_id"], order_ref, asin),
        ).fetchall()
        if not candidates:
            raise HTTPException(404, f"No open order line with ASIN {asin} found for {order_ref}.")
        line = candidates[0]
        quantity_needed = float(line["quantity"] or 1)
        quantity_available = float(item["quantity"] or 0)
        already_allocated = max(0.0, float(line.get("inventory_allocated_quantity") or 0))
        quantity_remaining = max(0.0, quantity_needed - already_allocated)
        reserved_quantity = min(quantity_available, quantity_remaining)
        if reserved_quantity <= 0:
            raise HTTPException(400, f"{order_ref} already has its required inventory quantity allocated.")
        allocated_quantity = already_allocated + reserved_quantity
        amazon_quantity = max(0.0, quantity_needed - allocated_quantity)
        inventory_only = amazon_quantity <= 0
        note = (
            f"Attached inventory item #{inventory_id} to {line['odoo_order_name']}: "
            f"qty {reserved_quantity:g} allocated; total local qty {allocated_quantity:g} of {quantity_needed:g}; "
            f"Amazon remaining qty {amazon_quantity:g}. Manually verify dispatch, then confirm sent from Inventory."
        )
        now = utc_now()
        conn.execute(
            "UPDATE inventory_items SET quantity=?, updated_at=? WHERE id=?",
            (max(0.0, quantity_available - reserved_quantity), now, inventory_id),
        )
        inserted = conn.execute(
            """
            INSERT INTO inventory_items
            (store_id, order_line_id, asin, quantity, product_name, source_odoo_order_id, source_odoo_order_name,
             amazon_order_id, amazon_order_url, amazon_account_name, image_url, image_source,
             source_tracking_id, source_delivered_at, source_received_at, source_shopify_cancelled_at,
             source_odoo_status, source_inventory_item_id, status, source_type, notes, reserved_order_line_id,
             reserved_quantity, reserved_at, manual_reference, created_at, updated_at)
            SELECT store_id, NULL, asin, ?, product_name, source_odoo_order_id, source_odoo_order_name,
                   amazon_order_id, amazon_order_url, amazon_account_name, image_url, image_source,
                   source_tracking_id, source_delivered_at, source_received_at, source_shopify_cancelled_at,
                   source_odoo_status, id, 'reserved', source_type, ?, ?, ?, ?, ?, ?, ?
            FROM inventory_items WHERE id=?
            RETURNING id
            """,
            (
                reserved_quantity,
                append_note(item["notes"], note),
                line["id"],
                reserved_quantity,
                now,
                f"allocation-{uuid.uuid4().hex[:12]}",
                now,
                now,
                inventory_id,
            ),
        ).fetchone()
        reserved_inventory_id = int(inserted["id"])
        conn.execute(
            """
            UPDATE order_lines
            SET state=CASE WHEN ? THEN 'inventory' ELSE state END,
                order_engine=CASE WHEN ? THEN 'inventory' ELSE order_engine END,
                inventory_allocated_quantity=?,
                fulfilment_note=?,
                last_error=NULL,
                updated_at=?
            WHERE id=?
            """,
            (
                inventory_only,
                inventory_only,
                allocated_quantity,
                append_note(line["fulfilment_note"], note),
                now,
                line["id"],
            ),
        )
        updated_item = conn.execute("SELECT * FROM inventory_items WHERE id=?", (inventory_id,)).fetchone()
        updated_reserved_item = conn.execute("SELECT * FROM inventory_items WHERE id=?", (reserved_inventory_id,)).fetchone()
        updated_line = conn.execute("SELECT * FROM order_lines WHERE id=?", (line["id"],)).fetchone()
    if updated_item:
        _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(updated_item) or {}: _index_named_document_sync("inventory_items", inventory_search_document(snapshot)))
    if updated_reserved_item and reserved_inventory_id != inventory_id:
        _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(updated_reserved_item) or {}: _index_named_document_sync("inventory_items", inventory_search_document(snapshot)))
    if updated_line:
        index_order_line(updated_line)
        try:
            allocation_key = hashlib.sha256(note.encode("utf-8")).hexdigest()[:20]
            post_order_note_once(
                get_store(int(item["store_id"])),
                int(line["odoo_order_id"]),
                "inventory_allocated",
                f"manual-inventory-{allocation_key}",
                note,
            )
        except Exception as exc:
            print(f"Manual inventory Odoo note failed: {exc}", flush=True)
        if inventory_only:
            queued = enqueue_shopify_fulfilment_for_rows([dict(updated_line)])
            if queued:
                start_shopify_fulfilment_worker()
    return {
        "ok": True,
        "message": (
            f"Attached qty {reserved_quantity:g} from inventory item #{reserved_inventory_id} to {line['odoo_order_name']}. "
            f"Amazon remaining qty: {amazon_quantity:g}. Confirm sent after manual verification."
        ),
        **refresh_inventory_response(int(item["store_id"]), 1, 100),
    }


@app.post("/api/inventory/{inventory_id}/confirm-sent")
def api_confirm_inventory_sent(inventory_id: int, payload: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    with db() as conn:
        item = conn.execute("SELECT * FROM inventory_items WHERE id=? FOR UPDATE", (inventory_id,)).fetchone()
        if not item:
            raise HTTPException(404, "Inventory item not found.")
        if clean_text(item["status"]) == "used":
            return {"ok": True, "message": "Inventory item was already marked sent.", **refresh_inventory_response(int(item["store_id"]), 1, 100)}
        line = None
        if item["reserved_order_line_id"]:
            line = conn.execute("SELECT * FROM order_lines WHERE id=? FOR UPDATE", (item["reserved_order_line_id"],)).fetchone()
        if not line:
            raise HTTPException(400, "Attach this inventory item to a new order before confirming it was sent.")
        now = utc_now()
        reserved_quantity = float(item["reserved_quantity"] or line["quantity"] or item["quantity"] or 0)
        current_quantity = float(item["quantity"] or 0)
        remaining_quantity = max(0, current_quantity - reserved_quantity)
        sent_note = f"Inventory item #{inventory_id} manually verified sent for {line['odoo_order_name']}."
        if remaining_quantity > 0:
            conn.execute(
                """
                UPDATE inventory_items
                SET quantity=?,
                    status='available',
                    reserved_order_line_id=NULL,
                    reserved_quantity=NULL,
                    reserved_at=NULL,
                    used_at=?,
                    notes=?,
                    updated_at=?
                WHERE id=?
                """,
                (remaining_quantity, now, append_note(item["notes"], sent_note), now, inventory_id),
            )
        else:
            conn.execute(
                """
                UPDATE inventory_items
                SET status='used',
                    used_at=?,
                    notes=?,
                    updated_at=?
                WHERE id=?
                """,
                (now, append_note(item["notes"], sent_note), now, inventory_id),
            )
        total_quantity = max(0.0, float(line["quantity"] or 0))
        allocated_quantity = max(0.0, float(line.get("inventory_allocated_quantity") or 0))
        sent_quantity = min(allocated_quantity, max(0.0, float(line.get("inventory_sent_quantity") or 0)) + reserved_quantity)
        inventory_only_complete = allocated_quantity >= total_quantity and sent_quantity >= total_quantity
        conn.execute(
            """
            UPDATE order_lines
            SET state=CASE WHEN ? THEN 'delivered' ELSE state END,
                order_engine=CASE WHEN ? THEN 'inventory' ELSE order_engine END,
                inventory_sent_quantity=?,
                tracking_status=CASE WHEN ? THEN 'Inventory sent' ELSE ? END,
                tracking_checked_at=?,
                fulfilment_note=?,
                last_error=NULL,
                updated_at=?
            WHERE id=?
            """,
            (
                inventory_only_complete,
                inventory_only_complete,
                sent_quantity,
                inventory_only_complete,
                f"Inventory sent qty {sent_quantity:g} of {total_quantity:g}; Amazon remainder retained.",
                now,
                append_note(line["fulfilment_note"], sent_note),
                now,
                line["id"],
            ),
        )
        updated_item = conn.execute("SELECT * FROM inventory_items WHERE id=?", (inventory_id,)).fetchone()
        updated_line = conn.execute("SELECT * FROM order_lines WHERE id=?", (line["id"],)).fetchone()
    if updated_item:
        _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(updated_item) or {}: _index_named_document_sync("inventory_items", inventory_search_document(snapshot)))
    if updated_line:
        index_order_line(updated_line)
        if inventory_only_complete or clean_text(updated_line.get("amazon_order_id")):
            queued = enqueue_shopify_fulfilment_for_rows([dict(updated_line)])
            if queued:
                start_shopify_fulfilment_worker()
    return {"ok": True, "message": f"Marked inventory sent for {line['odoo_order_name']}.", **refresh_inventory_response(int(item["store_id"]), 1, 100)}


