@app.post("/api/chrome/missing-asin-checks/report")
def api_chrome_missing_asin_report(payload: dict[str, Any]) -> dict[str, Any]:
    line_id = int(payload.get("line_id") or 0)
    asin = normalize_asin(payload.get("asin") or "")
    in_stock = bool(payload.get("in_stock"))
    status = "back_in_stock" if in_stock else "still_missing"
    message = clean_text(payload.get("message"))
    checked_url = clean_text(payload.get("checked_url")) or asin_product_url(asin)
    checked_by = clean_text(payload.get("checked_by")) or "Chrome background"
    price = float(payload.get("price") or 0) or None
    if not line_id or not asin:
        raise HTTPException(400, "line_id and asin are required.")
    now = utc_now()
    skipped_reason = ""
    with db() as conn:
        row = conn.execute("SELECT * FROM order_lines WHERE id=?", (line_id,)).fetchone()
        if not row:
            raise HTTPException(404, "Order line not found.")
        record_status = status
        conn.execute(
            """
            INSERT INTO missing_asin_availability (
                order_line_id, store_id, asin, product_name, odoo_order_id, odoo_order_name,
                status, availability_message, price, checked_url, checked_by, queued_at, first_seen_at, last_checked_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)
            ON CONFLICT(order_line_id, asin) DO UPDATE SET
                status=excluded.status,
                availability_message=excluded.availability_message,
                price=excluded.price,
                checked_url=excluded.checked_url,
                checked_by=excluded.checked_by,
                last_checked_at=excluded.last_checked_at
            """,
            (
                line_id,
                row["store_id"],
                asin,
                row["product_name"],
                row["odoo_order_id"],
                row["odoo_order_name"],
                record_status,
                message,
                price,
                checked_url,
                checked_by,
                now,
                now,
            ),
        )
        availability = conn.execute(
            "SELECT id FROM missing_asin_availability WHERE order_line_id=? AND asin=?",
            (line_id, asin),
        ).fetchone()
        availability_id = int(availability["id"] or 0) if availability else 0
        store_id = int(row["store_id"])
        odoo_order_id = int(row["odoo_order_id"] or 0)
    if in_stock and availability_id and odoo_order_id and auto_chrome_ordering_enabled():
        queued, queue_message = auto_queue_ready_missing_order(store_id, odoo_order_id)
        if not queued:
            skipped_reason = queue_message
        fast_page_cache_clear_matching({"back-in-stock", "chrome-jobs", "dashboard", "orders", "missing"})
        return {
            "ok": True,
            "status": "approved" if queued else record_status,
            "queued": queued,
            "requires_approval": False,
            "skipped_reason": skipped_reason,
            "message": queue_message,
        }
    if in_stock and not auto_chrome_ordering_enabled():
        skipped_reason = "Automatic Chrome ordering is paused; the ready ASIN will remain in Back In Stock until ordering is enabled."
    return {"ok": True, "status": record_status, "queued": 0, "requires_approval": False, "skipped_reason": skipped_reason}


@app.get("/api/partial-fulfilments")
def api_partial_fulfilments(store_id: Optional[int] = None, page: int = 1, per_page: int = 100) -> dict[str, Any]:
    page, per_page, _ = pagination_bounds(page, per_page)
    cache_key = ("partial-fulfilments", store_id, page, per_page)
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    raw_rows, total = list_partial_fulfilments(store_id, page, per_page)
    rows = [partial_fulfilment_to_dict(row) for row in raw_rows]
    stores = rows_to_dicts(list_stores())
    stores_by_id = {store["id"]: store for store in stores}
    for row in rows:
        store = stores_by_id.get(row.get("store_id"))
        row["odoo_order_url"] = odoo_order_admin_url(store, row.get("odoo_order_id")) if store else ""
        with db() as conn:
            amazon_rows = rows_to_dicts(conn.execute(
                """
                SELECT DISTINCT amazon_order_id, amazon_order_url, amazon_account_name
                FROM order_lines
                WHERE store_id=?
                  AND odoo_order_id=?
                  AND COALESCE(amazon_order_id, '') != ''
                ORDER BY amazon_order_id
                """,
                (row.get("store_id"), row.get("odoo_order_id")),
            ).fetchall())
        for amazon_row in amazon_rows:
            if amazon_row.get("amazon_order_id") and not amazon_row.get("amazon_order_url"):
                amazon_row["amazon_order_url"] = order_line_amazon_url(amazon_row["amazon_order_id"])
        row["amazon_orders"] = amazon_rows
        row["amazon_order_ids"] = [item.get("amazon_order_id") for item in amazon_rows if item.get("amazon_order_id")]
        row["missing_asin_urls"] = {
            asin: asin_product_url(asin)
            for asin in row.get("missing_asins") or []
            if asin
        }
    return fast_page_cache_set(cache_key, {"stores": stores, "current_store_id": store_id, "rows": rows, "page": page, "per_page": per_page, "total": total}, 90)


