@app.get("/api/profit-loss")
def api_profit_loss(
    store_id: Optional[int] = None,
    period: str = "monthly",
    month: str = "",
    start: str = "",
    end: str = "",
    q: str = "",
    amazon_ordered_only: bool = False,
    profit_scope: str = "all",
    page: int = 1,
    per_page: int = 100,
) -> dict[str, Any]:
    cache_key = (
        store_id or 0,
        clean_text(period).lower() or "monthly",
        clean_text(month),
        clean_text(start),
        clean_text(end),
        clean_text(q),
        bool(amazon_ordered_only),
        clean_text(profit_scope).lower() or "all",
        int(page or 1),
        int(per_page or 100),
    )
    now = time.monotonic()
    with _PROFIT_LOSS_CACHE_LOCK:
        cached = _PROFIT_LOSS_CACHE.get(cache_key)
        if cached and cached[0] > now:
            return json.loads(json.dumps(cached[1], default=str))
    redis_cache_key = ("profit-loss", *cache_key)
    redis_cached = fast_page_cache_get(redis_cache_key)
    if redis_cached is not None:
        return redis_cached
    candidate_order_names: Optional[list[str]] = None
    if q.strip():
        try:
            candidate_order_names = profit_loss_order_names_from_typesense(store_id, period, month, start, end, q)
        except HTTPException:
            candidate_order_names = None
        except Exception as exc:
            candidate_order_names = None
    start_dt, end_dt, _resolved_month = date_range_from_params(period, month, start, end)
    start_text = start_dt.strftime("%Y-%m-%d %H:%M:%S")
    end_text = end_dt.strftime("%Y-%m-%d %H:%M:%S")
    try:
        backfill_missing_profit_loss_order_dates(store_id)
        backfill_missing_order_financials_for_profit_loss(store_id, start_text, end_text)
        normalize_converted_profit_columns(store_id, start_text, end_text)
    except Exception:
        pass
    result = profit_loss_data(store_id, period, month, start, end, q, page, per_page, candidate_order_names, amazon_ordered_only, profit_scope)
    with _PROFIT_LOSS_CACHE_LOCK:
        if len(_PROFIT_LOSS_CACHE) > 256:
            _PROFIT_LOSS_CACHE.clear()
        _PROFIT_LOSS_CACHE[cache_key] = (now + PROFIT_LOSS_CACHE_TTL_SECONDS, json.loads(json.dumps(result, default=str)))
    return fast_page_cache_set(redis_cache_key, result, PROFIT_LOSS_CACHE_TTL_SECONDS)


@app.post("/api/profit-loss/manual-costs")
def api_profit_loss_manual_cost_save(payload: dict[str, Any]) -> dict[str, Any]:
    month = clean_text(payload.get("month"))
    if not re.match(r"^\d{4}-\d{2}$", month):
        raise HTTPException(400, "Enter a valid month in YYYY-MM format.")
    label = clean_text(payload.get("label")) or "Manual monthly cost"
    amount = round(float(payload.get("amount") or 0), 2)
    if amount < 0:
        raise HTTPException(400, "Manual cost amount cannot be negative.")
    note = clean_text(payload.get("note"))
    store_id = int(payload.get("store_id") or 0) or None
    cost_id = int(payload.get("id") or 0)
    now = utc_now()
    with db() as conn:
        if cost_id:
            row = conn.execute(
                """
                UPDATE profit_loss_manual_costs
                SET store_id=?, month=?, label=?, amount=?, note=?, updated_at=?
                WHERE id=?
                RETURNING *
                """,
                (store_id, month, label, amount, note, now, cost_id),
            ).fetchone()
            if not row:
                raise HTTPException(404, "Manual cost not found.")
        else:
            row = conn.execute(
                """
                INSERT INTO profit_loss_manual_costs
                (store_id, month, label, amount, note, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                RETURNING *
                """,
                (store_id, month, label, amount, note, now, now),
            ).fetchone()
    clear_profit_loss_cache()
    return {"ok": True, "message": "Manual monthly cost saved.", "cost": dict(row) if row else None}


