def run_pull_job(job_id: str) -> None:
    try:
        with db() as conn:
            job = conn.execute("SELECT * FROM pull_jobs WHERE id=?", (job_id,)).fetchone()
            if not job:
                return
            batch_size = normalize_pull_batch_size(job["batch_size"] if "batch_size" in job.keys() else stored_pull_batch_size())
            cursor = conn.execute("UPDATE pull_jobs SET status='running', batch_size=?, updated_at=? WHERE id=? AND status='queued'", (batch_size, utc_now(), job_id))
            if cursor.rowcount <= 0:
                return

        def progress(processed_orders: int, total_orders: int, inserted_records: int) -> None:
            with db() as progress_conn:
                cursor = progress_conn.execute(
                    """
                    UPDATE pull_jobs
                    SET processed_orders=?, total_orders=?, inserted_records=?, updated_at=?
                    WHERE id=? AND status='running'
                    """,
                    (processed_orders, total_orders, inserted_records, utc_now(), job_id),
                )
                if cursor.rowcount <= 0:
                    raise PullJobCancelled("Pull job was stopped.")

        inserted = fetch_odoo_lines_exclusive(
            get_store(int(job["store_id"])),
            int(job["days"] or 7),
            normalize_pull_limit(job["limit_value"], 0),
            batch_size,
            progress,
            wait=True,
        )
        inserted = int(inserted or 0)
        with db() as conn:
            cursor = conn.execute(
                """
                UPDATE pull_jobs
                SET status='completed', inserted_records=?, updated_at=?, completed_at=?
                WHERE id=? AND status='running'
                """,
                (inserted, utc_now(), utc_now(), job_id),
            )
        if cursor.rowcount > 0:
            fast_page_cache_clear_matching({"pull-jobs"})
            start_typesense_reindex_job()
    except PullJobCancelled:
        fast_page_cache_clear_matching({"pull-jobs"})
        return
    except Exception as exc:
        with db() as conn:
            conn.execute(
                "UPDATE pull_jobs SET status='failed', error=?, updated_at=?, completed_at=? WHERE id=? AND status IN ('queued', 'running')",
                (str(exc)[:1000], utc_now(), utc_now(), job_id),
            )
        fast_page_cache_clear_matching({"pull-jobs"})


def mark_stale_pull_jobs(conn: Any) -> int:
    cutoff = (datetime.now(timezone.utc) - timedelta(minutes=PULL_JOB_STALE_MINUTES)).isoformat()
    cursor = conn.execute(
        """
        UPDATE pull_jobs
        SET status='failed',
            error=?,
            updated_at=?,
            completed_at=?
        WHERE status IN ('queued', 'running')
          AND COALESCE(NULLIF(updated_at, ''), created_at)::timestamp < ?::timestamp
        """,
        (
            f"Pull job stopped updating for more than {PULL_JOB_STALE_MINUTES} minutes. Start the pull again; Odoo calls now have a timeout so a stalled batch can fail cleanly.",
            utc_now(),
            utc_now(),
            cutoff,
        ),
    )
    return cursor.rowcount


def pull_job_payload(job_id: str, store_id: int, days: int, limit: int, batch_size: int, now: str) -> dict[str, Any]:
    return {"id": job_id, "store_id": store_id, "status": "queued", "days": days, "limit_value": limit, "batch_size": batch_size, "total_orders": 0, "processed_orders": 0, "inserted_records": 0, "error": "", "created_at": now, "updated_at": now, "completed_at": ""}


def start_pull_jobs(store_ids: list[int], days: int, limit: int, batch_size: int) -> list[dict[str, Any]]:
    normalized_store_ids = list(dict.fromkeys(int(store_id) for store_id in store_ids if int(store_id or 0) > 0))
    if not normalized_store_ids:
        return []
    jobs: list[dict[str, Any]] = []
    now = utc_now()
    with db() as conn:
        for store_id in normalized_store_ids:
            job_id = uuid.uuid4().hex
            conn.execute(
                """
                INSERT INTO pull_jobs
                (id, store_id, status, days, limit_value, batch_size, total_orders, processed_orders, inserted_records, error, created_at, updated_at)
                VALUES (?, ?, 'queued', ?, ?, ?, 0, 0, 0, '', ?, ?)
                """,
                (job_id, store_id, days, limit, batch_size, now, now),
            )
            jobs.append(pull_job_payload(job_id, store_id, days, limit, batch_size, now))
    fast_page_cache_clear_matching({"pull-jobs"})
    for job in jobs:
        threading.Thread(target=run_pull_job, args=(job["id"],), daemon=True).start()
    return jobs


def start_pull_job(store_id: int, days: int, limit: int, batch_size: int) -> dict[str, Any]:
    jobs = start_pull_jobs([store_id], days, limit, batch_size)
    if not jobs:
        raise HTTPException(400, "Select at least one store to pull orders.")
    return jobs[0]


@app.post("/api/pull")
def api_pull_orders(payload: PullPayload) -> dict[str, Any]:
    store_ids = [int(store_id) for store_id in (payload.store_ids or ([] if payload.store_id is None else [payload.store_id]))]
    store_ids = list(dict.fromkeys(store_id for store_id in store_ids if store_id > 0))
    if not store_ids:
        raise HTTPException(400, "Select at least one store to pull orders.")
    days = max(1, min(365, int(payload.days or 7)))
    limit = normalize_pull_limit(payload.limit, 0)
    batch_size = normalize_pull_batch_size(payload.batch_size or stored_pull_batch_size())
    set_setting("pull_orders_days", str(days))
    set_setting("pull_orders_limit", str(limit))
    set_service_settings({"pull_orders_batch_size": str(batch_size)})
    with db() as conn:
        mark_stale_pull_jobs(conn)
        active_jobs = conn.execute(
            """
            SELECT pull_jobs.*, stores.name AS store_name
            FROM pull_jobs
            LEFT JOIN stores ON stores.id = pull_jobs.store_id
            WHERE pull_jobs.status IN ('queued', 'running')
            ORDER BY pull_jobs.created_at ASC
            """
        ).fetchall()
        if active_jobs:
            jobs = rows_to_dicts(active_jobs)
            return {
                "ok": True,
                "message": f"An Odoo pull is already running. Reusing {len(jobs)} active job{'s' if len(jobs) != 1 else ''} instead of starting a duplicate.",
                "jobs": jobs,
                "defer_refresh": True,
            }
    jobs = start_pull_jobs(store_ids, days, limit, batch_size)
    message = f"Started {len(jobs)} background pull job{'s' if len(jobs) != 1 else ''}."
    return {"ok": True, "message": message, "jobs": jobs, "defer_refresh": True}


@app.post("/api/pull/order-names")
def api_pull_order_names(payload: dict[str, Any]) -> dict[str, Any]:
    raw_store_ids = payload.get("store_ids") or ([] if payload.get("store_id") is None else [payload.get("store_id")])
    if isinstance(raw_store_ids, (str, int, float)):
        raw_store_ids = [raw_store_ids]
    store_ids = list(dict.fromkeys(int(store_id) for store_id in raw_store_ids if int(store_id or 0) > 0))
    if not store_ids:
        raise HTTPException(400, "Select at least one store.")
    raw_values = payload.get("order_names") or payload.get("order_refs") or payload.get("orders") or payload.get("source_text") or ""
    if isinstance(raw_values, str):
        order_names = [raw_values]
    elif isinstance(raw_values, list):
        order_names = [str(value or "") for value in raw_values]
    else:
        order_names = [str(raw_values or "")]
    refs = list(dict.fromkeys(match.group(0).upper() for value in order_names for match in ORDER_REF_RE.finditer(value)))
    inserted_total = 0
    pulled_stores: list[str] = []
    locked_stores: list[str] = []
    warnings: list[str] = []
    for store_id in store_ids:
        store = get_store(store_id)
        result = fetch_odoo_orders_by_names_exclusive(store, order_names, wait=False, return_details=True)
        if result is None:
            locked_stores.append(store.name)
            continue
        inserted = int(result.get("inserted") or 0) if isinstance(result, dict) else int(result or 0)
        inserted_total += inserted
        if isinstance(result, dict):
            warnings.extend(clean_text(warning) for warning in (result.get("warnings") or []) if clean_text(warning))
        pulled_stores.append(store.name)
    start_typesense_reindex_job()
    if not pulled_stores and locked_stores:
        return {
            "ok": False,
            "message": "Another Odoo pull is already running. Try targeted pull again after it completes.",
            "defer_refresh": True,
        }
    store_message = ", ".join(pulled_stores)
    if locked_stores:
        store_message += f"; skipped busy store(s): {', '.join(locked_stores)}"
    warning_suffix = f" Warnings: {'; '.join(warnings[:8])}" if warnings else ""
    if len(warnings) > 8:
        warning_suffix += f"; plus {len(warnings) - 8} more."
    return {
        "ok": True,
        "message": f"Pulled {len(refs)} requested Odoo order{'s' if len(refs) != 1 else ''} from {store_message or len(store_ids)} store{'s' if len(store_ids) != 1 else ''}; saved {inserted_total} order-line record{'s' if inserted_total != 1 else ''}.{warning_suffix}",
        "pulled": inserted_total,
        "order_names": refs,
        "store_ids": store_ids,
        "warnings": warnings,
    }


@app.get("/api/pull/jobs")
def api_pull_jobs(page: int = 1, per_page: int = 100) -> dict[str, Any]:
    page, per_page, offset = pagination_bounds(page, per_page)
    cache_key = ("pull-jobs", page, per_page)
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    with db() as conn:
        total = int(conn.execute("SELECT COUNT(*) AS count FROM pull_jobs").fetchone()["count"] or 0)
        rows = conn.execute(
            """
            SELECT pull_jobs.*, stores.name AS store_name
            FROM pull_jobs
            LEFT JOIN stores ON stores.id = pull_jobs.store_id
            ORDER BY pull_jobs.created_at DESC
            LIMIT ? OFFSET ?
            """,
            (per_page, offset),
        ).fetchall()
    return fast_page_cache_set(cache_key, {"ok": True, "jobs": rows_to_dicts(rows), "page": page, "per_page": per_page, "total": total}, 30)


@app.post("/api/pull/jobs/{job_id}/cancel")
def api_cancel_pull_job(job_id: str) -> dict[str, Any]:
    clean_job_id = clean_text(job_id)
    if not clean_job_id:
        raise HTTPException(400, "Missing pull job id.")
    now = utc_now()
    with db() as conn:
        cursor = conn.execute(
            """
            UPDATE pull_jobs
            SET status='cancelled',
                error=?,
                updated_at=?,
                completed_at=?
            WHERE id=? AND status IN ('queued', 'running')
            """,
            ("Stopped by user.", now, now, clean_job_id),
        )
        row = conn.execute("SELECT pull_jobs.*, stores.name AS store_name FROM pull_jobs LEFT JOIN stores ON stores.id=pull_jobs.store_id WHERE pull_jobs.id=?", (clean_job_id,)).fetchone()
    if not row:
        raise HTTPException(404, "Pull job not found.")
    fast_page_cache_clear_matching({"pull-jobs"})
    if cursor.rowcount <= 0:
        return {"ok": True, "message": f"Pull job is already {row['status']}.", "job": row_to_dict(row)}
    return {"ok": True, "message": "Pull job stopped.", "job": row_to_dict(row)}


@app.post("/api/pull/jobs/clear")
def api_clear_pull_jobs() -> dict[str, Any]:
    now = utc_now()
    with db() as conn:
        active = int(conn.execute("SELECT COUNT(*) AS count FROM pull_jobs WHERE status IN ('queued', 'running')").fetchone()["count"] or 0)
        total = int(conn.execute("SELECT COUNT(*) AS count FROM pull_jobs").fetchone()["count"] or 0)
        conn.execute(
            """
            UPDATE pull_jobs
            SET status='cancelled',
                error=?,
                updated_at=?,
                completed_at=?
            WHERE status IN ('queued', 'running')
            """,
            ("Cleared by user.", now, now),
        )
        conn.execute("DELETE FROM pull_jobs")
    fast_page_cache_clear_matching({"pull-jobs"})
    return {
        "ok": True,
        "message": f"Cleared {total} pull job{'s' if total != 1 else ''}. {active} active job{'s' if active != 1 else ''} will stop on the next progress check.",
        "cleared": total,
        "active_cancelled": active,
        "jobs": [],
        "total": 0,
    }


