@app.post("/api/place")
def api_place(payload: PlacePayload) -> dict[str, Any]:
    if payload.line_ids:
        with db() as conn:
            selected_ids = sorted({int(line_id) for line_id in payload.line_ids if int(line_id or 0) > 0})
            if not selected_ids:
                raise HTTPException(400, "Select at least one valid order line to place.")
            placeholders = ",".join("?" for _ in selected_ids)
            selected_rows = rows_to_dicts(conn.execute(
                f"""
                SELECT order_lines.id, order_lines.store_id, order_lines.odoo_order_name,
                       COALESCE(stores.name, 'Store ' || order_lines.store_id) AS store_name
                FROM order_lines
                LEFT JOIN stores ON stores.id=order_lines.store_id
                WHERE order_lines.id IN ({placeholders})
                ORDER BY order_lines.store_id, order_lines.id
                """,
                selected_ids,
            ).fetchall()) if selected_ids else []
        found_ids = {int(row["id"]) for row in selected_rows}
        missing_ids = [line_id for line_id in selected_ids if line_id not in found_ids]
        if missing_ids:
            raise HTTPException(404, f"Place selected includes {len(missing_ids)} order line(s) that no longer exist. Refresh and try again.")
        line_ids_by_store: dict[int, list[int]] = {}
        store_names: dict[int, str] = {}
        for row in selected_rows:
            selected_store_id = int(row["store_id"])
            line_ids_by_store.setdefault(selected_store_id, []).append(int(row["id"]))
            store_names[selected_store_id] = clean_text(row.get("store_name")) or f"Store {selected_store_id}"
        if len(line_ids_by_store) > 1:
            ordering_engine = normalize_ordering_engine(payload.ordering_engine or get_default_ordering_engine())
            results: list[dict[str, Any]] = []
            total_queued = 0
            queued_line_ids: list[int] = []
            failures = 0
            for selected_store_id, store_line_ids in line_ids_by_store.items():
                store_payload = PlacePayload(
                    store_id=selected_store_id,
                    address_id=payload.address_id,
                    amazon_account_id=payload.amazon_account_id,
                    line_ids=store_line_ids,
                    club=payload.club,
                    ordering_engine=payload.ordering_engine,
                    allow_missing_spaid=payload.allow_missing_spaid,
                    include_missing_asins=payload.include_missing_asins,
                )
                try:
                    store_result = place_orders_for_store_payload(store_payload)
                    store_queued = int(store_result.get("queued") or store_result.get("ordered") or 0)
                    total_queued += store_queued
                    store_ok = bool(store_result.get("ok", True))
                    if not store_ok:
                        failures += 1
                    results.append({
                        "store_id": selected_store_id,
                        "store_name": store_names[selected_store_id],
                        "ok": store_ok,
                        "queued": store_queued,
                        "message": clean_text(store_result.get("message")),
                    })
                except Exception as exc:
                    failures += 1
                    detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
                    results.append({
                        "store_id": selected_store_id,
                        "store_name": store_names[selected_store_id],
                        "ok": False,
                        "queued": 0,
                        "message": clean_text(detail) or "Store fulfilment failed.",
                    })
            if ordering_engine == "chrome":
                with db() as conn:
                    queued_line_ids = [
                        int(row["id"])
                        for row in conn.execute(
                            f"""
                            SELECT id
                            FROM order_lines
                            WHERE id IN ({','.join('?' for _ in selected_ids)})
                              AND state='submitted'
                              AND order_engine='chrome'
                            ORDER BY id
                            """,
                            selected_ids,
                        ).fetchall()
                    ]
            summaries = [
                f"{result['store_name']}: {result['message']}"
                for result in results
            ]
            return {
                "ok": failures == 0 and any(result["ok"] for result in results),
                "message": (
                    f"Processed {len(results)} stores together using {ordering_engine}; "
                    f"queued/placed {total_queued} order group{'s' if total_queued != 1 else ''}. "
                    + " | ".join(summaries)
                ),
                "defer_refresh": ordering_engine == "chrome",
                "queued": total_queued,
                "queued_line_ids": queued_line_ids,
                "store_results": results,
            }
        if line_ids_by_store:
            payload.store_id = next(iter(line_ids_by_store))
            payload.line_ids = next(iter(line_ids_by_store.values()))
    return place_orders_for_store_payload(payload)


def place_orders_for_store_payload(payload: PlacePayload) -> dict[str, Any]:
    ordering_engine = normalize_ordering_engine(payload.ordering_engine or get_default_ordering_engine())
    if ordering_engine == "chrome":
        selected_count = len(payload.line_ids or [])
        queued, cleared, skipped, account, details = queue_chrome_order_groups_fast(
            payload.store_id,
            payload.amazon_account_id,
            payload.address_id,
            payload.line_ids or None,
            payload.club,
            payload.include_missing_asins,
        )
        message = (
            f"Using engine: chrome. Queued {queued} order group{'s' if queued != 1 else ''} "
            f"from {selected_count or 'matching'} selected line{'s' if selected_count != 1 else ''} "
            f"for {account['name']}."
        )
        if cleared:
            message += f" Cleared {cleared} dry-run marker{'s' if cleared != 1 else ''}."
        if skipped:
            message += f" Skipped {skipped} order{'s' if skipped != 1 else ''} that already had an Amazon order assigned; reset fulfilment before resending."
        skip_details = details if queued and payload.line_ids else selected_line_reasons(payload.store_id, payload.line_ids) if payload.line_ids else []
        if skip_details:
            message += " Reason: " + " | ".join(skip_details)
        return {
            "ok": queued > 0,
            "message": message,
            "defer_refresh": True,
            "queued": queued,
            "details": details,
        }

    cleared = clear_dry_run_order_markers(payload.store_id)
    account = get_amazon_account(payload.amazon_account_id)
    ordered, skipped = place_orders(
        payload.store_id,
        address_id=payload.address_id,
        amazon_account_id=payload.amazon_account_id,
        line_ids=payload.line_ids or None,
        club=payload.club,
        ordering_engine=ordering_engine,
        allow_missing_spaid=payload.allow_missing_spaid,
        include_missing_asins=payload.include_missing_asins,
    )
    if ordered or payload.line_ids:
        with db() as conn:
            line_filter = ""
            params: list[Any] = [payload.store_id]
            if payload.line_ids:
                line_filter = f" AND id IN ({','.join('?' for _ in payload.line_ids)})"
                params.extend(payload.line_ids)
            queued_rows = rows_to_dicts(conn.execute(
                f"""
                SELECT *
                FROM order_lines
                WHERE store_id=?
                  AND (
                    (
                      COALESCE(amazon_order_id, '') != ''
                      AND order_engine IN ('chrome', 'rest', 'cxml', 'manual_amazon', 'third_party')
                      AND state IN ('ordered', 'dispatched', 'delivered')
                    )
                    OR (
                      order_engine='inventory'
                      AND state IN ('inventory', 'delivered')
                    )
                  )
                  {line_filter}
                """,
                params,
            ).fetchall())
        queued = enqueue_shopify_fulfilment_for_rows(queued_rows)
        if queued:
            start_shopify_fulfilment_worker()
    details = selected_line_reasons(payload.store_id, payload.line_ids or None)
    account_type = "sandbox" if "sandbox." in str(account["api_base_url"]) else "production"
    data = dashboard_data(payload.store_id)
    message = (
        f"Using engine: {ordering_engine}. Using Amazon account: {account['name']} ({account_type}, {account['api_base_url']}). "
        f"Placed {ordered} Amazon order{'s' if ordered != 1 else ''}; failed/skipped {skipped}."
    )
    if cleared:
        message += f" Cleared {cleared} old dry-run marker{'s' if cleared != 1 else ''} before placing."
    if details:
        message += " Reason: " + " | ".join(details)
    data["message"] = message
    data["ok"] = skipped == 0 and ordered > 0
    data["ordered"] = ordered
    data["skipped"] = skipped
    if ordering_engine == "cxml" and skipped and not payload.allow_missing_spaid:
        line = first_missing_spaid_line(payload.store_id, payload.line_ids or None)
        if line:
            query = urlencode(
                {
                    "store_id": payload.store_id,
                    "amazon_account_id": payload.amazon_account_id or "",
                    "line_id": line["id"],
                }
            )
            data["punchout_launch_url"] = f"/punchout/launch?{query}"
            data["message"] += " Opening Amazon Punchout to create the required cart/session."
    return data


@app.post("/api/place/recent-chrome")
def api_place_recent_chrome(payload: dict[str, Any]) -> dict[str, Any]:
    store_id = int(payload.get("store_id") or 0)
    if not store_id:
        raise HTTPException(400, "Store is required.")
    days = normalize_days_window(int(payload.get("days") or 1), 1)
    address_id = parse_optional_int(payload.get("address_id"))
    amazon_account_id = parse_optional_int(payload.get("amazon_account_id"))
    pulled = fetch_odoo_lines_exclusive(get_store(store_id), days=days, limit=0, batch_size=stored_pull_batch_size(), wait=True)
    queued, skipped = place_orders(
        store_id,
        address_id=address_id,
        amazon_account_id=amazon_account_id,
        line_ids=None,
        club=False,
        ordering_engine="chrome",
        allow_missing_spaid=True,
        include_missing_asins=bool(payload.get("include_missing_asins")),
    )
    data = dashboard_data(store_id)
    data["message"] = (
        f"Pulled last {days} day{'s' if days != 1 else ''} fresh from Odoo and queued {queued} Chrome order group"
        f"{'s' if queued != 1 else ''}. Skipped {skipped} order{'s' if skipped != 1 else ''} already fulfilled or blocked."
    )
    if not queued:
        data["message"] += (
            " No Chrome jobs were created. Check that the selected store has recent eligible lines with ASINs, "
            "no Amazon order ID, and a status that is not cancelled, refunded, costly, inventory, ignored, or already ordered. "
            "Tick retry missing/out-of-stock ASINs if you want missing rows included."
        )
    data["ok"] = queued > 0
    data["pulled"] = pulled or 0
    data["queued"] = queued
    data["skipped"] = skipped
    return data


