def exact_amazon_history_match_for_chrome_job(job: dict[str, Any]) -> Optional[dict[str, Any]]:
    """Return one exact existing Amazon order, or None when evidence is ambiguous."""
    order_names = {clean_text(value).upper() for value in job.get("order_names") or [] if clean_text(value)}
    expected: dict[str, float] = {}
    for item in job.get("items") or []:
        asin = normalize_asin(item.get("asin"))
        if not asin:
            return None
        expected[asin] = expected.get(asin, 0.0) + float(item.get("quantity") or 1)
    if not order_names or not expected:
        return None
    cancelled_ids = {clean_text(value) for value in job.get("cancelled_amazon_order_ids") or [] if clean_text(value)}
    cutoff = (datetime.now(timezone.utc) - timedelta(days=14)).isoformat(timespec="seconds")
    with db() as conn:
        history_rows = rows_to_dicts(conn.execute(
            """
            SELECT amazon_order_id, amazon_order_url, recipient, status, order_date,
                   asins_json, items_json, last_seen_at
            FROM amazon_order_history_unmatched
            WHERE last_seen_at >= ?
              AND LOWER(COALESCE(status, '')) NOT LIKE '%cancel%'
            ORDER BY last_seen_at DESC, amazon_order_id DESC
            LIMIT 500
            """,
            (cutoff,),
        ).fetchall())
        linked_ids = {
            clean_text(row["amazon_order_id"])
            for row in conn.execute(
                "SELECT DISTINCT amazon_order_id FROM order_lines WHERE COALESCE(amazon_order_id, '') != ''"
            ).fetchall()
            if clean_text(row["amazon_order_id"])
        }
        known_cancelled_ids = {
            clean_text(row["amazon_cancelled_order_id"])
            for row in conn.execute(
                "SELECT DISTINCT amazon_cancelled_order_id FROM order_lines WHERE COALESCE(amazon_cancelled_order_id, '') != ''"
            ).fetchall()
            if clean_text(row["amazon_cancelled_order_id"])
        }
    matches: list[dict[str, Any]] = []
    for row in history_rows:
        amazon_order_id = clean_text(row.get("amazon_order_id"))
        if not amazon_order_id or amazon_order_id in cancelled_ids or amazon_order_id in known_cancelled_ids or amazon_order_id in linked_ids:
            continue
        recipient_refs = set(amazon_history_order_refs_from_text(row.get("recipient") or ""))
        if not order_names.issubset(recipient_refs):
            continue
        try:
            items = json.loads(row.get("items_json") or "[]")
        except (TypeError, ValueError, json.JSONDecodeError):
            items = []
        actual: dict[str, float] = {}
        for item in items if isinstance(items, list) else []:
            if not isinstance(item, dict):
                continue
            asin = normalize_asin(item.get("asin"))
            if asin:
                try:
                    quantity = max(1.0, float(item.get("quantity") or 1))
                except (TypeError, ValueError):
                    actual = {}
                    break
                actual[asin] = actual.get(asin, 0.0) + quantity
        if not actual:
            try:
                asins = json.loads(row.get("asins_json") or "[]")
            except (TypeError, ValueError, json.JSONDecodeError):
                asins = []
            for value in asins if isinstance(asins, list) else []:
                asin = normalize_asin(value)
                if asin:
                    actual[asin] = actual.get(asin, 0.0) + 1.0
        if set(actual) != set(expected):
            continue
        if any(abs(float(actual[asin]) - float(quantity)) >= 0.0001 for asin, quantity in expected.items()):
            continue
        matches.append({
            "amazon_order_id": amazon_order_id,
            "amazon_order_url": clean_text(row.get("amazon_order_url")) or order_line_amazon_url(amazon_order_id),
            "recipient": clean_text(row.get("recipient")),
            "order_date": clean_text(row.get("order_date")),
            "asins": sorted(actual),
        })
    # Multiple exact Amazon orders are suspected duplicates and must be
    # reviewed rather than silently selecting one for the Odoo lines.
    return matches[0] if len(matches) == 1 else None


def complete_chrome_job_from_exact_history_match(
    job: dict[str, Any],
    existing: dict[str, Any],
    worker_id: str,
) -> dict[str, Any]:
    """Save one server-verified Amazon history match for a Chrome job."""
    amazon_order_id = clean_text(existing.get("amazon_order_id"))
    amazon_order_url = clean_text(existing.get("amazon_order_url")) or order_line_amazon_url(amazon_order_id)
    line_ids = sorted({
        int(value)
        for value in job.get("line_ids") or []
        if str(value or "").isdigit() and int(value) > 0
    })
    return api_chrome_job_complete(
        clean_text(job.get("group_key")),
        ChromeJobCompletePayload(
            amazon_order_id=amazon_order_id,
            amazon_order_url=amazon_order_url,
            amazon_account_name=clean_text(job.get("amazon_account_name")) or "Chrome Extension",
            order_date=clean_text(existing.get("order_date")),
            amazon_recipient=clean_text(existing.get("recipient")),
            amazon_asins=[
                asin
                for asin in (normalize_asin(value) for value in existing.get("asins") or [])
                if asin
            ],
            line_ids=line_ids,
            order_mappings=[
                {
                    "amazon_order_id": amazon_order_id,
                    "amazon_order_url": amazon_order_url,
                    "asin": normalize_asin(item.get("asin")),
                    "line_ids": [
                        int(value)
                        for value in item.get("line_ids") or []
                        if str(value or "").isdigit() and int(value) > 0
                    ],
                }
                for item in job.get("items") or []
            ],
            worker_id=clean_text(worker_id),
        ),
    )


def reconcile_exact_submitted_chrome_jobs_from_history(limit: int = 8) -> list[dict[str, Any]]:
    """Complete protected Chrome submissions from unique exact history evidence."""
    with db() as conn:
        groups = rows_to_dicts(conn.execute(
            """
            SELECT amazon_group_key, chrome_claimed_by, MAX(updated_at) AS updated_at
            FROM order_lines
            WHERE order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '')=''
              AND COALESCE(amazon_group_key, '')!=''
              AND COALESCE(chrome_claimed_by, '')!=''
              AND COALESCE(amazon_status, '') IN ('order_submitted', 'reporting_complete')
            GROUP BY amazon_group_key, chrome_claimed_by
            ORDER BY MAX(updated_at) DESC
            LIMIT ?
            """,
            (max(1, min(50, int(limit or 8))),),
        ).fetchall())
    reconciled: list[dict[str, Any]] = []
    for group in groups:
        group_key = clean_text(group.get("amazon_group_key"))
        worker_id = clean_text(group.get("chrome_claimed_by"))
        if not group_key or not worker_id:
            continue
        with db() as conn:
            group_rows = rows_to_dicts(conn.execute(
                """
                SELECT *
                FROM order_lines
                WHERE amazon_group_key=?
                  AND order_engine='chrome'
                  AND state='submitted'
                  AND COALESCE(amazon_order_id, '')=''
                ORDER BY id
                """,
                (group_key,),
            ).fetchall())
        if not group_rows:
            continue
        job = chrome_job_from_rows(group_rows)
        existing = exact_amazon_history_match_for_chrome_job(job)
        if not existing:
            continue
        try:
            completion = complete_chrome_job_from_exact_history_match(job, existing, worker_id)
        except Exception as exc:
            print(f"Chrome exact history auto-completion held {group_key}: {exc}", flush=True)
            continue
        reconciled.append({
            "group_key": group_key,
            "amazon_order_id": clean_text(existing.get("amazon_order_id")),
            "order_names": job.get("order_names") or [],
            "odoo_chatter_queued": bool(completion.get("odoo_chatter_queued")),
            "odoo_chatter_confirmed": bool(completion.get("odoo_chatter_confirmed")),
        })
    return reconciled


def repair_missing_chrome_order_chatter(limit: int = 20) -> list[dict[str, Any]]:
    """Backstop every saved Chrome order with a durable Odoo chatter outbox row."""
    with db() as conn:
        groups = rows_to_dicts(conn.execute(
            """
            SELECT DISTINCT ol.amazon_group_key, ol.amazon_order_id
            FROM order_lines ol
            WHERE ol.order_engine='chrome'
              AND COALESCE(ol.amazon_group_key, '')!=''
              AND COALESCE(ol.amazon_order_id, '')!=''
              AND NOT EXISTS (
                  SELECT 1
                  FROM odoo_chatter_note_log log
                  WHERE log.store_id=ol.store_id
                    AND log.odoo_order_id=ol.odoo_order_id
                    AND log.event_type='amazon_order_placed'
                    AND log.amazon_order_id=ol.amazon_order_id
              )
            ORDER BY ol.amazon_order_id DESC
            LIMIT ?
            """,
            (max(1, min(100, int(limit or 20))),),
        ).fetchall())
    repaired: list[dict[str, Any]] = []
    for group in groups:
        group_key = clean_text(group.get("amazon_group_key"))
        amazon_order_id = clean_text(group.get("amazon_order_id"))
        if not group_key or not amazon_order_id:
            continue
        with db() as conn:
            rows = rows_to_dicts(conn.execute(
                """
                SELECT *
                FROM order_lines
                WHERE amazon_group_key=? AND amazon_order_id=? AND order_engine='chrome'
                ORDER BY id
                """,
                (group_key, amazon_order_id),
            ).fetchall())
            history = conn.execute(
                "SELECT recipient, amazon_order_url FROM amazon_order_history_unmatched WHERE amazon_order_id=?",
                (amazon_order_id,),
            ).fetchone()
        if not rows:
            continue
        worker_id = clean_text(rows[0].get("chrome_claimed_by"))
        queued = queue_chrome_complete_odoo_chatter(
            group_key,
            rows,
            {},
            amazon_order_id,
            clean_text((history or {}).get("amazon_order_url")) or clean_text(rows[0].get("amazon_order_url")) or order_line_amazon_url(amazon_order_id),
            clean_text(rows[0].get("amazon_account_name")) or "Chrome Extension",
            worker_id,
            clean_text((history or {}).get("recipient")),
        )
        if queued:
            repaired.append({
                "group_key": group_key,
                "amazon_order_id": amazon_order_id,
                "order_names": sorted({clean_text(row.get("odoo_order_name")) for row in rows if clean_text(row.get("odoo_order_name"))}),
            })
    return repaired


@app.get("/api/chrome/jobs")
def api_chrome_jobs(
    store_id: Optional[int] = None,
    worker_id: str = "",
    claim: bool = True,
    resume_existing: bool = True,
    job_limit: int = 50,
    split_mixed_asin: bool = False,
    account_experience: str = "",
    preferred_group_key: str = "",
    preferred_only: bool = False,
    manual_claim: bool = False,
) -> dict[str, Any]:
    if claim:
        if not manual_claim and not auto_chrome_ordering_enabled():
            return {
                "ok": True,
                "jobs": [],
                "auto_ordering_paused": True,
                "message": "Automatic Chrome ordering is paused in app settings.",
            }
        history_reconciled = reconcile_exact_submitted_chrome_jobs_from_history()
        chatter_repaired = repair_missing_chrome_order_chatter()
        # Older loaded extension workers used resume_existing=false, which can
        # abandon an in-progress checkout and jump to a different order. Claims
        # should be resumed by default for the same worker so a refresh/reload
        # continues the current Amazon flow instead of corrupting the queue.
        resume_existing = True
        reconciled_existing: list[dict[str, Any]] = []
        job = claim_next_chrome_job(
            store_id,
            worker_id,
            resume_existing=resume_existing,
            split_mixed_asin=split_mixed_asin,
            account_experience=account_experience,
            preferred_group_key=preferred_group_key,
            preferred_only=preferred_only,
        )
        # Before handing a fresh claim to Chrome, consume any one exact,
        # non-cancelled Amazon-history match. This prevents a previously
        # placed order whose report was interrupted from reaching cart again.
        for _ in range(5):
            if not job or job.get("submitted_to_amazon"):
                break
            existing = exact_amazon_history_match_for_chrome_job(job)
            if not existing:
                break
            try:
                completion = complete_chrome_job_from_exact_history_match(job, existing, worker_id)
                reconciled_existing.append({
                    "group_key": clean_text(job.get("group_key")),
                    "amazon_order_id": existing["amazon_order_id"],
                    "order_names": job.get("order_names") or [],
                    "message": completion.get("message") or "Recovered existing Amazon order before Chrome checkout.",
                })
            except Exception as exc:
                print(f"Chrome pre-claim history reconciliation held {job.get('group_key')}: {exc}", flush=True)
                break
            job = claim_next_chrome_job(
                store_id,
                worker_id,
                resume_existing=True,
                split_mixed_asin=split_mixed_asin,
                account_experience=account_experience,
                preferred_group_key=preferred_group_key,
                preferred_only=preferred_only,
            )
        return {
            "ok": True,
            "jobs": [job] if job else [],
            "reconciled_existing": reconciled_existing,
            "history_reconciled": history_reconciled,
            "chatter_repaired": chatter_repaired,
        }
    snapshot = chrome_queue_snapshot(
        store_id,
        limit=job_limit,
        worker_id=worker_id,
        account_experience=account_experience,
    )
    return {"ok": True, **snapshot}


def queued_chrome_order_by_name(order_name: str) -> Optional[dict[str, Any]]:
    """Return the live whole-order Chrome queue entry for an exact Odoo order."""
    with db() as conn:
        rows = rows_to_dicts(conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE UPPER(odoo_order_name)=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '')=''
              AND COALESCE(amazon_group_key, '')!=''
            ORDER BY updated_at DESC, id ASC
            """,
            (order_name,),
        ).fetchall())
    if not rows:
        return None
    group_key = clean_text(rows[0].get("amazon_group_key"))
    group_rows = [row for row in rows if clean_text(row.get("amazon_group_key")) == group_key]
    return chrome_job_from_rows(group_rows) if group_rows else None


def queue_one_chrome_order_by_name(order_name: str) -> dict[str, Any]:
    """Pull one Odoo order and enqueue all of its eligible ASIN lines atomically."""
    order_name = clean_text(order_name).upper()
    if not ORDER_REF_RE.fullmatch(order_name):
        raise HTTPException(400, "Enter one valid Odoo order number, for example ES00259.")

    # Never refresh a live queue entry from Odoo. The regular Odoo upsert may
    # update line state, so pulling here could otherwise disturb an active or
    # waiting whole-order job.
    existing_job = queued_chrome_order_by_name(order_name)
    if existing_job:
        return {
            "ok": True,
            "already_queued": True,
            "queued": 0,
            "order_name": order_name,
            "group_key": existing_job["group_key"],
            "preferred_group_key": existing_job["group_key"],
            "job": existing_job,
            "message": f"{order_name} is already in the queue and will be processed first when you click Process queued orders.",
        }

    with db() as conn:
        known_rows = rows_to_dicts(conn.execute(
            """
            SELECT store_id, odoo_order_id, amazon_order_id
            FROM order_lines
            WHERE UPPER(odoo_order_name)=?
            ORDER BY updated_at DESC, id ASC
            """,
            (order_name,),
        ).fetchall())
    existing_amazon_ids = sorted({
        clean_text(row.get("amazon_order_id"))
        for row in known_rows
        if clean_text(row.get("amazon_order_id"))
    })
    if existing_amazon_ids:
        raise HTTPException(
            409,
            f"{order_name} already has Amazon order {', '.join(existing_amazon_ids)} and was not queued again.",
        )

    known_store_ids = sorted({int(row["store_id"]) for row in known_rows if int(row.get("store_id") or 0) > 0})
    candidate_store_ids = known_store_ids or [int(store["id"]) for store in list_stores()]
    if not candidate_store_ids:
        raise HTTPException(400, "Add an Odoo store before queueing an order.")

    pulled = 0
    fetched = 0
    eligible = 0
    busy_stores: list[str] = []
    warnings: list[str] = []
    for store_id in candidate_store_ids:
        store = get_store(store_id)
        result = fetch_odoo_orders_by_names_exclusive(store, [order_name], wait=False, return_details=True)
        if result is None:
            busy_stores.append(store.name)
            continue
        if isinstance(result, dict):
            pulled += int(result.get("inserted") or 0)
            fetched += int(result.get("fetched") or 0)
            eligible += int(result.get("eligible") or 0)
            warnings.extend(clean_text(value) for value in (result.get("warnings") or []) if clean_text(value))
        else:
            pulled += int(result or 0)

    if busy_stores:
        raise HTTPException(409, f"Another Odoo pull is running for {', '.join(busy_stores)}. Try again when it finishes.")
    if eligible <= 0:
        warning_text = f" {'; '.join(warnings[:4])}" if warnings else ""
        if fetched:
            raise HTTPException(409, f"{order_name} was found in Odoo but is not eligible for fulfilment.{warning_text}")
        raise HTTPException(404, f"{order_name} was not found in the configured Odoo stores.{warning_text}")

    with db() as conn:
        order_rows = rows_to_dicts(conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE UPPER(odoo_order_name)=?
            ORDER BY store_id, odoo_order_id, id
            """,
            (order_name,),
        ).fetchall())
    if not order_rows:
        warning_text = f" {'; '.join(warnings[:4])}" if warnings else ""
        raise HTTPException(404, f"{order_name} was not found in the configured Odoo stores.{warning_text}")

    identities = {(int(row["store_id"]), int(row["odoo_order_id"])) for row in order_rows}
    if len(identities) != 1:
        raise HTTPException(409, f"{order_name} matched more than one configured Odoo order. Select it from the app instead.")
    store_id, _odoo_order_id = next(iter(identities))
    amazon_ids = sorted({clean_text(row.get("amazon_order_id")) for row in order_rows if clean_text(row.get("amazon_order_id"))})
    if amazon_ids:
        raise HTTPException(409, f"{order_name} already has Amazon order {', '.join(amazon_ids)} and was not queued again.")

    queued, _cleared, blocked, account, details = queue_chrome_order_groups_fast(
        store_id,
        line_ids=[int(row["id"]) for row in order_rows],
    )
    job = queued_chrome_order_by_name(order_name)
    if not queued or not job:
        reason = " | ".join(details[:4]) if details else "No eligible unfulfilled ASIN lines were available."
        if warnings:
            reason += f" {'; '.join(warnings[:4])}"
        return {
            "ok": False,
            "queued": 0,
            "blocked": blocked,
            "order_name": order_name,
            "message": f"{order_name} was imported but not queued. {reason}",
        }

    asin_count = len(job.get("items") or [])
    return {
        "ok": True,
        "already_queued": False,
        "queued": queued,
        "pulled": pulled,
        "blocked": blocked,
        "order_name": order_name,
        "group_key": job["group_key"],
        "preferred_group_key": job["group_key"],
        "amazon_account_name": clean_text(account["name"]),
        "job": job,
        "message": f"Imported {order_name} and queued all {asin_count} ASIN{'s' if asin_count != 1 else ''}. It will be processed first when you click Process queued orders.",
    }


@app.post("/api/chrome/queue/order")
def api_chrome_queue_order(payload: dict[str, Any]) -> dict[str, Any]:
    """Import and queue one or more exact Odoo order references."""
    raw_values = (
        payload.get("order_names")
        or payload.get("orders")
        or payload.get("order_name")
        or payload.get("odoo_order_name")
        or payload.get("source_text")
        or ""
    )
    values = raw_values if isinstance(raw_values, list) else [raw_values]
    order_names = list(dict.fromkeys(
        match.group(0).upper()
        for value in values
        for match in ORDER_REF_RE.finditer(str(value or ""))
    ))[:100]
    if not order_names:
        raise HTTPException(400, "Enter at least one valid Odoo order number, for example ES00259.")

    results: list[dict[str, Any]] = []
    for order_name in order_names:
        try:
            results.append(queue_one_chrome_order_by_name(order_name))
        except HTTPException as exc:
            results.append({
                "ok": False,
                "queued": 0,
                "order_name": order_name,
                "status_code": int(exc.status_code),
                "message": clean_text(exc.detail) or f"{order_name} could not be queued.",
            })
        except Exception as exc:
            results.append({
                "ok": False,
                "queued": 0,
                "order_name": order_name,
                "status_code": 500,
                "message": str(exc) or f"{order_name} could not be queued.",
            })

    successful = [result for result in results if result.get("ok")]
    failed = [result for result in results if not result.get("ok")]
    newly_queued = sum(int(result.get("queued") or 0) for result in successful)
    already_queued = sum(1 for result in successful if result.get("already_queued"))
    preferred_group_keys = list(dict.fromkeys(
        clean_text(result.get("preferred_group_key") or result.get("group_key"))
        for result in successful
        if clean_text(result.get("preferred_group_key") or result.get("group_key"))
    ))
    if len(order_names) == 1:
        result = results[0]
        return {
            **result,
            "results": results,
            "preferred_group_keys": preferred_group_keys,
        }

    summary = (
        f"Processed {len(order_names)} Odoo order numbers: "
        f"{newly_queued} newly queued, {already_queued} already queued, {len(failed)} failed."
    )
    if failed:
        summary += " " + " | ".join(
            f"{result['order_name']}: {clean_text(result.get('message'))}"
            for result in failed[:6]
        )
        if len(failed) > 6:
            summary += f" | plus {len(failed) - 6} more failure(s)."
    return {
        "ok": bool(successful) and not failed,
        "partial_success": bool(successful) and bool(failed),
        "order_names": order_names,
        "queued": newly_queued,
        "already_queued": already_queued,
        "failed": len(failed),
        "preferred_group_key": preferred_group_keys[0] if preferred_group_keys else "",
        "preferred_group_keys": preferred_group_keys,
        "results": results,
        "message": summary,
    }


@app.get("/api/chrome/jobs/recover-submitted")
def api_chrome_recover_submitted_job(
    store_id: Optional[int] = None,
    worker_id: str = "",
) -> dict[str, Any]:
    worker_id = clean_text(worker_id)[:120]
    if not worker_id:
        return {"ok": True, "job": None}
    none_cache_key = (store_id, worker_id)
    now_monotonic = time.monotonic()
    with _CHROME_RECOVER_SUBMITTED_NONE_LOCK:
        if _CHROME_RECOVER_SUBMITTED_NONE_CACHE.get(none_cache_key, 0) > now_monotonic:
            return {"ok": True, "job": None}
    with db() as conn:
        rows = conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(amazon_group_key, '') != ''
              AND chrome_claimed_by=?
              AND COALESCE(amazon_status, '') = ?
              AND (? IS NULL OR store_id=?)
            ORDER BY COALESCE(NULLIF(odoo_order_date, ''), NULLIF(pulled_at, ''), created_at) DESC,
                     odoo_order_id DESC,
                     id ASC
            """,
            (worker_id, CHROME_ORDER_SUBMITTED_STATUS, store_id, store_id),
        ).fetchall()
        if not rows:
            with _CHROME_RECOVER_SUBMITTED_NONE_LOCK:
                if len(_CHROME_RECOVER_SUBMITTED_NONE_CACHE) > 500:
                    _CHROME_RECOVER_SUBMITTED_NONE_CACHE.clear()
                _CHROME_RECOVER_SUBMITTED_NONE_CACHE[none_cache_key] = time.monotonic() + 10
            return {"ok": True, "job": None}
        group_key = str(rows[0]["amazon_group_key"])
        expiry = chrome_job_lease_expiry()
        conn.execute(
            """
            UPDATE order_lines
            SET chrome_claim_expires_at=?, updated_at=?
            WHERE amazon_group_key=?
              AND chrome_claimed_by=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(amazon_status, '') = ?
            """,
            (expiry, utc_now(), group_key, worker_id, CHROME_ORDER_SUBMITTED_STATUS),
        )
        group_rows = rows_to_dicts(conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
            ORDER BY id
            """,
            (group_key,),
        ).fetchall())
    job = chrome_job_from_rows(group_rows)
    existing = exact_amazon_history_match_for_chrome_job(job)
    if existing:
        try:
            completion = complete_chrome_job_from_exact_history_match(job, existing, worker_id)
            return {
                "ok": True,
                "job": None,
                "recovered": True,
                "group_key": clean_text(job.get("group_key")),
                "amazon_order_id": clean_text(existing.get("amazon_order_id")),
                "message": completion.get("message") or "Recovered exact Amazon order-history match.",
            }
        except Exception as exc:
            # Keep the protected submitted job available to the extension when
            # a downstream follow-up (for example Odoo chatter) is temporarily
            # unavailable. Never clear the lock or permit a second checkout.
            print(f"Chrome submitted history reconciliation held {group_key}: {exc}", flush=True)
    return {"ok": True, "job": job, "claim_expires_at": expiry}


@app.post("/api/chrome/jobs/{group_key}/heartbeat")
def api_chrome_job_heartbeat(group_key: str, payload: ChromeJobHeartbeatPayload) -> dict[str, Any]:
    worker_id = clean_text(payload.worker_id)
    if not worker_id:
        raise HTTPException(400, "worker_id is required")
    expiry = chrome_job_lease_expiry()
    diagnostic = {
        "event": "chrome_job_heartbeat",
        "at": utc_now(),
        "worker_id": worker_id,
        "stage": clean_text(payload.stage),
        "item_index": max(0, int(payload.item_index or 0)),
        "item_count": max(0, int(payload.item_count or 0)),
        "asins": [
            asin
            for asin in (normalize_asin(value) for value in (payload.asins or []))
            if asin
        ],
        "target_window_id": payload.target_window_id,
        "extension_build": clean_text(payload.extension_build),
        "paused": bool(payload.paused),
        "paused_stage": clean_text(payload.paused_stage),
        "last_error": clean_text(payload.last_error)[:500],
    }
    with db() as conn:
        cursor = conn.execute(
            """
            UPDATE order_lines
            SET chrome_claim_expires_at=?, updated_at=?
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND chrome_claimed_by=?
            """,
            (expiry, utc_now(), group_key, worker_id),
        )
        conn.execute(
            """
            UPDATE amazon_attempts
            SET response_json=?
            WHERE external_id=? AND mode='chrome'
            """,
            (json.dumps(diagnostic), group_key),
        )
    if not cursor.rowcount:
        raise HTTPException(409, "Chrome job lock is no longer owned by this worker.")
    return {"ok": True, "claim_expires_at": expiry}


@app.post("/api/chrome/jobs/{group_key}/submitted")
def api_chrome_job_submitted(group_key: str, payload: ChromeJobHeartbeatPayload) -> dict[str, Any]:
    worker_id = clean_text(payload.worker_id)
    if not worker_id:
        raise HTTPException(400, "worker_id is required")
    expiry = chrome_job_lease_expiry()
    now = utc_now()
    blocked_message = ""
    submitted_count = 0
    with db() as conn:
        ensure_chrome_job_owner(conn, group_key, worker_id)
        pending_rows = rows_to_dicts(conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(amazon_status, '') NOT IN ('order_submitted', 'reporting_complete')
            ORDER BY id
            """,
            (group_key,),
        ).fetchall())
        if not pending_rows:
            protected_row = conn.execute(
                """
                SELECT COUNT(*) AS count
                FROM order_lines
                WHERE amazon_group_key=?
                  AND order_engine='chrome'
                  AND state='submitted'
                  AND COALESCE(amazon_order_id, '') = ''
                  AND amazon_status IN ('order_submitted', 'reporting_complete')
                """,
                (group_key,),
            ).fetchone()
            submitted_count = int(protected_row["count"] or 0) if protected_row else 0
        else:
            _eligible, blocked_count, messages = filter_lines_by_live_odoo_status(
                conn,
                int(pending_rows[0]["store_id"]),
                pending_rows,
            )
            if blocked_count:
                blocked_message = messages[0] if messages else "Odoo order is not eligible for fulfilment."
            else:
                cursor = conn.execute(
                    """
                    UPDATE order_lines
                    SET amazon_status=?,
                        chrome_claimed_by=?,
                        chrome_claimed_at=COALESCE(chrome_claimed_at, ?),
                        chrome_claim_expires_at=?,
                        updated_at=?
                    WHERE amazon_group_key=?
                      AND order_engine='chrome'
                      AND state='submitted'
                      AND COALESCE(amazon_order_id, '') = ''
                    """,
                    (CHROME_ORDER_SUBMITTED_STATUS, worker_id, now, expiry, now, group_key),
                )
                submitted_count = cursor.rowcount
    if blocked_message:
        raise HTTPException(409, f"{blocked_message} Amazon Place Order was stopped.")
    if not submitted_count:
        raise HTTPException(404, "Chrome job not found")
    return {"ok": True, "submitted": submitted_count, "claim_expires_at": expiry}


@app.get("/api/chrome/jobs/{group_key}/completion-status")
def api_chrome_job_completion_status(group_key: str, line_ids: str = "") -> dict[str, Any]:
    group_key = clean_text(group_key)
    if not group_key:
        raise HTTPException(400, "Chrome group key is required")
    repair_missing_chrome_order_chatter()
    parsed_line_ids = sorted({
        int(match.group(0))
        for match in re.finditer(r"\d+", clean_text(line_ids))
        if int(match.group(0)) > 0
    })
    params: list[Any] = [group_key]
    line_filter = ""
    if parsed_line_ids:
        line_filter = f" AND id IN ({','.join('?' for _ in parsed_line_ids)})"
        params.extend(parsed_line_ids)
    with db() as conn:
        rows = rows_to_dicts(conn.execute(
            f"""
            SELECT id, store_id, odoo_order_id, odoo_order_name, asin, amazon_order_id, amazon_status, state,
                   chrome_claimed_by, chrome_claim_expires_at, updated_at
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              {line_filter}
            ORDER BY id
            """,
            params,
        ).fetchall())
        chatter_queued = bool(rows) and all(
            bool(clean_text(row.get("amazon_order_id"))) and bool(conn.execute(
                """
                SELECT 1
                FROM odoo_chatter_note_log
                WHERE store_id=?
                  AND odoo_order_id=?
                  AND event_type='amazon_order_placed'
                  AND amazon_order_id=?
                LIMIT 1
                """,
                (
                    int(row["store_id"]),
                    int(row["odoo_order_id"]),
                    clean_text(row.get("amazon_order_id")),
                ),
            ).fetchone())
            for row in rows
        )
        chatter_confirmed = chatter_queued and all(
            bool(conn.execute(
                """
                SELECT 1
                FROM odoo_chatter_note_log
                WHERE store_id=?
                  AND odoo_order_id=?
                  AND event_type='amazon_order_placed'
                  AND amazon_order_id=?
                  AND posted_at IS NOT NULL
                LIMIT 1
                """,
                (
                    int(row["store_id"]),
                    int(row["odoo_order_id"]),
                    clean_text(row.get("amazon_order_id")),
                ),
            ).fetchone())
            for row in rows
        )
    if not rows:
        raise HTTPException(404, "Chrome job not found")
    pending_rows = [row for row in rows if not clean_text(row.get("amazon_order_id"))]
    amazon_order_ids = sorted({
        clean_text(row.get("amazon_order_id"))
        for row in rows
        if clean_text(row.get("amazon_order_id"))
    })
    return {
        "ok": True,
        "group_key": group_key,
        "line_ids": [int(row["id"]) for row in rows],
        "completed": bool(rows) and not pending_rows and chatter_queued,
        "data_saved": bool(rows) and not pending_rows,
        "odoo_chatter_queued": chatter_queued,
        "odoo_chatter_confirmed": chatter_confirmed,
        "partial_completed": bool(amazon_order_ids) and bool(pending_rows),
        "amazon_order_ids": amazon_order_ids,
        "pending_line_ids": [int(row["id"]) for row in pending_rows],
        "pending_count": len(pending_rows),
        "claimed_by": clean_text(rows[0].get("chrome_claimed_by")),
        "claim_expires_at": clean_text(rows[0].get("chrome_claim_expires_at")),
    }


