@app.post("/api/chrome/jobs/{group_key}/post-submit-unplaced")
def api_chrome_job_post_submit_unplaced(group_key: str, payload: ChromeJobFailPayload) -> dict[str, Any]:
    group_key = clean_text(group_key)
    message = clean_error_message(payload.message or "Amazon did not place the order after submit.")
    missing_asin = normalize_asin(payload.missing_asin)
    if not group_key:
        raise HTTPException(400, "group_key is required")
    with db() as conn:
        ensure_chrome_job_owner(conn, group_key, payload.worker_id)
        rows = rows_to_dicts(conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(amazon_status, '')=?
            """,
            (group_key, CHROME_ORDER_SUBMITTED_STATUS),
        ).fetchall())
        if not rows:
            raise HTTPException(409, "Chrome job is not in a protected submitted state without an Amazon order ID.")
        eligible_ids = {int(row["id"]) for row in rows}
        if payload.line_ids:
            line_ids = {int(value) for value in payload.line_ids if int(value or 0) > 0}
            eligible_ids = eligible_ids.intersection(line_ids)
        if payload.missing_line_id:
            eligible_ids = eligible_ids.intersection({int(payload.missing_line_id)})
        if not eligible_ids:
            raise HTTPException(404, "No matching submitted Chrome line could be moved to Missing ASINs.")
        placeholders = ",".join("?" for _ in eligible_ids)
        now = utc_now()
        conn.execute(
            f"""
            UPDATE order_lines
            SET state='missing',
                amazon_status='missing',
                amazon_order_id='',
                amazon_order_url='',
                last_error=?,
                missing_asin=?,
                chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL,
                updated_at=?
            WHERE id IN ({placeholders})
            """,
            [message, missing_asin, now, *sorted(eligible_ids)],
        )
        conn.execute(
            """
            UPDATE amazon_attempts
            SET status='missing', error=?
            WHERE external_id=? AND mode='chrome'
            """,
            (message, group_key),
        )
        updated_rows = rows_to_dicts(conn.execute(
            f"SELECT * FROM order_lines WHERE id IN ({placeholders})",
            sorted(eligible_ids),
        ).fetchall())
    for updated in updated_rows:
        index_order_line(updated)
    return {
        "ok": True,
        "message": f"Moved {len(updated_rows)} Chrome line(s) to Missing ASINs because Amazon did not place the order after submit.",
        "moved": len(updated_rows),
    }


@app.post("/api/chrome/jobs/{group_key}/submit-uncertain")
def api_chrome_job_submit_uncertain(group_key: str, payload: ChromeJobFailPayload) -> dict[str, Any]:
    group_key = clean_text(group_key)
    message = clean_error_message(
        payload.message
        or "Amazon Place Order was submitted, but no matching Amazon order appeared in order history. Marked as Chrome error instead of Missing."
    )
    if not group_key:
        raise HTTPException(400, "group_key is required")
    recovered_reporting_state = False
    with db() as conn:
        ensure_chrome_job_owner(conn, group_key, payload.worker_id)
        rows = rows_to_dicts(conn.execute(
            """
            SELECT *
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(amazon_status, '')=?
            """,
            (group_key, CHROME_ORDER_SUBMITTED_STATUS),
        ).fetchall())
        if not rows:
            # Chrome can restore a persisted find_order_id stage after a
            # service-worker/browser restart while the database row has lost
            # its order_submitted marker. Rejecting the terminal uncertainty
            # report leaves that worker renewing the same lock forever and
            # deadlocks the entire queue. Only recover recognized post-submit
            # reporting outcomes, only for the current lock owner, and only
            # while no Amazon order ID exists.
            failure_code = clean_text(payload.failure_code).lower().replace("-", "_").replace(" ", "_")
            recoverable_codes = {"submitted_order_not_found", "ambiguous_submitted_order_history"}
            if failure_code not in recoverable_codes:
                raise HTTPException(409, "Chrome job is not in a protected submitted state without an Amazon order ID.")
            rows = rows_to_dicts(conn.execute(
                """
                SELECT *
                FROM order_lines
                WHERE amazon_group_key=?
                  AND order_engine='chrome'
                  AND state='submitted'
                  AND COALESCE(amazon_order_id, '') = ''
                  AND chrome_claimed_by=?
                """,
                (group_key, clean_text(payload.worker_id)),
            ).fetchall())
            if not rows:
                raise HTTPException(409, "Chrome job is not in a protected submitted state without an Amazon order ID.")
            recovered_reporting_state = True
            message = clean_error_message(
                f"{message} Recovered inconsistent Chrome submitted-reporting state so the remaining queue could continue."
            )
        eligible_ids = {int(row["id"]) for row in rows}
        if payload.line_ids:
            line_ids = {int(value) for value in payload.line_ids if int(value or 0) > 0}
            eligible_ids = eligible_ids.intersection(line_ids)
        if not eligible_ids:
            raise HTTPException(404, "No matching submitted Chrome line could be held for verification.")
        placeholders = ",".join("?" for _ in eligible_ids)
        now = utc_now()
        conn.execute(
            f"""
            UPDATE order_lines
            SET last_error=?, updated_at=?
            WHERE id IN ({placeholders})
            """,
            [message, now, *sorted(eligible_ids)],
        )
        conn.execute(
            """
            UPDATE amazon_attempts
            SET error=?
            WHERE external_id=? AND mode='chrome'
            """,
            (message, group_key),
        )
    send_email_alert_async(
        f"Chrome submit uncertain: {group_key}",
        f"Amazon Place Order was submitted, but no matching Amazon order was found.\nGroup: {group_key}\nWorker: {payload.worker_id}\nError: {message}",
    )
    return {
        "ok": False,
        "held_for_verification": True,
        "message": f"Held {len(eligible_ids)} submitted Chrome line(s) until a verified Amazon order ID is reported to Odoo.",
        "moved": 0,
        "recovered_reporting_state": recovered_reporting_state,
    }


@app.post("/api/chrome/jobs/{group_key}/preflight-missing")
def api_chrome_job_preflight_missing(group_key: str, payload: dict[str, Any]) -> dict[str, Any]:
    group_key = clean_text(group_key)
    message = clean_error_message(payload.get("message") or "Chrome split-order preflight found an unavailable ASIN.")
    missing_asin = normalize_asin(payload.get("missing_asin") or "")
    missing_line_id = parse_optional_int(payload.get("missing_line_id"))
    checked_url = clean_text(payload.get("checked_url") or "")
    if not group_key:
        raise HTTPException(400, "group_key is required")
    with db() as conn:
        ensure_chrome_job_not_protected_after_submit(conn, group_key, "preflight missing report")
        claimed = rows_to_dicts(conn.execute(
            """
            SELECT DISTINCT chrome_claimed_by
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND COALESCE(chrome_claimed_by, '') != ''
            """,
            (group_key,),
        ).fetchall())
        if claimed:
            raise HTTPException(409, "Chrome job is already claimed and cannot be preflight-moved.")
    full_message = message
    if checked_url:
        full_message = f"{message} Checked URL: {checked_url}"
    count = mark_chrome_group_missing(group_key, full_message, missing_asin, missing_line_id)
    if not count:
        raise HTTPException(404, "Chrome job not found")
    return {"ok": True, "message": f"Preflight moved {count} Chrome line(s) to Missing ASINs before split ordering.", "moved": count}


@app.post("/api/chrome/jobs/{group_key}/duplicate-check")
def api_chrome_job_duplicate_check(group_key: str, payload: ChromeJobResetPayload) -> dict[str, Any]:
    line_ids = sorted({int(line_id) for line_id in payload.line_ids if int(line_id or 0) > 0})
    if not line_ids:
        return {"ok": True, "duplicate": False, "orders": []}
    placeholders = ",".join("?" for _ in line_ids)
    with db() as conn:
        selected_rows = conn.execute(
            f"""
            SELECT id, store_id, odoo_order_id
            FROM order_lines
            WHERE id IN ({placeholders})
            """,
            line_ids,
        ).fetchall()
        if not selected_rows:
            return {"ok": True, "duplicate": False, "orders": []}
        duplicate_rows = conn.execute(
            f"""
            SELECT id, store_id, odoo_order_id, odoo_order_name, amazon_order_id,
                   amazon_order_url, amazon_cancelled_order_id
            FROM order_lines
            WHERE id IN ({placeholders})
              AND COALESCE(amazon_order_id, '') != ''
            ORDER BY odoo_order_name, amazon_order_id, id
            """,
            line_ids,
        ).fetchall()
    orders: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in duplicate_rows:
        amazon_order_id = clean_text(row["amazon_order_id"])
        if not amazon_order_id:
            continue
        if amazon_order_id == clean_text(row.get("amazon_cancelled_order_id")):
            continue
        key = f"{row['store_id']}:{row['odoo_order_id']}:{amazon_order_id}"
        if key in seen:
            continue
        seen.add(key)
        orders.append(
            {
                "line_id": row["id"],
                "store_id": row["store_id"],
                "odoo_order_id": row["odoo_order_id"],
                "order_name": row["odoo_order_name"],
                "amazon_order_id": amazon_order_id,
                "amazon_order_url": clean_text(row["amazon_order_url"]) or order_line_amazon_url(amazon_order_id),
            }
        )
    message = ""
    if orders:
        message = "Amazon order already exists in the app: " + ", ".join(
            f"{item['amazon_order_id']} ({item['order_name']})" for item in orders
        )
    return {"ok": True, "duplicate": bool(orders), "orders": orders, "message": message}


@app.post("/api/chrome/jobs/{group_key}/reset-fulfilment")
def api_chrome_job_reset_fulfilment(group_key: str, payload: ChromeJobResetPayload) -> dict[str, Any]:
    worker_id = clean_text(payload.worker_id)
    line_ids = sorted({int(line_id) for line_id in payload.line_ids if int(line_id or 0) > 0})
    if not worker_id:
        raise HTTPException(400, "worker_id is required")
    if not line_ids:
        raise HTTPException(400, "line_ids are required")
    placeholders = ",".join("?" for _ in line_ids)
    now = utc_now()
    expiry = chrome_job_lease_expiry()
    with db() as conn:
        rows = conn.execute(
            f"""
            SELECT *
            FROM order_lines
            WHERE id IN ({placeholders})
              AND amazon_group_key=?
              AND order_engine='chrome'
            """,
            [*line_ids, group_key],
        ).fetchall()
        if not rows:
            raise HTTPException(404, "Chrome job lines not found.")
        tag_pairs = {(int(row["store_id"]), int(row["odoo_order_id"])) for row in rows}
        # Resetting fulfilment must not remove replacement ASIN decisions.
        # Those fields are only changed by the manual replacement action on the orders page.
        cursor = conn.execute(
            f"""
            UPDATE order_lines
            SET amazon_order_id=NULL,
                amazon_order_url=NULL,
                amazon_account_name=NULL,
                amazon_status=NULL,
                tracking_status=NULL,
                tracking_payload=NULL,
                tracking_checked_at=NULL,
                state='submitted',
                chrome_claimed_by=?,
                chrome_claimed_at=COALESCE(chrome_claimed_at, ?),
                chrome_claim_expires_at=?,
                amazon_unit_price=NULL,
                amazon_total_price=NULL,
                chrome_profit_total=NULL,
                fulfilment_note=NULL,
                last_error=NULL,
                ordered_at=NULL,
                updated_at=?
            WHERE id IN ({placeholders})
              AND amazon_group_key=?
              AND order_engine='chrome'
            """,
            [worker_id, now, expiry, now, *line_ids, group_key],
        )
        conn.execute(
            f"""
            UPDATE amazon_attempts
            SET status='queued', error=NULL
            WHERE order_line_id IN ({placeholders})
              AND mode='chrome'
              AND status IN ('ok', 'error', 'costly', 'missing', 'reset')
            """,
            line_ids,
        )
        updated_rows = conn.execute(
            f"SELECT * FROM order_lines WHERE id IN ({placeholders})",
            line_ids,
        ).fetchall()
    for row in updated_rows:
        index_order_line(row)
    threading.Thread(target=sync_odoo_ordered_tags_for_pairs, args=(tag_pairs,), daemon=True).start()
    return {
        "ok": True,
        "reset": cursor.rowcount,
        "message": f"Cleared existing Amazon order from {cursor.rowcount} Chrome line(s). Replacement ASINs were preserved. You can continue fulfilment.",
    }


@app.post("/api/chrome/jobs/{group_key}/force-release")
def api_chrome_job_force_release(group_key: str, store_id: Optional[int] = None) -> dict[str, Any]:
    cleaned_group_key = clean_text(group_key)
    if not cleaned_group_key:
        raise HTTPException(400, "Chrome group key is required")
    with db() as conn:
        rows = conn.execute(
            """
            SELECT DISTINCT chrome_claimed_by
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND (? IS NULL OR store_id=?)
            """,
            (cleaned_group_key, store_id, store_id),
        ).fetchall()
        worker_ids = sorted({clean_text(row["chrome_claimed_by"]) for row in rows if clean_text(row["chrome_claimed_by"])})
        cursor = conn.execute(
            """
            UPDATE order_lines
            SET chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL,
                updated_at=?
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND state='submitted'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(chrome_claimed_by, '') != ''
              AND COALESCE(amazon_status, '') NOT IN ('order_submitted', 'reporting_complete')
              AND (? IS NULL OR store_id=?)
            """,
            (utc_now(), cleaned_group_key, store_id, store_id),
        )
    message = f"Released {cursor.rowcount} locked Chrome line(s) for {cleaned_group_key}."
    if worker_ids:
        message += f" Previous worker: {', '.join(worker_ids)}."
    return {"ok": True, "released": cursor.rowcount, "message": message}


