def reset_unsubmitted_chrome_queue(
    store_id: Optional[int] = None,
    *,
    attempt_status: str = "force_cleared",
    attempt_error: str = "Chrome queue force cleared from extension popup.",
) -> tuple[int, int]:
    now = utc_now()
    with db() as conn:
        protected = int(conn.execute(
            """
            SELECT COUNT(*) AS count
            FROM order_lines
            WHERE order_engine='chrome'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(amazon_group_key, '') != ''
              AND COALESCE(amazon_status, '') IN ('order_submitted', 'reporting_complete')
              AND (? IS NULL OR store_id=?)
            """,
            (store_id, store_id),
        ).fetchone()["count"] or 0)
        cursor = conn.execute(
            """
            UPDATE order_lines
            SET state='pulled',
                amazon_status=NULL,
                amazon_group_key=NULL,
                chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL,
                last_error=NULL,
                updated_at=?
            WHERE order_engine='chrome'
              AND COALESCE(amazon_order_id, '') = ''
              AND COALESCE(amazon_group_key, '') != ''
              AND COALESCE(amazon_status, '') NOT IN ('order_submitted', 'reporting_complete')
              AND (? IS NULL OR store_id=?)
            """,
            (now, store_id, store_id),
        )
        conn.execute(
            """
            UPDATE amazon_attempts
            SET status=?,
                error=?
            WHERE mode='chrome'
              AND status IN ('queued', 'error')
            """,
            (attempt_status, attempt_error),
        )
    return cursor.rowcount, protected


@app.post("/api/chrome/auto-ordering/pause")
def api_pause_chrome_auto_ordering() -> dict[str, Any]:
    # Block extension claims immediately. If a scheduler pass already owns the
    # lock, wait for it and then reset everything it left unsubmitted.
    set_setting("auto_chrome_fulfil_enabled", "false")
    with _AUTO_CHROME_QUEUE_CONTROL_LOCK:
        set_setting("auto_chrome_fulfil_last_message", "Automatic Chrome ordering paused; unsubmitted queue reset to pulled.")
        cleared, protected = reset_unsubmitted_chrome_queue(
            attempt_status="auto_ordering_paused",
            attempt_error="Automatic Chrome ordering paused from app settings.",
        )
    fast_page_cache_clear_matching({"settings-services"})
    message = f"Automatic Chrome ordering paused. Returned {cleared} unsubmitted queue line(s) to pulled."
    if protected:
        message += f" Preserved {protected} line(s) already submitted to Amazon and awaiting reporting."
    return {
        "ok": True,
        "enabled": False,
        "cleared": cleared,
        "protected": protected,
        "start_date": normalized_auto_chrome_start_date(get_service_settings().get("auto_chrome_fulfil_start_date")),
        "message": message,
    }


@app.post("/api/chrome/auto-ordering/resume")
def api_resume_chrome_auto_ordering(payload: dict[str, Any]) -> dict[str, Any]:
    start_date = normalized_auto_chrome_start_date(payload.get("start_date"))
    if not start_date:
        raise HTTPException(400, "Choose a valid auto-ordering start date before enabling.")
    with _AUTO_CHROME_QUEUE_CONTROL_LOCK:
        set_setting("auto_chrome_fulfil_start_date", start_date)
        set_setting("auto_chrome_fulfil_enabled", "true")
        set_setting("auto_chrome_fulfil_last_run_at", "")
        set_setting(
            "auto_chrome_fulfil_last_message",
            f"Automatic Chrome ordering enabled for eligible Odoo orders dated {start_date} or later; queue refresh pending.",
        )
        ready_missing_queued = auto_queue_all_ready_missing_orders()
    fast_page_cache_clear_matching({"settings-services"})
    return {
        "ok": True,
        "enabled": True,
        "start_date": start_date,
        "ready_missing_queued": ready_missing_queued,
        "message": (
            f"Automatic Chrome ordering enabled. Eligible orders dated {start_date} or later will be queued on the next scheduler pass. "
            f"Queued {ready_missing_queued} ready missing/replacement order(s)."
        ),
    }


@app.post("/api/chrome/queue/force-clear")
def api_chrome_force_clear_queue(store_id: Optional[int] = None) -> dict[str, Any]:
    cleared, protected = reset_unsubmitted_chrome_queue(store_id)
    message = f"Force cleared {cleared} unsubmitted Chrome queue line(s)."
    if protected:
        message += f" Preserved {protected} submitted line(s) waiting for Amazon order-number reporting."
    return {"ok": True, "cleared": cleared, "protected": protected, "message": message}


def amazon_asin_internal_note(current: Any, asin: str) -> str:
    current_text = str(current or "").strip()
    normalized_asin = normalize_asin(asin)
    if not normalized_asin:
        return current_text
    explicit_asins = {
        normalize_asin(match)
        for match in re.findall(r"Amazon\s+ASIN\s*:\s*([A-Z0-9]{10})", current_text, re.IGNORECASE)
        if normalize_asin(match)
    }
    if normalized_asin in explicit_asins:
        return current_text
    asin_line = f"<p>Amazon ASIN: {html.escape(normalized_asin)}</p>"
    return f"{current_text}\n{asin_line}".strip()


def update_replacement_asin_in_odoo(
    store_id: int,
    selected_rows: list[dict[str, Any]],
    replacement_asin: str,
) -> dict[str, Any]:
    asin = normalize_asin(replacement_asin)
    if not asin:
        raise HTTPException(400, "Enter a valid 10-character replacement ASIN before updating Odoo.")
    if len(selected_rows) != 1:
        raise HTTPException(
            400,
            "Select exactly one order line when updating an Odoo product replacement ASIN.",
        )
    row = selected_rows[0]
    odoo_line_ids = source_odoo_line_ids(row)
    if len(odoo_line_ids) != 1:
        raise HTTPException(400, "The selected row must point to exactly one Odoo order line.")
    try:
        odoo = OdooClient(get_store(int(store_id)))
        order_line_fields = odoo.existing_fields("sale.order.line", ["id", "product_id"])
        odoo_lines = odoo.read("sale.order.line", odoo_line_ids, order_line_fields)
        product_ids = sorted({
            int(line["product_id"][0])
            for line in odoo_lines
            if line.get("product_id")
        })
        if len(product_ids) != 1:
            raise HTTPException(400, "The selected Odoo order line does not point to exactly one product.")
        product_id = product_ids[0]
        product_fields = odoo.existing_fields(
            "product.product",
            ["id", "display_name", "default_code", "description", "product_tmpl_id"],
        )
        if "default_code" not in product_fields or "description" not in product_fields:
            raise HTTPException(400, "Odoo product reference or internal notes are unavailable for this product.")
        products = odoo.read("product.product", [product_id], product_fields)
        if not products:
            raise HTTPException(404, "The selected Odoo product was not found.")
        product = products[0]
        duplicates = odoo.execute(
            "product.product",
            "search_read",
            [[("default_code", "=ilike", asin), ("id", "!=", product_id)]],
            {
                "fields": [field for field in ("id", "display_name", "default_code") if field in product_fields],
                "limit": 5,
                "context": {"active_test": False},
            },
        )
        if duplicates:
            duplicate = duplicates[0]
            duplicate_name = clean_text(duplicate.get("display_name")) or f"product {duplicate.get('id')}"
            raise HTTPException(
                409,
                f"Odoo cannot have the same reference number on more than one product. "
                f"Reference {asin} already exists on {duplicate_name}. The product was not updated.",
            )
        current_reference = clean_text(product.get("default_code"))
        current_note = product.get("description") or ""
        next_note = amazon_asin_internal_note(current_note, asin)
        values: dict[str, Any] = {}
        if current_reference.upper() != asin:
            # This is intentionally the plain/decoded ASIN. Replacement ASINs
            # are promoted only through the explicit manual checkbox.
            values["default_code"] = asin
        if next_note != str(current_note or "").strip():
            values["description"] = next_note
        if values and not odoo.write("product.product", [product_id], values):
            raise RuntimeError("Odoo rejected the product update.")
        return {
            "asin": asin,
            "product_id": product_id,
            "product_name": clean_text(product.get("display_name")),
            "previous_reference": current_reference,
            "reference_updated": "default_code" in values,
            "note_updated": "description" in values,
            "internal_note": next_note,
        }
    except HTTPException:
        raise
    except Exception as exc:
        detail = clean_error_message(exc)[:500]
        lowered = detail.lower()
        if any(token in lowered for token in ("default_code", "reference", "unique", "already exists", "already used")):
            raise HTTPException(
                409,
                f"Odoo cannot have the same reference number on more than one product. "
                f"Reference {asin} was not saved. Odoo warning: {detail}",
            ) from exc
        raise HTTPException(502, f"Odoo product ASIN update failed. The product was not updated. {detail}") from exc


def amazon_product_cost_in_store_currency(row: dict[str, Any], pricing: dict[str, Any]) -> float:
    try:
        ordered_quantity = float(row.get("quantity") or pricing.get("ordered_quantity") or 1)
    except (TypeError, ValueError):
        ordered_quantity = 1.0
    try:
        amazon_total = float(pricing.get("amazon_total_price") or 0)
    except (TypeError, ValueError):
        amazon_total = 0.0
    try:
        amazon_unit = float(pricing.get("amazon_unit_price") or 0)
    except (TypeError, ValueError):
        amazon_unit = 0.0
    unit_cost_usd = (amazon_total / ordered_quantity) if amazon_total > 0 and ordered_quantity > 0 else amazon_unit
    if unit_cost_usd <= 0:
        return 0.0
    try:
        rate_to_usd = float(row.get("store_currency_rate_to_usd") or 1)
    except (TypeError, ValueError):
        rate_to_usd = 1.0
    if rate_to_usd <= 0:
        rate_to_usd = 1.0
    return round(unit_cost_usd / rate_to_usd, 4)


def source_odoo_line_ids(row: dict[str, Any]) -> list[int]:
    values = re.findall(r"\d+", clean_text(row.get("source_odoo_line_ids")))
    if not values and row.get("odoo_line_id"):
        values = [str(row["odoo_line_id"])]
    return sorted({int(value) for value in values if int(value) > 0})


def sync_amazon_order_products_to_odoo(
    rows: list[dict[str, Any]],
    pricing_by_asin: dict[str, dict[str, Any]],
) -> dict[str, int]:
    summary = {
        "products": 0,
        "notes": 0,
        "references": 0,
        "costs": 0,
        "sales_prices": 0,
        "replacement_skipped": 0,
        "errors": 0,
    }
    rows_by_store: dict[int, list[dict[str, Any]]] = {}
    for row in rows:
        try:
            rows_by_store.setdefault(int(row["store_id"]), []).append(row)
        except (KeyError, TypeError, ValueError):
            continue
    for store_id, store_rows in rows_by_store.items():
        try:
            odoo = OdooClient(get_store(store_id))
            line_plan: dict[int, dict[str, Any]] = {}
            for row in store_rows:
                requested_asin = normalize_asin(row.get("asin") or "")
                pricing = pricing_by_asin.get(requested_asin, {})
                purchased_asin = normalize_asin(pricing.get("purchased_asin") or requested_asin)
                if not purchased_asin:
                    continue
                if requested_asin and purchased_asin != requested_asin:
                    # A replacement is an order-specific customer offer. Never
                    # promote its ASIN or cost into the original Odoo product.
                    summary["replacement_skipped"] += 1
                    continue
                plan = {
                    "asin": purchased_asin,
                    "cost": amazon_product_cost_in_store_currency(row, pricing),
                }
                for line_id in source_odoo_line_ids(row):
                    line_plan[line_id] = plan
            if not line_plan:
                continue
            order_line_fields = odoo.existing_fields("sale.order.line", ["id", "product_id", "product_uom_qty"])
            order_lines = odoo.read("sale.order.line", sorted(line_plan), order_line_fields)
            product_ids = sorted({
                int(line["product_id"][0])
                for line in order_lines
                if line.get("product_id") and int(line["id"]) in line_plan
            })
            product_fields = odoo.existing_fields(
                "product.product",
                ["id", "product_tmpl_id", "default_code", "standard_price", "list_price"],
            )
            products = {
                int(product["id"]): product
                for product in odoo.read("product.product", product_ids, product_fields)
            }
            template_ids = sorted({
                int(product["product_tmpl_id"][0])
                for product in products.values()
                if product.get("product_tmpl_id")
            })
            template_fields = odoo.existing_fields(
                "product.template",
                ["id", "description", "default_code", "list_price"],
            )
            templates = {
                int(template["id"]): template
                for template in odoo.read("product.template", template_ids, template_fields)
            }
            plans_by_product: dict[int, dict[str, Any]] = {}
            for line in order_lines:
                line_id = int(line["id"])
                plan = line_plan.get(line_id)
                if not plan or not line.get("product_id"):
                    continue
                product_id = int(line["product_id"][0])
                product_plan = plans_by_product.setdefault(
                    product_id,
                    {"asins": [], "weighted_cost": 0.0, "cost_quantity": 0.0},
                )
                if plan["asin"] not in product_plan["asins"]:
                    product_plan["asins"].append(plan["asin"])
                cost = float(plan.get("cost") or 0)
                try:
                    quantity = max(0.0, float(line.get("product_uom_qty") or 1))
                except (TypeError, ValueError):
                    quantity = 1.0
                if cost > 0 and quantity > 0:
                    product_plan["weighted_cost"] += cost * quantity
                    product_plan["cost_quantity"] += quantity
            for product_id, plan in plans_by_product.items():
                product = products.get(product_id, {})
                template_id = many2one_id(product.get("product_tmpl_id"))
                template = templates.get(template_id or 0, {})
                asins = [asin for asin in plan["asins"] if normalize_asin(asin)]
                if not asins:
                    continue
                asin = asins[0]
                try:
                    product_values: dict[str, Any] = {}
                    template_values: dict[str, Any] = {}
                    current_reference = clean_text(product.get("default_code") or template.get("default_code") or "")
                    if not current_reference and "default_code" in product_fields:
                        product_values["default_code"] = encode_asin(asin)
                    if plan["cost_quantity"] > 0 and "standard_price" in product_fields:
                        next_cost = round(
                            float(plan["weighted_cost"]) / float(plan["cost_quantity"]),
                            4,
                        )
                        product_values["standard_price"] = next_cost
                        try:
                            current_sales_price = float(template.get("list_price") or product.get("list_price") or 0)
                        except (TypeError, ValueError):
                            current_sales_price = 0.0
                        if template_id and "list_price" in template_fields and next_cost > current_sales_price:
                            template_values["list_price"] = round(next_cost * 1.35, 2)
                    if product_values:
                        odoo.write("product.product", [product_id], product_values)
                        if "default_code" in product_values:
                            summary["references"] += 1
                        if "standard_price" in product_values:
                            summary["costs"] += 1
                    if template_id and "description" in template_fields:
                        current_note = template.get("description") or ""
                        next_note = amazon_asin_internal_note(current_note, asin)
                        if next_note != str(current_note or "").strip():
                            template_values["description"] = next_note
                            summary["notes"] += 1
                    if template_id and template_values:
                        odoo.write("product.template", [template_id], template_values)
                        if "list_price" in template_values:
                            summary["sales_prices"] += 1
                    summary["products"] += 1
                except Exception as exc:
                    summary["errors"] += 1
                    print(f"Amazon product metadata sync failed for store={store_id} product={product_id}: {exc}", flush=True)
        except Exception as exc:
            summary["errors"] += 1
            print(f"Amazon product metadata sync failed for store={store_id}: {exc}", flush=True)
    return summary


def chrome_complete_followups(
    rows: list[dict[str, Any]],
    pricing_by_asin: dict[str, dict[str, Any]],
    amazon_order_id: str,
    amazon_order_url: str,
    chrome_account_name: str,
    amazon_recipient: str = "",
) -> bool:
    """Durably queue Odoo chatter and run non-blocking report follow-ups.

    Chrome completion only waits for the unique outbox row to commit. Odoo
    network delivery and retries belong to the app-side outbox worker.
    """
    chatter_queued = False
    try:
        variant_notes_by_order: dict[int, list[str]] = {}
        for row in rows:
            pricing = pricing_by_asin.get(str(row["asin"] or "").upper(), {})
            fulfilment_note = append_note(
                clean_text(row.get("fulfilment_note")),
                clean_text(str(pricing.get("fulfilment_note") or "")),
            )
            if fulfilment_note:
                variant_notes_by_order.setdefault(int(row["odoo_order_id"]), []).append(fulfilment_note)
        order_url = amazon_order_url or order_line_amazon_url(amazon_order_id)
        store = get_store(int(rows[0]["store_id"]))
        chatter_queued = True
        for order_id in sorted({int(row["odoo_order_id"]) for row in rows}):
            order_rows = [row for row in rows if int(row["odoo_order_id"]) == order_id]
            order_note_parts = [
                f"<p><strong>Amazon Chrome order placed: {html.escape(amazon_order_id)}</strong></p>",
            ]
            if clean_text(amazon_recipient):
                order_note_parts.append(
                    f"<p><strong>Recipient:</strong> {html.escape(clean_text(amazon_recipient))}</p>"
                )
            item_lines: list[str] = []
            for row in order_rows:
                asin = normalize_asin(str(row.get("asin") or "")) or clean_text(row.get("asin")) or "UNKNOWN"
                quantity = float(row.get("quantity") or 1)
                quantity_text = str(int(quantity)) if quantity.is_integer() else f"{quantity:g}"
                item_lines.append(f"{html.escape(asin)} × {html.escape(quantity_text)}")
            order_note_parts.append(f"<p><strong>Items:</strong><br>{'<br>'.join(item_lines)}</p>")
            order_note_parts.append(f"<p><strong>Amazon account:</strong> {html.escape(chrome_account_name)}</p>")
            for fulfilment_note in variant_notes_by_order.get(order_id, []):
                order_note_parts.append(f"<p>{html.escape(fulfilment_note)}</p>")
            escaped_url = html.escape(order_url, quote=True)
            order_note_parts.append(
                f'<p><a href="{escaped_url}" target="_blank" rel="noopener noreferrer">Open Amazon order</a></p>'
            )
            order_note = "".join(order_note_parts)
            enqueue_odoo_chatter_note(
                store.id,
                order_id,
                "amazon_order_placed",
                amazon_order_id,
                order_note,
            )
    except Exception as exc:
        chatter_queued = False
        print(f"Chrome complete Odoo note enqueue failed: {exc}", flush=True)
    try:
        sync_odoo_ordered_tags_for_pairs({(int(row["store_id"]), int(row["odoo_order_id"])) for row in rows})
    except Exception as exc:
        print(f"Chrome complete Odoo tag failed: {exc}", flush=True)
    try:
        for store_id in sorted({int(row["store_id"]) for row in rows}):
            write_report(store_id)
    except Exception as exc:
        print(f"Chrome complete report refresh failed: {exc}", flush=True)
    return chatter_queued


def chrome_complete_shopify_followup(updated_for_shopify: list[dict[str, Any]]) -> None:
    """Queue Shopify fulfilment without blocking the Odoo audit follow-ups."""
    try:
        queued = enqueue_shopify_fulfilment_for_rows(updated_for_shopify)
        if queued:
            start_shopify_fulfilment_worker()
    except Exception as exc:
        print(f"Chrome complete Shopify enqueue failed: {exc}", flush=True)


def queue_chrome_complete_odoo_chatter(
    group_key: str,
    rows: list[dict[str, Any]],
    pricing_by_asin: dict[str, dict[str, Any]],
    amazon_order_id: str,
    amazon_order_url: str,
    chrome_account_name: str,
    worker_id: str,
    amazon_recipient: str = "",
) -> bool:
    queued = chrome_complete_followups(
        rows,
        pricing_by_asin,
        amazon_order_id,
        amazon_order_url,
        chrome_account_name,
        amazon_recipient,
    )
    if not queued:
        return False
    with db() as conn:
        conn.execute(
            """
            UPDATE order_lines
            SET chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL,
                updated_at=?
            WHERE amazon_group_key=?
              AND chrome_claimed_by=?
              AND COALESCE(amazon_order_id, '') != ''
            """,
            (utc_now(), clean_text(group_key), clean_text(worker_id)),
        )
    return True


def chrome_completion_history_evidence_error(
    group_key: str,
    rows: list[dict[str, Any]],
    payload: ChromeJobCompletePayload,
    pricing_by_asin: dict[str, dict[str, Any]],
    amazon_order_id: str,
) -> str:
    """Return a reason when the extension tries to attach an unproven ID.

    Amazon order IDs are only safe to save after the history card identifies
    the same Nutricity recipient and at least one expected ASIN (where Amazon
    exposes ASINs). This is deliberately enforced on the API as well as in
    the extension: a stale content script must never be able to write a
    neighbouring order's Amazon number.
    """
    if not re.fullmatch(r"\d{3}-\d{7}-\d{7}", amazon_order_id):
        return ""
    recipient = clean_text(payload.amazon_recipient)
    if not recipient:
        return f"Refused to report Amazon order {amazon_order_id}: no recipient evidence was supplied from Amazon order history."
    expected_refs = {
        clean_text(row.get("odoo_order_name")).upper()
        for row in rows
        if clean_text(row.get("odoo_order_name"))
    }
    recipient_refs = set(amazon_order_refs_from_text(recipient))
    if not expected_refs or not expected_refs.issubset(recipient_refs):
        expected_text = ", ".join(sorted(expected_refs)) or group_key
        return (
            f"Refused to report Amazon order {amazon_order_id}: Amazon history recipient \"{recipient}\" "
            f"does not match this job ({expected_text})."
        )

    observed_asins = {normalize_asin(value) for value in payload.amazon_asins if normalize_asin(value)}
    expected_asins = {normalize_asin(str(row.get("asin") or "")) for row in rows if normalize_asin(str(row.get("asin") or ""))}
    expected_asins.update(
        normalize_asin(str(pricing.get("purchased_asin") or ""))
        for pricing in pricing_by_asin.values()
        if normalize_asin(str(pricing.get("purchased_asin") or ""))
    )
    if observed_asins and expected_asins and not observed_asins.intersection(expected_asins):
        bundle_evidence = payload.business_bundle_expansion or {}

        def positive_number(value: Any) -> float:
            try:
                return max(0.0, float(value or 0))
            except (TypeError, ValueError):
                return 0.0

        verified_quantities = {
            normalize_asin(str(asin or "")): positive_number(quantity)
            for asin, quantity in (bundle_evidence.get("verified_cart_quantities") or {}).items()
            if normalize_asin(str(asin or "")) and positive_number(quantity) > 0
        }
        expected_bundle_units = positive_number(bundle_evidence.get("expected_bundle_units"))
        checkout_physical_units = positive_number(bundle_evidence.get("checkout_physical_units"))
        row_units = sum(positive_number(row.get("quantity")) for row in rows)
        verified_business_bundle = bool(
            required_chrome_account_experience(rows) == "business"
            and clean_text(bundle_evidence.get("group_key")) == clean_text(group_key)
            and clean_text(bundle_evidence.get("account_experience")).lower() == "business"
            and len(rows) == 1
            and set(verified_quantities) == expected_asins
            and abs(sum(verified_quantities.values()) - expected_bundle_units) < 0.001
            and abs(row_units - expected_bundle_units) < 0.001
            and checkout_physical_units > expected_bundle_units > 0
            and len(observed_asins) <= checkout_physical_units
        )
        if not verified_business_bundle:
            return (
                f"Refused to report Amazon order {amazon_order_id}: Amazon history ASINs "
                f"{', '.join(sorted(observed_asins))} do not match this job's ASINs {', '.join(sorted(expected_asins))}."
            )
    return ""


@app.post("/api/chrome/jobs/{group_key}/complete")
def api_chrome_job_complete(group_key: str, payload: ChromeJobCompletePayload) -> dict[str, Any]:
    amazon_order_id = clean_text(payload.amazon_order_id)
    if not re.fullmatch(r"\d{3}-\d{7}-\d{7}", amazon_order_id):
        raise HTTPException(409, "A valid Amazon order ID is required before a Chrome job can be completed.")
    amazon_order_url = clean_text(payload.amazon_order_url)
    chrome_account_name = clean_text(payload.amazon_account_name) or "Chrome Extension"
    amazon_order_placed_at = parse_amazon_order_placed_date(payload.order_date)
    ordered_at = amazon_order_placed_at or utc_now()
    pricing_by_asin: dict[str, dict[str, Any]] = {}
    for item in payload.pricing_summary or []:
        asin = normalize_asin(str(item.get("asin") or ""))
        if asin:
            pricing_by_asin[asin] = item
    order_by_line_id: dict[int, dict[str, str]] = {}
    order_by_asin: dict[str, dict[str, str]] = {}
    mapped_line_ids: set[int] = set()
    mapped_asins: set[str] = set()
    for mapping in payload.order_mappings or []:
        mapped_order_id = clean_text(str(mapping.get("amazon_order_id") or ""))
        if not mapped_order_id:
            continue
        mapped_url = clean_text(str(mapping.get("amazon_order_url") or "")) or order_line_amazon_url(mapped_order_id)
        normalized_mapping = {"amazon_order_id": mapped_order_id, "amazon_order_url": mapped_url}
        for line_id in mapping.get("line_ids") or []:
            try:
                normalized_line_id = int(line_id)
                order_by_line_id[normalized_line_id] = normalized_mapping
                mapped_line_ids.add(normalized_line_id)
            except (TypeError, ValueError):
                continue
        mapped_asin = normalize_asin(str(mapping.get("asin") or ""))
        if mapped_asin:
            order_by_asin[mapped_asin] = normalized_mapping
            mapped_asins.add(mapped_asin)
    with db() as conn:
        ensure_chrome_job_owner(conn, group_key, payload.worker_id)
        params: list[Any] = [group_key]
        line_filter = ""
        if payload.line_ids:
            line_filter = f" AND id IN ({','.join('?' for _ in payload.line_ids)})"
            params.extend(payload.line_ids)
        rows = conn.execute(
            f"""
            SELECT *
            FROM order_lines
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              AND (state='submitted' OR COALESCE(amazon_status, '') IN ('submitted', 'order_submitted', 'reporting_complete'))
              AND COALESCE(amazon_order_id, '') = ''
              {line_filter}
            """,
            params,
        ).fetchall()
        if not rows:
            completed_params: list[Any] = [group_key]
            completed_line_filter = ""
            if payload.line_ids:
                completed_line_filter = f" AND id IN ({','.join('?' for _ in payload.line_ids)})"
                completed_params.extend(payload.line_ids)
            completed_rows = conn.execute(
                """
                SELECT *
                FROM order_lines
                WHERE amazon_group_key=?
                  AND order_engine='chrome'
                  AND COALESCE(amazon_order_id, '') != ''
                  """ + completed_line_filter + """
                ORDER BY ordered_at DESC, updated_at DESC
                """,
                completed_params,
            ).fetchall()
            if completed_rows:
                completed_dicts = [dict(row) for row in completed_rows]
                evidence_error = chrome_completion_history_evidence_error(
                    group_key,
                    completed_dicts,
                    payload,
                    pricing_by_asin,
                    amazon_order_id,
                )
                if evidence_error:
                    raise HTTPException(409, evidence_error)
                existing_ids = sorted({
                    clean_text(str(row.get("amazon_order_id") or ""))
                    for row in completed_dicts
                    if clean_text(str(row.get("amazon_order_id") or ""))
                })
                incoming_is_real_order = re.fullmatch(r"\d{3}-\d{7}-\d{7}", amazon_order_id) is not None
                if incoming_is_real_order and amazon_order_id not in existing_ids:
                    completed_asins = sorted({
                        normalize_asin(str(row.get("asin") or ""))
                        for row in completed_dicts
                        if normalize_asin(str(row.get("asin") or ""))
                    })
                    if len(completed_dicts) > 1 and len(completed_asins) > 1 and not payload.order_mappings:
                        raise HTTPException(
                            409,
                            f"Refused to replace already-recorded Amazon order {', '.join(existing_ids) or 'UNKNOWN'} with {amazon_order_id} for multi-ASIN Chrome job {group_key} because no ASIN-to-order mapping was provided.",
                        )
                    if payload.order_mappings and len(completed_dicts) > 1:
                        unmapped_completed = [
                            row
                            for row in completed_dicts
                            if int(row["id"]) not in mapped_line_ids and normalize_asin(str(row.get("asin") or "")) not in mapped_asins
                        ]
                        if unmapped_completed:
                            expected = ", ".join(
                                f"{row['odoo_order_name']} line {row['id']} ASIN {normalize_asin(str(row.get('asin') or '')) or 'UNKNOWN'}"
                                for row in unmapped_completed[:5]
                            )
                            raise HTTPException(
                                409,
                                f"Refused to replace already-recorded Amazon order {', '.join(existing_ids) or 'UNKNOWN'} with {amazon_order_id} because ASIN mapping did not cover every line in multi-line Chrome job {group_key}. Unmapped: {expected}.",
                            )
                    updated_for_shopify: list[dict[str, Any]] = []
                    now = utc_now()
                    for row in completed_dicts:
                        row_asin = normalize_asin(str(row.get("asin") or ""))
                        row_order = order_by_line_id.get(int(row["id"])) or order_by_asin.get(row_asin) or {}
                        row_amazon_order_id = row_order.get("amazon_order_id") or amazon_order_id
                        row_amazon_order_url = row_order.get("amazon_order_url") or amazon_order_url or order_line_amazon_url(row_amazon_order_id)
                        conn.execute(
                            """
                            UPDATE order_lines
                            SET amazon_order_id=?,
                                amazon_order_url=?,
                                amazon_account_name=?,
                                amazon_status='ordered',
                                state='ordered',
                                missing_asin=NULL,
                                last_error=NULL,
                                ordered_at=?,
                                updated_at=?
                            WHERE id=?
                            """,
                            (
                                row_amazon_order_id,
                                row_amazon_order_url,
                                chrome_account_name,
                                ordered_at,
                                now,
                                row["id"],
                            ),
                        )
                        updated = conn.execute("SELECT * FROM order_lines WHERE id = ?", (row["id"],)).fetchone()
                        if updated:
                            updated_dict = dict(updated)
                            updated_for_shopify.append(updated_dict)
                            index_order_line(updated_dict)
                    conn.execute(
                        """
                        UPDATE amazon_attempts
                        SET response_json=?, status='ok', error=NULL
                        WHERE external_id=? AND mode='chrome'
                        """,
                        (
                            json.dumps(
                                {
                                    "amazon_order_id": amazon_order_id,
                                    "amazon_order_url": amazon_order_url or order_line_amazon_url(amazon_order_id),
                                    "previous_amazon_order_ids": existing_ids,
                                    "corrected_completed_order": True,
                                    "amazon_account_name": chrome_account_name,
                                }
                            ),
                            group_key,
                        ),
                    )
                    try:
                        for store_id in sorted({int(row["store_id"]) for row in updated_for_shopify}):
                            write_report(store_id)
                    except Exception as exc:
                        print(f"Chrome complete report refresh after correction failed: {exc}", flush=True)
                    clear_order_progress_caches()
                    chatter_queued = queue_chrome_complete_odoo_chatter(
                        group_key,
                        updated_for_shopify or completed_dicts,
                        pricing_by_asin,
                        amazon_order_id,
                        amazon_order_url or order_line_amazon_url(amazon_order_id),
                        chrome_account_name,
                        payload.worker_id,
                        payload.amazon_recipient,
                    )
                    if not chatter_queued:
                        raise HTTPException(
                            503,
                            f"Amazon order {amazon_order_id} was corrected, but the Odoo chatter outbox could not be queued.",
                        )
                    return {
                        "ok": True,
                        "message": f"Chrome job {group_key} corrected from Amazon {', '.join(existing_ids) or 'UNKNOWN'} to {amazon_order_id}.",
                        "amazon_order_id": amazon_order_id,
                        "previous_amazon_order_ids": existing_ids,
                        "corrected_completed": True,
                        "odoo_chatter_queued": True,
                        "odoo_chatter_confirmed": odoo_chatter_note_is_posted(
                            int((updated_for_shopify or completed_dicts)[0]["store_id"]),
                            int((updated_for_shopify or completed_dicts)[0]["odoo_order_id"]),
                            "amazon_order_placed",
                            amazon_order_id,
                        ),
                    }
                completed_order_id = existing_ids[0] if existing_ids else amazon_order_id
                chatter_queued = queue_chrome_complete_odoo_chatter(
                    group_key,
                    completed_dicts,
                    pricing_by_asin,
                    completed_order_id,
                    amazon_order_url or order_line_amazon_url(completed_order_id),
                    chrome_account_name,
                    payload.worker_id,
                    payload.amazon_recipient,
                )
                if not chatter_queued:
                    raise HTTPException(
                        503,
                        f"Amazon order {completed_order_id} is saved, but the Odoo chatter outbox could not be queued.",
                    )
                return {
                    "ok": True,
                    "message": f"Chrome job {group_key} was already marked ordered.",
                    "amazon_order_id": completed_order_id,
                    "already_completed": True,
                    "odoo_chatter_queued": True,
                    "odoo_chatter_confirmed": odoo_chatter_note_is_posted(
                        int(completed_dicts[0]["store_id"]),
                        int(completed_dicts[0]["odoo_order_id"]),
                        "amazon_order_placed",
                        completed_order_id,
                    ),
                }
            raise HTTPException(404, "Chrome job not found")
        row_dicts = [dict(row) for row in rows]
        evidence_error = chrome_completion_history_evidence_error(
            group_key,
            row_dicts,
            payload,
            pricing_by_asin,
            amazon_order_id,
        )
        if evidence_error:
            raise HTTPException(409, evidence_error)
        row_asins = sorted({normalize_asin(str(row["asin"] or "")) for row in row_dicts if normalize_asin(str(row["asin"] or ""))})
        if len(row_dicts) > 1 and len(row_asins) > 1 and not payload.order_mappings:
            raise HTTPException(
                409,
                f"Refused to report Amazon order {amazon_order_id} to multi-ASIN Chrome job {group_key} because no ASIN-to-order mapping was provided.",
            )
        if payload.order_mappings and len(row_dicts) > 1:
            unmapped_rows = [
                row
                for row in row_dicts
                if int(row["id"]) not in mapped_line_ids and normalize_asin(str(row["asin"] or "")) not in mapped_asins
            ]
            if unmapped_rows:
                expected = ", ".join(
                    f"{row['odoo_order_name']} line {row['id']} ASIN {normalize_asin(str(row['asin'] or '')) or 'UNKNOWN'}"
                    for row in unmapped_rows[:5]
                )
                raise HTTPException(
                    409,
                    f"Refused to report Amazon order {amazon_order_id} because ASIN mapping did not cover every line in multi-line Chrome job {group_key}. Unmapped: {expected}.",
                )
        updated_for_shopify: list[dict[str, Any]] = []
        for row in rows:
            pricing = pricing_by_asin.get(str(row["asin"] or "").upper(), {})
            row_asin = normalize_asin(str(row["asin"] or ""))
            purchased_asin = normalize_asin(str(pricing.get("purchased_asin") or ""))
            replacement_applies = bool(purchased_asin and row_asin and purchased_asin != row_asin)
            replacement_product_name = clean_text(
                str(
                    pricing.get("purchased_product_name")
                    or pricing.get("selected_variant_label")
                    or f"Replacement ASIN {purchased_asin}"
                )
            )
            replacement_note = clean_text(str(pricing.get("fulfilment_note") or ""))
            row_order = order_by_line_id.get(int(row["id"])) or order_by_asin.get(row_asin) or {}
            row_amazon_order_id = row_order.get("amazon_order_id") or amazon_order_id
            row_amazon_order_url = row_order.get("amazon_order_url") or amazon_order_url
            quantity = float(row["quantity"] or 1)
            store_total = order_line_store_total(row)
            amazon_unit = float(pricing.get("amazon_unit_price") or 0)
            amazon_total = float(pricing.get("amazon_total_price") or (amazon_unit * quantity if amazon_unit else 0))
            profit_total = store_total - amazon_total if amazon_total else None
            fulfilment_note = append_note(
                clean_text(row.get("fulfilment_note")),
                clean_text(str(pricing.get("fulfilment_note") or "")),
            )
            conn.execute(
                """
                UPDATE order_lines
                SET amazon_order_id=?,
                    amazon_order_url=?,
                    store_unit_price=?,
                    store_total_price=?,
                    amazon_unit_price=?,
                    amazon_total_price=?,
                    chrome_profit_total=?,
                    fulfilment_note=?,
                    original_asin=CASE WHEN ? THEN COALESCE(NULLIF(original_asin, ''), asin) ELSE original_asin END,
                    original_product_name=CASE WHEN ? THEN COALESCE(NULLIF(original_product_name, ''), product_name) ELSE original_product_name END,
                    replacement_asin=CASE WHEN ? THEN ? ELSE replacement_asin END,
                    replacement_product_name=CASE WHEN ? THEN ? ELSE replacement_product_name END,
                    replacement_note=CASE WHEN ? THEN ? ELSE replacement_note END,
                    replacement_assigned_at=CASE WHEN ? THEN ? ELSE replacement_assigned_at END,
                    asin=CASE WHEN ? THEN ? ELSE asin END,
                    product_name=CASE WHEN ? THEN ? ELSE product_name END,
                    amazon_account_name=?,
                    amazon_status='ordered',
                    state='ordered',
                    missing_asin=NULL,
                    last_error=NULL,
                    ordered_at=?,
                    updated_at=?
                WHERE id=?
                """,
                (
                    row_amazon_order_id,
                    row_amazon_order_url,
                    (store_total / quantity) if quantity else 0,
                    store_total,
                    amazon_unit or None,
                    amazon_total or None,
                    profit_total,
                    fulfilment_note or None,
                    replacement_applies,
                    replacement_applies,
                    replacement_applies,
                    purchased_asin,
                    replacement_applies,
                    replacement_product_name,
                    replacement_applies,
                    replacement_note or f"Chrome selected equivalent Amazon pack variant {purchased_asin}.",
                    replacement_applies,
                    utc_now(),
                    replacement_applies,
                    purchased_asin,
                    replacement_applies,
                    replacement_product_name,
                    chrome_account_name,
                    ordered_at,
                    utc_now(),
                    row["id"],
                ),
            )
            conn.execute(
                """
                UPDATE amazon_attempts
                SET response_json=?, status='ok', error=NULL
                WHERE external_id=? AND mode='chrome'
                """,
                (
                    json.dumps(
                        {
                            "amazon_order_id": amazon_order_id,
                            "amazon_order_url": amazon_order_url,
                            "line_amazon_order_id": row_amazon_order_id,
                            "line_amazon_order_url": row_amazon_order_url,
                            "pricing": pricing,
                            "store_total_price": store_total,
                            "amazon_total_price": amazon_total,
                            "chrome_profit_total": profit_total,
                            "fulfilment_note": fulfilment_note,
                            "replacement_asin": purchased_asin if replacement_applies else "",
                            "replacement_product_name": replacement_product_name if replacement_applies else "",
                            "replacement_note": replacement_note if replacement_applies else "",
                            "amazon_account_name": chrome_account_name,
                        }
                    ),
                    group_key,
                ),
            )
            updated = conn.execute("SELECT * FROM order_lines WHERE id = ?", (row["id"],)).fetchone()
            if updated:
                updated_for_shopify.append(dict(updated))
                ensure_inventory_for_line(updated)
                index_order_line(updated)
    clear_order_progress_caches()
    chatter_queued = queue_chrome_complete_odoo_chatter(
        group_key,
        [dict(row) for row in rows],
        pricing_by_asin,
        amazon_order_id,
        amazon_order_url,
        chrome_account_name,
        payload.worker_id,
        payload.amazon_recipient,
    )
    if not chatter_queued:
        raise HTTPException(
            503,
            f"Amazon order {amazon_order_id} was saved, but the Odoo chatter outbox could not be queued.",
        )
    threading.Thread(
        target=chrome_complete_shopify_followup,
        args=(updated_for_shopify,),
        daemon=True,
    ).start()
    return {
        "ok": True,
        "message": f"Chrome job {group_key} marked ordered; Odoo chatter was queued for background delivery.",
        "amazon_order_id": amazon_order_id,
        "odoo_chatter_queued": True,
        "odoo_chatter_confirmed": odoo_chatter_note_is_posted(
            int(rows[0]["store_id"]),
            int(rows[0]["odoo_order_id"]),
            "amazon_order_placed",
            amazon_order_id,
        ),
    }


@app.post("/api/chrome/jobs/{group_key}/fail")
def api_chrome_job_fail(group_key: str, payload: ChromeJobFailPayload) -> dict[str, Any]:
    message = clean_error_message(payload.message)
    missing_asin = normalize_asin(payload.missing_asin)
    failure_code = clean_text(payload.failure_code).lower().replace("-", "_").replace(" ", "_")
    with db() as conn:
        ensure_chrome_job_not_protected_after_submit(conn, group_key, "failure or missing report")
        ensure_chrome_job_owner(conn, group_key, payload.worker_id)
    if failure_code in {"manual_missing", "mark_missing", "missing"}:
        linked_message = message or "Marked missing from Chrome progress popup."
        count = mark_chrome_group_missing(group_key, linked_message, missing_asin, payload.missing_line_id)
        if count:
            return {"ok": True, "message": f"Moved {count} Chrome line(s) to Missing ASINs."}
    if chrome_fail_is_partial_quantity(payload, message):
        linked_message = partial_quantity_message(payload, message)
        count = mark_chrome_group_missing(group_key, linked_message, missing_asin, payload.missing_line_id)
        if count:
            quantity_reason = (
                "Amazon checkout quantity did not match Odoo"
                if failure_code in CHROME_CART_QUANTITY_FAILURE_CODES
                else "less quantity was available"
            )
            send_email_alert_async(
                f"Chrome fulfilment quantity issue: {group_key}",
                f"Chrome stopped because {quantity_reason}.\nGroup: {group_key}\nWorker: {payload.worker_id}\nError: {linked_message}",
            )
            return {"ok": True, "message": f"Moved {count} Chrome line(s) to Missing because {quantity_reason}."}
    zero_quantity_partial = False
    if (
        failure_code in CHROME_LOW_QUANTITY_FAILURE_CODES
        and payload.requested_quantity is not None
        and (payload.fulfilled_quantity is not None or payload.available_quantity is not None)
    ):
        try:
            zero_quantity_partial = float(payload.fulfilled_quantity if payload.fulfilled_quantity is not None else payload.available_quantity or 0) <= 0
        except (TypeError, ValueError):
            zero_quantity_partial = False
    if missing_asin and not zero_quantity_partial:
        linked_message = message if failure_code == "limit_purchase" else f"ASIN {missing_asin} is missing or unavailable on Amazon. Skipped fulfilment for this Odoo order."
        count = mark_chrome_group_missing(group_key, linked_message, missing_asin, payload.missing_line_id)
        if count:
            return {"ok": True, "message": f"Moved {count} Chrome line(s) to Missing because {missing_asin} is unavailable."}
    with db() as conn:
        params: list[Any] = [message, utc_now(), group_key]
        line_filter = ""
        if payload.line_ids:
            line_filter = f" AND id IN ({','.join('?' for _ in payload.line_ids)})"
            params.extend(payload.line_ids)
        cursor = conn.execute(
            f"""
            UPDATE order_lines
            SET state='error',
                amazon_status='chrome_error',
                last_error=?,
                updated_at=?,
                chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL
            WHERE amazon_group_key=?
              AND order_engine='chrome'
              {line_filter}
            """,
            params,
        )
        conn.execute(
            """
            UPDATE amazon_attempts
            SET status='error', error=?
            WHERE external_id=? AND mode='chrome'
            """,
            (message, group_key),
        )
    send_email_alert_async(
        f"Chrome fulfilment error: {group_key}",
        f"Chrome fulfilment job failed or paused.\nGroup: {group_key}\nWorker: {payload.worker_id}\nError: {message}",
    )
    return {"ok": True, "message": f"Marked {cursor.rowcount} Chrome line(s) as error."}


@app.post("/api/chrome/jobs/{group_key}/missing-line")
def api_chrome_job_missing_line(group_key: str, payload: ChromeJobFailPayload) -> dict[str, Any]:
    message = clean_error_message(payload.message)
    missing_asin = normalize_asin(payload.missing_asin)
    with db() as conn:
        ensure_chrome_job_not_protected_after_submit(conn, group_key, "missing-line report")
        ensure_chrome_job_owner(conn, group_key, payload.worker_id)
    result = mark_chrome_line_missing(group_key, message, missing_asin, payload.missing_line_id)
    count = int(result.get("count") or 0)
    if not count:
        raise HTTPException(404, "Could not identify the missing line in this Chrome job.")
    remaining_line_ids = [int(value) for value in result.get("remaining_line_ids") or []]
    return {
        "ok": True,
        "message": f"Moved {count} Chrome line(s) to Missing ASINs. {len(remaining_line_ids)} line(s) remain in this Amazon order.",
        "remaining_line_ids": remaining_line_ids,
        "remaining_count": len(remaining_line_ids),
    }


@app.post("/api/chrome/jobs/{group_key}/costly")
def api_chrome_job_costly(group_key: str, payload: ChromeJobCostlyPayload) -> dict[str, Any]:
    with db() as conn:
        ensure_chrome_job_not_protected_after_submit(conn, group_key, "costly-review report")
        ensure_chrome_job_owner(conn, group_key, payload.worker_id)
    costly_asin = normalize_asin(payload.costly_asin)
    message = clean_error_message(
        payload.message
        or f"ASIN {costly_asin} costs more on Amazon than the store sale value. Approval required before fulfilment."
    )
    count = mark_chrome_group_costly(
        group_key,
        message,
        costly_asin,
        payload.costly_line_id,
        payload.store_total_price,
        payload.amazon_total_price,
    )
    if not count:
        raise HTTPException(404, "Chrome job not found")
    return {"ok": True, "message": f"Moved {count} Chrome line(s) to Costly review."}


@app.get("/api/tracking/orders")
def api_tracking_orders(
    store_id: Optional[int] = None,
    page: int = 1,
    per_page: int = 100,
    status: str = "active",
    q: str = "",
    include_history_refresh: bool = True,
    amazon_account_name: str = "",
) -> dict[str, Any]:
    cache_key = ("tracking-orders", store_id, page, per_page, clean_text(status), clean_text(q), bool(include_history_refresh), clean_text(amazon_account_name).lower())
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    orders, rows, total, page, per_page = paged_tracking_orders(
        store_id,
        status,
        q,
        page,
        per_page,
        amazon_account_name=amazon_account_name,
    )
    if include_history_refresh and page == 1 and clean_text(status).lower() in {"", "active"} and not clean_text(q):
        seen_order_ids = {clean_text(order.get("amazon_order_id")) for order in orders}
        appended_history_orders = 0
        for stale_order in stale_dispatch_package_tracking_orders_for_refresh():
            order_id = clean_text(stale_order.get("amazon_order_id"))
            if order_id and order_id not in seen_order_ids:
                orders.append(stale_order)
                seen_order_ids.add(order_id)
                appended_history_orders += 1
        for history_order in amazon_history_tracking_orders_for_refresh():
            order_id = clean_text(history_order.get("amazon_order_id"))
            if order_id and order_id not in seen_order_ids:
                orders.append(history_order)
                seen_order_ids.add(order_id)
                appended_history_orders += 1
        total += appended_history_orders
    return fast_page_cache_set(cache_key, {"ok": True, "orders": orders, "rows": [], "page": page, "per_page": per_page, "total": total}, 60)


@app.get("/api/tracking/fulfilment-pending")
def api_tracking_fulfilment_pending(
    store_id: Optional[int] = None,
    page: int = 1,
    per_page: int = 100,
    q: str = "",
    sort_by: str = "delivery_date",
    sort_dir: str = "asc",
) -> dict[str, Any]:
    if page == 1 and not clean_text(q):
        maybe_repair_pending_dispatch_asin_mismatches(store_id)
    sort_by = clean_text(sort_by).lower().replace("-", "_") or "delivery_date"
    if sort_by not in {"delivery_date", "status", "checked_at"}:
        sort_by = "delivery_date"
    sort_dir = "desc" if clean_text(sort_dir).lower() == "desc" else "asc"
    cache_key = ("fulfilment-pending", store_id, page, per_page, clean_text(q), sort_by, sort_dir)
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    lock = fulfilment_pending_cache_lock(cache_key)
    with lock:
        cached = fast_page_cache_get(cache_key)
        if cached is not None:
            return cached
        rows, total, page, per_page = paged_delivered_unfulfilled_rows(store_id, page, per_page, q, sort_by, sort_dir)
        return fast_page_cache_set(cache_key, {"ok": True, "rows": rows, "count": total, "page": page, "per_page": per_page, "total": total, "checked": total}, 300)


PACKAGE_PICKUP_TIMEZONE = ZoneInfo("America/New_York")
PACKAGE_PICKUP_CUTOFF_HOUR = 9
PACKAGE_PICKUP_CUTOFF_MINUTE = 30


def normalize_package_pickup_time(value: Any) -> str:
    raw = clean_text(value).strip('"')
    if not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", raw):
        return "09:30"
    return raw


def package_pickup_time_setting() -> str:
    raw = get_setting("package_pickup_time", "09:30")
    try:
        decoded = json.loads(raw)
        raw = decoded if isinstance(decoded, str) else raw
    except (TypeError, ValueError, json.JSONDecodeError):
        pass
    return normalize_package_pickup_time(raw)


def normalize_package_pickup_confirmation_status(status: Any, legacy_received: Optional[bool] = None) -> str:
    normalized = clean_text(status).lower().replace("-", "_")
    if not normalized and legacy_received is not None:
        normalized = "received" if legacy_received else "unconfirmed"
    return normalized if normalized in {"received", "not_received", "unconfirmed"} else ""


def package_pickup_business_date(value: Any, local_display: Any = "") -> str:
    """Return the Amazon delivery's Brooklyn calendar date without pickup shifting."""
    display = clean_text(local_display)
    delivered: Optional[datetime] = None
    if display:
        for fmt in ("%b %d, %Y %I:%M %p", "%B %d, %Y %I:%M %p", "%b %d, %Y", "%B %d, %Y"):
            try:
                delivered = datetime.strptime(display, fmt).replace(tzinfo=PACKAGE_PICKUP_TIMEZONE)
                break
            except ValueError:
                continue
    if delivered is None:
        # Amazon's date-only statuses (for example ``Delivered today``) are
        # persisted at midnight as a calendar marker.  They are not an actual
        # UTC event time and must not shift to the previous Brooklyn day.  A
        # sparse report from another Chrome/Amazon-account scan may omit the
        # detailed delivery event, leaving this marker as our only date fact.
        raw_value = clean_text(value)
        date_only_marker = re.fullmatch(
            r"(\d{4}-\d{2}-\d{2})(?:[T ]00:00(?::00(?:\.\d+)?)?(?:Z|[+-]00:00)?)?",
            raw_value,
        )
        if date_only_marker:
            return date_only_marker.group(1)
        parsed = parse_any_datetime(value)
        if parsed is None:
            return ""
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        delivered = parsed.astimezone(PACKAGE_PICKUP_TIMEZONE)
    return delivered.date().isoformat()


def package_pickup_card_date(delivered_at: Any, scanned_at: Any = "", manual_pickup_date: Any = "", delivered_display: Any = "") -> str:
    """Group a received package by its first pickup scan date, otherwise by its expected delivery date."""
    scanned_date = package_pickup_business_date(scanned_at) if clean_text(scanned_at) else ""
    return scanned_date or clean_text(manual_pickup_date) or package_pickup_business_date(delivered_at, delivered_display)


def package_pickup_delivery_timestamp(
    package: dict[str, Any],
    delivery_info: dict[str, Any],
    primary_line: dict[str, Any],
) -> str:
    """Keep Amazon's delivery record independent from later team confirmations."""
    snapshot = clean_text(package.get("pickup_delivered_at"))
    if snapshot:
        return snapshot
    delivered_at = clean_text(delivery_info.get("amazon_delivered_at"))
    if delivered_at:
        return delivered_at
    tracking_recorded_at = clean_text(primary_line.get("updated_at"))
    package_tracking_updated_at = clean_text(package.get("updated_at"))
    return (
        package_tracker_delivery_date(
            package.get("package_status"),
            package.get("promise"),
            tracking_recorded_at or package_tracking_updated_at,
        )
        or tracking_recorded_at
        or package_tracking_updated_at
    )


def package_pickup_shopify_statuses(conn: Any) -> dict[tuple[int, str], dict[str, Any]]:
    rows = rows_to_dicts(conn.execute(
        """
        SELECT store_id, odoo_order_name, fulfillment_status, cancelled_at, synced_at
        FROM shopify_order_status_cache
        WHERE COALESCE(odoo_order_name, '') != ''
        ORDER BY synced_at DESC
        """
    ).fetchall())
    result: dict[tuple[int, str], dict[str, Any]] = {}
    for row in rows:
        key = (int(row.get("store_id") or 0), clean_text(row.get("odoo_order_name")).upper())
        result.setdefault(key, row)
    return result


def package_pickup_is_shopify_fulfilled(status: Any, cancelled_at: Any = "") -> bool:
    if clean_text(cancelled_at):
        return False
    normalized = clean_text(status).upper().replace(" ", "_")
    return normalized in {"FULFILLED", "PARTIALLY_FULFILLED", "PARTIAL", "SUCCESS"}


def package_pickup_tracking_matches(entered_value: Any, package_value: Any) -> bool:
    entered = normalize_dispatch_scan_code(entered_value)
    package_tracking = normalize_dispatch_scan_code(package_value)
    if len(entered) < 5 or not package_tracking:
        return False
    return package_tracking == entered if len(entered) >= len(package_tracking) else package_tracking.endswith(entered)


def package_pickup_placeholder_rows(package_type: str, count: int) -> list[tuple[int, int, str]]:
    is_amazon = package_type == "amazon"
    label = "Amazon" if is_amazon else "Non-Amazon"
    return [
        (package_number, -package_number if is_amazon else package_number, f"{label} Package {package_number}")
        for package_number in range(1, max(0, int(count)) + 1)
    ]


def package_pickup_data(
    store_id: Optional[int] = None,
    date_from: str = "",
    date_to: str = "",
) -> dict[str, Any]:
    today = datetime.now(PACKAGE_PICKUP_TIMEZONE).date()
    start_date = datetime.strptime(date_from, "%Y-%m-%d").date() if date_from else today - timedelta(days=13)
    end_date = datetime.strptime(date_to, "%Y-%m-%d").date() if date_to else today
    if end_date < start_date:
        start_date, end_date = end_date, start_date
    start_date = max(start_date, end_date - timedelta(days=92))
    with db() as conn:
        package_params: list[Any] = []
        store_sql = ""
        if store_id:
            store_sql = "AND packages.store_id=?"
            package_params.append(int(store_id))
        packages = rows_to_dicts(conn.execute(
            f"""
            SELECT packages.*
            FROM amazon_dispatch_packages packages
            WHERE LOWER(COALESCE(packages.package_status, '') || ' ' || COALESCE(packages.promise, '')) ~ '(^|[^a-z])delivered([^a-z]|$)'
              AND LOWER(COALESCE(packages.package_status, '') || ' ' || COALESCE(packages.promise, '')) NOT LIKE '%not delivered%'
              AND LOWER(COALESCE(packages.package_status, '') || ' ' || COALESCE(packages.promise, '')) NOT LIKE '%cancel%'
              {store_sql}
            ORDER BY packages.updated_at DESC
            LIMIT 10000
            """,
            package_params,
        ).fetchall())
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS package_pickup_delivery_records (
                package_id INTEGER PRIMARY KEY,
                delivered_at TEXT NOT NULL,
                scanned_at TEXT,
                last_scanned_at TEXT,
                scanned_code TEXT,
                scan_count INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT,
                created_at TEXT NOT NULL
            )
            """
        )
        saved_delivery_records = {
            int(row.get("package_id") or 0): row
            for row in rows_to_dicts(conn.execute(
                """
                SELECT package_id, delivered_at, scanned_at, last_scanned_at, scanned_code, scan_count
                FROM package_pickup_delivery_records
                """
            ).fetchall())
        }
        for package in packages:
            pickup_record = saved_delivery_records.get(int(package.get("id") or 0), {})
            package["pickup_delivered_at"] = clean_text(pickup_record.get("delivered_at"))
            package["pickup_scanned_at"] = clean_text(pickup_record.get("scanned_at"))
            package["pickup_last_scanned_at"] = clean_text(pickup_record.get("last_scanned_at"))
            package["pickup_scanned_code"] = clean_text(pickup_record.get("scanned_code"))
            package["pickup_scan_count"] = int(pickup_record.get("scan_count") or 0)
        line_params: list[Any] = []
        line_store_sql = ""
        if store_id:
            line_store_sql = "AND store_id=?"
            line_params.append(int(store_id))
        line_rows = rows_to_dicts(conn.execute(
            f"""
            SELECT id, store_id, odoo_order_id, odoo_order_name, amazon_order_id, amazon_order_url,
                   tracking_payload, tracking_checked_at, order_engine, manual_estimated_delivery_at, updated_at
            FROM order_lines
            WHERE COALESCE(amazon_order_id, '') != '' {line_store_sql}
            ORDER BY updated_at DESC
            LIMIT 20000
            """,
            line_params,
        ).fetchall())
        checks = rows_to_dicts(conn.execute(
            """
            SELECT * FROM package_pickup_checks
            WHERE store_id=? AND pickup_date>=? AND pickup_date<=?
            ORDER BY pickup_date DESC
            """,
            (int(store_id or 0), start_date.isoformat(), end_date.isoformat()),
        ).fetchall())
        check_ids = [int(row["id"]) for row in checks]
        non_amazon_rows: list[dict[str, Any]] = []
        if check_ids:
            placeholders = ",".join("?" for _ in check_ids)
            non_amazon_rows = rows_to_dicts(conn.execute(
                f"SELECT * FROM package_pickup_non_amazon WHERE check_id IN ({placeholders}) ORDER BY check_id, position",
                check_ids,
            ).fetchall())
        manual_params: list[Any] = [start_date.isoformat(), end_date.isoformat()]
        manual_store_sql = ""
        if store_id:
            manual_store_sql = "AND store_id=?"
            manual_params.append(int(store_id))
        manual_amazon_rows = rows_to_dicts(conn.execute(
            f"""
            SELECT * FROM package_pickup_manual_amazon
            WHERE pickup_date>=? AND pickup_date<=? {manual_store_sql}
            ORDER BY pickup_date DESC, id DESC
            """,
            manual_params,
        ).fetchall())
        packages_by_id = {int(package.get("id") or 0): package for package in packages}
        manual_pickup_date_by_package_id: dict[int, str] = {}
        matched_manual_ids: set[int] = set()
        reconciliation_now = utc_now()
        for manual in manual_amazon_rows:
            manual_id = int(manual.get("id") or 0)
            entered_tracking = normalize_dispatch_scan_code(manual.get("tracking_input"))
            tracking_suffix = normalize_dispatch_scan_code(manual.get("tracking_suffix"))
            matched_package = packages_by_id.get(int(manual.get("matched_dispatch_package_id") or 0))
            if not matched_package:
                candidates: list[dict[str, Any]] = []
                for package in packages:
                    if int(package.get("store_id") or 0) != int(manual.get("store_id") or 0):
                        continue
                    if clean_text(package.get("odoo_order_name")).upper() != clean_text(manual.get("odoo_order_name")).upper():
                        continue
                    package_tracking = next((
                        normalize_dispatch_scan_code(value)
                        for value in (package.get("canonical_scan_code"), package.get("scan_code"), package.get("display_code"))
                        if package_tracking_id_is_physical(value)
                    ), "")
                    if not package_tracking:
                        continue
                    if len(entered_tracking) > 5:
                        matches_tracking = package_tracking == entered_tracking
                    else:
                        matches_tracking = bool(tracking_suffix and package_tracking.endswith(tracking_suffix))
                    if matches_tracking:
                        candidates.append(package)
                if len(candidates) == 1:
                    matched_package = candidates[0]
            if not matched_package:
                continue
            package_id = int(matched_package.get("id") or 0)
            matched_manual_ids.add(manual_id)
            manual_pickup_date_by_package_id[package_id] = clean_text(manual.get("pickup_date"))
            manual_received_at = clean_text(manual.get("received_at"))
            manual_not_received_at = clean_text(manual.get("not_received_at"))
            if manual_received_at or manual_not_received_at:
                conn.execute(
                    "UPDATE amazon_dispatch_packages SET received_at=?, not_received_at=?, updated_at=? WHERE id=?",
                    (manual_received_at or None, manual_not_received_at or None, reconciliation_now, package_id),
                )
                matched_package["received_at"] = manual_received_at
                matched_package["not_received_at"] = manual_not_received_at
            if int(manual.get("matched_dispatch_package_id") or 0) != package_id:
                conn.execute(
                    "UPDATE package_pickup_manual_amazon SET matched_dispatch_package_id=?, updated_at=? WHERE id=?",
                    (package_id, reconciliation_now, manual_id),
                )
                manual["matched_dispatch_package_id"] = package_id
        # Team-counted Amazon extras can be identified by tracking alone. Odoo is
        # only used as an optional narrowing hint because the recipient may not
        # have entered it at pickup time.
        check_pickup_date_by_id = {int(row.get("id") or 0): clean_text(row.get("pickup_date")) for row in checks}
        matched_extra_ids: set[int] = set()
        for entry in non_amazon_rows:
            if clean_text(entry.get("package_type")).lower() != "amazon":
                continue
            entered_tracking = normalize_dispatch_scan_code(entry.get("tracking_input"))
            if len(entered_tracking) < 5:
                continue
            entered_order = clean_text(entry.get("order_number")).upper()
            if re.fullmatch(r"AMAZON PACKAGE \d+", entered_order):
                entered_order = ""
            candidates: list[dict[str, Any]] = []
            for package in packages:
                package_id = int(package.get("id") or 0)
                if package_id in manual_pickup_date_by_package_id:
                    continue
                if entered_order and clean_text(package.get("odoo_order_name")).upper() != entered_order:
                    continue
                package_tracking = next((
                    normalize_dispatch_scan_code(value)
                    for value in (package.get("canonical_scan_code"), package.get("scan_code"), package.get("display_code"), package.get("last_scanned_code"))
                    if package_tracking_id_is_physical(value)
                ), "")
                if not package_tracking:
                    continue
                if package_pickup_tracking_matches(entered_tracking, package_tracking):
                    candidates.append(package)
            if len(candidates) != 1:
                continue
            matched_package = candidates[0]
            package_id = int(matched_package.get("id") or 0)
            manual_pickup_date_by_package_id[package_id] = check_pickup_date_by_id.get(int(entry.get("check_id") or 0), "")
            received_at = clean_text(entry.get("received_at"))
            not_received_at = clean_text(entry.get("not_received_at"))
            if received_at or not_received_at:
                conn.execute(
                    "UPDATE amazon_dispatch_packages SET received_at=?, not_received_at=?, updated_at=? WHERE id=?",
                    (received_at or None, not_received_at or None, reconciliation_now, package_id),
                )
                matched_package["received_at"] = received_at
                matched_package["not_received_at"] = not_received_at
            conn.execute("DELETE FROM package_pickup_non_amazon WHERE id=?", (int(entry.get("id") or 0),))
            matched_extra_ids.add(int(entry.get("id") or 0))
        if matched_extra_ids:
            non_amazon_rows = [row for row in non_amazon_rows if int(row.get("id") or 0) not in matched_extra_ids]
        shopify_statuses = package_pickup_shopify_statuses(conn)

    lines_by_amazon: dict[tuple[int, str], list[dict[str, Any]]] = {}
    lines_by_odoo: dict[tuple[int, str], dict[str, Any]] = {}
    for line in line_rows:
        line_store = int(line.get("store_id") or 0)
        lines_by_amazon.setdefault((line_store, clean_text(line.get("amazon_order_id"))), []).append(line)
        order_key = (line_store, clean_text(line.get("odoo_order_name")).upper())
        lines_by_odoo.setdefault(order_key, line)

    check_by_date = {clean_text(row.get("pickup_date")): row for row in checks}
    non_amazon_by_check: dict[int, list[dict[str, Any]]] = {}
    for row in non_amazon_rows:
        non_amazon_by_check.setdefault(int(row.get("check_id") or 0), []).append(row)
    cards: dict[str, dict[str, Any]] = {}

    def ensure_card(pickup_date: str) -> dict[str, Any]:
        check = check_by_date.get(pickup_date) or {}
        return cards.setdefault(pickup_date, {
            "pickup_date": pickup_date,
            "amazon_picked_up": int(check.get("amazon_picked_up") or 0),
            "non_amazon_picked_up": int(check.get("non_amazon_picked_up") or 0),
            "amazon_packages": [],
            "manual_amazon_packages": [],
            "non_amazon_packages": [],
        })

    pickup_delivery_snapshots: list[tuple[str, int]] = []
    for package in packages:
        if package_tracker_delivery_kind(package.get("package_status"), package.get("promise")) != "delivered":
            continue
        line_matches = lines_by_amazon.get((int(package.get("store_id") or 0), clean_text(package.get("amazon_order_id"))), [])
        primary_line = next((line for line in line_matches if clean_text(line.get("odoo_order_name")).upper() == clean_text(package.get("odoo_order_name")).upper()), None)
        primary_line = primary_line or (line_matches[0] if line_matches else {})
        tracking_id = next((
            normalize_dispatch_scan_code(value)
            for value in (package.get("canonical_scan_code"), package.get("scan_code"), package.get("display_code"))
            if package_tracking_id_is_physical(value)
        ), "")
        matched_tracking_part: dict[str, Any] = {}
        matched_tracking_checked_at = ""
        if tracking_id:
            for line in line_matches:
                for part in parse_tracking_packages(clean_text(line.get("tracking_payload"))):
                    part_tracking_id = next((
                        normalize_dispatch_scan_code(part.get(key))
                        for key in ("tracking_id", "trackingId", "tracking_number", "trackingNumber")
                        if package_tracking_id_is_physical(part.get(key))
                    ), "")
                    if part_tracking_id == tracking_id:
                        matched_tracking_part = part
                        matched_tracking_checked_at = clean_text(line.get("tracking_checked_at"))
                        break
                if matched_tracking_part:
                    break
        delivery_source = matched_tracking_part or {
            "status": clean_text(package.get("package_status")),
            "promise": clean_text(package.get("promise")),
        }
        delivery_info = amazon_delivery_info_from_payload(
            json.dumps([delivery_source]),
            matched_tracking_checked_at or clean_text(primary_line.get("tracking_checked_at")) or clean_text(package.get("updated_at")),
        )
        delivered_at = package_pickup_delivery_timestamp(package, delivery_info, primary_line)
        delivered_display = clean_text(delivery_info.get("amazon_delivered_display"))
        package_id = int(package.get("id") or 0)
        if delivered_at and not clean_text(package.get("pickup_delivered_at")):
            pickup_delivery_snapshots.append((delivered_at, package_id))
        delivery_date = package_pickup_business_date(delivered_at, delivered_display)
        scanned_at = clean_text(package.get("pickup_scanned_at"))
        manual_pickup_date = manual_pickup_date_by_package_id.get(package_id, "")
        pickup_date = package_pickup_card_date(delivered_at, scanned_at, manual_pickup_date, delivered_display)
        delivery_in_range = bool(delivery_date and start_date.isoformat() <= delivery_date <= end_date.isoformat())
        pickup_in_range = bool(pickup_date and start_date.isoformat() <= pickup_date <= end_date.isoformat())
        # The date filters remain useful for the small Amazon delivery timestamp,
        # while a received package is physically grouped under the day it was scanned.
        if not pickup_date or not (delivery_in_range or pickup_in_range):
            continue
        order_name = clean_text(package.get("odoo_order_name") or primary_line.get("odoo_order_name"))
        status = shopify_statuses.get((int(package.get("store_id") or 0), order_name.upper()), {})
        fulfilled = package_pickup_is_shopify_fulfilled(status.get("fulfillment_status"), status.get("cancelled_at"))
        received_at = scanned_at or clean_text(package.get("received_at"))
        not_received_at = clean_text(package.get("not_received_at"))
        received = bool(received_at)
        carrier = clean_text(package.get("carrier") or matched_tracking_part.get("carrier") or matched_tracking_part.get("carrier_name"))
        if len(carrier) > 40 or re.search(r"\b(sorry|delivery|delivered|package|estimate|notify|updates?)\b", carrier, re.IGNORECASE):
            carrier = "Amazon"
        ensure_card(pickup_date)["amazon_packages"].append({
            "source_type": "amazon",
            "source_id": package_id,
            "store_id": int(package.get("store_id") or 0),
            "odoo_order_name": order_name,
            "amazon_order_id": clean_text(package.get("amazon_order_id")),
            "amazon_order_url": clean_text(package.get("amazon_order_url") or primary_line.get("amazon_order_url")),
            "tracking_id": tracking_id,
            "tracking_url": clean_text(package.get("tracking_url") or matched_tracking_part.get("tracking_url") or matched_tracking_part.get("trackingUrl")),
            "carrier": carrier or "Amazon",
            "delivery_status": clean_text(package.get("package_status") or package.get("promise") or matched_tracking_part.get("status")) or "Delivered",
            "delivered_at": delivered_at,
            "delivered_display": delivered_display,
            "delivery_date": delivery_date,
            "pickup_scanned_at": scanned_at,
            "pickup_last_scanned_at": clean_text(package.get("pickup_last_scanned_at")),
            "pickup_scanned_code": clean_text(package.get("pickup_scanned_code")),
            "pickup_scan_count": int(package.get("pickup_scan_count") or 0),
            "pickup_card_date": pickup_date,
            "package_type": "Amazon",
            "shopify_status": clean_text(status.get("fulfillment_status")) or "Pending",
            "shopify_fulfilled": fulfilled,
            "received": received,
            "received_at": received_at,
            "not_received": bool(not_received_at),
            "not_received_at": not_received_at,
            "confirmation_status": "received" if received_at else "not_received" if not_received_at else "unconfirmed",
        })

    if pickup_delivery_snapshots:
        with db() as conn:
            snapshot_created_at = utc_now()
            conn.execute_values(
                """
                INSERT INTO package_pickup_delivery_records (delivered_at, package_id, created_at)
                VALUES ?
                ON CONFLICT(package_id) DO NOTHING
                """,
                [(delivered_at, package_id, snapshot_created_at) for delivered_at, package_id in pickup_delivery_snapshots],
                template="(?, ?, ?)",
            )

    for manual in manual_amazon_rows:
        manual_id = int(manual.get("id") or 0)
        if manual_id in matched_manual_ids:
            continue
        pickup_date = clean_text(manual.get("pickup_date"))
        if not pickup_date or pickup_date < start_date.isoformat() or pickup_date > end_date.isoformat():
            continue
        manual_store_id = int(manual.get("store_id") or 0)
        order_name = clean_text(manual.get("odoo_order_name")).upper()
        linked = lines_by_odoo.get((manual_store_id, order_name), {})
        shopify = shopify_statuses.get((manual_store_id, order_name), {})
        fulfilled = package_pickup_is_shopify_fulfilled(shopify.get("fulfillment_status"), shopify.get("cancelled_at"))
        tracking_input = normalize_dispatch_scan_code(manual.get("tracking_input"))
        tracking_display = tracking_input if len(tracking_input) > 4 else f"••••{tracking_input}"
        ensure_card(pickup_date)["manual_amazon_packages"].append({
            "source_type": "manual_amazon",
            "source_id": manual_id,
            "store_id": manual_store_id,
            "odoo_order_name": order_name,
            "amazon_order_id": clean_text(linked.get("amazon_order_id")),
            "amazon_order_url": clean_text(linked.get("amazon_order_url")),
            "tracking_id": tracking_display,
            "tracking_url": "",
            "carrier": "Amazon",
            "delivery_status": "Awaiting Chrome extension sync",
            "delivered_at": "",
            "delivered_display": "Awaiting Chrome sync",
            "package_type": "Amazon (manual)",
            "shopify_status": clean_text(shopify.get("fulfillment_status")) or "Pending",
            "shopify_fulfilled": fulfilled,
            "received": bool(clean_text(manual.get("received_at"))),
            "received_at": clean_text(manual.get("received_at")),
            "not_received": bool(clean_text(manual.get("not_received_at"))),
            "not_received_at": clean_text(manual.get("not_received_at")),
            "confirmation_status": "received" if clean_text(manual.get("received_at")) else "not_received" if clean_text(manual.get("not_received_at")) else "unconfirmed",
            "tracking_suffix": clean_text(manual.get("tracking_suffix")),
        })

    for pickup_date, check in check_by_date.items():
        if pickup_date < start_date.isoformat() or pickup_date > end_date.isoformat():
            continue
        card = ensure_card(pickup_date)
        for entry in non_amazon_by_check.get(int(check.get("id") or 0), []):
            entry_type = clean_text(entry.get("package_type")).lower() or "non_amazon"
            order_number = clean_text(entry.get("order_number"))
            is_default_order = bool(re.fullmatch(r"(?:Amazon|Non-Amazon) Package \d+", order_number, re.IGNORECASE))
            linked = lines_by_odoo.get((int(store_id or 0), order_number.upper()), {}) if order_number and store_id else {}
            if not linked and order_number and not is_default_order:
                linked = next((line for (line_store, key), line in lines_by_odoo.items() if key == order_number.upper() and (not store_id or line_store == int(store_id))), {})
            linked_store = int(linked.get("store_id") or store_id or 0)
            linked_order = clean_text(linked.get("odoo_order_name") or order_number)
            status = shopify_statuses.get((linked_store, linked_order.upper()), {})
            fulfilled = package_pickup_is_shopify_fulfilled(status.get("fulfillment_status"), status.get("cancelled_at"))
            tracking_input = normalize_dispatch_scan_code(entry.get("tracking_input"))
            tracking_display = tracking_input if len(tracking_input) > 4 else (f"••••{tracking_input}" if tracking_input else "")
            pickup_row = {
                "source_type": "count_amazon" if entry_type == "amazon" else "non_amazon",
                "source_id": int(entry.get("id") or 0),
                "store_id": linked_store,
                "odoo_order_name": linked_order,
                "amazon_order_id": "",
                "amazon_order_url": "",
                "tracking_id": tracking_display,
                "delivered_at": clean_text(linked.get("manual_estimated_delivery_at")),
                "delivered_display": "Awaiting Chrome sync" if entry_type == "amazon" else "",
                "delivery_status": "Package details needed" if is_default_order else "Manually entered pickup",
                "package_type": "Amazon (counted)" if entry_type == "amazon" else "Non-Amazon",
                "shopify_status": clean_text(status.get("fulfillment_status")) or "Pending",
                "shopify_fulfilled": fulfilled,
                "received": bool(clean_text(entry.get("received_at"))),
                "received_at": clean_text(entry.get("received_at")),
                "not_received": bool(clean_text(entry.get("not_received_at"))),
                "not_received_at": clean_text(entry.get("not_received_at")),
                "confirmation_status": "received" if clean_text(entry.get("received_at")) else "not_received" if clean_text(entry.get("not_received_at")) else "unconfirmed",
                "position": int(entry.get("position") or 0),
                "needs_details": (not tracking_input) if entry_type == "amazon" else (is_default_order or not tracking_input),
                "tracking_input": clean_text(entry.get("tracking_input")),
            }
            card["manual_amazon_packages" if entry_type == "amazon" else "non_amazon_packages"].append(pickup_row)

    for pickup_date in check_by_date:
        ensure_card(pickup_date)
    cursor = start_date
    while cursor <= end_date:
        if cursor.weekday() < 5:
            ensure_card(cursor.isoformat())
        cursor += timedelta(days=1)
    card_rows = sorted(cards.values(), key=lambda card: card["pickup_date"], reverse=True)
    for card in card_rows:
        card["amazon_reported_delivered"] = len(card["amazon_packages"])
        card["reported_delivered"] = len(card["amazon_packages"])
        scanned_received = sum(1 for row in card["amazon_packages"] if clean_text(row.get("pickup_scanned_at")))
        card["amazon_scanned"] = scanned_received
        card["amazon_picked_up"] = max(int(card["amazon_picked_up"]), scanned_received)
        card["missing_amazon"] = sum(
            1 for row in card["amazon_packages"]
            if not clean_text(row.get("pickup_scanned_at")) and not bool(row.get("received"))
        )
        card["unreported_amazon"] = max(0, int(card["amazon_picked_up"]) - len(card["amazon_packages"]))
        card["physical_total"] = int(card["amazon_picked_up"]) + int(card["non_amazon_picked_up"])
        card["shopify_fulfilled"] = sum(1 for row in [*card["amazon_packages"], *card["manual_amazon_packages"], *card["non_amazon_packages"]] if row["shopify_fulfilled"])
    summary = {
        "amazon_reported_delivered": sum(card["amazon_reported_delivered"] for card in card_rows),
        "amazon_picked_up": sum(int(card["amazon_picked_up"]) for card in card_rows),
        "non_amazon_picked_up": sum(int(card["non_amazon_picked_up"]) for card in card_rows),
        "missing_amazon": sum(int(card["missing_amazon"]) for card in card_rows),
        "unreported_amazon": sum(int(card["unreported_amazon"]) for card in card_rows),
        "shopify_fulfilled": sum(int(card["shopify_fulfilled"]) for card in card_rows),
    }
    return {
        "ok": True,
        "timezone": "America/New_York",
        "cutoff": package_pickup_time_setting(),
        "date_from": start_date.isoformat(),
        "date_to": end_date.isoformat(),
        "summary": summary,
        "cards": card_rows,
    }


