@app.post("/api/dispatch-sorting/scan-events/{event_id}/resolve")
def api_dispatch_sorting_scan_event_resolve(event_id: int, payload: dict[str, Any]) -> dict[str, Any]:
    now = utc_now()
    with db() as conn:
        row = conn.execute("SELECT * FROM amazon_dispatch_scan_events WHERE id=?", (event_id,)).fetchone()
        if not row:
            raise HTTPException(404, "Scan event not found")
        conn.execute(
            """
            UPDATE amazon_dispatch_scan_events
            SET resolved_at=?, resolved_by=?, resolved_note=?
            WHERE id=?
            """,
            (
                now,
                clean_text(payload.get("operator") or payload.get("resolved_by") or "dispatch"),
                clean_text(payload.get("note") or "Resolved from dispatch sorting page."),
                event_id,
            ),
        )
        updated = conn.execute("SELECT * FROM amazon_dispatch_scan_events WHERE id=?", (event_id,)).fetchone()
    fast_page_cache_clear_matching({
        "dispatch-sorting-summary",
        "dispatch-sorting-summary-base",
        "dispatch-status",
        "dispatch-status-summary",
    })
    return {"ok": True, "message": "Scan exception marked resolved.", "event": row_to_dict(updated)}


@app.get("/api/dispatch-sorting/lookup")
def api_dispatch_sorting_lookup(q: str = "", store_id: Optional[int] = None) -> dict[str, Any]:
    query = clean_text(q)
    if not query:
        raise HTTPException(400, "q is required")
    with db() as conn:
        rows = dispatch_lookup_rows(conn, query, store_id, limit=30)
        packages: list[dict[str, Any]] = []
        for row in rows:
            package = dispatch_enrich_package_for_scan(conn, row)
            package["lookup_message"] = dispatch_scan_message(package, query_text=query)
            packages.append(package)
    summary = dispatch_lookup_summary(packages)
    if not packages:
        return {
            "ok": True,
            "matched": False,
            "query": query,
            "matches": [],
            "summary": summary,
            "message": f"No dispatch package or order was found for '{query}'. Nothing was marked scanned.",
        }
    return {
        "ok": True,
        "matched": True,
        "query": query,
        "matches": packages,
        "summary": summary,
        "message": f"Found {len(packages)} package match{'es' if len(packages) != 1 else ''} for '{query}'. Nothing was marked scanned.",
    }


@app.get("/api/dispatch-sorting/packages/{package_id}")
def api_dispatch_sorting_package(package_id: int) -> dict[str, Any]:
    with db() as conn:
        row = conn.execute("SELECT * FROM amazon_dispatch_packages WHERE id=?", (package_id,)).fetchone()
        if not row:
            raise HTTPException(404, "Dispatch package not found")
        if amazon_order_has_open_payment_failure(conn, row["amazon_order_id"]):
            raise HTTPException(404, "Dispatch package is blocked by an open Amazon payment revision.")
        package = dispatch_enrich_package_for_scan(conn, row)
        message = dispatch_scan_message(package)
    return {"ok": True, "package": package, "message": message}


@app.post("/api/dispatch-sorting/scan")
def api_dispatch_sorting_scan(payload: DispatchScanPayload) -> dict[str, Any]:
    scan_code = normalize_dispatch_scan_code(payload.scan_code)
    if not scan_code:
        raise HTTPException(400, "scan_code is required")
    query_text = clean_text(payload.scan_code)
    barcode_kind = dispatch_barcode_kind(payload.scan_code)
    alias_codes = [
        clean_text(value)
        for value in (payload.alias_codes or [])
        if clean_text(value) and dispatch_barcode_kind(value) == "amazon_internal_label"
    ]
    result_count_prefix = ""
    with db() as conn:
        enqueue_payment_failure_cleanup()
        if payload.store_id is None:
            row = conn.execute(
                f"""
                SELECT *
                FROM amazon_dispatch_packages
                WHERE (scan_code=? OR canonical_scan_code=? OR last_scanned_code=?)
                  AND {DISPATCH_PHYSICAL_SCAN_SQL}
                  AND NOT EXISTS (
                      SELECT 1
                      FROM amazon_payment_failures
                      WHERE amazon_payment_failures.amazon_order_id=amazon_dispatch_packages.amazon_order_id
                        AND amazon_payment_failures.status='open'
                  )
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (scan_code, scan_code, scan_code),
            ).fetchone()
        else:
            row = conn.execute(
                f"""
                SELECT *
                FROM amazon_dispatch_packages
                WHERE (scan_code=? OR canonical_scan_code=? OR last_scanned_code=?)
                  AND store_id=?
                  AND {DISPATCH_PHYSICAL_SCAN_SQL}
                  AND NOT EXISTS (
                      SELECT 1
                      FROM amazon_payment_failures
                      WHERE amazon_payment_failures.amazon_order_id=amazon_dispatch_packages.amazon_order_id
                        AND amazon_payment_failures.status='open'
                  )
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (scan_code, scan_code, scan_code, payload.store_id),
            ).fetchone()
        if not row:
            fragment_matches = dispatch_find_fragment_matches(conn, payload.scan_code, payload.store_id)
            if len(fragment_matches) == 1:
                row = fragment_matches[0]
                result_count_prefix = f"1 result found for '{query_text}'. "
            elif len(fragment_matches) > 1:
                message = f"{len(fragment_matches)} results found for '{query_text}'. Select the correct package."
                record_dispatch_scan_event(
                    conn,
                    scan_query=query_text,
                    normalized_query=scan_code,
                    result_status="multiple_matches",
                    result_count=len(fragment_matches),
                    suggested_tote="",
                    message=message,
                    store_id=payload.store_id,
                )
                return {
                    "ok": True,
                    "matched": False,
                    "ambiguous": True,
                    "scan_code": scan_code,
                    "matches": [dispatch_ambiguous_match_payload(match) for match in fragment_matches],
                    "suggested_tote": "",
                    "message": message,
                }
        if not row and barcode_kind == "amazon_internal_label":
            message = "Amazon internal label code detected. Scan the long barcode beside the printed TBA tracking number to link both codes safely."
            record_dispatch_scan_event(
                conn,
                scan_query=query_text,
                normalized_query=scan_code,
                result_status="needs_tracking_pair",
                result_count=0,
                suggested_tote="",
                message=message,
                store_id=payload.store_id,
            )
            return {
                "ok": True,
                "matched": False,
                "requires_tracking_scan": True,
                "barcode_kind": barcode_kind,
                "scan_code": scan_code,
                "suggested_tote": "",
                "message": message,
            }
        if not row:
            message = f"0 known Amazon dispatched packages found for '{query_text}'. Place it in Exception rack."
            record_dispatch_scan_event(
                conn,
                scan_query=query_text,
                normalized_query=scan_code,
                result_status="not_found",
                result_count=0,
                suggested_tote="EXCEPTION-SCAN-01",
                message=message,
                store_id=payload.store_id,
            )
            return {
                "ok": True,
                "matched": False,
                "scan_code": scan_code,
                "suggested_tote": "EXCEPTION-SCAN-01",
                "message": message,
                "exception_reasons": ["not_found", "wrong_barcode", "old_order_not_backfilled", "damaged_label"],
            }
        row_data = row_to_dict(row)
        row_canonical = normalize_dispatch_scan_code(row_data.get("canonical_scan_code") or row_data.get("scan_code"))
        for alias in alias_codes:
            alias_normalized = normalize_dispatch_scan_code(alias)
            existing_alias_rows = dispatch_find_fragment_matches(conn, alias, payload.store_id)
            conflicts = []
            for existing in existing_alias_rows:
                exact_aliases = {normalize_dispatch_scan_code(value) for value in dispatch_scanned_codes(existing)}
                existing_canonical = normalize_dispatch_scan_code(existing.get("canonical_scan_code") or existing.get("scan_code"))
                if alias_normalized in exact_aliases and existing_canonical != row_canonical:
                    conflicts.append(existing)
            if conflicts:
                message = f"Amazon label code '{alias}' is already linked to another tracking ID. Nothing was changed; review the physical label."
                record_dispatch_scan_event(
                    conn,
                    scan_query=query_text,
                    normalized_query=scan_code,
                    result_status="alias_conflict",
                    result_count=len(conflicts),
                    suggested_tote="EXCEPTION-SCAN-01",
                    message=message,
                    store_id=payload.store_id,
                )
                return {
                    "ok": True,
                    "matched": False,
                    "alias_conflict": True,
                    "scan_code": scan_code,
                    "suggested_tote": "EXCEPTION-SCAN-01",
                    "message": message,
                }
        package, message = dispatch_apply_matched_scan(
            conn,
            row_data,
            query_text,
            scan_code,
            payload.store_id,
            result_count_prefix,
            alias_codes=alias_codes,
        )
    return {"ok": True, "matched": True, "barcode_kind": barcode_kind, "package": package, "message": message}


@app.post("/api/dispatch-sorting/packages/{package_id}/place")
def api_dispatch_sorting_place(package_id: int, payload: DispatchPlacePayload) -> dict[str, Any]:
    status = clean_text(payload.status) or "sorted_holding"
    if status not in {"received_unopened", "sorted_holding", "opened_verified", "dispatched", "exception"}:
        raise HTTPException(400, "Invalid dispatch package status")
    now = utc_now()
    raw_tote_code = clean_text(payload.tote_code)
    if re.match(r"^(Today|Tomorrow|Later)-\d{2}-\d{2}$", raw_tote_code, flags=re.IGNORECASE):
        label, section = raw_tote_code.split("-", 1)
        tote_code = f"{label[:1].upper()}{label[1:].lower()}-{section}"
    else:
        tote_code = normalize_dispatch_scan_code(payload.tote_code) or raw_tote_code.upper()
    with db() as conn:
        row = conn.execute("SELECT * FROM amazon_dispatch_packages WHERE id=?", (package_id,)).fetchone()
        if not row:
            raise HTTPException(404, "Dispatch package not found")
        if amazon_order_has_open_payment_failure(conn, row["amazon_order_id"]):
            raise HTTPException(400, "This package is blocked by an open Amazon payment revision. Resolve/check the payment before sorting.")
        if not tote_code and status != "exception":
            enriched = dispatch_enrich_package_for_scan(conn, row)
            tote_code = enriched.get("suggested_tote") or suggested_dispatch_tote(conn, row_to_dict(row), bool(enriched.get("order_ready")))
        else:
            enriched = dispatch_enrich_package_for_scan(conn, row)
        moving_to_today = clean_text(tote_code).upper().startswith("TODAY-") or status == "dispatched"
        if moving_to_today and not enriched.get("order_ready"):
            raise HTTPException(400, "This recipient order is not ready for Today/Fulfilled. Keep it in Later/Hold or Tomorrow until all parts are scanned.")
        conn.execute(
            """
            UPDATE amazon_dispatch_packages
            SET tote_code=?,
                scan_status=?,
                exception_reason=?,
                placed_at=CASE WHEN ?='sorted_holding' THEN COALESCE(placed_at, ?) ELSE placed_at END,
                updated_at=?
            WHERE id=?
            """,
            (tote_code, status, clean_text(payload.exception_reason), status, now, now, package_id),
        )
        updated = conn.execute("SELECT * FROM amazon_dispatch_packages WHERE id=?", (package_id,)).fetchone()
        package = dispatch_package_payload(conn, updated)
    fast_page_cache_clear_matching({
        "dispatch-sorting-summary",
        "dispatch-sorting-summary-base",
        "dispatch-status",
        "dispatch-status-summary",
    })
    enqueue_dispatch_summary_warm(package.get("store_id"))
    return {"ok": True, "package": package, "message": f"Package moved to {package.get('tote_code') or status}."}


_TRACKING_UPDATE_LOCK = threading.RLock()


def tracking_cancellation_downstream_reasons(
    conn: Any,
    rows: list[dict[str, Any]],
) -> dict[tuple[int, int], list[str]]:
    """Return completed downstream work that must not be reversed automatically."""
    grouped: dict[tuple[int, int], list[dict[str, Any]]] = {}
    for raw_row in rows:
        row = dict(raw_row)
        key = (int(row["store_id"]), int(row["odoo_order_id"]))
        grouped.setdefault(key, []).append(row)

    protected: dict[tuple[int, int], list[str]] = {}
    for key, order_rows in grouped.items():
        store_id, odoo_order_id = key
        order_name = clean_text(order_rows[0].get("odoo_order_name"))
        reasons: list[str] = []
        completed_local_line = conn.execute(
            """
            SELECT 1
            FROM order_lines
            WHERE store_id=?
              AND odoo_order_id=?
              AND state IN ('delivered', 'inventory')
            LIMIT 1
            """,
            (store_id, odoo_order_id),
        ).fetchone()
        if completed_local_line:
            reasons.append("the app already marks the order delivered/inventory fulfilled")
        if order_name:
            cached_rows = conn.execute(
                """
                SELECT fulfillment_status, shopify_order_name, shopify_order_id
                FROM shopify_order_status_cache
                WHERE store_id=?
                  AND UPPER(odoo_order_name)=UPPER(?)
                  AND COALESCE(cancelled_at, '') = ''
                """,
                (store_id, order_name),
            ).fetchall()
            for cached in cached_rows:
                if shopify_status_is_fulfilled(cached.get("fulfillment_status")):
                    shopify_ref = clean_text(cached.get("shopify_order_name")) or clean_text(cached.get("shopify_order_id"))
                    reasons.append(f"Shopify order {shopify_ref or order_name} is already fulfilled")
                    break
            completed_job = conn.execute(
                """
                SELECT 1
                FROM shopify_fulfilment_jobs
                WHERE store_id=?
                  AND odoo_order_id=?
                  AND (status='completed' OR COALESCE(completed_at, '') != '')
                LIMIT 1
                """,
                (store_id, odoo_order_id),
            ).fetchone()
            if completed_job:
                reasons.append("a Shopify fulfilment job has already completed")
        if reasons:
            protected[key] = list(dict.fromkeys(reasons))
    return protected


def clear_stale_downstream_fulfilment_for_order(
    conn: Any,
    store_id: int,
    odoo_order_id: int,
    odoo_order_name: str,
) -> dict[str, int]:
    """Clear downstream app records only when no active fulfilment remains."""
    remaining = conn.execute(
        """
        SELECT COUNT(*) AS count
        FROM order_lines
        WHERE store_id=?
          AND odoo_order_id=?
          AND (
            COALESCE(amazon_order_id, '') != ''
            OR state IN ('ordered', 'dispatched', 'delivered', 'inventory')
          )
        """,
        (store_id, odoo_order_id),
    ).fetchone()
    if int((remaining or {}).get("count") or 0) > 0:
        return {"jobs": 0, "status": 0, "maps": 0}
    jobs = conn.execute(
        "DELETE FROM shopify_fulfilment_jobs WHERE store_id=? AND odoo_order_id=?",
        (store_id, odoo_order_id),
    ).rowcount
    status = conn.execute(
        "DELETE FROM shopify_order_status_cache WHERE store_id=? AND UPPER(odoo_order_name)=UPPER(?)",
        (store_id, odoo_order_name),
    ).rowcount
    store_row = conn.execute("SELECT odoo_db FROM stores WHERE id=?", (store_id,)).fetchone()
    source_key = f"{clean_text(store_row.get('odoo_db'))}:{odoo_order_name}" if store_row else ""
    maps = 0
    if source_key.strip(":"):
        maps = conn.execute(
            "DELETE FROM shopify_export_order_map WHERE src_order_key=?",
            (source_key,),
        ).rowcount
    return {"jobs": int(jobs or 0), "status": int(status or 0), "maps": int(maps or 0)}


def reset_cancelled_amazon_fulfilment(
    conn: Any,
    amazon_order_id: str,
    rows: list[dict[str, Any]],
    cancellation_message: str,
    now: str,
) -> dict[str, Any]:
    """Reset safe orders and retain completed downstream orders for manual review."""
    row_dicts = [dict(row) for row in rows]
    protected = tracking_cancellation_downstream_reasons(conn, row_dicts)
    reset_rows: list[dict[str, Any]] = []
    review_rows: list[dict[str, Any]] = []
    reset_line_ids: list[int] = []
    reset_orders: set[tuple[int, int, str]] = set()
    cancellation_payload = json_payload_for_storage(
        {"order_cancelled": True, "amazon_order_id": amazon_order_id, "message": cancellation_message}
    )
    cancellation_note = (
        f"Earlier Amazon order {amazon_order_id} was cancelled. "
        f"Reset to fresh pulled state for reorder. {cancellation_message}"
    )
    for row in row_dicts:
        key = (int(row["store_id"]), int(row["odoo_order_id"]))
        reasons = protected.get(key) or []
        if reasons:
            review_message = (
                f"Amazon reports order {amazon_order_id} cancelled, but automatic reset was blocked because "
                f"{'; '.join(reasons)}. Review Odoo/Shopify fulfilment manually."
            )
            conn.execute(
                """
                UPDATE order_lines
                SET amazon_status='cancelled_review',
                    tracking_status='Amazon cancelled - manual review',
                    tracking_payload=?,
                    tracking_checked_at=?,
                    amazon_cancelled_at=?,
                    amazon_cancelled_order_id=?,
                    fulfilment_note=CASE
                      WHEN COALESCE(fulfilment_note, '') = '' THEN ?
                      WHEN fulfilment_note LIKE ? THEN fulfilment_note
                      ELSE fulfilment_note || ' | ' || ?
                    END,
                    last_error=?,
                    updated_at=?
                WHERE id=?
                """,
                (
                    cancellation_payload,
                    now,
                    now,
                    amazon_order_id,
                    review_message,
                    f"%Amazon reports order {amazon_order_id} cancelled%",
                    review_message,
                    review_message,
                    now,
                    row["id"],
                ),
            )
            updated = conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone()
            if updated:
                review_rows.append(dict(updated))
            continue

        conn.execute(
            """
            UPDATE order_lines
            SET amazon_order_id=NULL,
                amazon_order_url=NULL,
                amazon_account_id=NULL,
                amazon_account_name=NULL,
                amazon_status=NULL,
                tracking_status=NULL,
                tracking_payload=NULL,
                tracking_checked_at=NULL,
                state='pulled',
                order_engine='chrome',
                amazon_group_key=NULL,
                chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL,
                amazon_cancelled_at=?,
                amazon_cancelled_order_id=?,
                amazon_unit_price=NULL,
                amazon_total_price=NULL,
                chrome_profit_total=NULL,
                fulfilment_note=CASE
                  WHEN COALESCE(fulfilment_note, '') = '' THEN ?
                  WHEN fulfilment_note LIKE ? THEN fulfilment_note
                  ELSE fulfilment_note || ' | ' || ?
                END,
                last_error=NULL,
                ordered_at=NULL,
                updated_at=?
            WHERE id=?
            """,
            (
                now,
                amazon_order_id,
                cancellation_note,
                f"%Earlier Amazon order {amazon_order_id} was cancelled%",
                cancellation_note,
                now,
                row["id"],
            ),
        )
        reset_line_ids.append(int(row["id"]))
        reset_orders.add((key[0], key[1], clean_text(row.get("odoo_order_name"))))
        updated = conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone()
        if updated:
            reset_rows.append(dict(updated))

    if reset_line_ids:
        placeholders = ",".join("?" for _ in reset_line_ids)
        conn.execute(
            f"""
            UPDATE amazon_attempts
            SET status='reset', error=NULL
            WHERE order_line_id IN ({placeholders})
              AND mode IN ('chrome', 'rest', 'cxml')
              AND status IN ('queued', 'submitted', 'ok', 'error', 'costly', 'missing', 'ignored')
            """,
            reset_line_ids,
        )

    cleanup = {"jobs": 0, "status": 0, "maps": 0, "dispatch_packages": 0}
    for store_id, odoo_order_id, order_name in reset_orders:
        result = clear_stale_downstream_fulfilment_for_order(
            conn, store_id, odoo_order_id, order_name
        )
        for name, count in result.items():
            cleanup[name] += count
    if reset_rows and not review_rows:
        cleanup["dispatch_packages"] = dispatch_clear_packages_for_amazon_order(conn, amazon_order_id)
    payment_failure_resolved = bool(resolve_payment_failure_for_order(conn, amazon_order_id, now))
    return {
        "reset_rows": reset_rows,
        "review_rows": review_rows,
        "protected": protected,
        "cleanup": cleanup,
        "payment_failure_resolved": payment_failure_resolved,
    }


@app.post("/api/tracking/update")
def api_tracking_update(payload: ChromeTrackingUpdatePayload) -> dict[str, Any]:
    for attempt in range(3):
        try:
            with _TRACKING_UPDATE_LOCK:
                result = api_tracking_update_impl(payload)
            return result
        except (db_session.psycopg2.errors.DeadlockDetected, db_session.psycopg2.OperationalError):
            if attempt >= 2:
                raise
            time.sleep(0.25 * (attempt + 1))
    raise HTTPException(500, "Tracking update failed after retry")


def api_tracking_update_impl(payload: ChromeTrackingUpdatePayload) -> dict[str, Any]:
    amazon_order_id = clean_text(payload.amazon_order_id)
    if not amazon_order_id:
        raise HTTPException(400, "amazon_order_id is required")
    order_products = order_level_products_from_tracking_payload(payload)
    packages = enforce_tracking_payload_order_guard(
        amazon_order_id,
        merge_order_products_into_tracking_packages(
            sanitize_tracking_packages(payload.packages or []),
            order_products,
        ),
    )
    if (
        not packages
        and not payload.order_cancelled
        and not payload_has_payment_revision(payload)
        and not tracking_payload_otp(payload, packages)
    ):
        raise HTTPException(
            422,
            "Empty Amazon tracking update rejected; existing shipment data was preserved.",
        )
    status = tracking_status_from_packages(packages)
    status_only_payload = bool(packages) and all(package.get("status_only") and not package.get("tracking_id") for package in packages)
    delivered_flag = status == "Delivered" and packages and all(
        tracking_package_delivered(package) for package in packages if isinstance(package, dict)
    )
    with db() as conn:
        otp_updated = upsert_amazon_otp_from_tracking_payload(
            conn,
            amazon_order_id,
            clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
            tracking_payload_otp(payload, packages),
            packages,
        )
        if otp_updated:
            fast_page_cache_clear_matching({"amazon-otp", "public-amazon-otp"})
        if status_only_payload and not payload.order_cancelled and not payload_has_payment_revision(payload):
            now = utc_now()
            line_delivered = status == "Delivered" and packages and all(
                tracking_package_delivered(package) for package in packages if isinstance(package, dict)
            )
            cursor = conn.execute(
                """
                UPDATE order_lines
                SET amazon_order_url=COALESCE(NULLIF(?, ''), amazon_order_url),
                    tracking_status=?,
                    tracking_payload=?,
                    tracking_checked_at=?,
                    state=CASE WHEN ? THEN 'delivered' ELSE state END,
                    last_error=NULL,
                    updated_at=?
                WHERE amazon_order_id=? AND state IN ('ordered', 'dispatched', 'delivered')
                  AND (? OR NOT (state='delivered' OR LOWER(COALESCE(tracking_status, '')) LIKE 'delivered%'))
                """,
                (
                    clean_text(payload.amazon_order_url),
                    status,
                    tracking_payload_json_for_storage(packages),
                    now,
                    bool(line_delivered),
                    now,
                    amazon_order_id,
                    bool(line_delivered),
                ),
            )
            resolved_payment_failure = resolve_payment_failure_for_order(conn, amazon_order_id, now)
            if resolved_payment_failure:
                failure_row = conn.execute(
                    "SELECT * FROM amazon_payment_failures WHERE amazon_order_id=?",
                    (amazon_order_id,),
                ).fetchone()
                if failure_row:
                    _TYPESENSE_INDEX_EXECUTOR.submit(
                        lambda snapshot=row_to_dict(failure_row) or {}: _index_named_document_sync(
                            "amazon_payment_failures",
                            payment_failure_search_document(snapshot),
                        )
                    )
                fast_page_cache_clear_matching({
                    "dispatch-sorting-summary",
                    "dispatch-sorting-summary-base",
                    "dispatch-status",
                    "dispatch-status-summary",
                    "tracking-orders",
                    "payment-failures",
                })
            if cursor.rowcount <= 0:
                refreshed_packages, affected_line_ids = refresh_dispatch_packages_from_tracking(
                    conn,
                    amazon_order_id,
                    clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                    packages,
                )
                if refreshed_packages:
                    updated_line_rows = []
                    for line_id in affected_line_ids:
                        current_line = conn.execute("SELECT * FROM order_lines WHERE id=?", (line_id,)).fetchone()
                        if current_line and order_line_currently_delivered(current_line) and not line_delivered:
                            continue
                        conn.execute(
                            """
                            UPDATE order_lines
                            SET tracking_status=?,
                                tracking_payload=?,
                                tracking_checked_at=?,
                                state=CASE WHEN ? THEN 'delivered' ELSE state END,
                                last_error=NULL,
                                updated_at=?
                            WHERE id=?
                            """,
                            (
                                status,
                                tracking_payload_json_for_storage(packages),
                                now,
                                bool(line_delivered),
                                now,
                                line_id,
                            ),
                        )
                        updated_row = conn.execute("SELECT * FROM order_lines WHERE id=?", (line_id,)).fetchone()
                        if updated_row:
                            updated_line_rows.append(updated_row)
                    for updated_row in updated_line_rows:
                        index_order_line(updated_row)
                        if line_delivered:
                            ensure_inventory_for_line(updated_row)
                    fast_page_cache_clear_matching({
                        "dispatch-sorting-summary",
                        "dispatch-sorting-summary-base",
                        "dispatch-status",
                        "dispatch-status-summary",
                        "tracking-orders",
                        "fulfilment-pending",
                    })
                    enqueue_dispatch_summary_warm(None)
                    related_updated, related_packages = update_related_tracking_orders_from_packages(
                        conn,
                        amazon_order_id,
                        clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                        packages,
                    )
                    return {
                        "ok": True,
                        "updated": len(updated_line_rows) + related_updated,
                        "dispatch_packages_updated": refreshed_packages + related_packages,
                        "tracking_status": status,
                        "message": "Updated old/manual status-only Amazon tracking through dispatch package records.",
                    }
                history_updated, history_packages = update_history_matched_order_from_tracking(
                    conn,
                    amazon_order_id,
                    clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                    packages,
                )
                if history_updated:
                    fast_page_cache_clear_matching({
                        "dispatch-sorting-summary",
                        "dispatch-sorting-summary-base",
                        "dispatch-status",
                        "dispatch-status-summary",
                        "tracking-orders",
                        "fulfilment-pending",
                    })
                    enqueue_dispatch_summary_warm(None)
                    related_updated, related_packages = update_related_tracking_orders_from_packages(
                        conn,
                        amazon_order_id,
                        clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                        packages,
                    )
                    return {
                        "ok": True,
                        "updated": history_updated + related_updated,
                        "dispatch_packages_updated": history_packages + related_packages,
                        "tracking_status": status,
                        "message": "Updated old/manual history Amazon tracking by recipient ref and ASIN.",
                    }
                otp_packages = save_otp_tracking_dispatch_packages(
                    conn,
                    amazon_order_id,
                    clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                    packages,
                )
                if otp_packages:
                    fast_page_cache_clear_matching({"amazon-otp", "public-amazon-otp"})
                    return {
                        "ok": True,
                        "updated": 0,
                        "dispatch_packages_updated": otp_packages,
                        "tracking_status": status,
                        "message": "Saved Amazon OTP package tracking ID.",
                    }
                if otp_updated:
                    return {
                        "ok": True,
                        "updated": 0,
                        "dispatch_packages_updated": 0,
                        "tracking_status": status,
                        "message": "Saved Amazon OTP from tracking page.",
                    }
                raise HTTPException(404, "Tracked Amazon order not found")
            related_updated, related_packages = update_related_tracking_orders_from_packages(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                packages,
            )
            refreshed_packages, _affected_line_ids = refresh_dispatch_packages_from_tracking(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                packages,
            )
            fast_page_cache_clear_matching({
                "dispatch-sorting-summary",
                "dispatch-sorting-summary-base",
                "dispatch-status",
                "dispatch-status-summary",
                "tracking-orders",
                "fulfilment-pending",
            })
            enqueue_dispatch_summary_warm(None)
            return {
                "ok": True,
                "updated": cursor.rowcount + related_updated,
                "tracking_status": status,
                "dispatch_packages_updated": refreshed_packages + related_packages,
                "payment_failure_resolved": bool(resolved_payment_failure),
            }
        rows = []
        for attempt in range(2):
            try:
                rows = conn.execute(
                    "SELECT * FROM order_lines WHERE amazon_order_id=? AND state IN ('ordered', 'dispatched', 'delivered', 'inventory')",
                    (amazon_order_id,),
                ).fetchall()
                break
            except (db_session.psycopg2.InterfaceError, db_session.psycopg2.OperationalError):
                if attempt:
                    raise
                conn.rollback()
                time.sleep(0.15)
        if not rows:
            now = utc_now()
            refreshed_packages, affected_line_ids = refresh_dispatch_packages_from_tracking(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                packages,
            )
            if refreshed_packages:
                line_status = tracking_status_from_packages(packages)
                line_delivered = line_status == "Delivered" and packages and all(
                    tracking_package_delivered(package) for package in packages if isinstance(package, dict)
                )
                updated_line_rows = []
                for line_id in affected_line_ids:
                    current_line = conn.execute("SELECT * FROM order_lines WHERE id=?", (line_id,)).fetchone()
                    if current_line and order_line_currently_delivered(current_line) and not line_delivered:
                        continue
                    conn.execute(
                        """
                        UPDATE order_lines
                        SET tracking_status=?,
                            tracking_payload=?,
                            tracking_checked_at=?,
                            state=CASE WHEN ? THEN 'delivered' ELSE state END,
                            last_error=NULL,
                            updated_at=?
                        WHERE id=?
                        """,
                        (
                            line_status,
                            tracking_payload_json_for_storage(packages),
                            now,
                            bool(line_delivered),
                            now,
                            line_id,
                        ),
                    )
                    updated_row = conn.execute("SELECT * FROM order_lines WHERE id=?", (line_id,)).fetchone()
                    if updated_row:
                        updated_line_rows.append(updated_row)
                for updated_row in updated_line_rows:
                    index_order_line(updated_row)
                    if line_delivered:
                        ensure_inventory_for_line(updated_row)
                fast_page_cache_clear_matching({
                    "dispatch-sorting-summary",
                    "dispatch-sorting-summary-base",
                    "dispatch-status",
                    "dispatch-status-summary",
                    "tracking-orders",
                    "fulfilment-pending",
                })
                enqueue_dispatch_summary_warm(None)
                related_updated, related_packages = update_related_tracking_orders_from_packages(
                    conn,
                    amazon_order_id,
                    clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                    packages,
                )
                return {
                    "ok": True,
                    "updated": len(updated_line_rows) + related_updated,
                    "dispatch_packages_updated": refreshed_packages + related_packages,
                    "tracking_status": line_status,
                    "message": "Updated old/manual Amazon order tracking through dispatch package records.",
                }
            historical_rows = []
            if payload.order_cancelled:
                historical_rows = conn.execute(
                    """
                    SELECT *
                    FROM order_lines
                    WHERE amazon_cancelled_order_id=?
                       OR (amazon_order_id=? AND (state='delivered' OR LOWER(COALESCE(tracking_status, ''))='delivered'))
                    """,
                    (amazon_order_id, amazon_order_id),
                ).fetchall()
            if historical_rows:
                now = utc_now()
                cancellation_message = clean_text(payload.cancellation_message) or "This order has been cancelled."
                for row in historical_rows:
                    current_order_id = clean_text(row["amazon_order_id"])
                    existing_cancelled_order_id = clean_text(row["amazon_cancelled_order_id"])
                    should_store_cancelled_id = current_order_id != amazon_order_id
                    note = (
                        f"Older Amazon order {amazon_order_id} is cancelled; current fulfilment remains {current_order_id or existing_cancelled_order_id}."
                        if should_store_cancelled_id
                        else f"Ignored cancellation signal for delivered Amazon order {amazon_order_id}; current fulfilment remains delivered."
                    )
                    conn.execute(
                        """
                        UPDATE order_lines
                        SET amazon_cancelled_order_id=?,
                            tracking_checked_at=COALESCE(NULLIF(tracking_checked_at, ''), ?),
                            tracking_payload=CASE
                              WHEN COALESCE(tracking_payload, '') = '' THEN ?
                              ELSE tracking_payload
                            END,
                            fulfilment_note=CASE
                              WHEN COALESCE(fulfilment_note, '') = '' THEN ?
                              WHEN fulfilment_note LIKE ? THEN fulfilment_note
                              ELSE fulfilment_note || ' | ' || ?
                            END,
                            updated_at=?
                        WHERE id=?
                        """,
                        (
                            existing_cancelled_order_id or (amazon_order_id if should_store_cancelled_id else ""),
                            now,
                            json_payload_for_storage({"ignored_cancelled_order": amazon_order_id, "message": cancellation_message}),
                            note,
                            f"%Older Amazon order {amazon_order_id} is cancelled%",
                            note,
                            now,
                            row["id"],
                        ),
                    )
                    updated_row = conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone()
                    if updated_row:
                        index_order_line(updated_row)
                payment_failure_resolved = bool(
                    resolve_payment_failure_and_clear_dispatch(conn, amazon_order_id, now)
                )
                fast_page_cache_clear_matching({
                    "dispatch-sorting-summary",
                    "dispatch-sorting-summary-base",
                    "dispatch-status",
                    "dispatch-status-summary",
                    "tracking-orders",
                    "payment-failures",
                })
                return {
                    "ok": True,
                    "updated": 0,
                    "ignored": True,
                    "tracking_status": "Older Amazon cancellation ignored",
                    "payment_failure_resolved": payment_failure_resolved,
                    "message": f"Ignored cancelled historical Amazon order {amazon_order_id}; current/latest fulfilment was kept.",
                }
            history_updated, history_packages = update_history_matched_order_from_tracking(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                packages,
            )
            if history_updated:
                fast_page_cache_clear_matching({
                    "dispatch-sorting-summary",
                    "dispatch-sorting-summary-base",
                    "dispatch-status",
                    "dispatch-status-summary",
                    "tracking-orders",
                    "fulfilment-pending",
                })
                enqueue_dispatch_summary_warm(None)
                related_updated, related_packages = update_related_tracking_orders_from_packages(
                    conn,
                    amazon_order_id,
                    clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                    packages,
                )
                return {
                    "ok": True,
                    "updated": history_updated + related_updated,
                    "dispatch_packages_updated": history_packages + related_packages,
                    "tracking_status": tracking_status_from_packages(packages),
                    "message": "Updated old/manual history Amazon tracking by recipient ref and ASIN.",
                }
            otp_packages = save_otp_tracking_dispatch_packages(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                packages,
            )
            if otp_packages:
                fast_page_cache_clear_matching({"amazon-otp", "public-amazon-otp"})
                return {
                    "ok": True,
                    "updated": 0,
                    "dispatch_packages_updated": otp_packages,
                    "tracking_status": tracking_status_from_packages(packages),
                    "message": "Saved Amazon OTP package tracking ID.",
                }
            if otp_updated:
                return {
                    "ok": True,
                    "updated": 0,
                    "dispatch_packages_updated": 0,
                    "tracking_status": tracking_status_from_packages(packages),
                    "message": "Saved Amazon OTP from tracking page.",
                }
            raise HTTPException(404, "Tracked Amazon order not found")
        incoming_account_name = clean_text(payload.amazon_account_name)
        if incoming_account_name and not tracking_account_name_is_placeholder(incoming_account_name):
            refreshed_rows = []
            for row in rows:
                resolved_account_name = preserve_real_amazon_account_name(
                    row["amazon_account_name"],
                    incoming_account_name,
                )
                if resolved_account_name != clean_text(row["amazon_account_name"]):
                    conn.execute(
                        "UPDATE order_lines SET amazon_account_name=?, updated_at=? WHERE id=?",
                        (resolved_account_name, utc_now(), row["id"]),
                    )
                refreshed_rows.append(conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone())
            rows = [row for row in refreshed_rows if row]
        if payload.order_cancelled:
            tag_pairs = {(int(row["store_id"]), int(row["odoo_order_id"])) for row in rows}
            now = utc_now()
            cancellation_message = clean_text(payload.cancellation_message) or "This order has been cancelled."
            cancellation_result = reset_cancelled_amazon_fulfilment(
                conn,
                amazon_order_id,
                [dict(row) for row in rows],
                cancellation_message,
                now,
            )
            updated_rows = cancellation_result["reset_rows"] + cancellation_result["review_rows"]
            for updated_row in updated_rows:
                index_order_line(updated_row)
            fast_page_cache_clear_matching({
                "dispatch-sorting-summary",
                "dispatch-sorting-summary-base",
                "dispatch-status",
                "dispatch-status-summary",
                "tracking-orders",
                "fulfilment-pending",
                "dashboard",
                "orders",
                "search",
                "chrome-jobs",
                "shopify-fulfilment",
                "payment-failures",
            })
            sync_odoo_ordered_tags_after_commit(tag_pairs)
            reset_count = len(cancellation_result["reset_rows"])
            review_count = len(cancellation_result["review_rows"])
            message = f"Reset {reset_count} cancelled Amazon fulfilment line(s) for reorder."
            if review_count:
                message += f" Kept {review_count} completed downstream line(s) linked and flagged for manual review."
            return {
                "ok": True,
                "updated": len(updated_rows),
                "reset": reset_count,
                "manual_review": review_count,
                "tracking_status": "Amazon cancelled - manual review" if review_count else "Amazon cancelled",
                "order_cancelled": True,
                "payment_failure_resolved": cancellation_result["payment_failure_resolved"],
                "cleanup": cancellation_result["cleanup"],
                "message": message,
            }
        if payload_has_payment_revision(payload):
            now = utc_now()
            message = "Payment revision needed. Please update your payment method."
            revise_url = payment_revision_url(payload)
            store_id = int(rows[0]["store_id"]) if rows else None
            order_names = sorted({str(row["odoo_order_name"]) for row in rows if row["odoo_order_name"]})
            payload_data = payload.model_dump() if hasattr(payload, "model_dump") else payload.dict()
            conn.execute(
                """
                INSERT INTO amazon_payment_failures (
                    amazon_order_id, amazon_order_url, revise_payment_url, store_id,
                    odoo_order_names, message, status, raw_json, detected_at, updated_at, resolved_at
                ) VALUES (?, ?, ?, ?, ?, ?, 'open', ?, ?, ?, NULL)
                ON CONFLICT(amazon_order_id) DO UPDATE SET
                    amazon_order_url=excluded.amazon_order_url,
                    revise_payment_url=excluded.revise_payment_url,
                    store_id=excluded.store_id,
                    odoo_order_names=excluded.odoo_order_names,
                    message=excluded.message,
                    status='open',
                    raw_json=excluded.raw_json,
                    updated_at=excluded.updated_at,
                    resolved_at=NULL
                """,
                (
                    amazon_order_id,
                    clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                    revise_url,
                    store_id,
                    json.dumps(order_names),
                    message,
                    json_payload_for_storage(payload_data),
                    now,
                    now,
                ),
            )
            for row in rows:
                conn.execute(
                    """
                    UPDATE order_lines
                    SET amazon_order_url=COALESCE(NULLIF(?, ''), amazon_order_url),
                        tracking_status='Payment revision needed',
                        tracking_payload=?,
                        tracking_checked_at=?,
                        last_error=?,
                        updated_at=?
                    WHERE id=?
                    """,
                    (
                        clean_text(payload.amazon_order_url),
                        tracking_payload_json_for_storage(payload.packages or []),
                        now,
                        message,
                        now,
                        row["id"],
                    ),
                )
                updated_row = conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone()
                if updated_row:
                    index_order_line(updated_row)
            failure_row = conn.execute("SELECT * FROM amazon_payment_failures WHERE amazon_order_id=?", (amazon_order_id,)).fetchone()
            if failure_row:
                _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(failure_row) or {}: _index_named_document_sync("amazon_payment_failures", payment_failure_search_document(snapshot)))
            dispatch_clear_packages_for_amazon_order(conn, amazon_order_id)
            fast_page_cache_clear_matching({
                "dispatch-sorting-summary",
                "dispatch-sorting-summary-base",
                "dispatch-status",
                "dispatch-status-summary",
                "tracking-orders",
                "payment-failures",
            })
            send_email_alert_async(
                f"Amazon payment revision needed: {amazon_order_id}",
                f"Amazon order requires manual payment revision.\nAmazon order: {amazon_order_id}\nRevise payment: {revise_url or order_line_amazon_url(amazon_order_id)}\nOdoo orders: {', '.join(order_names)}",
            )
            return {"ok": True, "updated": len(rows), "tracking_status": "Payment revision needed", "payment_revision_needed": True}
        resolved_payment_failure = resolve_payment_failure_for_order(conn, amazon_order_id, utc_now())
        if resolved_payment_failure:
            failure_row = conn.execute("SELECT * FROM amazon_payment_failures WHERE amazon_order_id=?", (amazon_order_id,)).fetchone()
            if failure_row:
                _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(failure_row) or {}: _index_named_document_sync("amazon_payment_failures", payment_failure_search_document(snapshot)))
            fast_page_cache_clear_matching({
                "dispatch-sorting-summary",
                "dispatch-sorting-summary-base",
                "dispatch-status",
                "dispatch-status-summary",
                "tracking-orders",
                "payment-failures",
            })
        updated = 0
        updated_rows_for_index = []
        package_asins_present = any(package.get("asins") for package in packages)
        downstream_packages = packages
        packages_by_line_id, unmatched_rows = tracking_packages_by_line_with_one_to_one_fallback(
            packages,
            list(rows),
        )
        for row in rows:
            line_packages = packages_by_line_id.get(int(row["id"]), [])
            if not line_packages:
                if package_asins_present:
                    continue
                line_packages = packages
            replacement_product = tracking_unambiguous_replacement_product(line_packages, row)
            if replacement_product:
                conn.execute(
                    """
                    UPDATE order_lines
                    SET replacement_asin=COALESCE(NULLIF(replacement_asin, ''), ?),
                        replacement_product_name=COALESCE(NULLIF(replacement_product_name, ''), ?)
                    WHERE id=?
                    """,
                    (
                        replacement_product["asin"],
                        clean_text(replacement_product.get("title")),
                        row["id"],
                    ),
                )
            line_status = tracking_status_from_packages(line_packages)
            line_delivered = line_status == "Delivered" and line_packages and all(
                tracking_package_delivered(package) for package in line_packages if isinstance(package, dict)
            )
            if order_line_currently_delivered(row) and not line_delivered:
                continue
            conn.execute(
                """
                UPDATE order_lines
                SET amazon_order_url=COALESCE(NULLIF(?, ''), amazon_order_url),
                    tracking_status=?,
                    tracking_payload=?,
                    tracking_checked_at=?,
                    state=CASE WHEN ? THEN 'delivered' ELSE state END,
                    last_error=NULL,
                    updated_at=?
                WHERE id=?
                """,
                (
                    clean_text(payload.amazon_order_url),
                    line_status,
                    tracking_payload_json_for_storage(line_packages),
                    utc_now(),
                    bool(line_delivered),
                    utc_now(),
                    row["id"],
                ),
            )
            updated += 1
            if not status_only_payload or line_delivered:
                updated_row = conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone()
                if updated_row:
                    updated_rows_for_index.append(updated_row)
                if line_delivered:
                    ensure_inventory_for_line(updated_row)
        if package_asins_present and not updated and unmatched_rows:
            now = utc_now()
            message = "Tracking package ASINs did not match this order line. Review the Amazon package manually."
            downstream_packages = strip_untrusted_tracking_item_proof(packages)
            for row in unmatched_rows:
                conn.execute(
                    """
                    UPDATE order_lines
                    SET amazon_order_url=COALESCE(NULLIF(?, ''), amazon_order_url),
                        tracking_status='ASIN mismatch',
                        tracking_payload=?,
                        tracking_checked_at=?,
                        last_error=?,
                        updated_at=?
                    WHERE id=?
                    """,
                    (
                        clean_text(payload.amazon_order_url),
                        tracking_payload_json_for_storage(downstream_packages),
                        now,
                        message,
                        now,
                        row["id"],
                    ),
                )
                updated += 1
                updated_row = conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone()
                if updated_row:
                    updated_rows_for_index.append(updated_row)
    for updated_row in updated_rows_for_index:
        index_order_line(updated_row)
    related_updated = 0
    related_packages = 0
    if packages and not status_only_payload:
        with db() as conn:
            refresh_dispatch_packages_from_tracking(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                downstream_packages,
            )
            mark_history_tracking_order_status(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                downstream_packages,
            )
            related_updated, related_packages = update_related_tracking_orders_from_packages(
                conn,
                amazon_order_id,
                clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id),
                downstream_packages,
            )
        sync_dispatch_packages_for_order_async(amazon_order_id)
        for related_order_id in related_tracking_order_ids_from_packages(amazon_order_id, downstream_packages):
            sync_dispatch_packages_for_order_async(related_order_id)
        # Package identities can be promoted from an AMZPKG shipment alias to a
        # physical TBA/UPS code during this update. Related-parts responses cache
        # the old row ids separately from the dispatch summary, so invalidate both
        # or a corrected split order continues to look duplicated until expiry.
        fast_page_cache_clear_matching({
            "dispatch-related-parts",
            "dispatch-sorting-summary",
            "dispatch-sorting-summary-base",
            "dispatch-status",
            "dispatch-status-summary",
            "package-pickups",
        })
    if delivered_flag:
        try:
            store = get_store(int(rows[0]["store_id"]))
            note = f"Amazon tracking delivered for order {html.escape(amazon_order_id)}."
            for order_id in sorted({int(row["odoo_order_id"]) for row in rows}):
                post_order_note_once(store, order_id, "amazon_tracking_delivered", amazon_order_id, note)
        except Exception:
            pass
    return {
        "ok": True,
        "updated": updated + related_updated,
        "tracking_status": status,
        "payment_failure_resolved": bool(resolved_payment_failure),
        "related_dispatch_packages_updated": related_packages,
    }


@app.get("/api/tracking/payment-failures")
def api_tracking_payment_failures(store_id: Optional[int] = None, page: int = 1, per_page: int = 100, status: str = "open") -> dict[str, Any]:
    page, per_page, _ = pagination_bounds(page, per_page)
    status = clean_text(status or "open")
    cache_key = ("payment-failures", store_id, page, per_page, status)
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    rows, total, page, per_page = payment_failure_rows(store_id, page, per_page, status)
    search_engine = "postgres"
    result = fast_page_cache_set(cache_key, {"ok": True, "rows": rows, "page": page, "per_page": per_page, "total": total, "search_engine": search_engine}, 300)
    threading.Thread(target=enqueue_payment_failure_cleanup, daemon=True).start()
    return result


@app.get("/api/notifications")
def api_notifications(limit: int = 40) -> dict[str, Any]:
    limit = max(1, min(int(limit or 40), 100))
    with db() as conn:
        rows = rows_to_dicts(conn.execute(
            """
            SELECT id, notification_key, kind, title, message, odoo_order_name,
                   amazon_order_id, delivery_date, pinned, dismissed, created_at, updated_at
            FROM fulfilment_notifications
            WHERE dismissed = 0
            ORDER BY pinned DESC, created_at DESC, id DESC
            LIMIT ?
            """,
            (limit,),
        ).fetchall())
    return {"ok": True, "notifications": rows, "count": len(rows)}


@app.post("/api/notifications")
async def api_create_notification(request: Request) -> dict[str, Any]:
    payload = await request.json()
    notification_key = str(payload.get("notification_key") or "").strip()
    title = str(payload.get("title") or "Notification").strip()
    message = str(payload.get("message") or "").strip()
    if not notification_key or not message:
        raise HTTPException(status_code=422, detail="notification_key and message are required")
    now = utc_now()
    with db() as conn:
        conn.execute(
            """
            INSERT INTO fulfilment_notifications
                (notification_key, kind, title, message, odoo_order_name, amazon_order_id,
                 delivery_date, pinned, dismissed, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 0, 0, ?, ?)
            ON CONFLICT(notification_key) DO UPDATE SET
                kind=excluded.kind,
                title=excluded.title,
                message=excluded.message,
                odoo_order_name=excluded.odoo_order_name,
                amazon_order_id=excluded.amazon_order_id,
                delivery_date=excluded.delivery_date,
                updated_at=excluded.updated_at
            """,
            (
                notification_key,
                str(payload.get("kind") or "warning").strip() or "warning",
                title,
                message,
                str(payload.get("odoo_order_name") or "").strip(),
                str(payload.get("amazon_order_id") or "").strip(),
                str(payload.get("delivery_date") or "").strip(),
                now,
                now,
            ),
        )
        row = conn.execute(
            "SELECT * FROM fulfilment_notifications WHERE notification_key=?",
            (notification_key,),
        ).fetchone()
    return {"ok": True, "notification": dict(row) if row else None}


@app.post("/api/notifications/{notification_id}/dismiss")
def api_dismiss_notification(notification_id: int) -> dict[str, Any]:
    with db() as conn:
        row = conn.execute(
            "SELECT pinned FROM fulfilment_notifications WHERE id=?",
            (int(notification_id),),
        ).fetchone()
        if row and int(row["pinned"] or 0):
            return {"ok": True, "dismissed": False, "pinned": True}
        updated = conn.execute(
            "UPDATE fulfilment_notifications SET dismissed=1, updated_at=? WHERE id=?",
            (utc_now(), int(notification_id)),
        )
    return {"ok": True, "dismissed": bool(updated.rowcount)}


@app.post("/api/notifications/{notification_id}/pin")
async def api_pin_notification(notification_id: int, request: Request) -> dict[str, Any]:
    payload = await request.json()
    pinned = 1 if bool(payload.get("pinned")) else 0
    with db() as conn:
        conn.execute(
            "UPDATE fulfilment_notifications SET pinned=?, updated_at=? WHERE id=?",
            (pinned, utc_now(), int(notification_id)),
        )
    return {"ok": True, "pinned": bool(pinned)}


@app.post("/api/tracking/payment-failures/{amazon_order_id}/resolve")
def api_tracking_payment_failure_resolve(amazon_order_id: str) -> dict[str, Any]:
    amazon_order_id = clean_text(amazon_order_id)
    if not amazon_order_id:
        raise HTTPException(400, "amazon_order_id is required")
    now = utc_now()
    with db() as conn:
        cursor = conn.execute(
            """
            UPDATE amazon_payment_failures
            SET status='resolved', resolved_at=?, updated_at=?
            WHERE amazon_order_id=?
            """,
            (now, now, amazon_order_id),
        )
        resolve_payment_failure_for_order(conn, amazon_order_id, now)
        removed_scan_rows = dispatch_clear_packages_for_amazon_order(conn, amazon_order_id)
        failure_row = conn.execute("SELECT * FROM amazon_payment_failures WHERE amazon_order_id=?", (amazon_order_id,)).fetchone()
    if cursor.rowcount == 0:
        raise HTTPException(404, "Payment failure record not found")
    if failure_row:
        _TYPESENSE_INDEX_EXECUTOR.submit(lambda snapshot=row_to_dict(failure_row) or {}: _index_named_document_sync("amazon_payment_failures", payment_failure_search_document(snapshot)))
    fast_page_cache_clear_matching({
        "dispatch-sorting-summary",
        "dispatch-sorting-summary-base",
        "dispatch-status",
        "dispatch-status-summary",
        "payment-failures",
    })
    return {"ok": True, "message": f"Marked payment issue resolved for {amazon_order_id}. Removed {removed_scan_rows} stale dispatch scan row(s)."}


@app.post("/api/manual-amazon/match")
def api_manual_amazon_match(payload: ManualAmazonOrderMatchPayload) -> dict[str, Any]:
    amazon_order_id = clean_text(payload.amazon_order_id)
    if not amazon_order_id:
        raise HTTPException(400, "amazon_order_id is required")
    requested_refs: list[str] = []
    for value in payload.order_names or []:
        requested_refs.extend(amazon_order_refs_from_text(str(value or "")))
    requested_refs = list(dict.fromkeys(requested_refs))
    source_refs = amazon_order_refs_from_text(payload.source_text or "")
    if requested_refs and (not source_refs or not set(requested_refs).issubset(source_refs)):
        raise HTTPException(
            409,
            "Amazon recipient evidence is missing or does not contain every selected Nutricity order reference; match refused.",
        )
    refs = requested_refs or source_refs
    if not refs:
        return {"ok": True, "matched": 0, "skipped": 0, "order_names": [], "message": f"No Nutricity order references found for {amazon_order_id}."}
    amazon_order_url = clean_text(payload.amazon_order_url) or order_line_amazon_url(amazon_order_id)
    amazon_account_name = clean_text(payload.amazon_account_name) or "Chrome Manual Matcher"
    amazon_order_placed_at = parse_amazon_order_placed_date(payload.order_date)
    ordered_at = amazon_order_placed_at or utc_now()
    line_ids = sorted({int(line_id) for line_id in payload.line_ids if int(line_id or 0) > 0})
    with db() as conn:
        params: list[Any] = refs[:]
        store_filter = ""
        line_filter = ""
        params.append(1 if payload.replace_existing else 0)
        if payload.store_id:
            store_filter = " AND store_id=?"
            params.append(int(payload.store_id))
        if line_ids:
            line_filter = f" AND id IN ({','.join('?' for _ in line_ids)})"
            params.extend(line_ids)
        rows = rows_to_dicts(conn.execute(
            f"""
            SELECT *
            FROM order_lines
            WHERE UPPER(odoo_order_name) IN ({','.join('?' for _ in refs)})
              AND (? = 1 OR COALESCE(amazon_order_id, '') = '')
              AND state NOT IN ('cancelled', 'refunded')
              AND COALESCE(odoo_status_label, '') NOT IN ('cancelled', 'refunded')
              {store_filter}
              {line_filter}
            ORDER BY store_id, odoo_order_id, id
            """,
            params,
        ).fetchall())
        if not rows:
            return {"ok": True, "matched": 0, "skipped": len(refs), "order_names": refs, "message": f"No unmatched pulled rows found for {', '.join(refs)}."}
        date_repair_only = bool(amazon_order_placed_at) and all(clean_text(row.get("amazon_order_id")) == amazon_order_id for row in rows)
        if not date_repair_only:
            allowed_rows: list[dict[str, Any]] = []
            blocked_total = 0
            blocked_messages: list[str] = []
            for row_store_id in sorted({int(row["store_id"]) for row in rows}):
                store_rows = [row for row in rows if int(row["store_id"]) == row_store_id]
                date_allowed, date_blocked, date_messages = block_lines_before_min_odoo_order_date(conn, store_rows)
                allowed, blocked_count, messages = block_lines_with_fulfilled_shopify_orders(conn, row_store_id, date_allowed, live_sync=False)
                allowed_rows.extend(allowed)
                blocked_total += date_blocked + blocked_count
                blocked_messages.extend([*date_messages, *messages])
            rows = allowed_rows
            if not rows:
                return {
                    "ok": False,
                    "matched": 0,
                    "skipped": blocked_total,
                    "order_names": refs,
                    "message": "Blocked because selected order is not placeable. " + " | ".join(sorted(set(blocked_messages))),
                }
        now = utc_now()
        updated_for_shopify: list[dict[str, Any]] = []
        for row in rows:
            resolved_account_name = preserve_real_amazon_account_name(
                row.get("amazon_account_name"),
                amazon_account_name,
            )
            if clean_text(row.get("amazon_order_id")) == amazon_order_id:
                if amazon_order_placed_at:
                    conn.execute(
                        """
                        UPDATE order_lines
                        SET amazon_order_url=?,
                            amazon_account_name=?,
                            order_engine='chrome',
                            amazon_status='ordered',
                            state='ordered',
                            missing_asin=NULL,
                            last_error=NULL,
                            ordered_at=?,
                            updated_at=?
                        WHERE id=?
                        """,
                        (amazon_order_url, resolved_account_name, amazon_order_placed_at, now, row["id"]),
                    )
                    updated_for_shopify.append({
                        **dict(row),
                        "amazon_order_url": amazon_order_url,
                        "amazon_account_name": resolved_account_name,
                        "order_engine": "chrome",
                        "amazon_status": "ordered",
                        "state": "ordered",
                        "missing_asin": None,
                        "last_error": None,
                        "ordered_at": amazon_order_placed_at,
                        "updated_at": now,
                    })
                else:
                    updated_for_shopify.append(dict(row))
                continue
            conn.execute(
                """
                UPDATE order_lines
                SET amazon_order_id=?,
                    amazon_order_url=?,
                    amazon_account_name=?,
                    amazon_cancelled_order_id=CASE
                        WHEN COALESCE(amazon_order_id, '') != '' AND amazon_order_id != ?
                        THEN COALESCE(NULLIF(amazon_cancelled_order_id, ''), amazon_order_id)
                        ELSE amazon_cancelled_order_id
                    END,
                    order_engine='chrome',
                    amazon_status='ordered',
                    state='ordered',
                    missing_asin=NULL,
                    tracking_status=CASE
                        WHEN COALESCE(amazon_order_id, '') != ? THEN NULL
                        ELSE tracking_status
                    END,
                    tracking_payload=CASE
                        WHEN COALESCE(amazon_order_id, '') != ? THEN NULL
                        ELSE tracking_payload
                    END,
                    tracking_checked_at=CASE
                        WHEN COALESCE(amazon_order_id, '') != ? THEN NULL
                        ELSE tracking_checked_at
                    END,
                    last_error=NULL,
                    ordered_at=?,
                    updated_at=?
                WHERE id=?
                """,
                (
                    amazon_order_id,
                    amazon_order_url,
                    resolved_account_name,
                    amazon_order_id,
                    amazon_order_id,
                    amazon_order_id,
                    amazon_order_id,
                    ordered_at,
                    now,
                    row["id"],
                ),
            )
            updated_for_shopify.append({
                **dict(row),
                "amazon_order_id": amazon_order_id,
                "amazon_order_url": amazon_order_url,
                "amazon_account_name": resolved_account_name,
                "amazon_cancelled_order_id": clean_text(row.get("amazon_cancelled_order_id")) or (
                    clean_text(row.get("amazon_order_id"))
                    if clean_text(row.get("amazon_order_id")) and clean_text(row.get("amazon_order_id")) != amazon_order_id
                    else clean_text(row.get("amazon_cancelled_order_id"))
                ),
                "order_engine": "chrome",
                "amazon_status": "ordered",
                "state": "ordered",
                "missing_asin": None,
                "tracking_status": None if clean_text(row.get("amazon_order_id")) != amazon_order_id else row.get("tracking_status"),
                "tracking_payload": None if clean_text(row.get("amazon_order_id")) != amazon_order_id else row.get("tracking_payload"),
                "tracking_checked_at": None if clean_text(row.get("amazon_order_id")) != amazon_order_id else row.get("tracking_checked_at"),
                "last_error": None,
                "ordered_at": ordered_at,
                "updated_at": now,
            })
    matched_refs = sorted({str(row["odoo_order_name"]).upper() for row in rows})
    # Clear order-history annotations immediately after a manual correction so
    # a former Amazon ID does not continue to display as a conflict.
    clear_order_progress_caches()
    followup_timer = threading.Timer(
        0.1,
        manual_amazon_match_followups,
        args=(rows, updated_for_shopify, amazon_order_id, amazon_order_url, amazon_account_name),
    )
    followup_timer.daemon = True
    followup_timer.start()
    return {
        "ok": True,
        "matched": len(rows),
        "order_names": matched_refs,
        "amazon_order_id": amazon_order_id,
        "message": f"Matched Amazon order {amazon_order_id} to {len(rows)} line(s): {', '.join(matched_refs)}.",
    }


@app.post("/api/lines/manual-fulfilment")
def api_manual_line_fulfilment(payload: ManualFulfilmentPayload) -> dict[str, Any]:
    store_id = int(payload.store_id or 0)
    line_ids = [int(line_id) for line_id in (payload.line_ids or []) if int(line_id or 0) > 0]
    reference = clean_text(payload.reference)
    url = clean_text(payload.url)
    third_party = bool(payload.third_party)
    total_cost = float(payload.total_cost or 0)
    estimated_delivery_at = clean_text(payload.estimated_delivery_at)
    if estimated_delivery_at and not parse_any_datetime(estimated_delivery_at):
        raise HTTPException(400, "Enter a valid estimated delivery date and time.")
    if not line_ids:
        raise HTTPException(400, "Select at least one order line.")
    if not reference and not url:
        raise HTTPException(400, "Enter an Amazon order ID, third-party order number, or URL.")
    if third_party and total_cost <= 0:
        raise HTTPException(400, "Enter the third-party order cost for profit/loss.")
    with db() as conn:
        selected_ids = validate_line_ids_for_store(conn, store_id, line_ids, "Manual fulfilment")
    placeholders = ",".join("?" for _ in selected_ids)
    now = utc_now()
    updated_for_shopify: list[dict[str, Any]] = []
    with db() as conn:
        selected_rows = rows_to_dicts(conn.execute(
            f"""
            SELECT *
            FROM order_lines
            WHERE store_id=?
              AND id IN ({placeholders})
              AND COALESCE(amazon_order_id, '') = ''
              AND state NOT IN ('cancelled', 'refunded', 'delivered', 'dispatched', 'ignored')
              AND COALESCE(odoo_status_label, '') NOT IN ('cancelled', 'refunded')
            """,
            [store_id, *selected_ids],
        ).fetchall())
        if not selected_rows:
            raise HTTPException(400, "No selected unfulfilled order lines can be manually fulfilled.")
        order_ids = sorted({int(row["odoo_order_id"]) for row in selected_rows})
        order_placeholders = ",".join("?" for _ in order_ids)
        rows = rows_to_dicts(conn.execute(
            f"""
            SELECT *
            FROM order_lines
            WHERE store_id=?
              AND odoo_order_id IN ({order_placeholders})
              AND COALESCE(amazon_order_id, '') = ''
              AND state NOT IN ('cancelled', 'refunded', 'delivered', 'dispatched', 'ignored')
              AND COALESCE(odoo_status_label, '') NOT IN ('cancelled', 'refunded')
            ORDER BY odoo_order_id, id
            """,
            [store_id, *order_ids],
        ).fetchall())
        if not rows:
            raise HTTPException(400, "No open lines found for the selected Odoo order.")
        rows, date_blocked, date_messages = block_lines_before_min_odoo_order_date(conn, rows)
        if not rows:
            raise HTTPException(
                409,
                "Blocked because Odoo order date is before 2026-05-18. "
                + (" | ".join(date_messages) if date_messages else "This order must never be placed."),
            )
        rows, shopify_blocked, shopify_messages = block_lines_with_fulfilled_shopify_orders(conn, store_id, rows)
        if not rows:
            raise HTTPException(
                409,
                "Blocked because matching Shopify order is already fulfilled. "
                + (" | ".join(shopify_messages) if shopify_messages else "The customer may have received it."),
            )
        total_store_value = sum(order_line_store_total(row) for row in rows)
        third_party_cost_by_id: dict[int, float] = {}
        if third_party:
            remaining_cost = total_cost
            for index, row in enumerate(rows):
                if index == len(rows) - 1:
                    line_cost = remaining_cost
                elif total_store_value > 0:
                    line_cost = round(total_cost * (order_line_store_total(row) / total_store_value), 2)
                else:
                    line_cost = round(total_cost / max(1, len(rows)), 2)
                third_party_cost_by_id[int(row["id"])] = max(0.0, line_cost)
                remaining_cost -= line_cost
            manual_ref = reference or url
            note = f"Third-party fulfilled: {manual_ref}"
            if url and url != manual_ref:
                note += f" ({url})"
            for row in rows:
                line_cost = third_party_cost_by_id.get(int(row["id"]), 0.0)
                quantity = float(row["quantity"] or 1)
                store_total = order_line_store_total(row)
                conn.execute(
                    """
                    UPDATE order_lines
                    SET amazon_order_id=?,
                        amazon_order_url=?,
                        amazon_account_id=NULL,
                        amazon_account_name='Third Party',
                        order_engine='third_party',
                        amazon_group_key=NULL,
                        amazon_status='third_party_fulfilled',
                        state='ordered',
                        missing_asin=NULL,
                        amazon_unit_price=?,
                        amazon_total_price=?,
                        chrome_profit_total=?,
                        manual_estimated_delivery_at=?,
                        fulfilment_note=CASE
                          WHEN COALESCE(fulfilment_note, '') = '' THEN ?
                          ELSE fulfilment_note || ' | ' || ?
                        END,
                        last_error=NULL,
                        ordered_at=COALESCE(ordered_at, ?),
                        updated_at=?
                    WHERE id=?
                    """,
                    (
                        manual_ref,
                        url,
                        (line_cost / quantity) if quantity else line_cost,
                        line_cost,
                        store_total - line_cost,
                        estimated_delivery_at or None,
                        f"{note}; cost {line_cost:.2f}",
                        f"{note}; cost {line_cost:.2f}",
                        now,
                        now,
                        row["id"],
                    ),
                )
        else:
            amazon_order_id = reference
            if not amazon_order_id:
                raise HTTPException(400, "Amazon order ID is required when third-party fulfilment is unchecked.")
            amazon_order_url = url or order_line_amazon_url(amazon_order_id)
            for row in rows:
                conn.execute(
                    """
                    UPDATE order_lines
                    SET amazon_order_id=?,
                        amazon_order_url=?,
                        amazon_account_id=NULL,
                        amazon_account_name='Manual Amazon',
                        order_engine='manual_amazon',
                        amazon_group_key=NULL,
                        amazon_status='ordered',
                        state='ordered',
                        missing_asin=NULL,
                        manual_estimated_delivery_at=?,
                        last_error=NULL,
                        ordered_at=COALESCE(ordered_at, ?),
                        updated_at=?
                    WHERE id=?
                    """,
                    (amazon_order_id, amazon_order_url, estimated_delivery_at or None, now, now, row["id"]),
                )
        for row in rows:
            updated = conn.execute("SELECT * FROM order_lines WHERE id=?", (row["id"],)).fetchone()
            if updated:
                ensure_inventory_for_line(updated)
                index_order_line(updated)
                updated_for_shopify.append(dict(updated))
    if updated_for_shopify:
        enqueue_shopify_fulfilment_for_rows(updated_for_shopify)
    if third_party:
        try:
            odoo = OdooClient(get_store(store_id))
            note = f"Third-party fulfilment recorded and queued to Shopify: {reference or url}"
            if url:
                note += f"\nThird-party order link: {url}"
            note += f"\nThird-party total cost: {total_cost:.2f}"
            if estimated_delivery_at:
                note += f"\nEstimated delivery: {estimated_delivery_at}"
            for order_id in sorted({int(row["odoo_order_id"]) for row in rows}):
                odoo.post_order_note(order_id, note)
        except Exception:
            pass
    write_report(store_id)
    data = dashboard_data(store_id)
    mode = "third-party" if third_party else "manual Amazon"
    data["message"] = f"Marked {len(rows)} line(s) across {len({row['odoo_order_name'] for row in rows})} Odoo order(s) as {mode} fulfilled."
    return data


@app.get("/api/epost/tracking")
def api_epost_tracking(store_id: Optional[int] = None, page: int = 1, per_page: int = 100, status: str = "all", stale_days: int = 10, stale_only: bool = False, q: str = "") -> dict[str, Any]:
    page, per_page, _ = pagination_bounds(page, per_page)
    status = clean_text(status or "all").lower()
    stale_days = max(1, min(90, int(stale_days or 10)))
    q = clean_text(q)
    search_engine = "postgres"
    cache_key = ("epost-tracking", store_id, page, per_page, status, stale_days, bool(stale_only), q)
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    try:
        rows, total, page, per_page = paged_epost_tracking_rows(store_id, page, per_page, status, stale_days, stale_only, q)
    except Exception as exc:
        raise HTTPException(
            status_code=503,
            detail=f"ePost tracking rows are temporarily unavailable. Please refresh again shortly. {clean_error_message(exc)}",
        ) from exc
    return fast_page_cache_set(cache_key, {"ok": True, "rows": rows, "page": page, "per_page": per_page, "total": total, "search_engine": search_engine, "stale_days": stale_days, "stale_only": stale_only, "q": q}, 90)


@app.post("/api/epost/tracking/{tracking_id}/refund")
def api_epost_refund_status(tracking_id: int, payload: EpostRefundPayload) -> dict[str, Any]:
    status = clean_text(payload.status).lower().replace("-", "_")
    if status not in {"claimed", "received", "clear"}:
        raise HTTPException(status_code=400, detail="Refund status must be claimed, received, or clear.")
    now = utc_now()
    with db() as conn:
        row = conn.execute("SELECT id FROM epost_global_tracking WHERE id=?", (tracking_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="ePost tracking row not found.")
        if status == "clear":
            conn.execute(
                """
                UPDATE epost_global_tracking
                SET refund_status='', refund_claimed_at=NULL, refund_received_at=NULL, updated_at=?
                WHERE id=?
                """,
                (now, tracking_id),
            )
        elif status == "claimed":
            conn.execute(
                """
                UPDATE epost_global_tracking
                SET refund_status='claimed',
                    refund_claimed_at=COALESCE(refund_claimed_at, ?),
                    refund_received_at=NULL,
                    updated_at=?
                WHERE id=?
                """,
                (now, now, tracking_id),
            )
        else:
            conn.execute(
                """
                UPDATE epost_global_tracking
                SET refund_status='received',
                    refund_claimed_at=COALESCE(refund_claimed_at, ?),
                    refund_received_at=?,
                    updated_at=?
                WHERE id=?
                """,
                (now, now, now, tracking_id),
            )
    updated = epost_tracking_rows_by_ids([tracking_id])
    return {"ok": True, "row": updated[0] if updated else None}


