def package_tracker_delivery_kind(package_status: Any, promise: Any) -> str:
    value = f"{clean_text(package_status)} {clean_text(promise)}".lower()
    if "cancel" in value or "refund issued" in value or "refunded" in value:
        return "cancelled"
    if re.search(r"\bdelivered\b", value) and not any(token in value for token in ("not delivered", "unable to deliver", "delivery attempted")):
        return "delivered"
    if any(token in value for token in ("delay", "late", "exception", "problem", "failed", "unable", "attempted", "lost", "return")):
        return "exception"
    return "arriving"


def package_tracker_delivery_date(package_status: Any, promise: Any, updated_at: Any) -> str:
    text = f"{clean_text(package_status)} {clean_text(promise)}"
    reference = parse_iso_date(clean_text(updated_at)) or datetime.now(timezone.utc)
    match = re.search(
        r"\b(?:delivered(?:\s+on)?\s+)?(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{1,2})(?:,?\s+(\d{4}))?\b",
        text,
        re.IGNORECASE,
    )
    if not match:
        if re.search(r"\bdelivered\s+today\b", text, re.IGNORECASE):
            brooklyn_date = reference.astimezone(PACKAGE_PICKUP_TIMEZONE).date()
            return datetime.combine(brooklyn_date, datetime.min.time(), tzinfo=PACKAGE_PICKUP_TIMEZONE).isoformat()
        return ""
    year = int(match.group(3) or reference.year)
    try:
        parsed = datetime.strptime(f"{match.group(1)[:3]} {match.group(2)} {year}", "%b %d %Y").replace(tzinfo=timezone.utc)
    except ValueError:
        return ""
    if not match.group(3) and parsed > reference + timedelta(days=14):
        parsed = parsed.replace(year=year - 1)
    return parsed.isoformat()


def package_tracker_stuck_analysis(
    *,
    status: Any,
    promise: Any = "",
    carrier: Any = "",
    order_date: Any = "",
    expected_at: Any = "",
    tracking_id: Any = "",
    updated_at: Any = "",
    today: Any = None,
) -> dict[str, Any]:
    """Flag delivery risk conservatively; never turn a heuristic into a delivery fact."""
    status_text = clean_text(status)
    combined = f"{status_text} {clean_text(promise)} {clean_text(carrier)}".lower()
    kind = package_tracker_delivery_kind(status_text, promise)
    if kind in {"delivered", "cancelled"}:
        return {"possibly_stuck": False, "stuck_score": 0, "stuck_reasons": []}

    current_date = today or dispatch_current_date()
    order_dt = parse_iso_date(parse_amazon_order_placed_date(order_date) or clean_text(order_date))
    updated_dt = parse_iso_date(clean_text(updated_at))
    order_age_days = max(0, (current_date - order_dt.date()).days) if order_dt else None
    update_age_days = max(0, (current_date - updated_dt.date()).days) if updated_dt else None
    score = 0
    reasons: list[str] = []

    explicit_late = any(token in combined for token in (
        "running late", "delivery is late", "delayed", "delay in transit",
        "now expected", "may be lost", "package is late",
    ))
    if explicit_late:
        score += 4
        reasons.append("Amazon reports a late or rescheduled delivery")

    expected_iso = package_tracker_delivery_date(status_text, promise, updated_at)
    expected_dt = parse_iso_date(clean_text(expected_at)) or parse_iso_date(expected_iso)
    if expected_dt and expected_dt.date() < current_date:
        score += 4
        reasons.append(f"Promised date passed on {expected_dt.date().isoformat()}")

    relative_promise = next((label for label in (
        "arriving tomorrow", "arriving today", "expected today", "out for delivery",
    ) if label in combined), "")
    if order_age_days is not None and order_age_days >= 2 and relative_promise:
        score += 3
        reasons.append(f'Still "{relative_promise.title()}" {order_age_days} days after ordering')
    elif order_age_days is not None and order_age_days >= 4:
        score += 3
        reasons.append(f"Not delivered {order_age_days} days after ordering")

    if order_age_days is not None and order_age_days >= 2 and not package_tracking_id_is_physical(tracking_id):
        score += 2
        reasons.append(f"No physical tracking ID {order_age_days} days after ordering")
    if update_age_days is not None and update_age_days >= 2:
        score += 1
        reasons.append(f"Amazon status has not refreshed for {update_age_days} days")

    possibly_stuck = score >= 3
    return {
        "possibly_stuck": possibly_stuck,
        "stuck_score": score,
        "stuck_reasons": reasons if possibly_stuck else [],
        "order_age_days": order_age_days,
        "last_status_age_days": update_age_days,
    }


_PACKAGE_TRACKER_IMAGE_URL_CACHE: dict[str, str] = {}
_PACKAGE_TRACKER_IMAGE_URL_CACHE_LOCK = threading.Lock()
_PACKAGE_TRACKER_IMAGE_FAILURE_CACHE: dict[str, float] = {}
_PACKAGE_TRACKER_CAPTURED_IMAGE_CACHE: dict[str, str] = {}
_PACKAGE_TRACKER_CAPTURED_IMAGE_CACHE_LOCK = threading.Lock()


def package_tracker_captured_image_urls(asins: Any) -> dict[str, str]:
    normalized_asins = list(dict.fromkeys(
        normalize_asin(value) for value in (asins or []) if normalize_asin(value)
    ))
    if not normalized_asins:
        return {}
    with _PACKAGE_TRACKER_CAPTURED_IMAGE_CACHE_LOCK:
        found = {
            asin: _PACKAGE_TRACKER_CAPTURED_IMAGE_CACHE[asin]
            for asin in normalized_asins
            if asin in _PACKAGE_TRACKER_CAPTURED_IMAGE_CACHE
        }
    missing = [asin for asin in normalized_asins if asin not in found]
    if not missing:
        return found

    candidates: list[dict[str, Any]] = []
    with db() as conn:
        placeholders = ",".join("?" for _ in missing)
        inventory_rows = rows_to_dicts(conn.execute(
            f"""SELECT asin, image_url FROM inventory_items
                WHERE UPPER(asin) IN ({placeholders}) AND COALESCE(image_url, '') != ''
                ORDER BY updated_at DESC""",
            missing,
        ).fetchall())
        for row in inventory_rows:
            candidates.append({"asin": row.get("asin"), "image_url": row.get("image_url")})
        for table, column, date_column in (
            ("amazon_order_history_unmatched", "items_json", "last_seen_at"),
            ("amazon_dispatch_packages", "products_json", "updated_at"),
        ):
            clauses = " OR ".join(f"{column} LIKE ?" for _ in missing)
            rows = rows_to_dicts(conn.execute(
                f"SELECT {column} FROM {table} WHERE {clauses} ORDER BY {date_column} DESC",
                [f"%{asin}%" for asin in missing],
            ).fetchall())
            for row in rows:
                candidates.extend(
                    dict(product)
                    for product in parse_json_list_value(row.get(column))
                    if isinstance(product, dict)
                )

    missing_set = set(missing)
    for product in candidates:
        asin = normalize_asin(product.get("asin"))
        image_url = clean_text(product.get("image_url"))
        if asin in missing_set and asin not in found and is_safe_amazon_image_url(image_url):
            found[asin] = image_url
    with _PACKAGE_TRACKER_CAPTURED_IMAGE_CACHE_LOCK:
        _PACKAGE_TRACKER_CAPTURED_IMAGE_CACHE.update(found)
    return found


def package_tracker_cached_image_url(asin: str, *, force_refresh: bool = False) -> str:
    now = time.monotonic()
    with _PACKAGE_TRACKER_IMAGE_URL_CACHE_LOCK:
        cached = _PACKAGE_TRACKER_IMAGE_URL_CACHE.get(asin)
        failed_until = _PACKAGE_TRACKER_IMAGE_FAILURE_CACHE.get(asin, 0.0)
    if cached:
        return cached
    captured = package_tracker_captured_image_urls([asin]).get(asin, "")
    if captured:
        with _PACKAGE_TRACKER_IMAGE_URL_CACHE_LOCK:
            _PACKAGE_TRACKER_IMAGE_URL_CACHE[asin] = captured
            _PACKAGE_TRACKER_IMAGE_FAILURE_CACHE.pop(asin, None)
        return captured
    if failed_until > now and not force_refresh:
        return ""
    image_url = amazon_product_page_image_url(asin)
    if image_url:
        with _PACKAGE_TRACKER_IMAGE_URL_CACHE_LOCK:
            if len(_PACKAGE_TRACKER_IMAGE_URL_CACHE) >= 4096:
                _PACKAGE_TRACKER_IMAGE_URL_CACHE.pop(next(iter(_PACKAGE_TRACKER_IMAGE_URL_CACHE)), None)
            _PACKAGE_TRACKER_IMAGE_URL_CACHE[asin] = image_url
            _PACKAGE_TRACKER_IMAGE_FAILURE_CACHE.pop(asin, None)
    else:
        with _PACKAGE_TRACKER_IMAGE_URL_CACHE_LOCK:
            _PACKAGE_TRACKER_IMAGE_FAILURE_CACHE[asin] = now + 10 * 60
    return image_url


def package_tracker_product_image_url(
    product: dict[str, Any],
    history_products: list[dict[str, Any]],
    *,
    allow_unambiguous_replacement: bool = False,
    captured_images_by_asin: Optional[dict[str, str]] = None,
) -> str:
    """Prefer captured Amazon images before the slower ASIN lookup fallback."""
    existing_url = clean_text(product.get("image_url"))
    if existing_url:
        return existing_url
    asin = normalize_asin(product.get("asin"))
    normalized_history = normalize_amazon_product_items(history_products)
    history_by_asin = {
        normalize_asin(item.get("asin")): item
        for item in normalized_history
        if normalize_asin(item.get("asin"))
    }
    matched = history_by_asin.get(asin)
    if not matched and allow_unambiguous_replacement and len(history_by_asin) == 1:
        matched = next(iter(history_by_asin.values()))
    captured_images_by_asin = captured_images_by_asin or {}
    captured_url = clean_text(captured_images_by_asin.get(asin)) or clean_text((matched or {}).get("image_url"))
    if captured_url:
        return captured_url
    image_asin = normalize_asin((matched or {}).get("asin")) or asin
    captured_url = clean_text(captured_images_by_asin.get(image_asin))
    if captured_url:
        return captured_url
    return f"/api/public/asin-image/{quote_plus(image_asin)}" if image_asin else ""


def package_tracker_missing_history_products(
    packages: list[dict[str, Any]],
    history: dict[str, Any],
) -> list[dict[str, Any]]:
    """Return only confidently missing products, never replacement-only ASIN differences."""
    package_asins: set[str] = set()
    for package in packages:
        package_asins.update(
            normalize_asin(value)
            for value in parse_json_list_value(package.get("asins_json"))
            if normalize_asin(value)
        )
        package_asins.update(
            normalize_asin(product.get("asin"))
            for product in parse_json_list_value(package.get("products_json"))
            if isinstance(product, dict) and normalize_asin(product.get("asin"))
        )
    history_products = normalize_amazon_product_items(parse_json_list_value(history.get("items_json")))
    history_by_asin = {
        normalize_asin(product.get("asin")): product
        for product in history_products
        if normalize_asin(product.get("asin"))
    }
    for value in parse_json_list_value(history.get("asins_json")):
        asin = normalize_asin(value)
        if asin and asin not in history_by_asin:
            history_by_asin[asin] = {
                "asin": asin,
                "title": asin,
                "image_url": "",
                "url": asin_product_url(asin),
            }
    history_asins = set(history_by_asin)
    # A strict superset proves Amazon knows about additional items. Disjoint
    # sets usually represent an ASIN replacement and must not create extras.
    if not package_asins or not package_asins < history_asins:
        return []
    return [dict(history_by_asin[asin]) for asin in sorted(history_asins - package_asins)]


def package_tracker_canonical_dispatch_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Hide stale order-level rows when an Amazon order has real shipment rows."""
    grouped: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        grouped.setdefault(clean_text(row.get("amazon_order_id")), []).append(row)
    visible: list[dict[str, Any]] = []
    for order_rows in grouped.values():
        specific: list[dict[str, Any]] = []
        for row in order_rows:
            scan_code = normalize_dispatch_scan_code(row.get("scan_code"))
            canonical_code = normalize_dispatch_scan_code(row.get("canonical_scan_code"))
            order_code = normalize_dispatch_scan_code(row.get("amazon_order_id"))
            has_real_carrier_code = (
                package_tracking_id_is_physical(canonical_code)
                and canonical_code != order_code
            )
            if (
                has_real_carrier_code
                or scan_code.startswith("AMZPKG-")
                or tracking_package_has_shipment_identity({"tracking_url": row.get("tracking_url")})
            ):
                specific.append(row)
        visible.extend(specific or order_rows)
    return visible


def package_tracker_allowed_asins_for_order(
    lines: list[dict[str, Any]],
    amazon_order_id: str,
    history: dict[str, Any],
) -> set[str]:
    """ASINs proven to belong to one Amazon order, including replacements."""
    order_id = clean_text(amazon_order_id)
    allowed: set[str] = set()
    for line in lines:
        if clean_text(line.get("amazon_order_id")) == order_id:
            allowed.update(order_line_asin_aliases(line))
    for product in parse_json_list_value(history.get("items_json")):
        if isinstance(product, dict):
            asin = normalize_asin(product.get("asin"))
            if asin:
                allowed.add(asin)
    allowed.update(
        normalize_asin(value)
        for value in parse_json_list_value(history.get("asins_json"))
        if normalize_asin(value)
    )
    return allowed


def package_tracker_single_package_history_products(
    order_packages: list[dict[str, Any]],
    history: dict[str, Any],
) -> list[dict[str, Any]]:
    """Use Amazon's order items as the complete product list for one-package orders."""
    if len(order_packages) != 1:
        return []
    return [
        dict(product)
        for product in normalize_amazon_product_items(parse_json_list_value(history.get("items_json")))
        if normalize_asin(product.get("asin"))
    ]


def package_tracker_tracking_parts_from_lines(source_lines: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collect distinct pre-tracking Amazon shipment groups stored across order lines."""
    parts: list[dict[str, Any]] = []
    seen: set[str] = set()
    for line in source_lines:
        for part in parse_tracking_packages(clean_text(line.get("tracking_payload"))):
            if not isinstance(part, dict):
                continue
            identity = clean_text(
                part.get("tracking_id")
                or part.get("trackingId")
                or part.get("tracking_url")
                or part.get("trackingUrl")
            )
            if not identity:
                identity = json.dumps({
                    "status": clean_text(part.get("delivery_status") or part.get("order_status") or part.get("promise") or part.get("status")),
                    "asins": sorted(unique_normalized_asins(part.get("asins") or [])),
                }, sort_keys=True)
            if identity in seen:
                continue
            seen.add(identity)
            parts.append(dict(part))
    return parts or [{}]


def package_tracker_history_products_by_package(
    order_packages: list[dict[str, Any]],
    history: dict[str, Any],
) -> dict[int, list[dict[str, Any]]]:
    """Map Amazon order-page items to split shipments only when the mapping is unambiguous."""
    history_products = [
        dict(product)
        for product in normalize_amazon_product_items(parse_json_list_value(history.get("items_json")))
        if normalize_asin(product.get("asin"))
    ]
    if not history_products or not order_packages:
        return {}
    sorted_packages = sorted(
        order_packages,
        key=lambda package: (int(package.get("package_index") or 9999), int(package.get("id") or 0)),
    )
    allocations: dict[int, list[dict[str, Any]]] = {}
    claimed_asins: set[str] = set()
    empty_packages: list[dict[str, Any]] = []
    for package in sorted_packages:
        package_id = int(package.get("id") or 0)
        explicit = normalize_amazon_product_items(parse_json_list_value(package.get("products_json")))
        if explicit:
            allocations[package_id] = [dict(product) for product in explicit]
            claimed_asins.update(normalize_asin(product.get("asin")) for product in explicit)
        else:
            empty_packages.append(package)
    remaining = [product for product in history_products if normalize_asin(product.get("asin")) not in claimed_asins]
    if len(remaining) == len(empty_packages):
        for package, product in zip(empty_packages, remaining):
            allocations[int(package.get("id") or 0)] = [dict(product)]
    return allocations


def package_tracker_fallback_asins_by_package(
    order_packages: list[dict[str, Any]],
    lines: list[dict[str, Any]],
    amazon_order_id: str,
) -> dict[int, list[str]]:
    """Allocate broad order-level ASIN fallbacks without repeating them on every shipment."""
    order_id = clean_text(amazon_order_id)
    occurrence_limits: dict[str, int] = {}
    for line in lines:
        if clean_text(line.get("amazon_order_id")) != order_id:
            continue
        try:
            quantity = max(1, int(float(line.get("quantity") or 1)))
        except (TypeError, ValueError):
            quantity = 1
        for asin in order_line_asin_aliases(line):
            occurrence_limits[asin] = occurrence_limits.get(asin, 0) + quantity

    allocations: dict[int, list[str]] = {}
    occurrences: dict[str, int] = {}
    sorted_packages = sorted(
        order_packages,
        key=lambda package: (int(package.get("package_index") or 9999), int(package.get("id") or 0)),
    )
    for package in sorted_packages:
        package_id = int(package.get("id") or 0)
        explicit_products = normalize_amazon_product_items(parse_json_list_value(package.get("products_json")))
        represented_asins = {
            normalize_asin(product.get("asin"))
            for product in explicit_products
            if normalize_asin(product.get("asin"))
        }
        allocated: list[str] = []
        for asin in unique_normalized_asins(parse_json_list_value(package.get("asins_json"))):
            if asin in represented_asins:
                continue
            # asins_json is often copied from the whole Amazon order onto each
            # split shipment. Odoo quantity safely limits how many shipment
            # rows may claim the same fallback ASIN.
            limit = occurrence_limits.get(asin, 1)
            if occurrences.get(asin, 0) >= limit:
                continue
            occurrences[asin] = occurrences.get(asin, 0) + 1
            allocated.append(asin)
        allocations[package_id] = allocated
    return allocations


def package_tracker_enforce_product_guard(
    packages: list[dict[str, Any]],
    history_by_order_id: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    """Ensure every product associated by Amazon is rendered on exactly one package row."""
    packages_by_order: dict[str, list[dict[str, Any]]] = {}
    for package in packages:
        packages_by_order.setdefault(clean_text(package.get("amazon_order_id")), []).append(package)

    expected_total = 0
    displayed_total = 0
    recovered_total = 0
    missing_keys: list[str] = []
    unverified_orders: list[str] = []
    for amazon_order_id, order_packages in packages_by_order.items():
        history_products = [
            dict(product)
            for product in normalize_amazon_product_items(
                parse_json_list_value(history_by_order_id.get(amazon_order_id, {}).get("items_json"))
            )
            if normalize_asin(product.get("asin"))
        ]
        expected_by_asin = {
            normalize_asin(product.get("asin")): product
            for product in history_products
            if normalize_asin(product.get("asin"))
        }
        if not expected_by_asin:
            for package in order_packages:
                for product in package.get("products") or []:
                    asin = normalize_asin(product.get("asin"))
                    if asin:
                        expected_by_asin.setdefault(asin, dict(product))
        if not expected_by_asin:
            unverified_orders.append(amazon_order_id or "unknown")
            continue

        displayed_asins = {
            normalize_asin(product.get("asin"))
            for package in order_packages
            for product in (package.get("products") or [])
            if normalize_asin(product.get("asin"))
        }
        missing_asins = [asin for asin in expected_by_asin if asin not in displayed_asins]
        if missing_asins:
            target = order_packages[0]
            target_products = target.setdefault("products", [])
            target_unassigned = target.setdefault("unassigned_products", [])
            for asin in missing_asins:
                recovered = dict(expected_by_asin[asin])
                recovered["guard_recovered"] = True
                target_unassigned.append(dict(recovered))
                if len(order_packages) == 1 and not tracking_package_has_shipment_identity(target):
                    target_products.append(recovered)
                recovered_total += 1

        displayed_after = {
            normalize_asin(product.get("asin"))
            for package in order_packages
            for product in [*(package.get("products") or []), *(package.get("unassigned_products") or [])]
            if normalize_asin(product.get("asin"))
        }
        still_missing = [asin for asin in expected_by_asin if asin not in displayed_after]
        missing_keys.extend(f"{amazon_order_id}:{asin}" for asin in still_missing)
        expected_total += len(expected_by_asin)
        displayed_total += len(set(expected_by_asin).intersection(displayed_after))

    return {
        "complete": not missing_keys and not unverified_orders,
        "expected_products": expected_total,
        "displayed_products": displayed_total,
        "recovered_products": recovered_total,
        "missing_product_keys": missing_keys,
        "unverified_amazon_orders": unverified_orders,
    }


def package_tracker_quantity_analysis(
    lines: list[dict[str, Any]],
    packages: list[dict[str, Any]],
    history_by_order_id: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    expected_by_canonical: dict[str, dict[str, Any]] = {}
    for line in lines:
        canonical = normalize_asin(line.get("original_asin")) or normalize_asin(line.get("asin"))
        if not canonical:
            continue
        group = expected_by_canonical.setdefault(canonical, {
            "odoo_asin": canonical,
            "aliases": set(),
            "expected_quantity": 0.0,
        })
        group["aliases"].update(order_line_asin_aliases(line))
        try:
            group["expected_quantity"] += max(0.0, float(line.get("quantity") or 0))
        except (TypeError, ValueError):
            group["expected_quantity"] += 1.0

    packages_by_order: dict[str, list[dict[str, Any]]] = {}
    for package in packages:
        if package_tracker_delivery_kind(package.get("package_status"), package.get("promise")) == "cancelled":
            continue
        packages_by_order.setdefault(clean_text(package.get("amazon_order_id")), []).append(package)

    amazon_by_asin: dict[str, dict[str, Any]] = {}

    def add_amazon_item(asin_value: Any, quantity_value: Any, amazon_order_id: str) -> None:
        asin = normalize_asin(asin_value)
        if not asin:
            return
        try:
            quantity = max(1.0, float(quantity_value or 1))
        except (TypeError, ValueError):
            quantity = 1.0
        entry = amazon_by_asin.setdefault(asin, {"quantity": 0.0, "amazon_order_ids": set()})
        entry["quantity"] += quantity
        if amazon_order_id:
            entry["amazon_order_ids"].add(amazon_order_id)

    for amazon_order_id, order_packages in packages_by_order.items():
        authoritative_history_products = normalize_amazon_product_items(
            parse_json_list_value(history_by_order_id.get(amazon_order_id, {}).get("items_json"))
        )
        if authoritative_history_products:
            for product in authoritative_history_products:
                add_amazon_item(product.get("asin"), product.get("quantity"), amazon_order_id)
            continue
        allowed_asins = package_tracker_allowed_asins_for_order(
            lines,
            amazon_order_id,
            history_by_order_id.get(amazon_order_id, {}),
        )
        fallback_asins_by_package = package_tracker_fallback_asins_by_package(
            order_packages,
            lines,
            amazon_order_id,
        )
        for package in order_packages:
            products = normalize_amazon_product_items(parse_json_list_value(package.get("products_json")))
            if allowed_asins:
                products = [product for product in products if normalize_asin(product.get("asin")) in allowed_asins]
            if products:
                for product in products:
                    add_amazon_item(product.get("asin"), product.get("quantity"), amazon_order_id)
            else:
                for asin in fallback_asins_by_package.get(int(package.get("id") or 0), []):
                    if allowed_asins and asin not in allowed_asins:
                        continue
                    add_amazon_item(asin, 1, amazon_order_id)
        if len(order_packages) == 1:
            for product in package_tracker_missing_history_products(
                order_packages,
                history_by_order_id.get(amazon_order_id, {}),
            ):
                # History quantity is frequently the total order item count,
                # so a recovered missing ASIN contributes one proven unit.
                add_amazon_item(product.get("asin"), 1, amazon_order_id)

    alias_to_canonical: dict[str, list[str]] = {}
    for canonical, expected in expected_by_canonical.items():
        expected["aliases"].add(canonical)
        for alias in expected["aliases"]:
            alias_to_canonical.setdefault(alias, []).append(canonical)

    amazon_by_canonical: dict[str, dict[str, Any]] = {}
    mismatches: list[dict[str, Any]] = []
    for amazon_asin, amazon in amazon_by_asin.items():
        candidates = alias_to_canonical.get(amazon_asin, [])
        if not candidates:
            mismatches.append({
                "amazon_asin": amazon_asin,
                "amazon_quantity": amazon["quantity"],
                "amazon_order_ids": sorted(amazon["amazon_order_ids"]),
            })
            continue
        canonical = amazon_asin if amazon_asin in candidates else candidates[0]
        total = amazon_by_canonical.setdefault(canonical, {
            "amazon_quantity": 0.0,
            "amazon_order_ids": set(),
            "amazon_asins": set(),
        })
        total["amazon_quantity"] += amazon["quantity"]
        total["amazon_order_ids"].update(amazon["amazon_order_ids"])
        total["amazon_asins"].add(amazon_asin)

    duplicate_items: list[dict[str, Any]] = []
    for canonical, amazon in amazon_by_canonical.items():
        expected = expected_by_canonical[canonical]
        expected_quantity = float(expected["expected_quantity"] or 0)
        amazon_quantity = float(amazon["amazon_quantity"] or 0)
        if amazon_quantity <= expected_quantity:
            continue
        duplicate_items.append({
            "odoo_asin": canonical,
            "replacement_asins": sorted(set(expected["aliases"]) - {canonical}),
            "expected_quantity": expected_quantity,
            "amazon_quantity": amazon_quantity,
            "excess_quantity": amazon_quantity - expected_quantity,
            "amazon_order_ids": sorted(amazon["amazon_order_ids"]),
            "amazon_asins": sorted(amazon["amazon_asins"]),
        })

    return {
        "suspected_duplicate": bool(duplicate_items),
        "duplicate_items": sorted(duplicate_items, key=lambda item: (-item["excess_quantity"], item["odoo_asin"])),
        "asin_mismatches": sorted(mismatches, key=lambda item: item["amazon_asin"]),
    }


@app.get("/api/public/asin-image/{asin}")
def api_public_package_tracker_asin_image(asin: str, retry: int = 0) -> Response:
    normalized_asin = normalize_asin(asin)
    if not normalized_asin:
        raise HTTPException(404, "Amazon product image not found.")
    image_url = package_tracker_cached_image_url(normalized_asin, force_refresh=retry > 0)
    if not image_url:
        raise HTTPException(404, "Amazon product image not found.")
    return RedirectResponse(
        image_url,
        status_code=302,
        headers={"Cache-Control": "private, max-age=3600"},
    )


@app.get("/api/public/package-tracker")
def api_public_package_tracker(
    page: int = 1,
    per_page: int = 12,
    q: str = "",
    field: str = "all",
    status: str = "all",
    sort: str = "recent_delivery",
    from_date: str = "",
    to_date: str = "",
) -> dict[str, Any]:
    """Return paged Odoo-order cards without loading the full package index in Python."""
    page, per_page, offset = pagination_bounds(page, min(per_page, 48))
    query = clean_text(q)[:160].upper()
    field = clean_text(field).lower() or "all"
    if field not in {"all", "order_number", "amazon_order", "asin", "product_name", "tracking_id", "recipient"}:
        field = "all"
    status = clean_text(status).lower() or "all"
    from_date = clean_text(from_date)[:10]
    to_date = clean_text(to_date)[:10]
    cache_key = ("public-package-tracker", page, per_page, query, field, status, sort, from_date, to_date)
    cached = fast_page_cache_get(cache_key)
    if cached is not None:
        return cached
    status_sql = {
        "arriving": "active_count > 0 AND delivered_count = 0",
        "partial": "delivered_count > 0 AND delivered_count < active_count",
        "delivered": "active_count > 0 AND delivered_count = active_count",
        "shopify_pending": "active_count > 0 AND delivered_count = active_count AND NOT shopify_fulfilled",
        "cancelled_history": "has_cancelled_history",
        "suspected_duplicate": "has_suspected_duplicates",
    }.get(status, "TRUE")
    sort_sql = {
        "delivery_asc": "NULLIF(delivery_date, '') ASC NULLS LAST, odoo_order_name ASC",
        "delivery_desc": "NULLIF(delivery_date, '') DESC NULLS LAST, odoo_order_name ASC",
        "partial_first": "(delivered_count > 0 AND delivered_count < active_count) DESC, NULLIF(delivery_date, '') DESC NULLS LAST, updated_at DESC",
        "shopify_action": "(active_count > 0 AND delivered_count = active_count AND NOT shopify_fulfilled) DESC, NULLIF(delivery_date, '') DESC NULLS LAST, updated_at DESC",
        "updated": "updated_at DESC, odoo_order_name ASC",
        "odoo": "odoo_order_name ASC, updated_at DESC",
        "recent_delivery": "NULLIF(delivery_date, '') DESC NULLS LAST, updated_at DESC, odoo_order_name ASC",
    }.get(sort, "updated_at DESC, odoo_order_name ASC")
    scoped_search_sql = {
        "order_number": "UPPER(e.odoo_order_name) LIKE ?",
        "amazon_order": """EXISTS (
            SELECT 1 FROM (
                SELECT UPPER(COALESCE(l.amazon_order_id, '')) AS value
                FROM order_lines l
                WHERE l.store_id=e.store_id AND UPPER(l.odoo_order_name)=UPPER(e.odoo_order_name)
                UNION ALL
                SELECT UPPER(COALESCE(p.amazon_order_id, ''))
                FROM amazon_dispatch_packages p
                WHERE p.store_id=e.store_id AND UPPER(p.odoo_order_name)=UPPER(e.odoo_order_name)
            ) scoped_values WHERE scoped_values.value LIKE ?
        )""",
        "asin": """EXISTS (
            SELECT 1 FROM (
                SELECT UPPER(COALESCE(l.asin, '')) AS value
                FROM order_lines l
                WHERE l.store_id=e.store_id AND UPPER(l.odoo_order_name)=UPPER(e.odoo_order_name)
                UNION ALL
                SELECT UPPER(COALESCE(p.asins_json, '') || ' ' || COALESCE(p.products_json, ''))
                FROM amazon_dispatch_packages p
                WHERE p.store_id=e.store_id AND UPPER(p.odoo_order_name)=UPPER(e.odoo_order_name)
            ) scoped_values WHERE scoped_values.value LIKE ?
        )""",
        "product_name": """EXISTS (
            SELECT 1 FROM (
                SELECT UPPER(COALESCE(l.product_name, '')) AS value
                FROM order_lines l
                WHERE l.store_id=e.store_id AND UPPER(l.odoo_order_name)=UPPER(e.odoo_order_name)
                UNION ALL
                SELECT UPPER(COALESCE(p.products_json, ''))
                FROM amazon_dispatch_packages p
                WHERE p.store_id=e.store_id AND UPPER(p.odoo_order_name)=UPPER(e.odoo_order_name)
            ) scoped_values WHERE scoped_values.value LIKE ?
        )""",
        "tracking_id": """EXISTS (
            SELECT 1 FROM (
                SELECT UPPER(COALESCE(l.tracking_payload, '')) AS value
                FROM order_lines l
                WHERE l.store_id=e.store_id AND UPPER(l.odoo_order_name)=UPPER(e.odoo_order_name)
                UNION ALL
                SELECT UPPER(COALESCE(p.scan_code, '') || ' ' || COALESCE(p.canonical_scan_code, '') || ' ' ||
                             COALESCE(p.display_code, '') || ' ' || COALESCE(p.tracking_url, ''))
                FROM amazon_dispatch_packages p
                WHERE p.store_id=e.store_id AND UPPER(p.odoo_order_name)=UPPER(e.odoo_order_name)
            ) scoped_values WHERE scoped_values.value LIKE ?
        )""",
        "recipient": """EXISTS (
            SELECT 1 FROM (
                SELECT UPPER(COALESCE(p.recipient_ref, '')) AS value
                FROM amazon_dispatch_packages p
                WHERE p.store_id=e.store_id AND UPPER(p.odoo_order_name)=UPPER(e.odoo_order_name)
                UNION ALL
                SELECT UPPER(COALESCE(h.recipient, ''))
                FROM order_lines l
                JOIN amazon_order_history_unmatched h ON h.amazon_order_id=l.amazon_order_id
                WHERE l.store_id=e.store_id AND UPPER(l.odoo_order_name)=UPPER(e.odoo_order_name)
            ) scoped_values WHERE scoped_values.value LIKE ?
        )""",
    }.get(field, "e.search_text LIKE ?")

    ensure_shopify_order_status_cache_table_once()
    with db() as conn:
        grouped_rows = rows_to_dicts(conn.execute(
            f"""
            WITH line_groups AS (
                SELECT l.store_id, l.odoo_order_id, MAX(l.odoo_order_name) AS odoo_order_name,
                       COUNT(DISTINCT l.amazon_order_id) FILTER (
                           WHERE COALESCE(l.amazon_order_id, '') != ''
                             AND COALESCE(l.amazon_cancelled_at, '') = ''
                             AND LOWER(COALESCE(l.tracking_status, '') || ' ' || COALESCE(l.amazon_status, '')) NOT LIKE '%cancel%'
                       ) AS active_count,
                       COUNT(DISTINCT l.amazon_order_id) FILTER (
                           WHERE LOWER(COALESCE(l.tracking_status, '') || ' ' || COALESCE(l.amazon_status, '')) LIKE '%deliver%'
                             AND LOWER(COALESCE(l.tracking_status, '') || ' ' || COALESCE(l.amazon_status, '')) NOT LIKE '%not delivered%'
                             AND COALESCE(l.amazon_cancelled_at, '') = ''
                       ) AS delivered_count,
                       BOOL_OR(COALESCE(l.amazon_cancelled_at, '') != '' OR LOWER(COALESCE(l.tracking_status, '') || ' ' || COALESCE(l.amazon_status, '')) LIKE '%cancel%') AS has_cancelled_history,
                       MAX(CASE
                           WHEN line_delivery.parts IS NOT NULL THEN TO_CHAR(
                               TO_DATE(LEFT(line_delivery.parts[1], 3) || ' ' || line_delivery.parts[2] || ' ' || COALESCE(line_delivery.parts[3], SUBSTRING(l.updated_at, 1, 4)), 'Mon DD YYYY'),
                               'YYYY-MM-DD'
                           )
                           WHEN LOWER(COALESCE(l.tracking_status, '') || ' ' || COALESCE(l.tracking_payload, '')) LIKE '%delivered today%'
                           THEN TO_CHAR(
                               COALESCE(NULLIF(l.tracking_checked_at, ''), l.updated_at)::timestamptz AT TIME ZONE 'America/New_York',
                               'YYYY-MM-DD'
                           )
                           ELSE ''
                       END) AS delivery_date,
                       MAX(COALESCE(NULLIF(l.tracking_checked_at, ''), NULLIF(l.ordered_at, ''), l.updated_at)) AS effective_date,
                       MAX(l.updated_at) AS updated_at,
                       STRING_AGG(UPPER(COALESCE(l.odoo_order_name, '') || ' ' || COALESCE(l.amazon_order_id, '') || ' ' ||
                           COALESCE(l.tracking_status, '') || ' ' || COALESCE(l.tracking_payload, '') || ' ' ||
                           COALESCE(l.asin, '') || ' ' || COALESCE(l.product_name, '')), ' ') AS search_text
                FROM order_lines l
                LEFT JOIN LATERAL (
                    SELECT REGEXP_MATCH(
                        COALESCE(l.tracking_status, '') || ' ' || COALESCE(l.tracking_payload, ''),
                        '(?i)delivered(?:\\s+on)?\\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\\s+([0-9]{{1,2}})(?:,?\\s+([0-9]{{4}}))?'
                    ) AS parts
                ) line_delivery ON TRUE
                WHERE COALESCE(l.odoo_order_name, '') != '' AND COALESCE(l.amazon_order_id, '') != ''
                  AND NOT EXISTS (
                      SELECT 1 FROM amazon_payment_failures failure
                      WHERE failure.amazon_order_id=l.amazon_order_id AND failure.status='open'
                  )
                GROUP BY l.store_id, l.odoo_order_id, UPPER(l.odoo_order_name)
            ), package_groups AS (
                SELECT p.store_id, p.odoo_order_id, MAX(p.odoo_order_name) AS odoo_order_name,
                       MAX(COALESCE(p.recipient_ref, '')) AS recipient_ref,
                       COUNT(*) FILTER (WHERE LOWER(COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, '')) NOT LIKE '%cancel%') AS active_count,
                       COUNT(*) FILTER (
                           WHERE LOWER(COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, '')) LIKE '%deliver%'
                             AND LOWER(COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, '')) NOT LIKE '%not delivered%'
                             AND LOWER(COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, '')) NOT LIKE '%cancel%'
                       ) AS delivered_count,
                       BOOL_OR(LOWER(COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, '')) LIKE '%cancel%') AS has_cancelled_history,
                       MAX(CASE
                           WHEN package_delivery.parts IS NOT NULL THEN TO_CHAR(
                               TO_DATE(LEFT(package_delivery.parts[1], 3) || ' ' || package_delivery.parts[2] || ' ' || COALESCE(package_delivery.parts[3], SUBSTRING(p.updated_at, 1, 4)), 'Mon DD YYYY'),
                               'YYYY-MM-DD'
                           )
                           WHEN LOWER(COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, '')) LIKE '%delivered today%'
                           THEN TO_CHAR(
                               COALESCE(NULLIF(p.received_at, ''), p.updated_at)::timestamptz AT TIME ZONE 'America/New_York',
                               'YYYY-MM-DD'
                           )
                           ELSE ''
                       END) AS delivery_date,
                       MAX(COALESCE(NULLIF(p.received_at, ''), NULLIF(p.dispatch_date, ''), p.updated_at)) AS effective_date,
                       MAX(p.updated_at) AS updated_at,
                       STRING_AGG(UPPER(COALESCE(p.odoo_order_name, '') || ' ' || COALESCE(p.recipient_ref, '') || ' ' ||
                           COALESCE(p.amazon_order_id, '') || ' ' || COALESCE(p.scan_code, '') || ' ' ||
                           COALESCE(p.canonical_scan_code, '') || ' ' || COALESCE(p.display_code, '') || ' ' ||
                           COALESCE(p.carrier, '') || ' ' || COALESCE(p.package_status, '') || ' ' ||
                           COALESCE(p.tote_code, '') || ' ' || COALESCE(p.asins_json, '') || ' ' || COALESCE(p.products_json, '')), ' ') AS search_text
                FROM amazon_dispatch_packages p
                LEFT JOIN LATERAL (
                    SELECT REGEXP_MATCH(
                        COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, ''),
                        '(?i)delivered(?:\\s+on)?\\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\\s+([0-9]{{1,2}})(?:,?\\s+([0-9]{{4}}))?'
                    ) AS parts
                ) package_delivery ON TRUE
                WHERE COALESCE(p.odoo_order_name, '') != ''
                  AND NOT EXISTS (
                      SELECT 1 FROM amazon_payment_failures failure
                      WHERE failure.amazon_order_id=p.amazon_order_id AND failure.status='open'
                  )
                GROUP BY p.store_id, p.odoo_order_id, UPPER(p.odoo_order_name)
            ), combined_groups AS (
                SELECT lines.store_id, lines.odoo_order_id, lines.odoo_order_name,
                       COALESCE(packages.recipient_ref, '') AS recipient_ref,
                       GREATEST(COALESCE(packages.active_count, 0), lines.active_count) AS active_count,
                       GREATEST(COALESCE(packages.delivered_count, 0), lines.delivered_count) AS delivered_count,
                       COALESCE(packages.has_cancelled_history, lines.has_cancelled_history) AS has_cancelled_history,
                       GREATEST(COALESCE(packages.delivery_date, ''), COALESCE(lines.delivery_date, '')) AS delivery_date,
                       GREATEST(COALESCE(packages.effective_date, ''), COALESCE(lines.effective_date, '')) AS effective_date,
                       GREATEST(COALESCE(packages.updated_at, ''), COALESCE(lines.updated_at, '')) AS updated_at,
                       COALESCE(lines.search_text, '') || ' ' || COALESCE(packages.search_text, '') AS search_text
                FROM line_groups lines
                LEFT JOIN package_groups packages
                  ON packages.store_id=lines.store_id AND UPPER(packages.odoo_order_name)=UPPER(lines.odoo_order_name)
                UNION ALL
                SELECT packages.store_id, packages.odoo_order_id, packages.odoo_order_name, packages.recipient_ref,
                       packages.active_count, packages.delivered_count, packages.has_cancelled_history,
                       packages.delivery_date, packages.effective_date, packages.updated_at, packages.search_text
                FROM package_groups packages
                WHERE NOT EXISTS (
                    SELECT 1 FROM line_groups lines
                    WHERE lines.store_id=packages.store_id AND UPPER(lines.odoo_order_name)=UPPER(packages.odoo_order_name)
                )
            ), odoo_expected_quantities AS (
                SELECT l.store_id, UPPER(l.odoo_order_name) AS order_key,
                       UPPER(COALESCE(NULLIF(l.original_asin, ''), NULLIF(l.asin, ''))) AS canonical_asin,
                       SUM(GREATEST(COALESCE(l.quantity, 1), 0)) AS expected_quantity
                FROM order_lines l
                WHERE COALESCE(l.odoo_order_name, '') != '' AND COALESCE(l.asin, '') != ''
                GROUP BY l.store_id, UPPER(l.odoo_order_name),
                         UPPER(COALESCE(NULLIF(l.original_asin, ''), NULLIF(l.asin, '')))
            ), odoo_expected_aliases AS (
                SELECT aliases.store_id, aliases.order_key, aliases.canonical_asin,
                       ARRAY_AGG(DISTINCT aliases.alias_asin) AS asin_aliases
                FROM (
                    SELECT l.store_id, UPPER(l.odoo_order_name) AS order_key,
                           UPPER(COALESCE(NULLIF(l.original_asin, ''), NULLIF(l.asin, ''))) AS canonical_asin,
                           UPPER(alias.value) AS alias_asin
                    FROM order_lines l
                    CROSS JOIN LATERAL UNNEST(ARRAY[
                        COALESCE(l.asin, ''), COALESCE(l.original_asin, ''), COALESCE(l.replacement_asin, ''),
                        COALESCE(l.asin_from_reference, ''), COALESCE(l.asin_from_note, '')
                    ]) alias(value)
                    WHERE COALESCE(l.odoo_order_name, '') != '' AND COALESCE(alias.value, '') != ''
                ) aliases
                GROUP BY aliases.store_id, aliases.order_key, aliases.canonical_asin
            ), odoo_expected_items AS (
                SELECT quantities.store_id, quantities.order_key, quantities.canonical_asin,
                       quantities.expected_quantity, aliases.asin_aliases
                FROM odoo_expected_quantities quantities
                JOIN odoo_expected_aliases aliases
                  ON aliases.store_id=quantities.store_id AND aliases.order_key=quantities.order_key
                 AND aliases.canonical_asin=quantities.canonical_asin
            ), package_json_sources AS (
                SELECT p.store_id, UPPER(p.odoo_order_name) AS order_key, p.amazon_order_id,
                       CASE WHEN COALESCE(p.products_json, '') ~ '^\\s*\\[' THEN p.products_json::jsonb ELSE '[]'::jsonb END AS products,
                       CASE WHEN COALESCE(p.asins_json, '') ~ '^\\s*\\[' THEN p.asins_json::jsonb ELSE '[]'::jsonb END AS asins
                FROM amazon_dispatch_packages p
                WHERE COALESCE(p.odoo_order_name, '') != '' AND COALESCE(p.amazon_order_id, '') != ''
                  AND LOWER(COALESCE(p.package_status, '') || ' ' || COALESCE(p.promise, '')) NOT LIKE '%cancel%'
            ), amazon_package_items AS (
                SELECT source.store_id, source.order_key, source.amazon_order_id,
                       UPPER(product.value->>'asin') AS amazon_asin,
                       CASE
                           WHEN COALESCE(product.value->>'quantity', '') ~ '^[0-9]+(?:\\.[0-9]+)?$'
                           THEN GREATEST((product.value->>'quantity')::numeric, 1)
                           ELSE 1::numeric
                       END AS amazon_quantity
                FROM package_json_sources source
                CROSS JOIN LATERAL jsonb_array_elements(source.products) product(value)
                WHERE COALESCE(product.value->>'asin', '') != ''
                UNION ALL
                SELECT DISTINCT source.store_id, source.order_key, source.amazon_order_id,
                       UPPER(package_asin.value) AS amazon_asin, 1::numeric AS amazon_quantity
                FROM package_json_sources source
                CROSS JOIN LATERAL jsonb_array_elements_text(source.asins) package_asin(value)
                WHERE jsonb_array_length(source.products)=0 AND COALESCE(package_asin.value, '') != ''
            ), amazon_item_totals AS (
                SELECT items.store_id, items.order_key, items.amazon_asin,
                       SUM(items.amazon_quantity) AS amazon_quantity
                FROM amazon_package_items items
                GROUP BY items.store_id, items.order_key, items.amazon_asin
            ), duplicate_item_groups AS (
                SELECT expected.store_id, expected.order_key, expected.canonical_asin
                FROM odoo_expected_items expected
                JOIN amazon_item_totals amazon
                  ON amazon.store_id=expected.store_id AND amazon.order_key=expected.order_key
                 AND amazon.amazon_asin=ANY(expected.asin_aliases)
                GROUP BY expected.store_id, expected.order_key, expected.canonical_asin, expected.expected_quantity
                HAVING SUM(amazon.amazon_quantity) > expected.expected_quantity
            ), duplicate_package_groups AS (
                SELECT duplicates.store_id, duplicates.order_key, TRUE AS has_suspected_duplicates
                FROM duplicate_item_groups duplicates
                GROUP BY duplicates.store_id, duplicates.order_key
            ), enriched AS (
                SELECT groups.*, COALESCE(shop.shopify_order_url, '') AS shopify_order_url,
                       COALESCE(shop.fulfillment_status, '') AS shopify_fulfillment_status,
                       COALESCE(shop.fulfillment_at, '') AS shopify_fulfillment_at,
                       COALESCE(shop.synced_at, '') AS shopify_synced_at,
                       LOWER(COALESCE(shop.fulfillment_status, '')) IN ('fulfilled', 'success') AS shopify_fulfilled,
                       COALESCE(duplicates.has_suspected_duplicates, FALSE) AS has_suspected_duplicates
                FROM combined_groups groups
                LEFT JOIN LATERAL (
                    SELECT cache.shopify_order_url, cache.fulfillment_status, cache.fulfillment_at, cache.synced_at
                    FROM shopify_order_status_cache cache
                    WHERE cache.store_id=groups.store_id AND UPPER(cache.odoo_order_name)=UPPER(groups.odoo_order_name)
                    ORDER BY CASE WHEN COALESCE(cache.cancelled_at, '') = '' THEN 0 ELSE 1 END, cache.synced_at DESC
                    LIMIT 1
                ) shop ON TRUE
                LEFT JOIN duplicate_package_groups duplicates
                  ON duplicates.store_id=groups.store_id AND duplicates.order_key=UPPER(groups.odoo_order_name)
            ), filtered AS (
                SELECT * FROM enriched e
                WHERE (? = '' OR ({scoped_search_sql}))
                  AND (? = '' OR NULLIF(delivery_date, '') >= ?)
                  AND (? = '' OR NULLIF(delivery_date, '') <= ?)
                  AND {status_sql}
            )
            SELECT *, COUNT(*) OVER() AS total_count,
                   COALESCE(SUM(active_count) OVER(), 0) AS summary_packages,
                   COALESCE(SUM(delivered_count) OVER(), 0) AS summary_delivered_packages,
                   COALESCE(SUM(CASE WHEN active_count > 0 AND delivered_count=active_count THEN 1 ELSE 0 END) OVER(), 0) AS summary_delivered,
                   COALESCE(SUM(CASE WHEN delivered_count > 0 AND delivered_count<active_count THEN 1 ELSE 0 END) OVER(), 0) AS summary_partial,
                   COALESCE(SUM(CASE WHEN active_count > 0 AND delivered_count=active_count AND NOT shopify_fulfilled THEN 1 ELSE 0 END) OVER(), 0) AS summary_shopify_pending
            FROM filtered ORDER BY {sort_sql} LIMIT ? OFFSET ?
            """,
            (query, f"%{query}%", from_date, from_date, to_date, to_date, per_page, offset),
        ).fetchall())

        package_rows: list[dict[str, Any]] = []
        line_rows: list[dict[str, Any]] = []
        history_rows: list[dict[str, Any]] = []
        if grouped_rows:
            key_sql = " OR ".join("(p.store_id=? AND UPPER(p.odoo_order_name)=UPPER(?))" for _ in grouped_rows)
            key_params: list[Any] = []
            for group in grouped_rows:
                key_params.extend([group.get("store_id"), group.get("odoo_order_name")])
            package_rows = rows_to_dicts(conn.execute(
                f"""SELECT p.* FROM amazon_dispatch_packages p
                    WHERE ({key_sql})
                      AND NOT EXISTS (SELECT 1 FROM amazon_payment_failures failure WHERE failure.amazon_order_id=p.amazon_order_id AND failure.status='open')
                    ORDER BY p.updated_at DESC, p.package_index, p.id""",
                key_params,
            ).fetchall())
            line_rows = rows_to_dicts(conn.execute(
                f"""SELECT l.id, l.store_id, l.odoo_order_id, l.odoo_order_name, l.amazon_order_id,
                            l.amazon_order_url, l.asin, l.original_asin, l.replacement_asin,
                            l.asin_from_reference, l.asin_from_note, l.quantity,
                            l.product_name, l.tracking_status, l.tracking_payload,
                            l.tracking_checked_at, l.amazon_cancelled_at, l.updated_at
                    FROM order_lines l
                    WHERE ({key_sql.replace('p.', 'l.')}) AND COALESCE(l.amazon_order_id, '') != ''
                    ORDER BY l.updated_at DESC, l.id""",
                key_params,
            ).fetchall())
            amazon_order_ids = sorted({
                clean_text(row.get("amazon_order_id"))
                for row in [*line_rows, *package_rows]
                if clean_text(row.get("amazon_order_id"))
            })
            if amazon_order_ids:
                placeholders = ",".join("?" for _ in amazon_order_ids)
                history_rows = rows_to_dicts(conn.execute(
                    f"SELECT amazon_order_id, amazon_order_url, recipient, status, order_date, items_json, last_seen_at FROM amazon_order_history_unmatched WHERE amazon_order_id IN ({placeholders})",
                    amazon_order_ids,
                ).fetchall())
        stores = {int(row["id"]): dict(row) for row in conn.execute("SELECT id, name, odoo_url FROM stores").fetchall()}

    packages_by_key: dict[tuple[int, str], list[dict[str, Any]]] = {}
    for package in package_rows:
        packages_by_key.setdefault((int(package.get("store_id") or 0), clean_text(package.get("odoo_order_name")).upper()), []).append(package)
    lines_by_key: dict[tuple[int, str], list[dict[str, Any]]] = {}
    for line in line_rows:
        lines_by_key.setdefault((int(line.get("store_id") or 0), clean_text(line.get("odoo_order_name")).upper()), []).append(line)
    history_by_order_id = {clean_text(row.get("amazon_order_id")): row for row in history_rows if clean_text(row.get("amazon_order_id"))}
    tracker_asins: set[str] = set()
    for line in line_rows:
        tracker_asins.update(order_line_asin_aliases(line))
    for package in package_rows:
        tracker_asins.update(unique_normalized_asins(parse_json_list_value(package.get("asins_json"))))
        tracker_asins.update(
            normalize_asin(product.get("asin"))
            for product in parse_json_list_value(package.get("products_json"))
            if isinstance(product, dict) and normalize_asin(product.get("asin"))
        )
    for history in history_rows:
        tracker_asins.update(unique_normalized_asins(parse_json_list_value(history.get("asins_json"))))
        tracker_asins.update(
            normalize_asin(product.get("asin"))
            for product in parse_json_list_value(history.get("items_json"))
            if isinstance(product, dict) and normalize_asin(product.get("asin"))
        )
    captured_images_by_asin = package_tracker_captured_image_urls(tracker_asins)
    source_title_by_order_asin: dict[tuple[str, str], str] = {}
    source_title_by_card_asin: dict[tuple[int, str, str], str] = {}
    for line in line_rows:
        amazon_order_id = clean_text(line.get("amazon_order_id"))
        asin = normalize_asin(line.get("asin"))
        title = clean_text(line.get("product_name")).splitlines()[0].strip()
        title = re.sub(r"^\[[^\]]+\]\s*", "", title).strip()
        if amazon_order_id and asin and title:
            source_title_by_order_asin[(amazon_order_id, asin)] = title
            source_title_by_card_asin[(int(line.get("store_id") or 0), clean_text(line.get("odoo_order_name")).upper(), asin)] = title

    cards: list[dict[str, Any]] = []
    for group in grouped_rows:
        store_id = int(group.get("store_id") or 0)
        order_name = clean_text(group.get("odoo_order_name")).upper()
        store = stores.get(store_id, {})
        recipient = clean_text(group.get("recipient_ref"))
        current_packages: list[dict[str, Any]] = []
        previous_orders: list[dict[str, Any]] = []
        card_package_rows = package_tracker_canonical_dispatch_rows(
            packages_by_key.get((store_id, order_name), [])
        )
        package_rows_by_amazon_order: dict[str, list[dict[str, Any]]] = {}
        for package in card_package_rows:
            package_rows_by_amazon_order.setdefault(clean_text(package.get("amazon_order_id")), []).append(package)
        fallback_asins_by_package_id: dict[int, list[str]] = {}
        history_products_by_package_id: dict[int, list[dict[str, Any]]] = {}
        for amazon_order_id, order_packages in package_rows_by_amazon_order.items():
            fallback_asins_by_package_id.update(package_tracker_fallback_asins_by_package(
                order_packages,
                lines_by_key.get((store_id, order_name), []),
                amazon_order_id,
            ))
            history_products_by_package_id.update(package_tracker_history_products_by_package(
                order_packages,
                history_by_order_id.get(amazon_order_id, {}),
            ))
        missing_history_products_by_order = {
            amazon_order_id: package_tracker_missing_history_products(
                order_packages,
                history_by_order_id.get(amazon_order_id, {}),
            )
            for amazon_order_id, order_packages in package_rows_by_amazon_order.items()
        }
        unassigned_warning_emitted: set[str] = set()
        for package in card_package_rows:
            history = history_by_order_id.get(clean_text(package.get("amazon_order_id")), {})
            amazon_order_id = clean_text(package.get("amazon_order_id"))
            order_packages = package_rows_by_amazon_order.get(amazon_order_id, [])
            history_products = [dict(item) for item in parse_json_list_value(history.get("items_json")) if isinstance(item, dict)]
            authoritative_history_products = package_tracker_single_package_history_products(order_packages, history)
            if not authoritative_history_products:
                authoritative_history_products = [
                    dict(product)
                    for product in history_products_by_package_id.get(int(package.get("id") or 0), [])
                ]
            allowed_asins = package_tracker_allowed_asins_for_order(
                lines_by_key.get((store_id, order_name), []),
                amazon_order_id,
                history,
            )
            kind = package_tracker_delivery_kind(package.get("package_status"), package.get("promise"))
            delivered_at = clean_text(package.get("received_at")) if kind == "delivered" else ""
            if kind == "delivered" and not delivered_at:
                delivered_at = package_tracker_delivery_date(package.get("package_status"), package.get("promise"), package.get("updated_at"))
            products = [dict(product) for product in authoritative_history_products]
            if not products:
                products = [dict(item) for item in parse_json_list_value(package.get("products_json")) if isinstance(item, dict)]
                if allowed_asins:
                    products = [product for product in products if normalize_asin(product.get("asin")) in allowed_asins]
                package_asins = [
                    asin
                    for asin in fallback_asins_by_package_id.get(int(package.get("id") or 0), [])
                    if not allowed_asins or asin in allowed_asins
                ]
                represented_asins = {normalize_asin(product.get("asin")) for product in products if normalize_asin(product.get("asin"))}
                products.extend(
                    {"asin": asin, "title": asin, "image_url": "", "url": f"https://www.amazon.com/dp/{quote_plus(asin)}"}
                    for asin in package_asins
                    if asin not in represented_asins
                )
            missing_history_products = missing_history_products_by_order.get(amazon_order_id, [])
            if missing_history_products and len(order_packages) == 1 and not authoritative_history_products:
                products.extend(dict(product) for product in missing_history_products)
            history_asins = list(dict.fromkeys(normalize_asin(item.get("asin")) for item in history_products if normalize_asin(item.get("asin"))))
            normalized_history_by_asin = {
                normalize_asin(item.get("asin")): item
                for item in normalize_amazon_product_items(history_products)
                if normalize_asin(item.get("asin"))
            }
            for product in products:
                asin = normalize_asin(product.get("asin"))
                product["asin"] = asin
                history_product = normalized_history_by_asin.get(asin, {})
                if product.get("quantity_verified"):
                    product["quantity"] = max(1.0, float(product.get("quantity") or 1))
                elif history_product.get("quantity_verified"):
                    product["quantity"] = max(
                        1.0, float(history_product.get("quantity") or 1)
                    )
                    product["quantity_verified"] = True
                else:
                    product["quantity"] = 1.0
                    product["quantity_verified"] = False
                title = clean_text(product.get("title"))
                if not useful_amazon_product_title(title) or title.upper() == asin:
                    title = source_title_by_order_asin.get((clean_text(package.get("amazon_order_id")), asin), "") or source_title_by_card_asin.get((store_id, order_name, asin), "")
                product["title"] = title or asin or "Amazon product"
                # A replacement ASIN is a safe image fallback only for the same Amazon order
                # when both the dispatch package and history describe one unambiguous product.
                product["image_url"] = package_tracker_product_image_url(
                    product,
                    history_products,
                    allow_unambiguous_replacement=len(products) == 1 and len(history_asins) == 1,
                    captured_images_by_asin=captured_images_by_asin,
                )
                product["url"] = clean_text(product.get("url")) or (f"https://www.amazon.com/dp/{quote_plus(asin)}" if asin else "")
            products_by_asin: dict[str, dict[str, Any]] = {}
            for product in products:
                asin = clean_text(product.get("asin"))
                key = asin or clean_text(product.get("url")) or clean_text(product.get("title"))
                existing = products_by_asin.get(key)
                if not existing:
                    products_by_asin[key] = product
                    continue
                if not useful_amazon_product_title(existing.get("title")) and useful_amazon_product_title(product.get("title")):
                    existing["title"] = product.get("title")
                if not clean_text(existing.get("image_url")) and clean_text(product.get("image_url")):
                    existing["image_url"] = product.get("image_url")
                existing["quantity"] = max(float(existing.get("quantity") or 1), float(product.get("quantity") or 1))
            products = list(products_by_asin.values())
            order_scan_code = normalize_dispatch_scan_code(amazon_order_id)
            tracking_id = next((
                clean_text(value)
                for value in (package.get("canonical_scan_code"), package.get("scan_code"), package.get("display_code"))
                if package_tracking_id_is_physical(value)
                and normalize_dispatch_scan_code(value) != order_scan_code
            ), "")
            item = {
                "amazon_order_id": amazon_order_id,
                "amazon_order_url": clean_text(package.get("amazon_order_url")) or order_line_amazon_url(package.get("amazon_order_id")),
                "order_date": parse_amazon_order_placed_date(history.get("order_date")),
                "recipient": clean_text(package.get("recipient_ref")) or recipient,
                "tracking_id": tracking_id, "tracking_url": clean_text(package.get("tracking_url")),
                "carrier": clean_text(package.get("carrier")) or "Amazon",
                "status": clean_text(package.get("package_status")) or clean_text(package.get("promise")) or "Status pending",
                "status_kind": kind,
                # dispatch_date is an internal rack code (for example D24), not
                # Amazon's customer-facing delivery estimate.
                "expected_at": tracking_package_promise_text(package) if kind != "delivered" else "",
                "delivered_at": delivered_at,
                "updated_at": clean_text(package.get("updated_at")),
                "dispatch_location": clean_text(package.get("tote_code")),
                "scan_status": clean_text(package.get("scan_status")).replace("_", " ").title() or "Pending",
                "products": products,
                "unassigned_products": (
                    [dict(product) for product in missing_history_products]
                    if missing_history_products
                    and len(package_rows_by_amazon_order.get(amazon_order_id, [])) > 1
                    and amazon_order_id not in unassigned_warning_emitted
                    else []
                ),
            }
            item.update(package_tracker_stuck_analysis(
                status=item["status"],
                promise=package.get("promise"),
                carrier=item["carrier"],
                order_date=item["order_date"],
                expected_at=item["expected_at"],
                tracking_id=item["tracking_id"],
                updated_at=item["updated_at"],
            ))
            if item["unassigned_products"]:
                unassigned_warning_emitted.add(amazon_order_id)
            if kind == "cancelled":
                item["hidden_reason"] = "cancelled"
                previous_orders.append(item)
            else:
                current_packages.append(item)
        indexed_order_ids = {clean_text(item.get("amazon_order_id")) for item in current_packages + previous_orders}
        source_lines_by_order: dict[str, list[dict[str, Any]]] = {}
        for line in lines_by_key.get((store_id, order_name), []):
            amazon_order_id = clean_text(line.get("amazon_order_id"))
            if amazon_order_id and amazon_order_id not in indexed_order_ids:
                source_lines_by_order.setdefault(amazon_order_id, []).append(line)
        for amazon_order_id, source_lines in source_lines_by_order.items():
            source = source_lines[0]
            history = history_by_order_id.get(amazon_order_id, {})
            history_recipient = clean_text(history.get("recipient"))
            if not recipient and history_recipient:
                recipient = history_recipient
            history_products = [dict(item) for item in parse_json_list_value(history.get("items_json")) if isinstance(item, dict)]
            products_by_asin: dict[str, dict[str, Any]] = {}
            for product in history_products:
                asin = normalize_asin(product.get("asin"))
                if not asin:
                    continue
                products_by_asin[asin] = {
                    "asin": asin,
                    "title": clean_text(product.get("title")) or asin,
                    "image_url": clean_text(product.get("image_url")) or clean_text(captured_images_by_asin.get(asin)) or f"/api/public/asin-image/{quote_plus(asin)}",
                    "url": clean_text(product.get("url")) or asin_product_url(asin),
                }
            for line in source_lines:
                asin = normalize_asin(line.get("asin"))
                if not asin:
                    continue
                product = products_by_asin.setdefault(asin, {
                    "asin": asin,
                    "title": asin,
                    "image_url": clean_text(captured_images_by_asin.get(asin)) or f"/api/public/asin-image/{quote_plus(asin)}",
                    "url": asin_product_url(asin),
                })
                title = clean_text(line.get("product_name")).splitlines()[0].strip()
                title = re.sub(r"^\[[^\]]+\]\s*", "", title).strip()
                if title:
                    product["title"] = title
            tracking_parts = canonical_tracking_packages([
                part
                for part in parse_tracking_packages(clean_text(source.get("tracking_payload")))
                if isinstance(part, dict)
            ]) or [{}]
            for part_index, part in enumerate(tracking_parts):
                status_text = clean_text(part.get("delivery_status") or part.get("order_status") or part.get("promise") or part.get("status") or source.get("tracking_status") or history.get("status")) or "Status pending"
                promise = clean_text(part.get("promise"))
                kind = "cancelled" if clean_text(source.get("amazon_cancelled_at")) else package_tracker_delivery_kind(status_text, promise)
                tracking_id = next((clean_text(part.get(key)) for key in ("tracking_id", "trackingId", "tracking_number", "trackingNumber") if package_tracking_id_is_physical(part.get(key))), "")
                product_values = list(products_by_asin.values()) if len(tracking_parts) == 1 else []
                part_products = normalize_amazon_product_items(part.get("products") or [])
                if not part_products and len(tracking_parts) == 1 and not tracking_package_has_shipment_identity(part):
                    part_products = normalize_amazon_product_items(part.get("order_products") or [])
                if part_products:
                    product_values = part_products
                for product in product_values:
                    asin = normalize_asin(product.get("asin"))
                    if not asin:
                        continue
                    product["image_url"] = clean_text(product.get("image_url")) or clean_text(captured_images_by_asin.get(asin)) or f"/api/public/asin-image/{quote_plus(asin)}"
                    product["url"] = clean_text(product.get("url")) or asin_product_url(asin)
                synthetic = {
                    "amazon_order_id": amazon_order_id,
                    "amazon_order_url": clean_text(history.get("amazon_order_url") or source.get("amazon_order_url")) or order_line_amazon_url(amazon_order_id),
                    "order_date": parse_amazon_order_placed_date(history.get("order_date")),
                    "recipient": history_recipient or recipient or order_name,
                    "tracking_id": tracking_id,
                    "tracking_url": clean_text(part.get("tracking_url") or part.get("trackingUrl")) or clean_text(source.get("amazon_order_url")),
                    "carrier": clean_text(part.get("carrier") or part.get("carrier_name")) or "Amazon",
                    "status": status_text, "status_kind": kind,
                    "expected_at": "", "delivered_at": package_tracker_delivery_date(status_text, promise, source.get("updated_at")) if kind == "delivered" else "",
                    "updated_at": clean_text(source.get("tracking_checked_at") or source.get("updated_at")),
                    "dispatch_location": "", "scan_status": "Awaiting package scan",
                    "products": product_values,
                }
                synthetic.update(package_tracker_stuck_analysis(
                    status=synthetic["status"],
                    promise=promise,
                    carrier=synthetic["carrier"],
                    order_date=synthetic["order_date"],
                    expected_at=synthetic["expected_at"],
                    tracking_id=synthetic["tracking_id"],
                    updated_at=synthetic["updated_at"],
                ))
                if kind == "cancelled":
                    synthetic["hidden_reason"] = "cancelled"
                    previous_orders.append(synthetic)
                else:
                    current_packages.append(synthetic)
        current_packages.sort(
            key=lambda item: (
                parse_iso_date(clean_text(item.get("order_date"))) or datetime.min.replace(tzinfo=timezone.utc),
                parse_iso_date(clean_text(item.get("updated_at"))) or datetime.min.replace(tzinfo=timezone.utc),
            ),
            reverse=True,
        )
        product_guard = package_tracker_enforce_product_guard(current_packages, history_by_order_id)
        quantity_analysis = package_tracker_quantity_analysis(
            lines_by_key.get((store_id, order_name), []),
            card_package_rows,
            history_by_order_id,
        )
        fulfillment = clean_text(group.get("shopify_fulfillment_status")).lower()
        cards.append({
            "id": f"{store_id}:{order_name}",
            "odoo_orders": [{"name": order_name, "url": odoo_order_admin_url(store, group.get("odoo_order_id"))}],
            "recipient": recipient or order_name,
            "recipient_verified": order_name in amazon_history_order_refs_from_text(recipient),
            "shopify_status": "fulfilled" if fulfillment in {"fulfilled", "success"} else ("partially_fulfilled" if "partial" in fulfillment else "unfulfilled"),
            "shopify_url": clean_text(group.get("shopify_order_url")),
            "shopify_fulfillment_at": clean_text(group.get("shopify_fulfillment_at")),
            "shopify_synced_at": clean_text(group.get("shopify_synced_at")),
            "updated_at": clean_text(group.get("updated_at")),
            "packages": current_packages,
            "previous_orders": previous_orders,
            "product_guard": product_guard,
            "quantity_analysis": quantity_analysis,
        })

    first = grouped_rows[0] if grouped_rows else {}
    total = int(first.get("total_count") or 0)
    result = {
        "ok": True, "rows": cards, "page": page, "per_page": per_page, "total": total,
        "pages": max(1, (total + per_page - 1) // per_page),
        "summary": {
            "cards": total, "packages": int(first.get("summary_packages") or 0),
            "delivered_packages": int(first.get("summary_delivered_packages") or 0),
            "delivered": int(first.get("summary_delivered") or 0), "partial": int(first.get("summary_partial") or 0),
            "shopify_pending": int(first.get("summary_shopify_pending") or 0),
        },
    }
    return fast_page_cache_set(cache_key, result, 60)


def redesigned_public_page_redirect(request: Request, path: str) -> RedirectResponse:
    query = f"?{request.url.query}" if request.url.query else ""
    return RedirectResponse(f"{path}{query}", status_code=307, headers={"Cache-Control": "no-store"})


@app.get("/public/epost")
def public_epost_page(request: Request) -> RedirectResponse:
    return redesigned_public_page_redirect(request, "/epost")


@app.get("/public/pending")
def public_pending_page(request: Request) -> RedirectResponse:
    return redesigned_public_page_redirect(request, "/fulfilment-pending")


@app.get("/public/tracking")
def public_tracking_page(request: Request) -> RedirectResponse:
    return redesigned_public_page_redirect(request, "/tracking")


@app.get("/public/package-pickups")
def public_package_pickups_page(request: Request) -> RedirectResponse:
    return redesigned_public_page_redirect(request, "/package-pickups")


@app.get("/track-order/{slug}", response_class=HTMLResponse)
def customer_track_order_page(
    request: Request,
    slug: str,
    q: str = "",
    store_id: Optional[int] = None,
) -> HTMLResponse:
    target_store_id = store_id or default_track_order_store_id(slug)
    stores = rows_to_dicts(list_stores())
    store = next((item for item in stores if int(item["id"]) == int(target_store_id or 0)), None)
    query = clean_text(q)
    rows = customer_track_order_rows(target_store_id, query) if query else []
    return templates.TemplateResponse(
        "customer_track_order.html",
        {
            "request": request,
            "slug": slug,
            "title": customer_track_order_page_title(slug, store),
            "store": store,
            "store_id": target_store_id,
            "query": query,
            "rows": rows,
            "searched": bool(query),
        },
    )


@app.get("/track-orders/{slug}", response_class=HTMLResponse)
def track_orders_page(
    request: Request,
    slug: str,
    store_id: Optional[int] = None,
    page: int = 1,
    per_page: int = 50,
    message: str = "",
    status: str = "",
) -> HTMLResponse:
    target_store_id = store_id or default_track_order_store_id(slug)
    stores = rows_to_dicts(list_stores())
    store = next((item for item in stores if int(item["id"]) == int(target_store_id or 0)), None)
    rows, total, page, per_page = track_order_rows(target_store_id, page, per_page)
    total_pages = max(1, (total + per_page - 1) // per_page)
    return templates.TemplateResponse(
        "track_orders.html",
        {
            "request": request,
            "slug": slug,
            "title": track_order_page_title(slug, store),
            "stores": stores,
            "store": store,
            "store_id": target_store_id,
            "rows": rows,
            "page": page,
            "per_page": per_page,
            "total": total,
            "total_pages": total_pages,
            "message": message,
            "status": status,
        },
    )


@app.post("/track-orders/{slug}/sync-latest")
def track_orders_sync_latest(slug: str, store_id: Optional[int] = Form(None)) -> RedirectResponse:
    target_store_id = int(store_id) if store_id else default_track_order_store_id(slug)
    synced = sync_epost_tracking_from_odoo(target_store_id, 30) if target_store_id else 0
    row_id = latest_track_order_row_id(target_store_id)
    status = "ok"
    if not row_id:
        message = "No EPG tracking rows found for this website yet."
    else:
        try:
            details = refresh_epost_final_mile_tracking(row_id)
            number = details.get("final_mile_tracking_number") or "not found"
            carrier = details.get("final_mile_carrier") or "carrier not found"
            message = f"Synced {synced} EPG code(s). Latest row final-mile result: {carrier} {number}."
        except Exception as exc:
            status = "error"
            message = f"Synced {synced} EPG code(s), but final-mile extraction failed: {clean_error_message(exc)}"
    return RedirectResponse(
        f"/track-orders/{quote_plus(slug)}?store_id={target_store_id or ''}&status={quote_plus(status)}&message={quote_plus(message)}",
        status_code=303,
    )


@app.post("/track-orders/{slug}/{tracking_id}/sync")
def track_orders_sync_row(slug: str, tracking_id: int, store_id: Optional[int] = Form(None), page: int = Form(1)) -> RedirectResponse:
    status = "ok"
    try:
        details = refresh_epost_final_mile_tracking(tracking_id)
        number = details.get("final_mile_tracking_number") or "not found"
        carrier = details.get("final_mile_carrier") or "carrier not found"
        message = f"Final-mile result: {carrier} {number}."
    except Exception as exc:
        status = "error"
        message = f"Final-mile extraction failed: {clean_error_message(exc)}"
    return RedirectResponse(
        f"/track-orders/{quote_plus(slug)}?store_id={store_id or ''}&page={page}&status={quote_plus(status)}&message={quote_plus(message)}",
        status_code=303,
    )


