@app.post("/api/lines/ignore")
def api_ignore_lines(payload: DeleteLinesPayload) -> dict[str, Any]:
    if not payload.line_ids:
        raise HTTPException(400, "Select at least one order line to mark do not process.")
    selected_ids = sorted({int(line_id) for line_id in payload.line_ids if int(line_id or 0) > 0})
    if not selected_ids:
        raise HTTPException(400, "Select at least one order line to mark do not process.")
    now = utc_now()
    with db() as conn:
        selected_ids = validate_line_ids_for_store(conn, payload.store_id, selected_ids, "Mark do not process")
        placeholders = ",".join("?" for _ in selected_ids)
        cursor = conn.execute(
            f"""
            UPDATE order_lines
            SET state='ignored',
                amazon_status='ignored',
                amazon_group_key=NULL,
                chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL,
                last_error='Marked do not process for Amazon fulfilment.',
                updated_at=?
            WHERE store_id=?
              AND id IN ({placeholders})
              AND COALESCE(amazon_order_id, '') = ''
              AND state NOT IN ('ordered', 'delivered', 'dispatched')
            """,
            [now, payload.store_id, *selected_ids],
        )
        conn.execute(
            f"""
            UPDATE amazon_attempts
            SET status='ignored', error=NULL
            WHERE order_line_id IN ({placeholders})
              AND mode IN ('chrome', 'rest', 'cxml')
              AND status IN ('queued', 'submitted', 'error', 'costly', 'missing')
            """,
            selected_ids,
        )
        updated_rows = conn.execute(
            f"SELECT * FROM order_lines WHERE store_id=? AND id IN ({placeholders})",
            [payload.store_id, *selected_ids],
        ).fetchall()
    for updated in updated_rows:
        index_order_line(updated)
    data = dashboard_data(payload.store_id)
    data["message"] = f"Marked {cursor.rowcount} selected line{'s' if cursor.rowcount != 1 else ''} do not process. Ignored lines stay visible and are skipped when placing orders."
    return data


@app.post("/api/lines/reset-fulfilment")
def api_reset_line_fulfilment(payload: DeleteLinesPayload) -> dict[str, Any]:
    if not payload.line_ids:
        raise HTTPException(400, "Select at least one order line to reset.")
    now = utc_now()
    with db() as conn:
        selected_ids = validate_line_ids_for_store(conn, payload.store_id, payload.line_ids, "Reset selected")
        placeholders = ",".join("?" for _ in selected_ids)
        selected_rows = conn.execute(
            f"""
            SELECT id, store_id, odoo_order_id, odoo_order_name, amazon_order_id
            FROM order_lines
            WHERE store_id=? AND id IN ({placeholders})
            """,
            [payload.store_id, *selected_ids],
        ).fetchall()
        tag_pairs = {(int(row["store_id"]), int(row["odoo_order_id"])) for row in selected_rows}
        selected_order_names = {
            (int(row["store_id"]), int(row["odoo_order_id"]), clean_text(row["odoo_order_name"]))
            for row in selected_rows
            if clean_text(row["odoo_order_name"])
        }
        previous_amazon_order_ids = [
            clean_text(row["amazon_order_id"])
            for row in selected_rows
            if clean_text(row["amazon_order_id"])
        ]
        # Resetting fulfilment must not remove replacement ASIN decisions.
        # Those fields are only changed by the manual replacement action on the orders page.
        cursor = conn.execute(
            f"""
            UPDATE order_lines
            SET state='pulled',
                amazon_cancelled_order_id=CASE
                  WHEN COALESCE(amazon_order_id, '') != '' THEN amazon_order_id
                  ELSE amazon_cancelled_order_id
                END,
                amazon_cancelled_at=CASE
                  WHEN COALESCE(amazon_order_id, '') != '' THEN ?
                  ELSE amazon_cancelled_at
                END,
                amazon_order_id=NULL,
                amazon_order_url=NULL,
                amazon_account_id=NULL,
                amazon_account_name=NULL,
                amazon_group_key=NULL,
                amazon_status=NULL,
                tracking_status=NULL,
                tracking_payload=NULL,
                tracking_checked_at=NULL,
                chrome_claimed_by=NULL,
                chrome_claimed_at=NULL,
                chrome_claim_expires_at=NULL,
                amazon_unit_price=NULL,
                amazon_total_price=NULL,
                chrome_profit_total=NULL,
                fulfilment_note=NULL,
                last_error=NULL,
                missing_asin=NULL,
                cost_approved_at=NULL,
                cost_review_loss=NULL,
                ordered_at=NULL,
                updated_at=?
            WHERE store_id=?
              AND id IN ({placeholders})
            """,
            [now, now, payload.store_id, *selected_ids],
        )
        conn.execute(
            f"""
            UPDATE amazon_attempts
            SET status='reset', error=NULL
            WHERE order_line_id IN ({placeholders})
              AND mode IN ('chrome', 'rest', 'cxml')
              AND status IN ('queued', 'submitted', 'ok', 'error', 'costly', 'missing', 'ignored')
            """,
            selected_ids,
        )
        stale_shopify_jobs = 0
        stale_shopify_maps = 0
        stale_shopify_status = 0
        stale_dispatch_packages = 0
        for amazon_order_id in dict.fromkeys(previous_amazon_order_ids):
            stale_dispatch_packages += dispatch_clear_packages_for_amazon_order(conn, amazon_order_id)
        for reset_store_id, reset_odoo_order_id, reset_order_name in selected_order_names:
            cleanup = clear_stale_downstream_fulfilment_for_order(
                conn,
                reset_store_id,
                reset_odoo_order_id,
                reset_order_name,
            )
            stale_shopify_jobs += cleanup["jobs"]
            stale_shopify_status += cleanup["status"]
            stale_shopify_maps += cleanup["maps"]
        updated_rows = conn.execute(
            f"SELECT * FROM order_lines WHERE store_id=? AND id IN ({placeholders})",
            [payload.store_id, *selected_ids],
        ).fetchall()
    for updated in updated_rows:
        index_order_line(updated)
    threading.Thread(target=sync_odoo_ordered_tags_for_pairs, args=(tag_pairs,), daemon=True).start()
    fast_page_cache_clear_matching({"dashboard", "orders", "search", "chrome-jobs", "shopify-fulfilment", "fulfilment-pending", "tracking-orders"})
    data = dashboard_data(payload.store_id)
    cleanup_notes = []
    if stale_shopify_jobs:
        cleanup_notes.append(f"removed {stale_shopify_jobs} stale Shopify fulfilment job{'s' if stale_shopify_jobs != 1 else ''}")
    if stale_shopify_maps or stale_shopify_status:
        cleanup_notes.append("cleared stale Shopify link/status cache")
    if stale_dispatch_packages:
        cleanup_notes.append(f"cleared {stale_dispatch_packages} stale dispatch package row{'s' if stale_dispatch_packages != 1 else ''}")
    cleanup_suffix = f" Also {'; '.join(cleanup_notes)}." if cleanup_notes else ""
    data["message"] = f"Reset {cursor.rowcount} selected line{'s' if cursor.rowcount != 1 else ''} to fresh pulled status. Replacement ASINs were preserved.{cleanup_suffix}"
    return data


@app.put("/api/lines/{line_id}/spaid")
def api_update_line_spaid(line_id: int, payload: LineSpaidPayload) -> dict[str, Any]:
    value = clean_text(payload.supplier_part_auxiliary_id)
    with db() as conn:
        row = conn.execute("SELECT id FROM order_lines WHERE id=? AND store_id=?", (line_id, payload.store_id)).fetchone()
        if not row:
            raise HTTPException(404, "Order line not found.")
        conn.execute(
            """
            UPDATE order_lines
            SET supplier_part_auxiliary_id=?, last_error=NULL, updated_at=?
            WHERE id=? AND store_id=?
            """,
            (value, utc_now(), line_id, payload.store_id),
        )
        updated = conn.execute("SELECT * FROM order_lines WHERE id=? AND store_id=?", (line_id, payload.store_id)).fetchone()
    if updated:
        index_order_line(updated)
    data = dashboard_data(payload.store_id)
    data["message"] = f"SupplierPartAuxiliaryID {'saved' if value else 'cleared'}."
    data["ok"] = True
    return data


